function SpecialtyScreen({ specialtyId, pulseKey, customArticles, customFlashcards, boards, onOpenMindmapBoard, onBack, onNavigate }: {
  specialtyId: string
  pulseKey: number
  customArticles: Article[]
  customFlashcards: FlashCard[]
  boards: MindBoard[]
  // Mở thẳng một bảng Sơ đồ tư duy đã gắn chuyên khoa này — không đi qua `onNavigate` như các mục
  // khác vì Mindmap có ID bảng riêng, không dùng chung không gian id với Screen thường (xem
  // openMindmapNode() ở App()).
  onOpenMindmapBoard: (boardId: string) => void
  onBack: () => void
  onNavigate: (s: Screen, id?: string) => void
}) {
  const spec = SPECIALTIES.find((s) => s.id === specialtyId) || SPECIALTIES[0]
  const customForSpec = customArticles.filter((a) => a.specialty === spec.name)
  const builtInForSpec = ARTICLES.filter((a) => a.specialty === spec.name)
  // Bài tự thêm hiển thị trước (giống LibraryScreen), sau đó tới bài dựng sẵn. Không còn fallback
  // hiển thị bài của chuyên khoa khác khi chuyên khoa này chưa có bài — trước đây làm vậy khiến
  // người dùng tưởng nhầm đây là nội dung của chuyên khoa đang xem.
  const all = [...customForSpec, ...builtInForSpec]
  const articleCount = all.length
  const flashcardCount = countFlashcardsFor(spec.name, FLASHCARDS, customFlashcards)
  // Bảng Sơ đồ tư duy có gắn ĐÚNG chuyên khoa này (Mindmap tự có bộ lọc chuyên khoa riêng — xem
  // MindmapGallery — nhưng trước đây một bảng gắn "Tim mạch" không hề xuất hiện lại ở màn Tim mạch
  // của Thư viện, nên gắn khoa cho bảng gần như vô nghĩa: không có nơi nào khác đọc lại nó).
  const mindmapBoardsForSpec = boards.filter((b) => b.specialtyId === spec.id)

  return (
    <div className="relative h-full flex flex-col screen-transition" style={{ background: `${spec.color}0c` }}>
      <div className="flex items-center gap-3 px-4 pb-4 border-b" style={{ paddingTop: 21, borderColor: `${spec.color}30`, background: "var(--c-surface)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: spec.color }}>
          {icons.back()}
          Quay lại trang chủ
        </button>
      </div>
      <div key={specialtyId} className="scroll-ios flex-1 pb-6 screen-transition">
        <div className="px-6 pt-6 pb-6" style={{ background: `linear-gradient(160deg, ${spec.color}40, ${spec.color}00 75%)` }}>
          <div
            key={pulseKey}
            className="w-16 h-16 rounded-2xl flex items-center justify-center pulse-scale"
            style={{ background: spec.color, color: "#fff", boxShadow: `0 10px 24px ${spec.color}55` }}
          >
            {specialtyIcon(spec.id, "w-9 h-9")}
          </div>
          <h1 className="text-2xl font-bold text-slate-900 mt-3">{spec.name}</h1>
          <p className="text-sm text-slate-500 mt-1">
            {articleCount} bài viết · {flashcardCount} thẻ ghi nhớ
            {mindmapBoardsForSpec.length > 0 && ` · ${mindmapBoardsForSpec.length} sơ đồ tư duy`}
          </p>
        </div>
        {mindmapBoardsForSpec.length > 0 && (
          <div className="px-6 pt-1 pb-1">
            <p className="text-xs font-semibold uppercase tracking-widest text-slate-400 mb-2">Sơ đồ tư duy</p>
            <div className="space-y-2">
              {mindmapBoardsForSpec.map((b) => (
                <button
                  key={b.id}
                  onClick={() => onOpenMindmapBoard(b.id)}
                  className="w-full flex items-center gap-3 p-3.5 rounded-2xl border card-press text-left"
                  style={{ borderColor: `${spec.color}25`, background: "var(--c-surface)" }}
                >
                  <span className="flex-none w-2.5 h-2.5 rounded-full" style={{ background: b.color }} />
                  <span className="flex-1 min-w-0 font-semibold text-sm text-slate-900 truncate">{b.name}</span>
                  <svg viewBox="0 0 24 24" fill="none" stroke="var(--c-line-strong)" strokeWidth={1.8} className="w-4 h-4 flex-none">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M9 6l6 6-6 6" />
                  </svg>
                </button>
              ))}
            </div>
          </div>
        )}
        <div className="px-6 pt-4 space-y-3">
          {all.length === 0 && (
            <div className="text-center py-10 px-4 rounded-2xl border" style={{ borderColor: `${spec.color}25`, background: "var(--c-surface)" }}>
              <p className="text-sm text-slate-500">Chuyên khoa này chưa có bài viết nào.</p>
              <p className="text-xs text-slate-400 mt-1">Dùng "Tạo mục mới" ở Trang chủ để thêm bài viết đầu tiên.</p>
            </div>
          )}
          {all.map((art) => {
            const isCustom = customForSpec.some((a) => a.id === art.id)
            return (
              <button key={art.id} onClick={() => onNavigate(isCustom ? "customEntry" : "article", art.id)}
                className="w-full text-left p-4 rounded-2xl border card-press"
                style={{ borderColor: `${spec.color}25`, background: "var(--c-surface)" }}>
                <div className="flex items-center gap-2 mb-1.5">
                  <DifficultyBadge level={art.difficulty} />
                  <span className="text-xs text-slate-400">{art.readTime} phút</span>
                  {isCustom && (
                    <span
                      className="text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-full"
                      style={{ background: "var(--c-green-soft)", color: "var(--c-green-deep)" }}
                    >
                      Mới
                    </span>
                  )}
                </div>
                <p className="font-semibold text-sm text-slate-900">{art.title}</p>
                <p className="text-xs text-slate-500 mt-1 line-clamp-2">{art.excerpt}</p>
              </button>
            )
          })}
        </div>
      </div>
    </div>
  )
}

// ─── Add Entry (Create custom session) ────────────────────────────────────────

// Loại nội dung của mục tự nhập, lưu như tag đầu tiên. Bỏ "Lưu đồ" khỏi danh sách: app không có màn
// nào vẽ/hiển thị lưu đồ nên chọn nó chỉ tạo ra một tag không dẫn tới đâu (muốn dựng lưu đồ thì đã
// có màn Sơ đồ tư duy). Mục cũ đã gắn tag "Lưu đồ" vẫn giữ nguyên tag đó, chỉ là không chọn mới được.
const ENTRY_TYPES = ["Bài viết", "Hướng dẫn nhanh", "Thuốc", "Phác đồ", "Máy tính"] as const

// Màn soạn bài viết tự nhập — dùng cho cả TẠO MỚI và SỬA (truyền `initial` là bài cần sửa).
// Nội dung chi tiết soạn tự do theo block (chữ + ảnh xen kẽ, xem components/BlockEditor.tsx).
function AddEntryScreen({
  initial,
  linkTargets,
  onSave,
  onBack,
}: {
  initial?: Article
  linkTargets: LinkTarget[]
  onSave: (a: Article) => void
  onBack: () => void
}) {
  // Loại nội dung được lưu như tag ĐẦU TIÊN (xem handleSave) — khi sửa thì tách ngược ra để hiển
  // thị đúng chip đang chọn và không nhân đôi tag.
  const initialType = ENTRY_TYPES.find((t) => t === initial?.tags[0]) ?? "Bài viết"
  const initialExtraTags = initial ? initial.tags.filter((t) => t !== initialType) : []

  const [title, setTitle] = useState(initial?.title ?? "")
  const [specialty, setSpecialty] = useState(initial?.specialty ?? SPECIALTIES[0].name)
  const [type, setType] = useState<(typeof ENTRY_TYPES)[number]>(initialType)
  const [difficulty, setDifficulty] = useState<"Cơ bản" | "Nâng cao">(initial?.difficulty ?? "Cơ bản")
  const [excerpt, setExcerpt] = useState(initial?.excerpt ?? "")
  const [blocks, setBlocks] = useState<ContentBlock[]>(() => blocksForEditing(initial ? articleBlocks(initial) : []))
  const [tagsText, setTagsText] = useState(initialExtraTags.join(", "))

  const canSave = title.trim().length > 0

  function handleSave() {
    if (!canSave) return
    const saved = cleanBlocks(blocks)
    // Tóm tắt tự động & thời gian đọc chỉ tính phần chữ — bỏ chú thích ảnh để tóm tắt đọc xuôi.
    const plain = blocksToPlainText(saved.filter((b) => b.type !== "image"))
    const wordCount = plain.trim() ? plain.trim().split(/\s+/).length : 0
    const newArticle: Article = {
      id: initial?.id ?? `custom-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      title: title.trim(),
      specialty,
      tags: [type, ...tagsText.split(",").map((t) => t.trim()).filter(Boolean)],
      readTime: Math.max(1, Math.round(wordCount / 200)),
      difficulty,
      excerpt: excerpt.trim() || plain.trim().slice(0, 140) || "(Chưa có tóm tắt)",
      lastUpdated: initial ? "Vừa sửa" : "Vừa tạo",
      blocks: saved,
    }
    onSave(newArticle)
  }

  const fieldClass = "w-full px-4 py-3 rounded-2xl text-sm border outline-none"
  const fieldStyle = { borderColor: "var(--c-line)", background: "var(--c-surface)" }

  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        <span className="text-sm font-semibold text-slate-900">{initial ? "Sửa mục" : "Tạo mục mới"}</span>
        <span className="w-10" />
      </div>

      <div className="scroll-ios flex-1 px-6 pt-6 pb-8 space-y-4">
        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Tiêu đề</label>
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="VD: Hạ natri máu cấp"
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Chuyên khoa</label>
          <select
            value={specialty}
            onChange={(e) => setSpecialty(e.target.value)}
            className={fieldClass}
            style={fieldStyle}
          >
            {SPECIALTIES.map((s) => (
              <option key={s.id} value={s.name}>
                {s.name}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Loại nội dung</label>
          <div className="flex flex-wrap gap-2">
            {ENTRY_TYPES.map((t) => (
              <button
                key={t}
                onClick={() => setType(t)}
                className="px-3 py-1.5 rounded-full text-xs font-semibold border"
                style={
                  type === t
                    ? { background: "var(--c-primary)", borderColor: "var(--c-primary)", color: "var(--c-on-bright)" }
                    : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                }
              >
                {t}
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Độ khó</label>
          <div className="flex gap-2">
            {(["Cơ bản", "Nâng cao"] as const).map((d) => (
              <button
                key={d}
                onClick={() => setDifficulty(d)}
                className="flex-1 py-2.5 rounded-2xl text-sm font-semibold border"
                style={
                  difficulty === d
                    ? { background: "var(--c-primary)", borderColor: "var(--c-primary)", color: "var(--c-on-bright)" }
                    : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                }
              >
                {d === "Nâng cao" ? "Nâng cao" : "Cơ bản"}
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Tóm tắt ngắn</label>
          <textarea
            value={excerpt}
            onChange={(e) => setExcerpt(e.target.value)}
            placeholder="1–2 câu tóm tắt hiển thị ở danh sách"
            rows={2}
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Nội dung chi tiết</label>
          <BlockEditor blocks={blocks} onChange={setBlocks} linkTargets={linkTargets} />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Thẻ tag (cách nhau bằng dấu phẩy)</label>
          <input
            value={tagsText}
            onChange={(e) => setTagsText(e.target.value)}
            placeholder="VD: điện giải, cấp cứu"
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <p className="text-xs text-slate-400 leading-relaxed">
          Mục tự nhập (kể cả ảnh chèn trong bài) được lưu trên máy (trình duyệt của bạn) nên vẫn còn sau khi tắt/mở lại app. Dùng màn "Đồng bộ dữ liệu" nếu muốn sao lưu hoặc chuyển sang thiết bị khác.
        </p>
      </div>

      <div className="flex-none px-6 pt-3 border-t" style={{ borderColor: "var(--c-line)", paddingBottom: "var(--nav-pad-bottom)" }}>
        <button
          onClick={handleSave}
          disabled={!canSave}
          className="w-full py-3.5 rounded-2xl font-semibold text-sm"
          style={{ background: canSave ? "var(--c-primary)" : "var(--c-muted)", color: "var(--c-on-bright)" }}
        >
          {initial ? "Lưu thay đổi" : "Lưu mục mới"}
        </button>
      </div>
    </div>
  )
}

// Danh mục đường dùng cố định cho kháng sinh tự nhập — chọn nhanh bằng chip thay vì gõ tự do,
// để đồng bộ với cách AntibioticDoseCard/AntibioticsScreen hiển thị `route`. "other" mở thêm
// một ô nhập chuỗi tự do (không có field riêng trong Antibiotic — giá trị gõ vào chính là `route`).
const ANTIBIOTIC_ROUTE_OPTIONS: { id: string; label: string }[] = [
  { id: "iv-infusion", label: "Truyền tĩnh mạch (TTM)" },
  { id: "iv-slow", label: "Tiêm tĩnh mạch chậm (TMC)" },
  { id: "im", label: "Tiêm bắp (TB)" },
  { id: "sc", label: "Tiêm dưới da (TDD)" },
  { id: "oral", label: "Uống" },
  { id: "other", label: "Vị trí khác" },
]

function AddAntibioticScreen({
  diseases,
  onSave,
  onBack,
}: {
  diseases: DiseaseEntry[]
  onSave: (a: Antibiotic) => void
  onBack: () => void
}) {
  const [name, setName] = useState("")
  const [routeId, setRouteId] = useState<string>("iv-infusion")
  const [routeOther, setRouteOther] = useState("")
  const [diseaseIds, setDiseaseIds] = useState<string[]>([])
  const [doseMode, setDoseMode] = useState<"fixed" | "crcl3" | "crcl4">("fixed")
  const [fixedDose, setFixedDose] = useState("")
  // Mức chung cho cả 2 chế độ CrCl (3 mức / 4 mức)
  const [tier50, setTier50] = useState("")
  const [tierBelow10, setTierBelow10] = useState("")
  // Riêng cho 3 mức: >50, 10–49, <10
  const [tier1049, setTier1049] = useState("")
  // Riêng cho 4 mức: >50, 31–50, 10–30, <10
  const [tier3150, setTier3150] = useState("")
  const [tier1030, setTier1030] = useState("")
  const [preparation, setPreparation] = useState("")
  const [note, setNote] = useState("")
  const [warningText, setWarningText] = useState("")
  const [warningSeverity, setWarningSeverity] = useState<"cao" | "trung bình">("trung bình")
  const [source, setSource] = useState("")
  const [reviewedOn, setReviewedOn] = useState("")
  // Liều nạp — vd Vancomycin cần liều nạp trước khi vào liều duy trì theo CrCl. Trước đây chỉ màn
  // Sửa có mục này, thêm nhanh kháng sinh mới hoàn toàn không khai báo được.
  const [boluses, setBoluses] = useState<BolusDraft[]>([])

  // "Cách dùng / Pha thuốc" có ích cho CẢ BỐN đường tiêm/truyền (TTM/TMC/IM/SC) — không chỉ truyền
  // tĩnh mạch. Trước đây chỉ hiện cho "iv-infusion" nên tiêm tĩnh mạch chậm/tiêm bắp/tiêm dưới da
  // không có chỗ ghi cách pha, dù các đường đó cũng cần hoàn nguyên/pha loãng như truyền tĩnh mạch.
  const isInjectableRoute = routeId === "iv-infusion" || routeId === "iv-slow" || routeId === "im" || routeId === "sc"
  const isOtherRoute = routeId === "other"
  const finalRoute = isOtherRoute ? routeOther.trim() : ANTIBIOTIC_ROUTE_OPTIONS.find((r) => r.id === routeId)?.label ?? ""

  const hasCrcl3Dose = tier50.trim() || tier1049.trim() || tierBelow10.trim()
  const hasCrcl4Dose = tier50.trim() || tier3150.trim() || tier1030.trim() || tierBelow10.trim()
  const doseValid =
    doseMode === "fixed" ? fixedDose.trim().length > 0 : doseMode === "crcl3" ? Boolean(hasCrcl3Dose) : Boolean(hasCrcl4Dose)
  const canSave = name.trim().length > 0 && finalRoute.length > 0 && doseValid

  function toggleDisease(id: string) {
    setDiseaseIds((prev) => (prev.includes(id) ? prev.filter((d) => d !== id) : [...prev, id]))
  }

  function handleSave() {
    if (!canSave) return
    const tiers: DoseTier[] =
      doseMode === "fixed"
        ? [{ min: 0, label: "Mọi mức CrCl", dose: fixedDose.trim() }]
        : doseMode === "crcl3"
          ? [
              ...(tier50.trim() ? [{ min: 50, label: "CrCl ≥ 50", dose: tier50.trim() }] : []),
              ...(tier1049.trim() ? [{ min: 10, label: "CrCl 10–49", dose: tier1049.trim() }] : []),
              ...(tierBelow10.trim() ? [{ min: 0, label: "CrCl < 10", dose: tierBelow10.trim() }] : []),
            ]
          : [
              ...(tier50.trim() ? [{ min: 50, label: "CrCl ≥ 50", dose: tier50.trim() }] : []),
              ...(tier3150.trim() ? [{ min: 31, label: "CrCl 31–50", dose: tier3150.trim() }] : []),
              ...(tier1030.trim() ? [{ min: 10, label: "CrCl 10–30", dose: tier1030.trim() }] : []),
              ...(tierBelow10.trim() ? [{ min: 0, label: "CrCl < 10", dose: tierBelow10.trim() }] : []),
            ]

    // Bệnh lý áp dụng: gắn `indications` theo từng bệnh lý đã chọn (dùng chung `tiers` ở trên) —
    // để AntibioticsScreen nhận diện được thuốc này khi người dùng chọn đúng bệnh lý đó ở Bước 2,
    // và AntibioticDoseCard hiển thị đúng nhãn "Chỉ định: ..." — đồng bộ với cách hiển thị chung.
    const indications: IndicationDose[] | undefined =
      diseaseIds.length > 0
        ? diseaseIds.map((diseaseId) => ({
            diseaseId,
            tiers,
            standardDose: doseMode === "fixed" ? fixedDose.trim() : undefined,
          }))
        : undefined

    const cleanedBoluses = boluses.map(draftToBolus).filter((b): b is BolusDose => b != null)
    const newDrug: Antibiotic = {
      id: `custom-abx-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      name: name.trim(),
      route: finalRoute,
      preparation: isInjectableRoute && preparation.trim() ? preparation.trim() : undefined,
      note: note.trim() || undefined,
      tiers,
      warnings: warningText.trim() ? [{ text: warningText.trim(), severity: warningSeverity }] : undefined,
      indications,
      boluses: cleanedBoluses.length > 0 ? cleanedBoluses : undefined,
      source: source.trim() || undefined,
      reviewedOn: reviewedOn.trim() || undefined,
      isCustom: true,
    }
    onSave(newDrug)
  }

  const fieldClass = "w-full px-4 py-3 rounded-2xl text-sm border outline-none"
  const fieldStyle = { borderColor: "var(--c-line)", background: "var(--c-surface)" }
  const chipStyle = (active: boolean) =>
    active
      ? { background: "var(--c-primary)", borderColor: "var(--c-primary)", color: "var(--c-on-bright)" }
      : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }

  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        <span className="text-sm font-semibold text-slate-900">Thêm kháng sinh tự nhập</span>
        <span className="w-10" />
      </div>

      <div className="scroll-ios flex-1 px-6 pt-6 pb-8 space-y-4">
        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Tên hoạt chất</label>
          <input value={name} onChange={(e) => setName(e.target.value)} placeholder="VD: Linezolid" className={fieldClass} style={fieldStyle} />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Đường dùng</label>
          <div className="flex flex-wrap gap-2">
            {ANTIBIOTIC_ROUTE_OPTIONS.map((r) => (
              <button
                key={r.id}
                onClick={() => setRouteId(r.id)}
                className="px-3.5 py-2 rounded-full text-xs font-semibold border transition-colors"
                style={chipStyle(routeId === r.id)}
              >
                {r.label}
              </button>
            ))}
          </div>
          {isOtherRoute && (
            <input
              value={routeOther}
              onChange={(e) => setRouteOther(e.target.value)}
              placeholder="Ghi rõ đường dùng, VD: Tiêm trong khớp, nhỏ mắt..."
              className={`${fieldClass} mt-2.5`}
              style={fieldStyle}
            />
          )}
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Bệnh lý áp dụng (tuỳ chọn)</label>
          <div className="flex flex-wrap gap-2">
            {diseases.map((d) => (
              <button
                key={d.id}
                onClick={() => toggleDisease(d.id)}
                className="px-3.5 py-2 rounded-full text-xs font-semibold border transition-colors"
                style={
                  diseaseIds.includes(d.id)
                    ? { background: "var(--c-primary-soft)", borderColor: "var(--c-primary)", color: "var(--c-primary)" }
                    : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                }
              >
                {d.name}
              </button>
            ))}
          </div>
          <p className="text-[12px] text-slate-400 mt-1.5">Không chọn = thuốc dùng chung, không gắn với bệnh lý cụ thể nào.</p>
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Cách chỉnh liều</label>
          <div className="flex flex-wrap gap-2 mb-2.5">
            {(
              [
                { id: "fixed" as const, label: "Liều cố định" },
                { id: "crcl3" as const, label: "Theo CrCl (3 mức)" },
                { id: "crcl4" as const, label: "Theo CrCl (4 mức)" },
              ]
            ).map((m) => (
              <button
                key={m.id}
                onClick={() => setDoseMode(m.id)}
                className="flex-1 py-2.5 rounded-2xl text-xs font-semibold border min-w-[30%]"
                style={chipStyle(doseMode === m.id)}
              >
                {m.label}
              </button>
            ))}
          </div>
          {doseMode === "fixed" && (
            <input value={fixedDose} onChange={(e) => setFixedDose(e.target.value)} placeholder="VD: 600 mg mỗi 12h — không cần chỉnh liều thận" className={fieldClass} style={fieldStyle} />
          )}
          {doseMode === "crcl3" && (
            <div className="space-y-2">
              <div>
                <label className="text-[12px] text-slate-400 mb-1 block">CrCl ≥ 50</label>
                <input value={tier50} onChange={(e) => setTier50(e.target.value)} placeholder="VD: 1 g mỗi 8h" className={fieldClass} style={fieldStyle} />
              </div>
              <div>
                <label className="text-[12px] text-slate-400 mb-1 block">CrCl 10–49</label>
                <input value={tier1049} onChange={(e) => setTier1049(e.target.value)} placeholder="VD: 1 g mỗi 12h" className={fieldClass} style={fieldStyle} />
              </div>
              <div>
                <label className="text-[12px] text-slate-400 mb-1 block">CrCl &lt; 10</label>
                <input value={tierBelow10} onChange={(e) => setTierBelow10(e.target.value)} placeholder="VD: 500 mg mỗi 24h" className={fieldClass} style={fieldStyle} />
              </div>
              <p className="text-[12px] text-slate-400">Có thể bỏ trống mức không áp dụng — chỉ cần điền ít nhất một mức.</p>
            </div>
          )}
          {doseMode === "crcl4" && (
            <div className="space-y-2">
              <div>
                <label className="text-[12px] text-slate-400 mb-1 block">CrCl &gt; 50</label>
                <input value={tier50} onChange={(e) => setTier50(e.target.value)} placeholder="VD: 1 g mỗi 8h" className={fieldClass} style={fieldStyle} />
              </div>
              <div>
                <label className="text-[12px] text-slate-400 mb-1 block">CrCl 31–50</label>
                <input value={tier3150} onChange={(e) => setTier3150(e.target.value)} placeholder="VD: 1 g mỗi 12h" className={fieldClass} style={fieldStyle} />
              </div>
              <div>
                <label className="text-[12px] text-slate-400 mb-1 block">CrCl 10–30</label>
                <input value={tier1030} onChange={(e) => setTier1030(e.target.value)} placeholder="VD: 500 mg mỗi 12h" className={fieldClass} style={fieldStyle} />
              </div>
              <div>
                <label className="text-[12px] text-slate-400 mb-1 block">CrCl &lt; 10</label>
                <input value={tierBelow10} onChange={(e) => setTierBelow10(e.target.value)} placeholder="VD: 500 mg mỗi 24h" className={fieldClass} style={fieldStyle} />
              </div>
              <p className="text-[12px] text-slate-400">Có thể bỏ trống mức không áp dụng — chỉ cần điền ít nhất một mức.</p>
            </div>
          )}
        </div>

        {isInjectableRoute && (
          <div className="fade-in">
            <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Cách dùng / Pha thuốc (tuỳ chọn)</label>
            <textarea value={preparation} onChange={(e) => setPreparation(e.target.value)} placeholder="VD: Pha với Natri Clorid 0,9%, truyền trong 30–60 phút" rows={3} className={fieldClass} style={fieldStyle} />
          </div>
        )}

        {/* Liều nạp — vd Vancomycin cần liều nạp trước khi vào liều duy trì theo CrCl. */}
        <BolusEditorField boluses={boluses} setBoluses={setBoluses} />

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Ghi chú (tuỳ chọn)</label>
          <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="VD: Theo dõi nồng độ đáy" className={fieldClass} style={fieldStyle} />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Cảnh báo / tương tác (tuỳ chọn)</label>
          <input value={warningText} onChange={(e) => setWarningText(e.target.value)} placeholder="VD: Thận trọng khi phối hợp với..." className={`${fieldClass} mb-2`} style={fieldStyle} />
          {warningText.trim() && (
            <div className="flex gap-2">
              {(["trung bình", "cao"] as const).map((s) => (
                <button
                  key={s}
                  onClick={() => setWarningSeverity(s)}
                  className="flex-1 py-2 rounded-xl text-xs font-semibold border"
                  style={
                    warningSeverity === s
                      ? { background: s === "cao" ? "var(--c-danger-icon)" : "var(--c-warn-icon)", borderColor: "transparent", color: "var(--c-on-bright)" }
                      : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                  }
                >
                  Mức độ: {s}
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="pt-2 border-t" style={{ borderColor: "var(--c-line-soft)" }}>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block mt-3">Nguồn dữ liệu (tuỳ chọn)</label>
          <input value={source} onChange={(e) => setSource(e.target.value)} placeholder="VD: Phác đồ ICU BV X 2026 / Sanford Guide" className={fieldClass} style={fieldStyle} />
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block mt-3">Rà soát lần cuối (YYYY-MM)</label>
          <input value={reviewedOn} onChange={(e) => setReviewedOn(e.target.value)} placeholder="VD: 2026-07" className={fieldClass} style={fieldStyle} />
          <p className="text-[12px] text-slate-400 leading-relaxed mt-1.5">
            Bỏ trống thì thẻ thuốc sẽ hiện rõ "chưa ghi nguồn · chưa rà soát".
          </p>
        </div>

        <p className="text-xs text-slate-400 leading-relaxed">
          Mục tự nhập được lưu trên máy (trình duyệt của bạn) nên vẫn còn sau khi tắt/mở lại app.
        </p>
      </div>

      <div className="flex-none px-6 pt-3 border-t" style={{ borderColor: "var(--c-line)", paddingBottom: "var(--nav-pad-bottom)" }}>
        <button
          onClick={handleSave}
          disabled={!canSave}
          className="w-full py-3.5 rounded-2xl font-semibold text-sm"
          style={{ background: canSave ? "var(--c-primary)" : "var(--c-muted)", color: "var(--c-on-bright)" }}
        >
          Lưu kháng sinh
        </button>
      </div>
    </div>
  )
}

// Sửa một kháng sinh đã có — dùng chung cho cả thuốc dựng sẵn (lưu thành bản "đã chỉnh sửa" đè
// lên bản gốc khi hiển thị, xem mergeWithOverrides) lẫn thuốc tự nhập trước đó. Cố tình KHÔNG dùng
// lại giao diện "liều cố định / CrCl 3 mức / CrCl 4 mức" của AddAntibioticScreen: dữ liệu dựng sẵn
// thực tế có nhiều mốc CrCl khác nhau (vd. 60/40/20/0, thậm chí 5 mức) không khớp khuôn cố định đó
// — ép vào khuôn đó khi sửa sẽ làm mất/lệch dữ liệu. Màn này cho sửa trực tiếp từng mức liều
// (min, nhãn, liều) và từng cảnh báo dưới dạng danh sách có thể thêm/xoá tự do, không mất dữ liệu.
// Một dòng "Chỉ định riêng theo bệnh lý" đang chỉnh sửa trong EditAntibioticScreen. `diseaseName`
// là ô nhập tự do — khi lưu, app tìm bệnh lý trùng tên (không phân biệt hoa/thường) trong danh mục
// hiện có (gốc + tự nhập); nếu không thấy, tự tạo một DiseaseEntry mới (xem handleSave bên dưới).
interface IndicationRow {
  key: string
  diseaseName: string
  standardDose: string
  tiers: { min: string; label: string; dose: string }[]
  note: string
}

function EditAntibioticScreen({
  drug,
  diseases,
  onSave,
  onBack,
}: {
  drug: Antibiotic
  diseases: DiseaseEntry[]
  onSave: (a: Antibiotic, newDiseases: DiseaseEntry[]) => void
  onBack: () => void
}) {
  const initialRouteMatch = ANTIBIOTIC_ROUTE_OPTIONS.find((r) => r.label === drug.route)
  const [name, setName] = useState(drug.name)
  const [routeId, setRouteId] = useState<string>(initialRouteMatch ? initialRouteMatch.id : "other")
  const [routeOther, setRouteOther] = useState(initialRouteMatch ? "" : drug.route)
  const [standardDose, setStandardDose] = useState(drug.standardDose ?? "")
  const [preparation, setPreparation] = useState(drug.preparation ?? "")
  const [note, setNote] = useState(drug.note ?? "")
  const [source, setSource] = useState(drug.source ?? "")
  const [reviewedOn, setReviewedOn] = useState(drug.reviewedOn ?? "")
  // Liều khi lọc máu — nhập được ngay tại đây để phác đồ của khoa vào thẳng app, thay vì mỗi lần
  // gặp bệnh nhân CRRT lại phải đi tra sổ.
  const [rrtIhd, setRrtIhd] = useState(drug.rrt?.ihd ?? "")
  const [rrtCrrt, setRrtCrrt] = useState(drug.rrt?.crrt ?? "")
  const [rrtSled, setRrtSled] = useState(drug.rrt?.sled ?? "")
  const [rrtPd, setRrtPd] = useState(drug.rrt?.pd ?? "")
  const [rrtNote, setRrtNote] = useState(drug.rrt?.note ?? "")
  const [rrtSource, setRrtSource] = useState(drug.rrt?.source ?? "")
  // Liều nạp — vd Vancomycin cần 25–30 mg/kg trước khi vào liều duy trì theo CrCl.
  const [boluses, setBoluses] = useState<BolusDraft[]>(() => (drug.boluses ?? []).map(bolusToDraft))
  const [tiers, setTiers] = useState<{ min: string; label: string; dose: string }[]>(
    drug.tiers.length > 0 ? drug.tiers.map((t) => ({ min: String(t.min), label: t.label, dose: t.dose })) : [{ min: "0", label: "Mọi mức CrCl", dose: "" }],
  )
  const [warnings, setWarnings] = useState<{ text: string; severity: "cao" | "trung bình" }[]>(
    (drug.warnings ?? []).map((w) => ({ text: w.text, severity: w.severity })),
  )
  // Chỉ định riêng theo bệnh lý — trước đây chỉ xem, giờ cho sửa/thêm/xoá được ngay ở màn này.
  const [indications, setIndications] = useState<IndicationRow[]>(() =>
    (drug.indications ?? []).map((ind, i) => {
      const dz = diseases.find((d) => d.id === ind.diseaseId)
      return {
        key: `${ind.diseaseId}-${i}`,
        diseaseName: dz?.name ?? ind.diseaseId,
        standardDose: ind.standardDose ?? "",
        tiers: ind.tiers.map((t) => ({ min: String(t.min), label: t.label, dose: t.dose })),
        note: ind.note ?? "",
      }
    }),
  )

  const isOtherRoute = routeId === "other"
  const finalRoute = isOtherRoute ? routeOther.trim() : ANTIBIOTIC_ROUTE_OPTIONS.find((r) => r.id === routeId)?.label ?? ""
  const canSave = name.trim().length > 0 && finalRoute.length > 0 && tiers.some((t) => t.dose.trim())

  function updateTier(idx: number, field: "min" | "label" | "dose", value: string) {
    setTiers((prev) => prev.map((t, i) => (i === idx ? { ...t, [field]: value } : t)))
  }
  function addTier() {
    setTiers((prev) => [...prev, { min: "", label: "", dose: "" }])
  }
  function removeTier(idx: number) {
    setTiers((prev) => (prev.length > 1 ? prev.filter((_, i) => i !== idx) : prev))
  }

  function updateWarningText(idx: number, value: string) {
    setWarnings((prev) => prev.map((w, i) => (i === idx ? { ...w, text: value } : w)))
  }
  function updateWarningSeverity(idx: number, severity: "cao" | "trung bình") {
    setWarnings((prev) => prev.map((w, i) => (i === idx ? { ...w, severity } : w)))
  }
  function addWarning() {
    setWarnings((prev) => [...prev, { text: "", severity: "trung bình" }])
  }
  function removeWarning(idx: number) {
    setWarnings((prev) => prev.filter((_, i) => i !== idx))
  }

  function addIndication() {
    setIndications((prev) => [
      ...prev,
      { key: `new-${Date.now()}-${prev.length}`, diseaseName: "", standardDose: "", tiers: [], note: "" },
    ])
  }
  function removeIndication(key: string) {
    setIndications((prev) => prev.filter((r) => r.key !== key))
  }
  function updateIndicationField(key: string, field: "diseaseName" | "standardDose" | "note", value: string) {
    setIndications((prev) => prev.map((r) => (r.key === key ? { ...r, [field]: value } : r)))
  }
  function pickIndicationDisease(key: string, diseaseName: string) {
    setIndications((prev) => prev.map((r) => (r.key === key ? { ...r, diseaseName } : r)))
  }
  function addIndicationTier(key: string) {
    setIndications((prev) => prev.map((r) => (r.key === key ? { ...r, tiers: [...r.tiers, { min: "", label: "", dose: "" }] } : r)))
  }
  function removeIndicationTier(key: string, idx: number) {
    setIndications((prev) => prev.map((r) => (r.key === key ? { ...r, tiers: r.tiers.filter((_, i) => i !== idx) } : r)))
  }
  function updateIndicationTier(key: string, idx: number, field: "min" | "label" | "dose", value: string) {
    setIndications((prev) =>
      prev.map((r) => (r.key === key ? { ...r, tiers: r.tiers.map((t, i) => (i === idx ? { ...t, [field]: value } : t)) } : r)),
    )
  }

  function handleSave() {
    if (!canSave) return
    const cleanedTiers: DoseTier[] = tiers
      .filter((t) => t.dose.trim())
      .map((t) => {
        const minNum = parseFloat(t.min)
        const min = isNaN(minNum) ? 0 : minNum
        return { min, label: t.label.trim() || `CrCl ≥ ${min}`, dose: t.dose.trim() }
      })
    const cleanedWarnings: AntibioticWarning[] = warnings.filter((w) => w.text.trim()).map((w) => ({ text: w.text.trim(), severity: w.severity }))
    const cleanedBoluses = boluses.map(draftToBolus).filter((b): b is BolusDose => b != null)
    const fallbackTiers = cleanedTiers.length > 0 ? cleanedTiers : drug.tiers

    // Với mỗi chỉ định theo bệnh lý: tìm bệnh lý trùng tên trong danh mục hiện có (không phân biệt
    // hoa/thường, không kể khoảng trắng thừa) để lấy đúng diseaseId; nếu tên không khớp mục nào,
    // đây là bệnh lý mới do người dùng gõ vào — tự tạo một DiseaseEntry mới cho bệnh lý đó. Cũng so
    // khớp với các bệnh lý VỪA được tạo ở chỉ định trước đó trong cùng lần lưu này, để hai chỉ định
    // cùng gõ một tên bệnh lý mới (chưa có trong danh mục) dùng chung một diseaseId thay vì tạo trùng.
    const newDiseases: DiseaseEntry[] = []
    const cleanedIndications: IndicationDose[] = indications
      .filter((row) => row.diseaseName.trim())
      .map((row) => {
        const trimmedName = row.diseaseName.trim()
        const matched =
          diseases.find((d) => d.name.trim().toLowerCase() === trimmedName.toLowerCase()) ??
          newDiseases.find((d) => d.name.trim().toLowerCase() === trimmedName.toLowerCase())
        let diseaseId = matched?.id
        if (!diseaseId) {
          diseaseId = `custom-disease-${slugifyDiseaseName(trimmedName) || "moi"}-${Date.now()}-${newDiseases.length}`
          newDiseases.push({ id: diseaseId, name: trimmedName, antibiotics: [drug.id], isCustom: true })
        }
        const indTiers: DoseTier[] = row.tiers
          .filter((t) => t.dose.trim())
          .map((t) => {
            const minNum = parseFloat(t.min)
            const min = isNaN(minNum) ? 0 : minNum
            return { min, label: t.label.trim() || `CrCl ≥ ${min}`, dose: t.dose.trim() }
          })
        const indication: IndicationDose = {
          diseaseId,
          tiers: indTiers.length > 0 ? indTiers : fallbackTiers,
          standardDose: row.standardDose.trim() || undefined,
          note: row.note.trim() || undefined,
        }
        return indication
      })

    const updated: Antibiotic = {
      ...drug,
      name: name.trim(),
      route: finalRoute,
      standardDose: standardDose.trim() || undefined,
      preparation: preparation.trim() || undefined,
      note: note.trim() || undefined,
      tiers: fallbackTiers,
      warnings: cleanedWarnings.length > 0 ? cleanedWarnings : undefined,
      indications: cleanedIndications.length > 0 ? cleanedIndications : undefined,
      boluses: cleanedBoluses.length > 0 ? cleanedBoluses : undefined,
      source: source.trim() || undefined,
      reviewedOn: reviewedOn.trim() || undefined,
      rrt:
        rrtIhd.trim() || rrtCrrt.trim() || rrtSled.trim() || rrtPd.trim() || rrtNote.trim()
          ? {
              ihd: rrtIhd.trim() || undefined,
              crrt: rrtCrrt.trim() || undefined,
              sled: rrtSled.trim() || undefined,
              pd: rrtPd.trim() || undefined,
              note: rrtNote.trim() || undefined,
              source: rrtSource.trim() || undefined,
              reviewedOn: drug.rrt?.reviewedOn,
            }
          : undefined,
      isCustom: true,
    }
    onSave(updated, newDiseases)
  }

  const fieldClass = "w-full px-4 py-3 rounded-2xl text-sm border outline-none"
  const fieldStyle = { borderColor: "var(--c-line)", background: "var(--c-surface)" }
  const chipStyle = (active: boolean) =>
    active
      ? { background: "var(--c-primary)", borderColor: "var(--c-primary)", color: "var(--c-on-bright)" }
      : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }

  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        <span className="text-sm font-semibold text-slate-900">Sửa kháng sinh</span>
        <span className="w-10" />
      </div>

      <div className="scroll-ios flex-1 px-6 pt-6 pb-8 space-y-4">
        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Tên hoạt chất</label>
          <input value={name} onChange={(e) => setName(e.target.value)} className={fieldClass} style={fieldStyle} />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Đường dùng</label>
          <div className="flex flex-wrap gap-2">
            {ANTIBIOTIC_ROUTE_OPTIONS.map((r) => (
              <button key={r.id} onClick={() => setRouteId(r.id)} className="px-3.5 py-2 rounded-full text-xs font-semibold border transition-colors" style={chipStyle(routeId === r.id)}>
                {r.label}
              </button>
            ))}
            <button onClick={() => setRouteId("other")} className="px-3.5 py-2 rounded-full text-xs font-semibold border transition-colors" style={chipStyle(routeId === "other")}>
              Khác
            </button>
          </div>
          {isOtherRoute && (
            <input value={routeOther} onChange={(e) => setRouteOther(e.target.value)} placeholder="Ghi rõ đường dùng" className={`${fieldClass} mt-2.5`} style={fieldStyle} />
          )}
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Liều chuẩn tham khảo (tuỳ chọn)</label>
          <input
            value={standardDose}
            onChange={(e) => setStandardDose(e.target.value)}
            placeholder="VD: 1–2 g mỗi 8h (IV)"
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Cách dùng / Pha thuốc (tuỳ chọn)</label>
          <textarea value={preparation} onChange={(e) => setPreparation(e.target.value)} rows={3} className={fieldClass} style={fieldStyle} />
        </div>

        <div>
          <div className="flex items-center justify-between mb-1.5">
            <label className="text-xs font-semibold text-slate-500">Mức liều theo CrCl</label>
            <button onClick={addTier} className="text-xs font-semibold" style={{ color: "var(--c-primary)" }}>
              + Thêm mức
            </button>
          </div>
          <div className="space-y-2.5">
            {tiers.map((t, idx) => (
              <div key={idx} className="p-3 rounded-2xl border" style={{ borderColor: "var(--c-line)" }}>
                <div className="flex items-center gap-2 mb-2">
                  <div className="flex-1">
                    {/* min-h-[3em] (issue "CrCl tối thiểu không ngay hàng"): nhãn này dài hơn "Nhãn
                        hiển thị" nên xuống 2 dòng ở cột hẹp trong khi nhãn kia chỉ 1 dòng, đẩy ô nhập
                        bên dưới tụt xuống lệch nhau. Đặt trước chiều cao ĐÚNG 2 dòng (line-height 1.5
                        ở cỡ chữ 10px) trên cả hai nhãn cùng hàng để hai ô nhập luôn ngang hàng. */}
                    <label className="text-[12px] text-slate-400 mb-1 block min-h-[3em]">CrCl tối thiểu (mL/phút)</label>
                    <input
                      value={t.min}
                      onChange={(e) => updateTier(idx, "min", normalizeDecimalInput(e.target.value))}
                      inputMode="decimal"
                      placeholder="0"
                      className="w-full px-3 py-2 rounded-xl text-sm border outline-none"
                      style={fieldStyle}
                    />
                  </div>
                  <div className="flex-[2]">
                    <label className="text-[12px] text-slate-400 mb-1 block min-h-[3em]">Nhãn hiển thị</label>
                    <input
                      value={t.label}
                      onChange={(e) => updateTier(idx, "label", e.target.value)}
                      placeholder="VD: CrCl 10–49"
                      className="w-full px-3 py-2 rounded-xl text-sm border outline-none"
                      style={fieldStyle}
                    />
                  </div>
                  {tiers.length > 1 && (
                    <button
                      onClick={() => removeTier(idx)}
                      className="w-9 h-9 rounded-full flex items-center justify-center flex-none mt-4"
                      style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }}
                      aria-label="Xoá mức"
                    >
                      {icons.x()}
                    </button>
                  )}
                </div>
                <label className="text-[12px] text-slate-400 mb-1 block">Liều</label>
                <input
                  value={t.dose}
                  onChange={(e) => updateTier(idx, "dose", e.target.value)}
                  placeholder="VD: 1 g mỗi 8h"
                  className="w-full px-3 py-2 rounded-xl text-sm border outline-none"
                  style={fieldStyle}
                />
              </div>
            ))}
          </div>
          <p className="text-[12px] text-slate-400 mt-1.5">Chỉ 1 mức với CrCl tối thiểu = 0 nghĩa là liều cố định, không cần chỉnh theo thận.</p>
        </div>

        {/* Liều nạp — vd Vancomycin cần 25–30 mg/kg trước khi vào liều duy trì theo CrCl. */}
        <BolusEditorField boluses={boluses} setBoluses={setBoluses} />

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Ghi chú (tuỳ chọn)</label>
          <input value={note} onChange={(e) => setNote(e.target.value)} className={fieldClass} style={fieldStyle} />
        </div>

        <div>
          <div className="flex items-center justify-between mb-1.5">
            <label className="text-xs font-semibold text-slate-500">Cảnh báo / tương tác (tuỳ chọn)</label>
            <button onClick={addWarning} className="text-xs font-semibold" style={{ color: "var(--c-primary)" }}>
              + Thêm cảnh báo
            </button>
          </div>
          <div className="space-y-2">
            {warnings.map((w, idx) => (
              <div key={idx} className="p-3 rounded-2xl border" style={{ borderColor: "var(--c-line)" }}>
                <div className="flex items-center gap-2 mb-2">
                  <input
                    value={w.text}
                    onChange={(e) => updateWarningText(idx, e.target.value)}
                    className="flex-1 px-3 py-2 rounded-xl text-sm border outline-none"
                    style={fieldStyle}
                  />
                  <button onClick={() => removeWarning(idx)} className="w-9 h-9 rounded-full flex items-center justify-center flex-none" style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }} aria-label="Xoá cảnh báo">
                    {icons.x()}
                  </button>
                </div>
                <div className="flex gap-2">
                  {(["trung bình", "cao"] as const).map((s) => (
                    <button
                      key={s}
                      onClick={() => updateWarningSeverity(idx, s)}
                      className="flex-1 py-1.5 rounded-xl text-xs font-semibold border"
                      style={
                        w.severity === s
                          ? { background: s === "cao" ? "var(--c-danger-icon)" : "var(--c-warn-icon)", borderColor: "transparent", color: "var(--c-on-bright)" }
                          : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                      }
                    >
                      Mức độ: {s}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div>
          <div className="flex items-center justify-between mb-1.5">
            <label className="text-xs font-semibold text-slate-500">Chỉ định riêng theo bệnh lý (tuỳ chọn)</label>
            <button onClick={addIndication} className="text-xs font-semibold" style={{ color: "var(--c-primary)" }}>
              + Thêm chỉ định
            </button>
          </div>
          <p className="text-[12px] text-slate-400 mb-2 leading-relaxed">
            Dùng khi thuốc cần liều khác cho một bệnh lý cụ thể (VD: viêm màng não cần liều cao hơn để thấm qua hàng rào
            máu não). Gõ tên bệnh lý có sẵn hoặc một tên mới — nếu tên không khớp bệnh lý nào đang có, app sẽ tự thêm
            bệnh lý đó vào danh mục khi lưu.
          </p>
          <div className="space-y-2.5">
            {indications.map((row) => {
              const trimmedName = row.diseaseName.trim()
              const matched = trimmedName ? diseases.find((d) => d.name.trim().toLowerCase() === trimmedName.toLowerCase()) : undefined
              const isNewDisease = trimmedName.length > 0 && !matched
              const suggestions = diseases.filter(
                (d) => !indications.some((r) => r.key !== row.key && r.diseaseName.trim().toLowerCase() === d.name.trim().toLowerCase()),
              )
              return (
                <div key={row.key} className="p-3 rounded-2xl border" style={{ borderColor: "var(--c-warn-line)", background: "var(--c-warn-soft)" }}>
                  <div className="flex items-center gap-2 mb-2">
                    <div className="flex-1">
                      <label className="text-[12px] text-slate-400 mb-1 block">Tên bệnh lý</label>
                      <input
                        value={row.diseaseName}
                        onChange={(e) => updateIndicationField(row.key, "diseaseName", e.target.value)}
                        placeholder="VD: Viêm màng não vi khuẩn"
                        className="w-full px-3 py-2 rounded-xl text-sm border outline-none"
                        style={fieldStyle}
                      />
                    </div>
                    <button
                      onClick={() => removeIndication(row.key)}
                      className="w-9 h-9 rounded-full flex items-center justify-center flex-none mt-3"
                      style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }}
                      aria-label="Xoá chỉ định"
                    >
                      {icons.x()}
                    </button>
                  </div>

                  {suggestions.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 mb-2">
                      {suggestions.map((d) => (
                        <button
                          key={d.id}
                          onClick={() => pickIndicationDisease(row.key, d.name)}
                          className="px-2.5 py-1 rounded-full text-[12px] font-semibold border transition-colors"
                          style={
                            matched?.id === d.id
                              ? { background: "var(--c-primary)", borderColor: "var(--c-primary)", color: "var(--c-on-bright)" }
                              : { background: "var(--c-surface)", borderColor: "var(--c-warn-line)", color: "var(--c-warn)" }
                          }
                        >
                          {d.name}
                        </button>
                      ))}
                    </div>
                  )}

                  {isNewDisease && (
                    <p className="text-[12px] font-semibold mb-2" style={{ color: "var(--c-warn-icon)" }}>
                      Bệnh lý mới — khi lưu, "{trimmedName}" sẽ được tự thêm vào danh mục bệnh lý.
                    </p>
                  )}

                  <label className="text-[12px] text-slate-400 mb-1 block">Liều chuẩn riêng cho bệnh lý này (tuỳ chọn)</label>
                  <input
                    value={row.standardDose}
                    onChange={(e) => updateIndicationField(row.key, "standardDose", e.target.value)}
                    placeholder="VD: 2 g mỗi 4h — liều cao hơn để thấm qua hàng rào máu não"
                    className="w-full px-3 py-2 rounded-xl text-sm border outline-none mb-2.5"
                    style={fieldStyle}
                  />

                  <div className="flex items-center justify-between mb-1.5">
                    <label className="text-[12px] text-slate-400">Mức liều theo CrCl riêng (tuỳ chọn — bỏ trống để dùng mức liều chung ở trên)</label>
                    <button onClick={() => addIndicationTier(row.key)} className="text-[12px] font-semibold" style={{ color: "var(--c-primary)" }}>
                      + Thêm mức
                    </button>
                  </div>
                  {row.tiers.length > 0 && (
                    <div className="space-y-2 mb-2.5">
                      {row.tiers.map((t, idx) => (
                        <div key={idx} className="p-2.5 rounded-xl border" style={{ borderColor: "var(--c-warn-line)", background: "var(--c-surface)" }}>
                          <div className="flex items-center gap-2 mb-2">
                            <div className="flex-1">
                              {/* min-h-[3em] (issue "CrCl tối thiểu không ngay hàng"): nhãn này dài hơn "Nhãn
                        hiển thị" nên xuống 2 dòng ở cột hẹp trong khi nhãn kia chỉ 1 dòng, đẩy ô nhập
                        bên dưới tụt xuống lệch nhau. Đặt trước chiều cao ĐÚNG 2 dòng (line-height 1.5
                        ở cỡ chữ 10px) trên cả hai nhãn cùng hàng để hai ô nhập luôn ngang hàng. */}
                    <label className="text-[12px] text-slate-400 mb-1 block min-h-[3em]">CrCl tối thiểu (mL/phút)</label>
                              <input
                                value={t.min}
                                onChange={(e) => updateIndicationTier(row.key, idx, "min", normalizeDecimalInput(e.target.value))}
                                inputMode="decimal"
                                placeholder="0"
                                className="w-full px-3 py-2 rounded-xl text-sm border outline-none"
                                style={fieldStyle}
                              />
                            </div>
                            <div className="flex-[2]">
                              <label className="text-[12px] text-slate-400 mb-1 block min-h-[3em]">Nhãn hiển thị</label>
                              <input
                                value={t.label}
                                onChange={(e) => updateIndicationTier(row.key, idx, "label", e.target.value)}
                                placeholder="VD: CrCl ≥ 50"
                                className="w-full px-3 py-2 rounded-xl text-sm border outline-none"
                                style={fieldStyle}
                              />
                            </div>
                            <button
                              onClick={() => removeIndicationTier(row.key, idx)}
                              className="w-9 h-9 rounded-full flex items-center justify-center flex-none mt-3"
                              style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }}
                              aria-label="Xoá mức"
                            >
                              {icons.x()}
                            </button>
                          </div>
                          <label className="text-[12px] text-slate-400 mb-1 block">Liều</label>
                          <input
                            value={t.dose}
                            onChange={(e) => updateIndicationTier(row.key, idx, "dose", e.target.value)}
                            placeholder="VD: 2 g mỗi 4h"
                            className="w-full px-3 py-2 rounded-xl text-sm border outline-none"
                            style={fieldStyle}
                          />
                        </div>
                      ))}
                    </div>
                  )}

                  <label className="text-[12px] text-slate-400 mb-1 block">Ghi chú riêng (tuỳ chọn)</label>
                  <input
                    value={row.note}
                    onChange={(e) => updateIndicationField(row.key, "note", e.target.value)}
                    className="w-full px-3 py-2 rounded-xl text-sm border outline-none"
                    style={fieldStyle}
                  />
                </div>
              )
            })}
            {indications.length === 0 && (
              <p className="text-[12px] text-slate-400">Chưa có chỉ định riêng nào — bấm "+ Thêm chỉ định" nếu cần.</p>
            )}
          </div>
        </div>

        <div className="pt-2 border-t" style={{ borderColor: "var(--c-line-soft)" }}>
          <p className="text-xs font-semibold text-slate-500 mt-3 mb-1.5">Liều khi lọc máu / CRRT (tuỳ chọn)</p>
          <p className="text-[12px] text-slate-400 leading-relaxed mb-2">
            Bỏ trống mục nào thì với bệnh nhân đang dùng phương thức đó, app sẽ nói rõ là chưa có dữ liệu — không bao giờ tự suy ra từ bậc CrCl.
          </p>
          <div className="space-y-2">
            <div>
              <label className="text-[12px] text-slate-400 mb-1 block">Chạy thận chu kỳ (IHD)</label>
              <input value={rrtIhd} onChange={(e) => setRrtIhd(e.target.value)} placeholder="VD: 500 mg sau mỗi buổi lọc" className={fieldClass} style={fieldStyle} />
            </div>
            <div>
              <label className="text-[12px] text-slate-400 mb-1 block">Lọc máu liên tục (CRRT) — ghi kèm tốc độ dịch thải của khuyến cáo</label>
              <input value={rrtCrrt} onChange={(e) => setRrtCrrt(e.target.value)} placeholder="VD: 1 g mỗi 8h khi Qeff ≥ 2 L/giờ" className={fieldClass} style={fieldStyle} />
            </div>
            <div>
              <label className="text-[12px] text-slate-400 mb-1 block">Lọc kéo dài chậm (SLED)</label>
              <input value={rrtSled} onChange={(e) => setRrtSled(e.target.value)} className={fieldClass} style={fieldStyle} />
            </div>
            <div>
              <label className="text-[12px] text-slate-400 mb-1 block">Lọc màng bụng (PD)</label>
              <input value={rrtPd} onChange={(e) => setRrtPd(e.target.value)} className={fieldClass} style={fieldStyle} />
            </div>
            <div>
              <label className="text-[12px] text-slate-400 mb-1 block">Ghi chú chung khi lọc máu</label>
              <textarea value={rrtNote} onChange={(e) => setRrtNote(e.target.value)} rows={2} placeholder="VD: đo nồng độ đáy trước buổi lọc thứ ba" className={fieldClass} style={fieldStyle} />
            </div>
            <div>
              <label className="text-[12px] text-slate-400 mb-1 block">Nguồn của liều lọc máu</label>
              <input value={rrtSource} onChange={(e) => setRrtSource(e.target.value)} placeholder="VD: Phác đồ lọc máu khoa HSTC 2026" className={fieldClass} style={fieldStyle} />
            </div>
          </div>
        </div>

        <div className="pt-2 border-t" style={{ borderColor: "var(--c-line-soft)" }}>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block mt-3">Nguồn dữ liệu (tuỳ chọn)</label>
          <input value={source} onChange={(e) => setSource(e.target.value)} placeholder="VD: Phác đồ ICU BV X 2026 / Sanford Guide" className={fieldClass} style={fieldStyle} />
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block mt-3">Rà soát lần cuối (YYYY-MM)</label>
          <input value={reviewedOn} onChange={(e) => setReviewedOn(e.target.value)} placeholder="VD: 2026-07" className={fieldClass} style={fieldStyle} />
          <p className="text-[12px] text-slate-400 leading-relaxed mt-1.5">
            Bỏ trống thì thẻ thuốc sẽ hiện rõ "chưa ghi nguồn · chưa rà soát".
          </p>
        </div>

        <p className="text-xs text-slate-400 leading-relaxed">
          Nội dung sửa được lưu ngay trên máy này, không đổi dữ liệu gốc trong app.
        </p>
      </div>

      <div className="flex-none px-6 pt-3 border-t" style={{ borderColor: "var(--c-line)", paddingBottom: "var(--nav-pad-bottom)" }}>
        <button onClick={handleSave} disabled={!canSave} className="w-full py-3.5 rounded-2xl font-semibold text-sm" style={{ background: canSave ? "var(--c-primary)" : "var(--c-muted)", color: "var(--c-on-bright)" }}>
          Lưu thay đổi
        </button>
      </div>
    </div>
  )
}

// Tiêu đề màn "thêm thuốc" — dựng từ chính nhãn của nhóm (data/categories.ts) thay vì một bảng
// chép tay song song, vốn là chỗ dễ quên nhất khi thêm nhóm mới.
function addInfusionTitle(category: InfusionCategory): string {
  return `Thêm ${infusionCategory(category).categoryLabel}`
}

// Bản nháp của một liều nạp trong lúc nhập: mọi ô số giữ ở dạng chuỗi để gõ dở dang ("0,", "1.")
// không bị nhảy về NaN giữa chừng, rồi mới đổi sang BolusDose khi lưu.
interface BolusDraft {
  label: string
  unit: string
  mode: "perKg" | "fixed"
  low: string
  high: string
  maxSingle: string
  over: string
  note: string
}

function emptyBolusDraft(): BolusDraft {
  return { label: "", unit: "mg", mode: "perKg", low: "", high: "", maxSingle: "", over: "", note: "" }
}

function bolusToDraft(b: BolusDose): BolusDraft {
  const perKg = b.perKgLow != null
  return {
    label: b.label,
    unit: b.unit,
    mode: perKg ? "perKg" : "fixed",
    low: String((perKg ? b.perKgLow : b.fixedLow) ?? ""),
    high: b.perKgHigh != null || b.fixedHigh != null ? String((perKg ? b.perKgHigh : b.fixedHigh) ?? "") : "",
    maxSingle: b.maxSingle != null ? String(b.maxSingle) : "",
    over: b.over ?? "",
    note: b.note ?? "",
  }
}

// null nếu bản nháp chưa đủ dùng (thiếu tên hoặc thiếu con số liều) — mục dở dang thì bỏ qua khi
// lưu chứ không sinh ra một liều nạp rỗng nằm trong thẻ thuốc.
function draftToBolus(d: BolusDraft): BolusDose | null {
  const label = d.label.trim()
  const low = parseFloat(d.low)
  if (!label || isNaN(low)) return null
  const high = parseFloat(d.high)
  const maxSingle = parseFloat(d.maxSingle)
  return {
    label,
    unit: d.unit.trim() || "mg",
    ...(d.mode === "perKg"
      ? { perKgLow: low, ...(isNaN(high) ? {} : { perKgHigh: high }) }
      : { fixedLow: low, ...(isNaN(high) ? {} : { fixedHigh: high }) }),
    ...(isNaN(maxSingle) ? {} : { maxSingle }),
    ...(d.over.trim() ? { over: d.over.trim() } : {}),
    ...(d.note.trim() ? { note: d.note.trim() } : {}),
  }
}

// Khối sửa liều nạp/bolus dùng chung cho AddInfusionScreen, AddAntibioticScreen và
// EditAntibioticScreen — trước đây chỉ AddInfusionScreen có, khiến kháng sinh cần liều nạp (vd
// Vancomycin) không có chỗ khai báo.
function BolusEditorField({ boluses, setBoluses }: { boluses: BolusDraft[]; setBoluses: (fn: (prev: BolusDraft[]) => BolusDraft[]) => void }) {
  const fieldClass = "w-full px-4 py-3 rounded-2xl text-sm border outline-none"
  const fieldStyle = { borderColor: "var(--c-line)", background: "var(--c-surface)" }
  return (
    <div className="pt-2 border-t" style={{ borderColor: "var(--c-line-soft)" }}>
      <div className="flex items-center justify-between mb-1.5 mt-3">
        <label className="text-xs font-semibold text-slate-500">Liều nạp / bolus (tuỳ chọn)</label>
        <button onClick={() => setBoluses((prev) => [...prev, emptyBolusDraft()])} className="text-xs font-semibold" style={{ color: "var(--c-primary)" }}>
          + Thêm liều nạp
        </button>
      </div>
      <div className="space-y-2">
        {boluses.map((b, idx) => {
          const set = (patch: Partial<BolusDraft>) => setBoluses((prev) => prev.map((x, i) => (i === idx ? { ...x, ...patch } : x)))
          return (
            <div key={idx} className="p-3 rounded-2xl border" style={{ borderColor: "var(--c-line)" }}>
              <div className="flex items-center gap-2 mb-2">
                <input
                  value={b.label}
                  onChange={(e) => set({ label: e.target.value })}
                  placeholder="VD: Liều nạp trước khi vào duy trì"
                  className="flex-1 px-3 py-2 rounded-xl text-sm border outline-none"
                  style={fieldStyle}
                />
                <button
                  onClick={() => setBoluses((prev) => prev.filter((_, i) => i !== idx))}
                  className="w-9 h-9 rounded-full flex items-center justify-center flex-none"
                  style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }}
                  aria-label="Xoá liều nạp"
                >
                  {icons.x()}
                </button>
              </div>
              <div className="flex gap-2 mb-2">
                {([
                  { v: "perKg" as const, label: "Theo cân nặng (/kg)" },
                  { v: "fixed" as const, label: "Liều cố định" },
                ]).map((opt) => (
                  <button
                    key={opt.v}
                    onClick={() => set({ mode: opt.v })}
                    className="flex-1 py-2 rounded-xl text-xs font-semibold border"
                    style={
                      b.mode === opt.v
                        ? { background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }
                        : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                    }
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
              <div className="grid grid-cols-3 gap-2">
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Liều{b.mode === "perKg" ? "/kg" : ""}</label>
                  <input value={b.low} onChange={(e) => set({ low: normalizeDecimalInput(e.target.value) })} inputMode="decimal" placeholder="1" className={fieldClass} style={fieldStyle} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Đến (tuỳ chọn)</label>
                  <input value={b.high} onChange={(e) => set({ high: normalizeDecimalInput(e.target.value) })} inputMode="decimal" placeholder="1,5" className={fieldClass} style={fieldStyle} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Đơn vị</label>
                  <input value={b.unit} onChange={(e) => set({ unit: e.target.value })} placeholder="mg" className={fieldClass} style={fieldStyle} />
                </div>
              </div>
              {b.mode === "perKg" && (
                <div className="mt-2">
                  <label className="text-[12px] text-slate-400 mb-1 block">Không vượt quá 1 lần (tuỳ chọn)</label>
                  <input value={b.maxSingle} onChange={(e) => set({ maxSingle: normalizeDecimalInput(e.target.value) })} inputMode="decimal" placeholder="VD: 100" className={fieldClass} style={fieldStyle} />
                </div>
              )}
              <div className="mt-2">
                {/* Thời gian tiêm là thứ hay bị bỏ sót và là nguyên nhân tụt huyết áp/phản ứng truyền
                    nhanh khi nạp nhanh. */}
                <label className="text-[12px] text-slate-400 mb-1 block">Cách dùng — tiêm/truyền trong bao lâu</label>
                <input value={b.over} onChange={(e) => set({ over: e.target.value })} placeholder="VD: truyền tĩnh mạch trong 60 phút" className={fieldClass} style={fieldStyle} />
              </div>
              <div className="mt-2">
                <label className="text-[12px] text-slate-400 mb-1 block">Ghi chú (tuỳ chọn)</label>
                <input value={b.note} onChange={(e) => set({ note: e.target.value })} className={fieldClass} style={fieldStyle} />
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

function AddInfusionScreen({
  category,
  initial,
  diseases,
  onSave,
  onBack,
}: {
  category: InfusionCategory
  initial?: InfusionDrug
  diseases: DiseaseEntry[]
  onSave: (d: InfusionDrug) => void
  onBack: () => void
}) {
  const isEdit = Boolean(initial)
  const [name, setName] = useState(initial?.name ?? "")
  const [route, setRoute] = useState(initial?.route ?? "")
  const [preparation, setPreparation] = useState(initial?.preparation ?? "")
  const [doseRange, setDoseRange] = useState(initial?.doseRange ?? "")
  const [note, setNote] = useState(initial?.note ?? "")
  // Bệnh lý áp dụng — giống hệt AddAntibioticScreen: chỉ TAG thuốc với bệnh lý để bước "Chỉ định"
  // nhận diện được, không sửa liều riêng theo từng bệnh lý ở màn này (đó là việc của dữ liệu dựng
  // sẵn/EditAntibioticScreen bên kháng sinh). Giữ lại đúng chỉ định đã có (kể cả liều/bolus riêng
  // của nó) khi sửa một thuốc đã có `indications` — chỉ thêm bớt theo đúng ô chọn, không xoá mất
  // override đã khai báo sẵn (vd Adrenaline: liều ngừng tim/phản vệ riêng).
  const [diseaseIds, setDiseaseIds] = useState<string[]>(() => (initial?.indications ?? []).map((i) => i.diseaseId))
  function toggleDisease(id: string) {
    setDiseaseIds((prev) => (prev.includes(id) ? prev.filter((d) => d !== id) : [...prev, id]))
  }
  const [warnings, setWarnings] = useState<{ text: string; severity: "cao" | "trung bình" }[]>(
    (initial?.warnings ?? []).map((w) => ({ text: w.text, severity: w.severity })),
  )
  // Liều nạp / bolus. Trước đây chỉ dữ liệu dựng sẵn mới có được mục này, nên một thuốc tự nhập
  // kiểu esmolol hay magie — đúng những thuốc luôn phải nạp trước rồi mới duy trì — không có chỗ
  // nào ghi liều nạp ngoài ô "Cách pha" dạng câu chữ, và không được tính giúp theo cân nặng.
  const [boluses, setBoluses] = useState<BolusDraft[]>(() => (initial?.boluses ?? []).map(bolusToDraft))
  const [addCalc, setAddCalc] = useState(Boolean(initial?.calc))
  const [weightBased, setWeightBased] = useState(initial?.calc?.weightBased ?? true)
  const [doseUnit, setDoseUnit] = useState(initial?.calc?.doseUnit ?? "")
  const [doseMin, setDoseMin] = useState(initial?.calc ? String(initial.calc.doseMin) : "")
  const [doseMax, setDoseMax] = useState(initial?.calc ? String(initial.calc.doseMax) : "")
  const [concUnit, setConcUnit] = useState(initial?.calc?.concUnit ?? "")
  const [concDefault, setConcDefault] = useState(initial?.calc?.concDefault != null ? String(initial.calc.concDefault) : "")
  // Công thức pha ở dạng số — để bảng pha thuốc tính được chiều "mấy ống, bao nhiêu mL → nồng độ".
  const [mixVialAmount, setMixVialAmount] = useState(initial?.calc?.mix ? String(initial.calc.mix.vialAmount) : "")
  const [mixVialUnit, setMixVialUnit] = useState(initial?.calc?.mix?.vialUnit ?? "")
  const [mixVials, setMixVials] = useState(initial?.calc?.mix?.vials != null ? String(initial.calc.mix.vials) : "1")
  const [mixVolume, setMixVolume] = useState(initial?.calc?.mix ? String(initial.calc.mix.volumeMl) : "")
  // Ống dung dịch hay lọ bột — thiếu chỗ khai báo này thì bảng pha không nói được câu "rút mấy mL
  // thuốc, thêm mấy mL dung môi" cho thuốc tự nhập.
  const [mixForm, setMixForm] = useState<VialForm>(initial?.calc?.mix?.vialForm ?? "solution")
  const [mixVialVolume, setMixVialVolume] = useState(initial?.calc?.mix?.vialVolumeMl != null ? String(initial.calc.mix.vialVolumeMl) : "")
  const [mixReconstitute, setMixReconstitute] = useState(initial?.calc?.mix?.reconstituteMl != null ? String(initial.calc.mix.reconstituteMl) : "")
  const [mixDisplacement, setMixDisplacement] = useState(initial?.calc?.mix?.displacementMl != null ? String(initial.calc.mix.displacementMl) : "")
  // Nguồn và ngày rà soát: bỏ trống thì thẻ thuốc sẽ hiện rõ "chưa ghi nguồn · chưa rà soát".
  const [source, setSource] = useState(initial?.source ?? "")
  const [reviewedOn, setReviewedOn] = useState(initial?.reviewedOn ?? "")

  // Kiểm tra ngay lúc nhập: nếu hai đơn vị không đọc được hoặc không quy đổi được cho nhau thì máy
  // tính sẽ không ra kết quả — chặn lưu ở đây tốt hơn là để người dùng phát hiện lúc đang cấp cứu.
  const unitProblem = useMemo(() => {
    if (!addCalc) return null
    if (!doseUnit.trim() || !concUnit.trim()) return null
    const u = parseDoseUnit(doseUnit.trim())
    if (!u) return `Đơn vị liều "${doseUnit.trim()}" không đọc được — phải có dạng <đơn vị>/phút, <đơn vị>/giờ, hoặc kèm /kg.`
    if (!concUnit.trim().includes("/")) return `Đơn vị nồng độ "${concUnit.trim()}" phải có dạng <đơn vị>/mL.`
    if (massFactor(u.mass, massOfConcUnit(concUnit.trim())) == null) {
      return `Không quy đổi được "${u.mass}" của liều sang "${massOfConcUnit(concUnit.trim())}" của nồng độ — hai đơn vị phải cùng họ (mcg/mg/g) hoặc trùng nhau.`
    }
    return null
  }, [addCalc, doseUnit, concUnit])

  // Các ô số của công thức pha/máy tính liều dùng chuỗi tự do (chỉ đổi dấu phẩy → chấm qua
  // normalizeDecimalInput), không ép kiểu số như input[type=number] — gõ nhầm "5oo" (chữ O) hay dán
  // nhầm "250mg" vào ô chỉ-nên-có-số vẫn được chấp nhận, và handleSave từng gọi thẳng parseFloat():
  // parseFloat("250mg") = 250 (coi như hợp lệ, im lặng cắt "mg") nhưng parseFloat("mg250") = NaN —
  // NaN đó lọt vào cấu hình máy tính liều của một thuốc tự nhập mà không ai biết cho tới lúc dùng
  // thật. Áp lại đúng `hasInvalidNumericInput` đã dùng cho khung Bệnh nhân (weight/height/age/scr)
  // thay vì để mỗi màn tự có tiêu chuẩn parse riêng.
  const numericFields = [doseMin, doseMax, concDefault, mixVialAmount, mixVials, mixVolume, mixVialVolume, mixReconstitute, mixDisplacement]
  const numericProblem = addCalc && numericFields.some(hasInvalidNumericInput)
    ? "Một hoặc nhiều ô số liệu (liều/nồng độ/công thức pha) có ký tự không phải số — sửa lại trước khi lưu, viền đỏ đánh dấu đúng ô."
    : null

  const calcValid = doseUnit.trim() && concUnit.trim() && doseMin.trim() && doseMax.trim() && !unitProblem && !numericProblem
  // Viền đỏ đúng ô số bị gõ nhầm, không chỉ một dòng cảnh báo chung — 9 ô cùng dạng đứng cạnh nhau,
  // nếu không chỉ thẳng ô nào thì người nhập phải dò lại toàn bộ để tìm chỗ sai.
  const numFieldStyle = (v: string) => (hasInvalidNumericInput(v) ? { ...fieldStyle, borderColor: "var(--c-danger)" } : fieldStyle)
  const canSave = name.trim().length > 0 && route.trim().length > 0 && doseRange.trim().length > 0 && (!addCalc || Boolean(calcValid))

  function updateWarningText(idx: number, value: string) {
    setWarnings((prev) => prev.map((w, i) => (i === idx ? { ...w, text: value } : w)))
  }
  function updateWarningSeverity(idx: number, severity: "cao" | "trung bình") {
    setWarnings((prev) => prev.map((w, i) => (i === idx ? { ...w, severity } : w)))
  }
  function addWarning() {
    setWarnings((prev) => [...prev, { text: "", severity: "trung bình" }])
  }
  function removeWarning(idx: number) {
    setWarnings((prev) => prev.filter((_, i) => i !== idx))
  }

  function handleSave() {
    if (!canSave) return
    const calc: InfusionCalcConfig | undefined = addCalc
      ? {
          weightBased,
          doseUnit: doseUnit.trim(),
          doseMin: parseFloat(doseMin),
          doseMax: parseFloat(doseMax),
          concUnit: concUnit.trim(),
          concDefault: concDefault.trim() ? parseFloat(concDefault) : undefined,
          // doseTimeBasis suy ra từ chính đơn vị liều (".../phút" hay ".../giờ") nên không còn ô
          // nhập riêng; vẫn ghi vào dữ liệu để file sao lưu cũ/mới cùng hình dạng.
          doseTimeBasis: parseDoseUnit(doseUnit.trim())?.per ?? "phút",
          mix:
            mixVialAmount.trim() && mixVolume.trim()
              ? {
                  // Giữ lại các trường không có ô nhập ở màn này (dung môi, hạn dùng sau pha, ngưỡng
                  // nồng độ...) khi SỬA một thuốc dựng sẵn — trước đây sửa hàm lượng ống một cái là
                  // xoá sạch phần dữ liệu đó mà không báo gì.
                  ...(initial?.calc?.mix ?? {}),
                  vialAmount: parseFloat(mixVialAmount),
                  vialUnit: mixVialUnit.trim() || massOfConcUnit(concUnit.trim()),
                  vials: mixVials.trim() ? parseFloat(mixVials) : 1,
                  volumeMl: parseFloat(mixVolume),
                  vialForm: mixForm,
                  vialVolumeMl: mixForm === "solution" && mixVialVolume.trim() ? parseFloat(mixVialVolume) : undefined,
                  reconstituteMl: mixForm === "powder" && mixReconstitute.trim() ? parseFloat(mixReconstitute) : undefined,
                  displacementMl: mixForm === "powder" && mixDisplacement.trim() ? parseFloat(mixDisplacement) : undefined,
                }
              : undefined,
        }
      : undefined
    const cleanedWarnings: AntibioticWarning[] = warnings.filter((w) => w.text.trim()).map((w) => ({ text: w.text.trim(), severity: w.severity }))
    const cleanedBoluses = boluses.map(draftToBolus).filter((b): b is BolusDose => b != null)
    // Giữ nguyên chỉ định đã có (kể cả liều/bolus riêng của nó, vd Adrenaline) nếu vẫn còn được
    // chọn; chỉ định MỚI bấm chọn thì thêm bản trống (chưa có liều riêng, dùng liều chung của thuốc).
    const indications: InfusionIndicationDose[] | undefined =
      diseaseIds.length > 0
        ? diseaseIds.map((diseaseId) => initial?.indications?.find((i) => i.diseaseId === diseaseId) ?? { diseaseId })
        : undefined
    const savedDrug: InfusionDrug = {
      ...(initial ?? {}),
      id: initial ? initial.id : `custom-${category}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      name: name.trim(),
      route: route.trim(),
      preparation: preparation.trim() || "Pha theo nồng độ chuẩn đang dùng.",
      doseRange: doseRange.trim(),
      note: note.trim() || undefined,
      warnings: cleanedWarnings.length > 0 ? cleanedWarnings : undefined,
      boluses: cleanedBoluses.length > 0 ? cleanedBoluses : undefined,
      indications,
      calc,
      source: source.trim() || undefined,
      reviewedOn: reviewedOn.trim() || undefined,
      isCustom: true,
    }
    onSave(savedDrug)
  }

  const fieldClass = "w-full px-4 py-3 rounded-2xl text-sm border outline-none"
  const fieldStyle = { borderColor: "var(--c-line)", background: "var(--c-surface)" }

  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        <span className="text-sm font-semibold text-slate-900">
          {isEdit ? `Sửa: ${initial?.name}` : addInfusionTitle(category)}
        </span>
        <span className="w-10" />
      </div>

      <div className="scroll-ios flex-1 px-6 pt-6 pb-8 space-y-4">
        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Tên thuốc</label>
          <input value={name} onChange={(e) => setName(e.target.value)} placeholder="VD: Isoprenaline" className={fieldClass} style={fieldStyle} />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Đường dùng</label>
          <input
            value={route}
            onChange={(e) => setRoute(e.target.value)}
            placeholder="VD: Truyền tĩnh mạch qua bơm tiêm điện (BTĐ)"
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Bệnh lý áp dụng (tuỳ chọn)</label>
          <div className="flex flex-wrap gap-2">
            {diseases.map((d) => (
              <button
                key={d.id}
                onClick={() => toggleDisease(d.id)}
                className="px-3.5 py-2 rounded-full text-xs font-semibold border transition-colors"
                style={
                  diseaseIds.includes(d.id)
                    ? { background: "var(--c-primary-soft)", borderColor: "var(--c-primary)", color: "var(--c-primary)" }
                    : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                }
              >
                {d.name}
              </button>
            ))}
          </div>
          <p className="text-[12px] text-slate-400 mt-1.5">
            Chọn thì màn chọn thuốc hiện thêm bước "Chỉ định" cho thuốc này. Không chọn = thuốc dùng chung, không gắn với bệnh lý cụ thể nào.
          </p>
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Cách pha (tuỳ chọn)</label>
          <textarea
            value={preparation}
            onChange={(e) => setPreparation(e.target.value)}
            placeholder="VD: Pha 1 ống với Natri Clorid 0,9% vừa đủ 50 mL..."
            rows={3}
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Khoảng liều (mô tả)</label>
          <input value={doseRange} onChange={(e) => setDoseRange(e.target.value)} placeholder="VD: 0,05–0,5 mcg/kg/phút, chỉnh theo đáp ứng" className={fieldClass} style={fieldStyle} />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Ghi chú (tuỳ chọn)</label>
          <input value={note} onChange={(e) => setNote(e.target.value)} className={fieldClass} style={fieldStyle} />
        </div>

        <div>
          <div className="flex items-center justify-between mb-1.5">
            <label className="text-xs font-semibold text-slate-500">Cảnh báo (tuỳ chọn)</label>
            <button onClick={addWarning} className="text-xs font-semibold" style={{ color: "var(--c-primary)" }}>
              + Thêm cảnh báo
            </button>
          </div>
          <div className="space-y-2">
            {warnings.map((w, idx) => (
              <div key={idx} className="p-3 rounded-2xl border" style={{ borderColor: "var(--c-line)" }}>
                <div className="flex items-center gap-2 mb-2">
                  <input
                    value={w.text}
                    onChange={(e) => updateWarningText(idx, e.target.value)}
                    className="flex-1 px-3 py-2 rounded-xl text-sm border outline-none"
                    style={fieldStyle}
                  />
                  <button onClick={() => removeWarning(idx)} className="w-9 h-9 rounded-full flex items-center justify-center flex-none" style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }} aria-label="Xoá cảnh báo">
                    {icons.x()}
                  </button>
                </div>
                <div className="flex gap-2">
                  {(["trung bình", "cao"] as const).map((s) => (
                    <button
                      key={s}
                      onClick={() => updateWarningSeverity(idx, s)}
                      className="flex-1 py-2 rounded-xl text-xs font-semibold border"
                      style={
                        w.severity === s
                          ? { background: s === "cao" ? "var(--c-danger-icon)" : "var(--c-warn-icon)", borderColor: "transparent", color: "var(--c-on-bright)" }
                          : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                      }
                    >
                      Mức độ: {s}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Liều nạp / bolus — amiodarone, magie, lidocaine, esmolol đều phải nạp trước rồi mới duy
            trì, và nhân nhẩm mg/kg lúc cấp cứu chính là chỗ dễ sai nhất. */}
        <BolusEditorField boluses={boluses} setBoluses={setBoluses} />

        <div className="pt-2 border-t" style={{ borderColor: "var(--c-line-soft)" }}>
          <button onClick={() => setAddCalc((v) => !v)} className="flex items-center gap-2 mt-3 mb-1">
            <span
              className="w-9 h-5 rounded-full relative flex-none transition-colors"
              style={{ background: addCalc ? "var(--c-primary)" : "var(--c-line)" }}
            >
              {/* `left-0` là bắt buộc, không phải cho đẹp: thiếu nó thì vị trí tĩnh của nút tròn được
                  tính theo `text-align: center` mà thẻ <button> áp cho cả cụm, tức là lệch sẵn 18px
                  vào giữa track. Cộng thêm translateX(18px) lúc bật, nút tròn văng hẳn ra ngoài
                  track và đè lên dòng chữ bên cạnh. */}
              <span
                className="absolute left-0 top-0.5 w-4 h-4 rounded-full bg-white transition-transform"
                style={{ transform: addCalc ? "translateX(18px)" : "translateX(2px)" }}
              />
            </span>
            <span className="text-xs font-semibold text-slate-700">Thêm máy tính tốc độ truyền (mL/giờ)</span>
          </button>

          {addCalc && (
            <div className="space-y-2.5 mt-3 fade-in">
              <div className="flex gap-2">
                {(
                  [
                    { v: true, label: "Tính theo cân nặng" },
                    { v: false, label: "Liều cố định (không theo cân nặng)" },
                  ]
                ).map((opt) => (
                  <button
                    key={String(opt.v)}
                    onClick={() => setWeightBased(opt.v)}
                    className="flex-1 py-2 rounded-xl text-xs font-semibold border"
                    style={
                      weightBased === opt.v
                        ? { background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }
                        : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                    }
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
              {/* Chọn nhanh đơn vị liều. Máy tính đọc trực tiếp chuỗi này để biết đơn vị lượng
                  thuốc, có theo cân nặng hay không, và tính theo phút hay giờ — nên gõ tay dễ sai
                  (vd "mcg/kg/min" tiếng Anh sẽ không đọc được). Vẫn cho sửa tay bên dưới cho các
                  đơn vị lạ, kèm kiểm tra định dạng ngay tại chỗ. */}
              <div>
                <label className="text-[12px] text-slate-400 mb-1.5 block">Đơn vị liều</label>
                <div className="flex flex-wrap gap-1.5 mb-2">
                  {COMMON_DOSE_UNITS.map((u) => (
                    <button
                      key={u}
                      onClick={() => {
                        setDoseUnit(u)
                        setWeightBased(u.includes("/kg"))
                      }}
                      className="px-2.5 py-1.5 rounded-full text-[12px] font-semibold border whitespace-nowrap"
                      style={
                        doseUnit === u
                          ? { background: "var(--c-primary)", borderColor: "var(--c-primary)", color: "var(--c-on-bright)" }
                          : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                      }
                    >
                      {u}
                    </button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-2 gap-2.5">
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Đơn vị liều (sửa tay nếu cần)</label>
                  <input value={doseUnit} onChange={(e) => setDoseUnit(e.target.value)} placeholder="mcg/kg/phút" className={fieldClass} style={fieldStyle} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Đơn vị nồng độ</label>
                  <input value={concUnit} onChange={(e) => setConcUnit(e.target.value)} placeholder="mg/mL" className={fieldClass} style={fieldStyle} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Liều tối thiểu gợi ý</label>
                  <input value={doseMin} onChange={(e) => setDoseMin(normalizeDecimalInput(e.target.value))} inputMode="decimal" className={fieldClass} style={numFieldStyle(doseMin)} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Liều tối đa gợi ý</label>
                  <input value={doseMax} onChange={(e) => setDoseMax(normalizeDecimalInput(e.target.value))} inputMode="decimal" className={fieldClass} style={numFieldStyle(doseMax)} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Nồng độ pha mặc định (tuỳ chọn)</label>
                  <input value={concDefault} onChange={(e) => setConcDefault(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="Để trống nếu tuỳ khoa" className={fieldClass} style={numFieldStyle(concDefault)} />
                </div>
              </div>

              {/* Công thức pha dạng số — có phần này thì bảng "ống ⇄ nồng độ" mới tính giúp được */}
              <p className="text-[12px] font-semibold text-slate-500 mt-1">Công thức pha chuẩn (tuỳ chọn)</p>
              <div className="flex gap-2">
                {([
                  { v: "solution" as VialForm, label: "Ống dung dịch" },
                  { v: "powder" as VialForm, label: "Lọ bột" },
                ]).map((opt) => (
                  <button
                    key={opt.v}
                    onClick={() => setMixForm(opt.v)}
                    className="flex-1 py-2 rounded-xl text-xs font-semibold border"
                    style={
                      mixForm === opt.v
                        ? { background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }
                        : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                    }
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-2.5">
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Hàm lượng 1 ống/lọ</label>
                  <input value={mixVialAmount} onChange={(e) => setMixVialAmount(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 250" className={fieldClass} style={numFieldStyle(mixVialAmount)} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Đơn vị của ống</label>
                  <input value={mixVialUnit} onChange={(e) => setMixVialUnit(e.target.value)} placeholder="mg" className={fieldClass} style={fieldStyle} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Số ống của công thức chuẩn</label>
                  <input value={mixVials} onChange={(e) => setMixVials(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="1" className={fieldClass} style={numFieldStyle(mixVials)} />
                </div>
                <div>
                  <label className="text-[12px] text-slate-400 mb-1 block">Pha vừa đủ (mL)</label>
                  <input value={mixVolume} onChange={(e) => setMixVolume(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 50" className={fieldClass} style={numFieldStyle(mixVolume)} />
                </div>
                {mixForm === "solution" && (
                  <div>
                    <label className="text-[12px] text-slate-400 mb-1 block">Thể tích 1 ống (mL)</label>
                    <input value={mixVialVolume} onChange={(e) => setMixVialVolume(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 20" className={fieldClass} style={numFieldStyle(mixVialVolume)} />
                  </div>
                )}
              </div>
              {/* "Thể tích bột tăng sau pha" dài hơn hẳn "Pha ban đầu với" — ghép chung một hàng 2
                  cột thì nhãn dài xuống 2 dòng còn nhãn ngắn chỉ 1 dòng, đẩy lệch ô nhập. Mỗi ô một
                  hàng riêng, rộng hết cỡ, để nhãn dài nào cũng chỉ cần 1 dòng. */}
              {mixForm === "powder" && (
                <div className="space-y-2.5">
                  <div>
                    <label className="text-[12px] text-slate-400 mb-1 block">Pha ban đầu với (mL/lọ)</label>
                    <input value={mixReconstitute} onChange={(e) => setMixReconstitute(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 10" className={fieldClass} style={numFieldStyle(mixReconstitute)} />
                  </div>
                  <div>
                    <label className="text-[12px] text-slate-400 mb-1 block">Thể tích bột tăng sau pha (mL/lọ)</label>
                    <input value={mixDisplacement} onChange={(e) => setMixDisplacement(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 0,7" className={fieldClass} style={numFieldStyle(mixDisplacement)} />
                  </div>
                </div>
              )}

              {numericProblem && (
                <p className="text-[12px] font-semibold leading-relaxed" style={{ color: "var(--c-danger-icon)" }}>
                  {numericProblem}
                </p>
              )}
              {unitProblem ? (
                <p className="text-[12px] leading-relaxed" style={{ color: "var(--c-danger-icon)" }}>
                  {unitProblem}
                </p>
              ) : (
                <p className="text-[12px] text-slate-400 leading-relaxed">
                  Đơn vị liều phải kết thúc bằng <b>/phút</b> hoặc <b>/giờ</b>, thêm <b>/kg</b> nếu tính theo cân nặng. Đơn vị nồng độ dạng <b>&lt;đơn vị&gt;/mL</b>. Hệ số quy đổi không cần khai báo nữa — máy tính tự suy ra từ hai đơn vị này.
                </p>
              )}
            </div>
          )}
        </div>

        <div className="pt-2 border-t" style={{ borderColor: "var(--c-line-soft)" }}>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block mt-3">Nguồn dữ liệu (tuỳ chọn)</label>
          <input value={source} onChange={(e) => setSource(e.target.value)} placeholder="VD: Phác đồ ICU BV X 2026 / Sanford Guide / tờ HDSD" className={fieldClass} style={fieldStyle} />
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block mt-3">Rà soát lần cuối (YYYY-MM)</label>
          <input value={reviewedOn} onChange={(e) => setReviewedOn(e.target.value)} placeholder="VD: 2026-07" className={fieldClass} style={fieldStyle} />
          <p className="text-[12px] text-slate-400 leading-relaxed mt-1.5">
            Bỏ trống thì thẻ thuốc sẽ hiện rõ "chưa ghi nguồn · chưa rà soát" — để sau này biết mục nào còn phải kiểm chứng lại.
          </p>
        </div>

        <p className="text-xs text-slate-400 leading-relaxed">
          {isEdit
            ? "Nội dung sửa được lưu ngay trên máy này, không đổi dữ liệu gốc trong app."
            : "Mục tự nhập được lưu trên máy (trình duyệt của bạn) nên vẫn còn sau khi tắt/mở lại app."}
        </p>
      </div>

      <div className="flex-none px-6 pt-3 border-t" style={{ borderColor: "var(--c-line)", paddingBottom: "var(--nav-pad-bottom)" }}>
        <button
          onClick={handleSave}
          disabled={!canSave}
          className="w-full py-3.5 rounded-2xl font-semibold text-sm"
          style={{ background: canSave ? "var(--c-primary)" : "var(--c-muted)", color: "var(--c-on-bright)" }}
        >
          {isEdit ? "Lưu thay đổi" : "Lưu thuốc"}
        </button>
      </div>
    </div>
  )
}

// Một dòng dữ liệu trong màn "Đồng bộ dữ liệu": vừa dùng để hiển thị ô thống kê + hộp chọn xuất,
// vừa dùng để so khớp id lúc xem trước file nhập (`incomingOf` tự tra đúng nhánh của mình trong dữ
// liệu đã phân tích từ file — nhóm thuốc truyền tra theo `InfusionCategory.id`, còn khoá lưu trong
// JSON của file lại là `backupKey`, hai tên khác nhau nên phải tách riêng thay vì dùng chung `key`).
type SyncCategoryRow = {
  key: string
  label: string
  current: { id: string }[]
  incomingOf: (d: ImportPayload) => { id: string }[]
}

type ImportPayload = {
  articles: Article[]
  antibiotics: Antibiotic[]
  diseases: DiseaseEntry[]
  infusions: Record<InfusionCategory, InfusionDrug[]>
  ecgLessons: EcgLesson[]
  flashcards: FlashCard[]
  mindmapBoards: { board: MindBoard; mindmap: MindmapData }[]
  wardRecipes: WardRecipe[]
}

// Snapshot đủ để hoàn tác một lần nhập file — CHỈ gồm các bảng gộp theo id (nơi nhập nhầm file cũ
// thật sự làm mất nội dung vừa sửa, vì mục trùng id bị THAY THẾ toàn bộ). Sơ đồ tư duy không nằm
// trong snapshot: nó được gộp theo node/cạnh (`mergeMindmaps`), không thay thế toàn bộ, nên rủi ro
// mất nét vẽ đã có do nhập nhầm thấp hơn hẳn — hoàn tác cho phần này chưa cấp thiết bằng phần còn lại.
type SyncSnapshot = {
  articles: Article[]
  antibiotics: Antibiotic[]
  diseases: DiseaseEntry[]
  infusions: Record<InfusionCategory, InfusionDrug[]>
  ecgLessons: EcgLesson[]
  flashcards: FlashCard[]
  wardRecipes: WardRecipe[]
}

function DataSyncScreen({
  customArticles,
  customAntibiotics,
  customDiseases,
  customInfusions,
  customEcgLessons,
  customFlashcards,
  boards,
  activeBoardId,
  onImport,
  onRestoreSnapshot,
  onBackupDone,
  onBack,
}: {
  customArticles: Article[]
  customAntibiotics: Antibiotic[]
  customDiseases: DiseaseEntry[]
  customInfusions: Record<InfusionCategory, InfusionDrug[]>
  customEcgLessons: EcgLesson[]
  customFlashcards: FlashCard[]
  boards: MindBoard[]
  activeBoardId: string
  onImport: (data: ImportPayload) => void
  onRestoreSnapshot: (snapshot: SyncSnapshot) => void
  onBackupDone: () => void
  onBack: () => void
}) {
  const [status, setStatus] = useState<string | null>(null)
  const [exporting, setExporting] = useState(false)
  const [importing, setImporting] = useState(false)
  // File đã đọc/phân tích xong, đang CHỜ người dùng xác nhận — chưa động gì tới dữ liệu trên máy.
  const [pendingImport, setPendingImport] = useState<{ data: ImportPayload; rows: { label: string; added: number; updated: number }[] } | null>(null)
  // Snapshot của lần nhập GẦN NHẤT trong phiên xem màn này — còn giữ thì còn hoàn tác được. Mất khi
  // rời màn hình (đổi tab/đóng app) vì dữ liệu đã lưu xuống máy ngay khi nhập, không có ý nghĩa "chưa
  // lưu" để giữ lại lâu hơn; đây là lưới an toàn cho đúng cái vừa bấm nhập, không phải một lịch sử.
  const [undoSnapshot, setUndoSnapshot] = useState<SyncSnapshot | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  // Công thức pha (bảng "Cách dùng"/"Đường dùng" người dùng tự chỉnh mỗi thuốc) đọc thẳng từ
  // localStorage — KHÔNG được quên trong bản sao lưu, vì đây chính là dữ liệu tốn công nhập nhất
  // (mỗi khoa một kiểu pha) và trước đây bị bỏ sót hoàn toàn khỏi "Xuất file"/"Nhập file".
  const wardRecipesByDrug = loadWardRecipes()
  const wardRecipeList = Object.values(wardRecipesByDrug).flat()

  const categoryRows: SyncCategoryRow[] = [
    { key: "articles", label: "Bài viết", current: customArticles, incomingOf: (d) => d.articles },
    { key: "antibiotics", label: "Kháng sinh", current: customAntibiotics, incomingOf: (d) => d.antibiotics },
    { key: "diseases", label: "Bệnh lý tự thêm", current: customDiseases, incomingOf: (d) => d.diseases },
    // Một dòng cho mỗi nhóm thuốc truyền, đọc từ danh mục nhóm — thêm nhóm mới là bảng này tự có
    // thêm dòng, không còn nguy cơ quên một nhóm rồi tưởng nhóm đó không có dữ liệu.
    ...INFUSION_CATEGORIES.map((c) => ({
      key: c.backupKey,
      label: c.title,
      current: customInfusions[c.id] ?? [],
      incomingOf: (d: ImportPayload) => d.infusions[c.id] ?? [],
    })),
    { key: "wardRecipes", label: "Công thức pha đã lưu", current: wardRecipeList, incomingOf: (d) => d.wardRecipes },
    { key: "ecgLessons", label: "Bài học ECG", current: customEcgLessons, incomingOf: (d) => d.ecgLessons },
    { key: "flashcards", label: "Thẻ ghi nhớ tự nhập", current: customFlashcards, incomingOf: (d) => d.flashcards },
    // Sơ đồ tư duy cũng có id (id bảng) nên tra được số bảng file nhập sẽ đụng tới, dù nội dung mỗi
    // bảng được gộp riêng theo node/cạnh chứ không thay thế toàn bộ như các dòng khác ở trên.
    { key: "mindmapBoards", label: "Bảng Sơ đồ tư duy", current: boards, incomingOf: (d) => d.mindmapBoards.map((mb) => mb.board) },
  ]

  const [exportSelection, setExportSelection] = useState<Record<string, boolean>>(() =>
    Object.fromEntries(categoryRows.map((r) => [r.key, true])),
  )
  const selectedCount = categoryRows.filter((r) => exportSelection[r.key] !== false).length

  function toggleExportKey(key: string) {
    setExportSelection((prev) => ({ ...prev, [key]: prev[key] === false }))
  }
  function selectAllExport(value: boolean) {
    setExportSelection(Object.fromEntries(categoryRows.map((r) => [r.key, value])))
  }

  // Đọc dữ liệu THẬT của TỪNG bảng trực tiếp từ IndexedDB ngay lúc xuất, thay vì giữ sẵn tất cả các
  // bảng trong bộ nhớ suốt lúc dùng app — phần lớn thời gian chỉ một bảng đang mở là cần tới.
  async function handleExport() {
    if (selectedCount === 0) {
      setStatus("Chọn ít nhất một mục để xuất.")
      return
    }
    setExporting(true)
    try {
      const includeMindmap = exportSelection.mindmapBoards !== false
      const mindmapBoards = includeMindmap
        ? await Promise.all(boards.map(async (board) => ({ board, mindmap: await loadMindmap(board.id) })))
        : []
      const pick = <T,>(key: string, items: T[]): T[] => (exportSelection[key] !== false ? items : [])
      const payload = {
        app: "drtrong",
        version: 2,
        exportedAt: new Date().toISOString(),
        data: {
          articles: pick("articles", customArticles),
          antibiotics: pick("antibiotics", customAntibiotics),
          diseases: pick("diseases", customDiseases),
          // Mỗi nhóm thuốc truyền một khoá riêng trong file, tên khoá lấy từ `backupKey` của nhóm
          // (data/categories.ts) — 5 nhóm cũ giữ nguyên tên cũ nên file xuất từ bản trước và file
          // xuất từ bản này đọc lẫn nhau được.
          ...Object.fromEntries(INFUSION_CATEGORIES.map((c) => [c.backupKey, pick(c.backupKey, customInfusions[c.id] ?? [])])),
          ecgLessons: pick("ecgLessons", customEcgLessons),
          flashcards: pick("flashcards", customFlashcards),
          mindmapBoards,
          wardRecipes: pick("wardRecipes", wardRecipeList),
        },
      }
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" })
      const url = URL.createObjectURL(blob)
      const a = document.createElement("a")
      const now = new Date()
      const two = (n: number) => String(n).padStart(2, "0")
      const stamp = `${now.getFullYear()}-${two(now.getMonth() + 1)}-${two(now.getDate())}-${two(now.getHours())}${two(now.getMinutes())}`
      a.href = url
      a.download = `drtrong-du-lieu-${stamp}.json`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)
      markBackupDone()
      onBackupDone()
      const exportedCount = categoryRows.filter((r) => r.key !== "mindmapBoards").reduce((n, r) => n + (exportSelection[r.key] !== false ? r.current.length : 0), 0)
      setStatus(`Đã xuất ${exportedCount} mục${includeMindmap ? ` + ${boards.length} bảng sơ đồ tư duy` : ""} ra file${selectedCount < categoryRows.length ? " (đã bỏ một số mục theo lựa chọn)" : ""}.`)
    } finally {
      setExporting(false)
    }
  }

  function handleImportClick() {
    fileInputRef.current?.click()
  }

  // Chỉ ĐỌC và PHÂN TÍCH file — chưa ghi gì vào máy. Kết quả (kèm số mục mới/số mục sẽ bị đè theo
  // từng nhóm) đứng chờ ở `pendingImport` cho tới khi người dùng xem qua rồi bấm "Xác nhận nhập".
  function handleFileChange(e: ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    setStatus(null)
    setImporting(true)
    const reader = new FileReader()
    reader.onload = () => {
      try {
        const parsed = JSON.parse(String(reader.result))
        // Hỗ trợ cả file export chuẩn ({ data: {...} }) lẫn file JSON thô { articles, antibiotics, ... }
        const data = parsed && typeof parsed === "object" && "data" in parsed ? (parsed as { data: unknown }).data : parsed
        const d = (data ?? {}) as Record<string, unknown>
        const articles: Article[] = Array.isArray(d.articles) ? (d.articles as Article[]) : []
        const antibiotics: Antibiotic[] = Array.isArray(d.antibiotics) ? (d.antibiotics as Antibiotic[]) : []
        const diseases: DiseaseEntry[] = Array.isArray(d.diseases) ? (d.diseases as DiseaseEntry[]) : []
        // Thuốc truyền: đọc theo `backupKey` của từng nhóm. File cũ (chỉ có 5 nhóm) đơn giản là
        // thiếu khoá của 4 nhóm mới — mỗi khoá thiếu thành mảng rỗng, không phải lỗi.
        const infusions = Object.fromEntries(
          INFUSION_CATEGORIES.map((c) => [c.id, Array.isArray(d[c.backupKey]) ? (d[c.backupKey] as InfusionDrug[]) : []]),
        ) as Record<InfusionCategory, InfusionDrug[]>
        const ecgLessons: EcgLesson[] = Array.isArray(d.ecgLessons) ? (d.ecgLessons as EcgLesson[]) : []
        const flashcards: FlashCard[] = Array.isArray(d.flashcards) ? (d.flashcards as FlashCard[]) : []
        const wardRecipes: WardRecipe[] = Array.isArray(d.wardRecipes) ? (d.wardRecipes as WardRecipe[]) : []

        // Sơ đồ tư duy: file mới (từ khi có nhiều bảng) có `mindmapBoards` — mảng {board, mindmap},
        // mỗi bảng nhập vào đúng bảng cùng id trên máy (hoặc tạo bảng mới nếu chưa từng có). File cũ
        // hơn (trước khi có nhiều bảng) chỉ có `mindmap` — không biết id bảng gốc, nên gộp vào bảng
        // ĐANG MỞ trên máy này, giống hành vi "một bảng duy nhất" trước đây.
        let mindmapBoards: { board: MindBoard; mindmap: MindmapData }[] = []
        if (Array.isArray(d.mindmapBoards)) {
          mindmapBoards = (d.mindmapBoards as unknown[])
            .map((row) => row as { board?: MindBoard; mindmap?: { nodes?: unknown; edges?: unknown; strokes?: unknown; images?: unknown } })
            .filter(
              (row): row is { board: MindBoard; mindmap: { nodes: unknown[]; edges: unknown[]; strokes?: unknown[]; images?: unknown[] } } =>
                !!row.board &&
                typeof row.board.id === "string" &&
                !!row.mindmap &&
                Array.isArray(row.mindmap.nodes) &&
                Array.isArray(row.mindmap.edges),
            )
            // File sao lưu có thể bị sửa tay hoặc hỏng giữa chừng — một node/nét vẽ sai kiểu lọt
            // xuống tới bảng vẽ sẽ làm sập cả cây React (xem sanitizeMindmapData). Lọc ngay tại cửa
            // nhập, trước khi ghép vào dữ liệu hiện có.
            .map((row) => ({ board: row.board, mindmap: sanitizeMindmapData(row.mindmap) }))
        } else {
          const rawMindmap = d.mindmap as { nodes?: unknown; edges?: unknown; strokes?: unknown; images?: unknown } | undefined
          if (rawMindmap && Array.isArray(rawMindmap.nodes) && Array.isArray(rawMindmap.edges)) {
            const targetBoard = boards.find((b) => b.id === activeBoardId) ?? boards[0]
            if (targetBoard) {
              mindmapBoards = [
                { board: targetBoard, mindmap: sanitizeMindmapData(rawMindmap as { nodes: unknown[]; edges: unknown[]; strokes?: unknown[]; images?: unknown[] }) },
              ]
            }
          }
        }

        const parsedData: ImportPayload = { articles, antibiotics, diseases, infusions, ecgLessons, flashcards, mindmapBoards, wardRecipes }
        const count =
          articles.length +
          antibiotics.length +
          diseases.length +
          INFUSION_CATEGORIES.reduce((n, c) => n + infusions[c.id].length, 0) +
          ecgLessons.length +
          flashcards.length +
          wardRecipes.length
        if (count === 0 && mindmapBoards.length === 0) {
          setStatus("Không tìm thấy dữ liệu hợp lệ trong file này.")
          setImporting(false)
          return
        }
        const rows = categoryRows
          .map((row) => {
            const { added, updated } = diffImportCounts(row.current, row.incomingOf(parsedData))
            return { label: row.label, added, updated }
          })
          .filter((r) => r.added > 0 || r.updated > 0)
        setPendingImport({ data: parsedData, rows })
      } catch {
        setStatus("File không đọc được — cần đúng định dạng JSON đã xuất từ app này.")
      } finally {
        setImporting(false)
      }
    }
    reader.onerror = () => {
      setStatus("Không đọc được file này.")
      setImporting(false)
    }
    reader.readAsText(file)
    e.target.value = ""
  }

  function handleCancelImport() {
    setPendingImport(null)
  }

  // Chụp lại nguyên trạng TRƯỚC khi gộp — đây là thứ "Hoàn tác" sẽ trả về, nên phải lấy đúng lúc
  // này (dữ liệu hiện có trên máy, chưa bị file mới đè lên).
  function handleConfirmImport() {
    if (!pendingImport) return
    const snapshot: SyncSnapshot = {
      articles: customArticles,
      antibiotics: customAntibiotics,
      diseases: customDiseases,
      infusions: customInfusions,
      ecgLessons: customEcgLessons,
      flashcards: customFlashcards,
      wardRecipes: wardRecipeList,
    }
    onImport(pendingImport.data)
    setUndoSnapshot(snapshot)
    const totalAdded = pendingImport.rows.reduce((n, r) => n + r.added, 0)
    const totalUpdated = pendingImport.rows.reduce((n, r) => n + r.updated, 0)
    const mindmapCount = pendingImport.data.mindmapBoards.length
    setStatus(`Đã nhập: ${totalAdded} mục mới, ${totalUpdated} mục cập nhật${mindmapCount ? ` + ${mindmapCount} bảng sơ đồ tư duy` : ""}.`)
    setPendingImport(null)
  }

  function handleUndo() {
    if (!undoSnapshot) return
    onRestoreSnapshot(undoSnapshot)
    setUndoSnapshot(null)
    setStatus("Đã hoàn tác — dữ liệu trở lại như trước khi nhập file.")
  }

  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        <span className="text-sm font-semibold text-slate-900">Đồng bộ dữ liệu</span>
        <span className="w-10" />
      </div>

      <div className="scroll-ios flex-1 px-6 pt-6 pb-8 space-y-5">
        <div className="p-4 rounded-2xl border" style={{ borderColor: "var(--c-primary-line)", background: "var(--c-primary-soft)" }}>
          <p className="text-sm text-slate-700 leading-relaxed">
            Mục bạn tự nhập (bài viết kèm ảnh chèn trong bài, kháng sinh, các thuốc truyền trong "Dùng thuốc", công thức pha riêng đã lưu cho từng thuốc, thẻ ghi nhớ, bài học ECG, và cả nét vẽ tay trên Sơ đồ tư duy) được lưu ngay trên máy này, không qua máy chủ nào. Dùng "Xuất file" để sao lưu hoặc chuyển sang thiết bị khác, rồi "Nhập file" trên thiết bị kia để khôi phục.
          </p>
        </div>

        {pendingImport ? (
          // ─── Xem trước file trước khi ghi gì vào máy ───────────────────────────
          <div className="space-y-4">
            <div>
              <p className="text-sm font-bold text-slate-900">Xem trước trước khi nhập</p>
              <p className="text-xs text-slate-500 mt-1 leading-relaxed">
                {pendingImport.rows.length === 0
                  ? "File này chỉ có sơ đồ tư duy (gộp theo node/cạnh) hoặc không có gì mới."
                  : "Mục \"cập nhật\" nghĩa là trên máy ĐÃ CÓ id này — nội dung hiện tại sẽ bị THAY bằng nội dung trong file."}
              </p>
            </div>
            {pendingImport.rows.length > 0 && (
              <div className="rounded-2xl border divide-y" style={{ borderColor: "var(--c-line)" }}>
                {pendingImport.rows.map((r) => (
                  <div key={r.label} className="flex items-center justify-between px-3.5 py-2.5">
                    <span className="text-sm text-slate-700">{r.label}</span>
                    <span className="text-xs font-semibold flex items-center gap-2">
                      {r.added > 0 && <span style={{ color: "var(--c-green)" }}>+{r.added} mới</span>}
                      {r.updated > 0 && <span style={{ color: "var(--c-accent)" }}>{r.updated} cập nhật</span>}
                    </span>
                  </div>
                ))}
              </div>
            )}
            <div className="flex gap-2.5">
              <button
                onClick={handleCancelImport}
                className="flex-1 py-3 rounded-2xl font-semibold text-sm border"
                style={{ borderColor: "var(--c-line)", color: "var(--c-muted)", background: "var(--c-surface)" }}
              >
                Huỷ
              </button>
              <button
                onClick={handleConfirmImport}
                className="flex-1 py-3 rounded-2xl font-semibold text-sm"
                style={{ background: "var(--c-primary)", color: "var(--c-on-bright)" }}
              >
                Xác nhận nhập
              </button>
            </div>
          </div>
        ) : (
          <>
            <div>
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Hiện có trên máy này</p>
                <button
                  onClick={() => selectAllExport(selectedCount < categoryRows.length)}
                  className="text-xs font-semibold"
                  style={{ color: "var(--c-primary)" }}
                >
                  {selectedCount < categoryRows.length ? "Chọn tất cả" : "Bỏ chọn tất cả"}
                </button>
              </div>
              <p className="text-[11px] text-slate-400 mb-2">Chạm một ô để bỏ/chọn xuất mục đó — đang chọn {selectedCount}/{categoryRows.length}.</p>
              <div className="grid grid-cols-2 gap-2.5">
                {categoryRows.map((row) => {
                  const selected = exportSelection[row.key] !== false
                  const latest = latestTimestamp(row.current)
                  return (
                    <button
                      key={row.key}
                      onClick={() => toggleExportKey(row.key)}
                      className="p-3 rounded-xl border text-left relative"
                      style={{ borderColor: selected ? "var(--c-primary-line)" : "var(--c-line)", background: selected ? "var(--c-primary-soft)" : "var(--c-surface)" }}
                    >
                      <span
                        className="absolute top-2.5 right-2.5 w-4 h-4 rounded-full flex items-center justify-center"
                        style={{ background: selected ? "var(--c-primary)" : "var(--c-line-soft)", color: "var(--c-on-bright)" }}
                      >
                        {selected && icons.check()}
                      </span>
                      <p className="text-lg font-bold text-slate-900">{row.current.length}</p>
                      <p className="text-xs text-slate-500 pr-4">{row.label}</p>
                      {latest != null && <p className="text-[10px] text-slate-400 mt-0.5">Mới nhất: {formatDateTime(latest)}</p>}
                    </button>
                  )
                })}
              </div>
            </div>

            <button
              onClick={handleExport}
              disabled={exporting || importing}
              className="w-full flex items-center justify-center gap-2 py-3.5 rounded-2xl font-semibold text-sm disabled:opacity-60"
              style={{ background: "var(--c-primary)", color: "var(--c-on-bright)" }}
            >
              {icons.download()}
              {exporting ? "Đang xuất…" : "Xuất file sao lưu (.json)"}
            </button>

            <button
              onClick={handleImportClick}
              disabled={exporting || importing}
              className="w-full flex items-center justify-center gap-2 py-3.5 rounded-2xl font-semibold text-sm border disabled:opacity-60"
              style={{ borderColor: "var(--c-primary)", color: "var(--c-primary)", background: "var(--c-surface)" }}
            >
              {icons.upload()}
              {importing ? "Đang đọc file…" : "Nhập file đã sao lưu"}
            </button>
            <input ref={fileInputRef} type="file" accept="application/json,.json" onChange={handleFileChange} disabled={importing} className="hidden" />
          </>
        )}

        {status && (
          <div className="text-center space-y-2">
            <p className="text-xs leading-relaxed" style={{ color: "var(--c-accent)" }}>{status}</p>
            {undoSnapshot && (
              <button onClick={handleUndo} className="inline-flex items-center gap-1.5 text-xs font-bold" style={{ color: "var(--c-danger-icon)" }}>
                {icons.undo()}
                Hoàn tác lần nhập vừa rồi
              </button>
            )}
          </div>
        )}

        {!pendingImport && (
          <p className="text-xs text-slate-400 leading-relaxed">
            Nhập file sẽ gộp theo id: mục đã có cùng id được cập nhật theo file mới, mục id chưa có sẽ được thêm vào — dữ liệu hiện có trên máy không bị xoá. Sơ đồ tư duy được gộp theo node/cạnh, không thay thế toàn bộ. Có thể hoàn tác ngay sau khi nhập, miễn còn đứng ở màn này.
          </p>
        )}
      </div>
    </div>
  )
}

// Màn ĐỌC bài tự nhập, dựng theo cùng khuôn với ArticleScreen (bài dựng sẵn) để bài mình viết đọc
// lên cũng ra dáng một bài tra cứu kiểu UpToDate: đầu bài có chuyên khoa / độ khó / thời gian đọc,
// mục lục gập mở tự sinh từ các dòng tiêu đề, nội dung chia mục có đường kẻ, và danh sách bài liên
// quan ở cuối.
function CustomEntryScreen({
  article,
  relatedArticles,
  onEdit,
  onDelete,
  onOpenLink,
  onOpenArticle,
  onBack,
}: {
  article: Article | undefined
  relatedArticles: Article[]
  onEdit: (a: Article) => void
  onDelete: (id: string) => void
  onOpenLink: (target: string) => void
  onOpenArticle: (a: Article) => void
  onBack: () => void
}) {
  const [tocOpen, setTocOpen] = useState(false)
  const headingEls = useRef(new Map<string, HTMLElement>())

  const blocks = useMemo(() => (article ? articleBlocks(article) : []), [article])
  const toc = useMemo(() => blocksToToc(blocks), [blocks])
  const wordCount = useMemo(() => {
    const plain = blocksToPlainText(blocks).trim()
    return plain ? plain.split(/\s+/).length : 0
  }, [blocks])

  if (!article) {
    return (
      <div className="h-full flex flex-col items-center justify-center gap-3 px-5">
        <p className="text-sm text-slate-500">Không tìm thấy mục này.</p>
        <button onClick={onBack} className="text-sm font-semibold" style={{ color: "var(--c-primary)" }}>
          Quay lại
        </button>
      </div>
    )
  }

  const related = relatedArticles.filter((a) => a.id !== article.id).slice(0, 3)

  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        <div className="flex items-center gap-2">
          <button
            onClick={() => onEdit(article)}
            className="w-11 h-11 rounded-full flex items-center justify-center"
            style={{ background: "var(--c-primary-soft)", color: "var(--c-primary)" }}
            aria-label="Sửa mục này"
          >
            {icons.edit()}
          </button>
          <ConfirmIconButton
            onConfirm={() => onDelete(article.id)}
            ariaLabel="Xoá mục này"
            className="w-11 h-11 rounded-full flex items-center justify-center"
            style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }}
          />
        </div>
      </div>

      <div className="scroll-ios flex-1 pb-10">
        <div className="px-6 pt-6">
          <span className="text-xs font-bold uppercase tracking-widest" style={{ color: "var(--c-primary)" }}>
            {article.specialty}
          </span>
          <h1 className="text-2xl font-bold text-slate-900 mt-1 leading-tight">{article.title}</h1>
          <div className="flex items-center gap-3 mt-2.5 flex-wrap">
            <DifficultyBadge level={article.difficulty} />
            <span className="text-xs text-slate-400">{Math.max(1, Math.round(wordCount / 200))} phút đọc</span>
            <span className="text-xs text-slate-400">{article.lastUpdated}</span>
          </div>
          <div className="flex gap-1.5 mt-3 flex-wrap">
            {article.tags.map((t) => (
              <TagPill key={t} tag={t} />
            ))}
          </div>

          <p className="text-sm text-slate-600 mt-5 leading-relaxed">{article.excerpt}</p>
        </div>

        {/* Mục lục — chỉ hiện khi bài có ít nhất một dòng tiêu đề. Bấm một mục là cuộn tới đúng chỗ. */}
        {toc.length > 0 && (
          <div className="px-5 mt-5">
            <button
              onClick={() => setTocOpen(!tocOpen)}
              className="w-full flex items-center justify-between px-4 py-3 rounded-2xl border"
              style={{ borderColor: "var(--c-primary-line)", background: "var(--c-primary-soft)" }}
            >
              <span className="text-sm font-semibold" style={{ color: "var(--c-primary)" }}>
                Mục lục ({toc.length})
              </span>
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="var(--c-primary)"
                strokeWidth={2}
                className={`w-4 h-4 transition-transform ${tocOpen ? "rotate-180" : ""}`}
              >
                <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
              </svg>
            </button>
            {tocOpen && (
              <div className="mt-2 rounded-2xl border overflow-hidden fade-in" style={{ borderColor: "var(--c-line)" }}>
                {toc.map((item, i) => (
                  <button
                    key={item.id}
                    onClick={() => {
                      setTocOpen(false)
                      headingEls.current.get(item.id)?.scrollIntoView({ behavior: "smooth", block: "start" })
                    }}
                    className="w-full flex items-center gap-3 px-4 py-3 text-left border-b last:border-0"
                    style={{ borderColor: "var(--c-line-soft)", background: "var(--c-surface)" }}
                  >
                    <span className="text-xs font-mono text-slate-400 w-4 flex-none">{i + 1}</span>
                    <span className="text-sm font-medium text-slate-700">{item.label}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        <div className="px-6">
          <BlockContent
            blocks={blocks}
            onOpenLink={onOpenLink}
            headingRefs={(id, el) => {
              if (el) headingEls.current.set(id, el)
              else headingEls.current.delete(id)
            }}
          />
        </div>

        {related.length > 0 && (
          <div className="px-6 mt-8">
            <h3 className="text-base font-bold text-slate-900 mb-1">Bài viết liên quan</h3>
            <p className="text-xs text-slate-400 mb-2">Cùng chuyên khoa {article.specialty}</p>
            {related.map((a) => (
              <button
                key={a.id}
                onClick={() => onOpenArticle(a)}
                className="w-full flex items-center gap-3 py-3 border-b text-left"
                style={{ borderColor: "var(--c-line-soft)" }}
              >
                <div className="w-8 h-8 rounded-lg flex items-center justify-center flex-none" style={{ background: "var(--c-line-soft)", color: "var(--c-text-muted)" }}>
                  {specialtyIcon(SPECIALTIES.find((s) => s.name === a.specialty)?.id, "w-[18px] h-[18px]")}
                </div>
                <span className="text-sm font-medium text-slate-800 flex-1 truncate">{a.title}</span>
                <span className="flex-none text-slate-300 text-lg leading-none">›</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

// ─── ECG ──────────────────────────────────────────────────────────────────────
// Truy cập từ mục "ECG" trong "Truy cập nhanh" ở Trang chủ (không nằm trong thanh tab dưới cùng).
// Chưa có bài học dựng sẵn (ECG_LESSONS luôn rỗng) — toàn bộ nội dung do người dùng tự nhập, lưu
// bằng IndexedDB (useEcgLessons/ecgStorage.ts) vì có thể kèm ảnh.

function EcgScreen({
  lessons,
  onNavigate,
  onBack,
}: {
  lessons: EcgLesson[]
  onNavigate: (s: Screen, id?: string) => void
  onBack: () => void
}) {
  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        <span className="text-sm font-semibold text-slate-900">ECG</span>
        <button
          onClick={() => onNavigate("addEcg")}
          className="w-11 h-11 rounded-full flex items-center justify-center"
          style={{ background: "var(--c-primary-soft)", color: "var(--c-primary)" }}
          aria-label="Thêm bài học ECG"
        >
          {icons.plus()}
        </button>
      </div>

      <div className="scroll-ios flex-1 px-5 pt-5 pb-8">
        {lessons.length === 0 ? (
          <div className="flex flex-col items-center text-center gap-3 pt-16 px-6">
            <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ background: "var(--c-primary-soft)", color: "var(--c-primary)" }}>
              {icons.ecg()}
            </div>
            <p className="font-bold text-slate-900 text-[15px]">Chưa có bài học ECG nào</p>
            <p className="text-xs text-slate-400 leading-relaxed">
              Nhấn nút "+" ở trên để tạo bài học đầu tiên — có thể kèm ảnh chụp bản ghi ECG.
            </p>
          </div>
        ) : (
          <div className="space-y-2.5">
            {lessons.map((l) => {
              // Ảnh đại diện & số ảnh lấy từ nội dung dạng block (ảnh có thể nằm xen giữa các dòng
              // chữ), ecgBlocks() lo luôn phần bài cũ vốn để ảnh trong mảng `images` riêng.
              const lessonBlocks = ecgBlocks(l)
              const thumb = firstImageUrl(lessonBlocks)
              const imageCount = countImages(lessonBlocks)
              return (
              <button
                key={l.id}
                onClick={() => onNavigate("ecgDetail", l.id)}
                className="w-full flex items-center gap-3 p-3 rounded-2xl border card-press text-left"
                style={{ borderColor: "var(--c-line)", background: "var(--c-surface)" }}
              >
                <div
                  className="flex-none w-14 h-14 rounded-xl overflow-hidden flex items-center justify-center"
                  style={{ background: "var(--c-line-soft)", color: "var(--c-muted)" }}
                >
                  {thumb ? <img src={thumb} alt="" className="w-full h-full object-cover" /> : icons.ecg()}
                </div>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-1.5 min-w-0">
                    <p className="font-bold text-slate-900 text-[14px] truncate">{l.title}</p>
                    {l.isCustom && (
                      <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full flex-none" style={{ background: "var(--c-green-soft)", color: "var(--c-green)" }}>
                        Tự nhập
                      </span>
                    )}
                  </div>
                  {l.summary && <p className="text-xs text-slate-400 truncate mt-0.5">{l.summary}</p>}
                  {l.tags.length > 0 && (
                    <div className="flex gap-1 mt-1 flex-wrap">
                      {l.tags.slice(0, 3).map((t) => (
                        <TagPill key={t} tag={t} />
                      ))}
                    </div>
                  )}
                </div>
                {imageCount > 0 && (
                  <span className="flex-none text-[10px] font-semibold text-slate-400">{imageCount} ảnh</span>
                )}
              </button>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

function EcgDetailScreen({
  lesson,
  onEdit,
  onDelete,
  onOpenLink,
  onBack,
}: {
  lesson: EcgLesson | undefined
  onEdit: (l: EcgLesson) => void
  onDelete: (id: string) => void
  onOpenLink: (target: string) => void
  onBack: () => void
}) {
  if (!lesson) {
    return (
      <div className="h-full flex flex-col items-center justify-center gap-3 px-5">
        <p className="text-sm text-slate-500">Không tìm thấy bài học này.</p>
        <button onClick={onBack} className="text-sm font-semibold" style={{ color: "var(--c-primary)" }}>
          Quay lại
        </button>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        {lesson.isCustom ? (
          <div className="flex items-center gap-2">
            <button
              onClick={() => onEdit(lesson)}
              className="w-11 h-11 rounded-full flex items-center justify-center"
              style={{ background: "var(--c-primary-soft)", color: "var(--c-primary)" }}
              aria-label="Sửa bài học"
            >
              {icons.edit()}
            </button>
            <ConfirmIconButton
              onConfirm={() => onDelete(lesson.id)}
              ariaLabel="Xoá bài học"
              className="w-11 h-11 rounded-full flex items-center justify-center"
              style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }}
            />
          </div>
        ) : (
          <span className="w-8" />
        )}
      </div>

      <div className="scroll-ios flex-1 px-6 pt-6 pb-10">
        <h1 className="text-2xl font-bold text-slate-900 leading-tight">{lesson.title}</h1>
        {lesson.tags.length > 0 && (
          <div className="flex gap-1.5 mt-3 flex-wrap">
            {lesson.tags.map((t) => (
              <TagPill key={t} tag={t} />
            ))}
          </div>
        )}
        {lesson.summary && <p className="text-sm text-slate-600 mt-4 leading-relaxed">{lesson.summary}</p>}

        <BlockContent blocks={ecgBlocks(lesson)} onOpenLink={onOpenLink} />
      </div>
    </div>
  )
}

// Màn soạn bài học ECG — dùng cho cả TẠO MỚI và SỬA (truyền `initial`). Nội dung chi tiết soạn tự
// do theo block: chữ và ảnh bản ghi ECG xen kẽ nhau tuỳ ý (xem components/BlockEditor.tsx).
function AddEcgScreen({
  initial,
  linkTargets,
  onSave,
  onBack,
}: {
  initial?: EcgLesson
  linkTargets: LinkTarget[]
  onSave: (l: EcgLesson) => void
  onBack: () => void
}) {
  const [title, setTitle] = useState(initial?.title ?? "")
  const [tagsText, setTagsText] = useState(initial?.tags.join(", ") ?? "")
  const [summary, setSummary] = useState(initial?.summary ?? "")
  const [blocks, setBlocks] = useState<ContentBlock[]>(() => blocksForEditing(initial ? ecgBlocks(initial) : []))

  const canSave = title.trim().length > 0

  function handleSave() {
    if (!canSave) return
    const lesson: EcgLesson = {
      id: initial?.id ?? `custom-ecg-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      title: title.trim(),
      tags: tagsText
        .split(",")
        .map((t) => t.trim())
        .filter(Boolean),
      summary: summary.trim() || undefined,
      blocks: cleanBlocks(blocks),
      createdAt: initial?.createdAt ?? new Date().toISOString(),
      isCustom: true,
    }
    onSave(lesson)
  }

  const fieldClass = "w-full px-4 py-3 rounded-2xl text-sm border outline-none"
  const fieldStyle = { borderColor: "var(--c-line)", background: "var(--c-surface)" }

  return (
    <div className="h-full flex flex-col screen-transition">
      <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: "var(--c-line)" }}>
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: "var(--c-primary)" }}>
          {icons.back()}
          Quay lại
        </button>
        <span className="text-sm font-semibold text-slate-900">{initial ? "Sửa bài học ECG" : "Bài học ECG mới"}</span>
        <span className="w-10" />
      </div>

      <div className="scroll-ios flex-1 px-6 pt-6 pb-8 space-y-4">
        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Tiêu đề</label>
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="VD: Rung nhĩ đáp ứng thất nhanh"
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Thẻ tag (cách nhau bằng dấu phẩy)</label>
          <input
            value={tagsText}
            onChange={(e) => setTagsText(e.target.value)}
            placeholder="VD: rối loạn nhịp, cấp cứu"
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Tóm tắt ngắn</label>
          <textarea
            value={summary}
            onChange={(e) => setSummary(e.target.value)}
            placeholder="1–2 câu tóm tắt hiển thị ở danh sách"
            rows={2}
            className={fieldClass}
            style={fieldStyle}
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Nội dung chi tiết</label>
          <BlockEditor blocks={blocks} onChange={setBlocks} linkTargets={linkTargets} />
        </div>

        <p className="text-xs text-slate-400 leading-relaxed">
          Bài học ECG được lưu trên máy (trình duyệt của bạn), kể cả ảnh, nên vẫn còn sau khi tắt/mở lại app. Dùng mục "Đồng bộ dữ liệu" ở Trang chủ nếu muốn sao lưu hoặc chuyển sang thiết bị khác.
        </p>
      </div>

      <div className="flex-none px-6 pt-3 border-t" style={{ borderColor: "var(--c-line)", paddingBottom: "var(--nav-pad-bottom)" }}>
        <button
          onClick={handleSave}
          disabled={!canSave}
          className="w-full py-3.5 rounded-2xl font-semibold text-sm"
          style={{ background: canSave ? "var(--c-primary)" : "var(--c-muted)", color: "var(--c-on-bright)" }}
        >
          {initial ? "Lưu thay đổi" : "Lưu bài học"}
        </button>
      </div>
    </div>
  )
}

// ─── "Bệnh nhân hiện tại" — bối cảnh dùng chung cho cả tab Dùng thuốc ─────────
//
// Trước đây cân nặng phải gõ lại cho từng thẻ thuốc: bệnh nhân sốc chạy 3 vận mạch là 3 lần gõ vào
// 3 chỗ, 3 cơ hội gõ nhầm, và không có chỗ nào giữ "bệnh nhân hiện tại" để đối chiếu. Nay mọi máy
// tính liều (kháng sinh lẫn thuốc truyền) đọc chung một bộ thông số từ context này.

interface DosingContextValue {
  patient: PatientVitals
  setPatientField: <K extends keyof PatientVitals>(key: K, value: PatientVitals[K]) => void
  resetPatient: () => void
  // Còn khác null trong 10 giây sau khi bấm "Bệnh nhân mới" — bản sao thông số + bảng đang dùng
  // NGAY TRƯỚC lúc xoá, để dải "Hoàn tác" phục hồi lại đúng như cũ.
  resetUndo: { patient: PatientVitals; running: RunningDrug[] } | null
  undoResetPatient: () => void
  abwKg: number | null
  heightCm: number | null
  ageYears: number | null
  crcl: number | null
  // false khi bệnh nhân có tổn thương thận cấp hoặc đang lọc máu — lúc đó con số CrCl KHÔNG được
  // dùng để chọn bậc liều.
  crclUsable: boolean
  openPatientPanel: () => void
  // Gấp khung bệnh nhân lại khi người dùng đã chuyển sang chọn thuốc. Khung này mở sẵn chiếm gần
  // 700px — trên điện thoại nghĩa là thẻ thuốc vừa chọn nằm dưới hơn hai màn hình cuộn.
  collapsePatientPanel: () => void
  running: RunningDrug[]
  pinRunning: (item: Omit<RunningDrug, "id" | "at">) => void
  unpinRunning: (id: string) => void
  setRunningLine: (id: string, line: number) => void
  logCalc: (entry: Omit<CalcLogEntry, "id" | "at" | "patient" | "weightKg">) => void
  // Công thức pha thực tế của người dùng, lưu theo từng thuốc — có thể nhiều công thức/thuốc (mỗi
  // khoa/mỗi cách pha một tiêu đề riêng) — xem lib/wardRecipes.ts.
  wardRecipes: Record<string, WardRecipe[]>
  // `id` bỏ trống = thêm công thức mới (tự sinh id); có `id` = ghi đè đúng công thức đó.
  saveWard: (recipe: Omit<WardRecipe, "savedAt" | "id"> & { id?: string }) => void
  clearWard: (drugId: string, recipeId: string) => void
  // Ghim/gỡ ghim một công thức làm mặc định cố định — độc lập với "lưu gần nhất" (xem
  // useActiveWardRecipe và lib/wardRecipes.ts).
  pinWard: (drugId: string, recipeId: string) => void
}

const DosingContext = createContext<DosingContextValue | null>(null)

function useDosing(): DosingContextValue {
  const ctx = useContext(DosingContext)
  if (!ctx) throw new Error("useDosing chỉ dùng được bên trong màn hình Dùng thuốc")
  return ctx
}

// Số CrCl / tốc độ bơm ĐẾM CHẠY từ giá trị cũ sang giá trị mới thay vì bật thẳng vào số mới
// (trước đây dùng `key` để dựng lại phần tử, kích hoạt lại hoạt ảnh `pop-value` nảy một nhịp).
// Đếm chạy nói được NHIỀU hơn "số vừa đổi" — nó cho thấy đổi TĂNG hay GIẢM và đổi bao nhiêu, đúng
// tinh thần "đừng đọc nhầm số cũ" mà pop-value đã theo đuổi, chỉ là rõ ràng hơn một bậc.
//
// `finalText` luôn là chuỗi ĐÃ ĐỊNH DẠNG THẬT (formatDoseNumber(...)/String(crcl)...) — hook này
// không tự quyết định cách hiển thị số cuối cùng, chỉ nội suy MÀN HÌNH GIỮA CHỪNG bằng `decimals`
// rồi khoá lại đúng `finalText` khi đếm xong. Nhờ vậy con số nghỉ (không đang đếm) không bao giờ
// lệch khỏi con số mà phần tính liều thật sự tin dùng.
function useCountUp(target: number | null, decimals: number, finalText: string, durationMs = 380): string {
  const [display, setDisplay] = useState(finalText)
  const prevValueRef = useRef<number | null>(target)
  const rafRef = useRef<number | null>(null)
  useEffect(() => {
    if (rafRef.current != null) cancelAnimationFrame(rafRef.current)
    if (target == null) {
      prevValueRef.current = null
      setDisplay(finalText)
      return
    }
    const from = prevValueRef.current
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if (from == null || from === target || reduceMotion) {
      prevValueRef.current = target
      setDisplay(finalText)
      return
    }
    const start = performance.now()
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / durationMs)
      // Cùng đường cong "đến nơi chắc chắn" dùng cho mọi hoạt ảnh xác nhận khác trong màn này.
      const eased = 1 - Math.pow(1 - t, 3)
      if (t < 1) {
        setDisplay((from + (target - from) * eased).toFixed(decimals))
        rafRef.current = requestAnimationFrame(tick)
      } else {
        prevValueRef.current = target
        setDisplay(finalText)
      }
    }
    rafRef.current = requestAnimationFrame(tick)
    return () => {
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, finalText, decimals, durationMs])
  return display
}

// ─── Mảnh giao diện dùng chung cho màn Dùng thuốc ────────────────────────────
// Mọi tiêu đề mục, ô tìm kiếm, chip chọn thuốc và khối gấp/mở đều đi qua đây, để không còn chuyện
// mỗi chỗ một cỡ chữ và một kiểu canh lề. Xem lib/ui.ts.

function SectionLabel({ children, tone = "muted" }: { children: React.ReactNode; tone?: "muted" | "accent" | "danger" }) {
  // C.muted (~3,1:1) chỉ đủ cho icon/placeholder, KHÔNG đủ cho chữ đọc được (dưới ngưỡng AA
  // 4,5:1) — đây là NHÃN MỤC thật, phải đọc được, nên dùng C.textSoft (~4,x:1) cho tone mặc định.
  const color = tone === "accent" ? C.accent : tone === "danger" ? C.danger : C.textSoft
  return (
    <p className={`${T.label} mb-2`} style={{ color }}>
      {children}
    </p>
  )
}

function SearchField({ value, onChange, placeholder, autoFocus }: { value: string; onChange: (v: string) => void; placeholder: string; autoFocus?: boolean }) {
  return (
    <div className={`mind-search-pill flex items-center gap-2.5 px-3.5 h-11 ${R.pill} mb-2.5`} style={{ background: C.lineSoft }}>
      <span style={{ color: C.muted }}>{icons.search(false)}</span>
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        // Ô này được mở CÓ CHỦ ĐÍCH bằng nút kính lúp — không tự focus là bắt người dùng chạm
        // thêm một lần nữa đúng lúc đang vội. type="search" + enterKeyHint cho bàn phím ảo đúng
        // nút "Tìm"; tắt viết-hoa-đầu-câu/tự-sửa-chính-tả vì đây là tên thuốc, không phải văn xuôi.
        autoFocus={autoFocus}
        type="search"
        enterKeyHint="search"
        autoCapitalize="off"
        autoCorrect="off"
        className={`flex-1 h-full bg-transparent  outline-none`}
      />
      {value && (
        <button onClick={() => onChange("")} className="w-11 h-11 flex items-center justify-center flex-none" style={{ color: C.muted }} aria-label="Xoá tìm kiếm">
          {icons.x()}
        </button>
      )}
    </div>
  )
}

// `index` bật hiệu ứng hiện lần lượt (lệch 28ms mỗi chip) — mắt bắt được thứ tự danh sách thay vì
// thấy cả mảng bật ra cùng lúc. Bỏ qua khi người dùng bật "Giảm chuyển động".
function Chip({
  active,
  onClick,
  children,
  tone = "primary",
  index,
}: {
  active: boolean
  onClick: () => void
  children: React.ReactNode
  tone?: "primary" | "accent"
  index?: number
}) {
  const on = tone === "accent" ? C.accent : C.primary
  return (
    <button
      onClick={() => {
        onClick()
        tickHaptic()
      }}
      className={`${CHIP}${index != null ? " rise-in" : ""}`}
      style={{
        ...(active ? { background: on, borderColor: on, color: "var(--c-on-bright)" } : { background: C.surface, borderColor: C.line, color: C.textSoft }),
        ...(index != null ? ({ "--i": index } as React.CSSProperties) : {}),
      }}
      aria-pressed={active}
    >
      {children}
    </button>
  )
}

// Khối gấp/mở. Ở ICU thứ cần nhìn ngay là tốc độ bơm, không phải bốn đoạn văn cảnh báo — nên mọi
// nội dung tham khảo đều nằm sau một dòng tiêu đề gấp lại được (progressive disclosure).
// `alert` = true thì tiêu đề đổi màu để cảnh báo mức cao không bị giấu mất.
function Disclosure({
  label,
  count,
  alert,
  defaultOpen,
  children,
}: {
  label: string
  count?: number
  alert?: boolean
  defaultOpen?: boolean
  children: React.ReactNode
}) {
  const [open, setOpen] = useState(Boolean(defaultOpen))
  // C.muted (~3,1:1) chỉ đủ cho icon/placeholder — đây là tiêu đề mục thật, phải đọc được.
  const color = alert ? C.warn : C.textSoft
  const contentId = useId()
  return (
    <div className="mt-2.5 pt-2.5 border-t" style={{ borderColor: C.lineSoft }}>
      <button
        onClick={() => setOpen((v) => !v)}
        className={`w-full flex items-center justify-between gap-2 ${TAP} -my-2.5 py-2.5`}
        aria-expanded={open}
        aria-controls={contentId}
      >
        <span className={T.label} style={{ color }}>
          {label}
          {count != null && count > 0 ? ` · ${count}` : ""}
        </span>
        <span className="flex-none" style={{ color, transform: open ? "rotate(180deg)" : "none", transition: "transform .15s" }}>
          {icons.chevronDown()}
        </span>
      </button>
      {/* Trước đây `{open && <div>}` — nội dung xuất hiện/biến mất TỨC THÌ và đẩy cả phần dưới
          nhảy theo, đặc biệt rõ trên thẻ có 4-5 Disclosure xếp chồng. `.disc-body` (index.css)
          dùng grid-template-rows 0fr→1fr để chiều cao co giãn mượt mà không cần đo bằng JS —
          luôn render children, chỉ ẩn bằng chiều cao 0 + overflow hidden khi đóng. */}
      <div id={contentId} className="disc-body" data-open={open}>
        <div>{children}</div>
      </div>
    </div>
  )
}

// Nút icon-only XOÁ VĨNH VIỄN dữ liệu đã lưu (bài viết/ECG/kháng sinh/thuốc truyền tự nhập/công
// thức pha đã lưu) — chạm lần 1 chuyển icon sang dấu cảnh báo và giữ vậy vài giây chờ chạm lần 2
// mới thực sự xoá; không chạm tiếp thì tự quay lại icon thùng rác. Khác các nút "×" xoá một DÒNG
// đang soạn dở NGAY TRONG FORM (cảnh báo, mức liều...) trước khi bấm Lưu — những dòng đó chưa từng
// được lưu nên mất đi không tốn công gì để làm lại.
const CONFIRM_ICON_RESET_MS = 2500

function ConfirmIconButton({
  onConfirm,
  ariaLabel,
  className,
  style,
}: {
  onConfirm: () => void
  ariaLabel: string
  className?: string
  style?: React.CSSProperties
}) {
  const [confirm, setConfirm] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current)
    },
    [],
  )
  return (
    <button
      onClick={() => {
        if (!confirm) {
          setConfirm(true)
          tickHaptic()
          if (timer.current) clearTimeout(timer.current)
          timer.current = setTimeout(() => setConfirm(false), CONFIRM_ICON_RESET_MS)
          return
        }
        if (timer.current) clearTimeout(timer.current)
        setConfirm(false)
        onConfirm()
      }}
      className={className}
      style={{ ...(confirm ? { background: "var(--c-danger-icon)", color: "var(--c-on-bright)" } : style), position: "relative" }}
      aria-label={confirm ? `${ariaLabel} — chạm lần nữa để xác nhận` : ariaLabel}
    >
      {/* Chạm lần 1 trước đây chỉ đổi icon (thùng rác → cảnh báo) cùng kích thước, cùng vị trí,
          không chữ — rất dễ tưởng "máy không nhận" rồi chạm lại, mà lần chạm đó xoá thật. Vòng
          đếm ngược viền quanh icon cho biết rõ: đã nhận, đang chờ chạm lần hai, còn bấy nhiêu
          thời gian nữa thì tự huỷ. */}
      {confirm && (
        <svg viewBox="0 0 36 36" className="absolute inset-0 w-full h-full" style={{ transform: "rotate(-90deg)" }} aria-hidden="true">
          <circle
            cx="18" cy="18" r="15.5" fill="none" stroke="currentColor" strokeWidth="2" opacity="0.55"
            strokeDasharray={2 * Math.PI * 15.5}
            style={{ animation: `confirmRing ${CONFIRM_ICON_RESET_MS}ms linear forwards` }}
          />
        </svg>
      )}
      {confirm ? icons.alert() : icons.trash()}
    </button>
  )
}

// Hộp thông báo một kiểu duy nhất cho cả màn — trước đây mỗi chỗ tự chọn nền/viền/cỡ chữ riêng.
function Note({ tone, children }: { tone: "info" | "warn" | "danger" | "ok"; children: React.ReactNode }) {
  const map = {
    info: { bg: C.primarySoft, fg: C.primary, line: C.primaryLine },
    warn: { bg: C.warnSoft, fg: C.warn, line: C.warnLine },
    danger: { bg: C.dangerSoft, fg: C.danger, line: C.dangerLine },
    ok: { bg: C.accentSoft, fg: C.accent, line: C.accentLine },
  }[tone]
  return (
    <p className={`${T.meta} px-2.5 py-2 ${R.box} mb-2`} style={{ background: map.bg, color: map.fg, border: `1px solid ${map.line}` }}>
      {children}
    </p>
  )
}

// ─── Nguồn dữ liệu & ngày rà soát ─────────────────────────────────────────────
// Không mục nào được phép im lặng về nguồn gốc: có nguồn thì ghi rõ, chưa có thì nói thẳng là chưa
// có. Đây là cách duy nhất để người dùng biết mục nào còn hợp thời — ví dụ đích nồng độ vancomycin
// đã đổi từ "đáy 15–20 mg/L" (2009) sang AUC/MIC (đồng thuận 2020).

function formatReviewedOn(value: string): string {
  const m = /^(\d{4})-(\d{2})$/.exec(value.trim())
  return m ? `${m[2]}/${m[1]}` : value
}

function SourceLine({ item, bare }: { item: SourceInfo; bare?: boolean }) {
  const hasAny = Boolean(item.source || item.reviewedOn)
  const inner = hasAny ? (
    <p className={T.meta} style={{ color: C.textSoft }}>
      {item.source && <>Nguồn: {item.source}</>}
      {item.source && item.reviewedOn && " · "}
      {item.reviewedOn && <>Rà soát: {formatReviewedOn(item.reviewedOn)}</>}
    </p>
  ) : (
    <p className={`${T.meta} px-2.5 py-2 ${R.box}`} style={{ background: C.warnSoft, color: "var(--c-warn-icon)" }}>
      Chưa ghi nguồn · chưa có ngày rà soát — bổ sung qua nút Sửa.
    </p>
  )
  if (bare) return inner
  return (
    <div className="mt-3 pt-2.5 border-t" style={{ borderColor: C.lineSoft }}>
      {inner}
    </div>
  )
}

// ─── Miễn trừ trách nhiệm ─────────────────────────────────────────────────────
// Một app tính liều thuốc vận mạch mà không có dòng nào nói rõ phạm vi sử dụng thì vừa là vấn đề an
// toàn vừa là vấn đề pháp lý cho chính tác giả. Hiện một lần bắt buộc đọc, sau đó vẫn giữ một dải
// nhắc thường trực ở đầu màn hình.

const DISCLAIMER_KEY = "drtrong:disclaimerAck"
const DISCLAIMER_VERSION = "2026-07"
const DISCLAIMER_TEXT =
  "Đây là sổ tay tra cứu nhanh cho nhân viên y tế, không thay thế phác đồ của cơ sở và tờ hướng dẫn sử dụng thuốc."

function DisclaimerGate() {
  const [ack, setAck] = useState<boolean>(() => {
    try {
      return localStorage.getItem(DISCLAIMER_KEY) === DISCLAIMER_VERSION
    } catch {
      return false
    }
  })
  const panelRef = useRef<HTMLDivElement | null>(null)
  // Không truyền onEscape: đây là màn xác nhận BẮT BUỘC đọc trước khi dùng, không có lối tắt Esc để
  // né qua — chỉ đóng được bằng cách chạm "Tôi đã hiểu". Vẫn cần bẫy Tab để bàn phím không lọt ra
  // ngoài tấm phủ vào nội dung màn hình đang bị che phía sau.
  useDialogFocus(panelRef)
  if (ack) return null
  return (
    // Trước đây bung ra tức thì dù có rounded-t-3xl — trông như bottom sheet nhưng không có động
    // tác của bottom sheet. `.fade-in` cho nền phủ, `.mind-sheet` (trượt lên từ đáy) cho tấm sheet.
    <div className="absolute inset-0 z-50 flex items-end fade-in" style={{ background: "var(--c-scrim)" }}>
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="disclaimer-gate-title"
        className="mind-sheet w-full rounded-t-3xl px-6 pt-6"
        style={{ background: "var(--c-surface)", paddingBottom: "var(--nav-pad-bottom)" }}
      >
        <div className="flex items-center gap-2 mb-2" style={{ color: "var(--c-warn-icon)" }}>
          {icons.alert()}
          <p id="disclaimer-gate-title" className="text-[13px] font-bold">Trước khi dùng</p>
        </div>
        <p className="text-[13px] text-slate-700 leading-[1.45] mb-3">{DISCLAIMER_TEXT}</p>
        <p className="text-[12px] text-slate-500 leading-[1.45] mb-4">
          Mỗi mục đều ghi nguồn và ngày rà soát ngay trên thẻ thuốc; mục nào chưa có thì được đánh dấu rõ.
        </p>
        <button
          onClick={() => {
            try {
              localStorage.setItem(DISCLAIMER_KEY, DISCLAIMER_VERSION)
            } catch {
              // Không lưu được thì lần sau vẫn hiện lại — chấp nhận được, không chặn việc dùng app.
            }
            setAck(true)
          }}
          className="w-full py-3.5 rounded-2xl font-semibold text-[13px] mb-2"
          style={{ background: "var(--c-primary)", color: "var(--c-on-bright)" }}
        >
          Tôi đã hiểu
        </button>
      </div>
    </div>
  )
}

// Dải nhắc thường trực — rút còn MỘT dòng. Bản đầy đủ đã hiện ở màn xác nhận lần đầu; ở đây chỉ
// cần một lời nhắc không chiếm chỗ, vì nó nằm trên đầu mọi lần mở app.
function DisclaimerBar() {
  // Trước đây `truncate` trên một dòng pháp lý: máy hẹp cắt mất nửa câu, không cách nào đọc hết.
  // Bỏ truncate, cho xuống tối đa hai dòng — đổi hình dạng từ viên (rounded-full, chỉ đẹp một
  // dòng) sang khối bo góc mềm để hai dòng không trông méo.
  return (
    <p className={`${T.meta} px-3 py-1.5 ${R.box} mx-5 mb-2`} style={{ background: C.surfaceAlt, color: C.textSoft }}>
      Công cụ tham khảo — luôn kiểm tra lại trước khi thực hiện.
    </p>
  )
}

// Dòng cảnh báo nhỏ cho một ô nhập (cân nặng gõ nhầm 700 kg, chiều cao 17 cm...).
function InputWarning({ text, level }: { text: string; level: "check" | "implausible" }) {
  const color = level === "implausible" ? { bg: "var(--c-danger-soft)", fg: "var(--c-danger)" } : { bg: "var(--c-warn-soft)", fg: "var(--c-warn-icon)" }
  return (
    <p className="fade-in text-[12px] font-semibold leading-[1.45] mt-1 px-2 py-1 rounded-lg" style={{ background: color.bg, color: color.fg }}>
      {text}
    </p>
  )
}

// ─── Khung thông số bệnh nhân ─────────────────────────────────────────────────

// Một ô nhập trong khung bệnh nhân. Điểm chính: hàng nhãn có CHIỀU CAO CỐ ĐỊNH, nên dù ô bên cạnh
// có hay không có nút phụ, đáy các ô nhập vẫn nằm trên cùng một đường.
//
// Cảnh báo (vd "dữ liệu dành cho NGƯỜI LỚN") KHÔNG còn vẽ bên trong ô này nữa: ô nằm trong lưới 2
// cột nên bề ngang chỉ còn một nửa màn hình, câu cảnh báo dài bị bóp xuống 5-6 dòng chữ hẹp. Cảnh
// báo giờ vẽ ở PatientPanel, ngay dưới cả hàng, rộng bằng toàn bộ khung.
function PatientField({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <label className={`${T.label} h-4 flex items-end mb-1.5`} style={{ color: C.textSoft }}>
        {label}
      </label>
      {children}
    </div>
  )
}

function PatientPanel({ open, onToggle }: { open: boolean; onToggle: () => void }) {
  const { patient, setPatientField, resetPatient, running, abwKg, heightCm, ageYears, crcl, crclUsable } = useDosing()
  const hasData = patientHasData(patient)
  // "Bệnh nhân mới" xoá SẠCH thông số lẫn bảng đang dùng — hành động phá huỷ nhất màn hình, nên
  // bắt xác nhận hai bước như mọi nút xoá khác thay vì thực thi ngay từ một chạm.
  const [confirmReset, setConfirmReset] = useState(false)
  const confirmResetTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => () => { if (confirmResetTimer.current) clearTimeout(confirmResetTimer.current) }, [])

  const weightWarn = checkWeight(abwKg)
  const heightWarn = checkHeight(heightCm)
  const ageWarn = checkAge(ageYears)

  // "70abc" hay "1.2.9" vẫn còn NGUYÊN trong ô nhập (không tự sửa), nhưng abwKg/heightCm/ageYears
  // ở trên giờ trả về null cho các chuỗi này (parseStrictNumber) — nói rõ ra đây, kẻo trông như ô
  // trống bình thường trong khi thực ra người dùng đã gõ/dán một thứ gì đó vào.
  const weightInvalid = hasInvalidNumericInput(patient.weight)
  const heightInvalid = hasInvalidNumericInput(patient.height)
  const ageInvalid = hasInvalidNumericInput(patient.age)
  const scrInvalid = hasInvalidNumericInput(patient.scr)

  // Cân nặng dùng để ước tính CrCl: ABW nếu bình thường/thiếu cân, AdjBW nếu béo phì (ABW > 130% IBW).
  const crclWeight = useMemo(
    () => resolveDosingWeight(abwKg, heightCm, patient.sex, "adjusted"),
    [abwKg, heightCm, patient.sex],
  )

  function switchScrUnit(next: "mgdl" | "umol") {
    if (next === patient.scrUnit) return
    const s = parseStrictNumber(patient.scr)
    if (s != null) {
      const converted = next === "umol" ? s * SCR_UMOL_PER_MGDL : s / SCR_UMOL_PER_MGDL
      setPatientField("scr", (Math.round(converted * 100) / 100).toString())
    }
    setPatientField("scrUnit", next)
  }

  const crclFinalText = crclUsable && crcl != null ? String(crcl) : "—"
  const crclDisplay = useCountUp(crclUsable ? crcl : null, 0, crclFinalText)

  const summary = [
    abwKg != null ? `${abwKg} kg` : null,
    heightCm != null ? `${heightCm} cm` : null,
    patient.sex === "male" ? "Nam" : "Nữ",
    ageYears != null ? `${ageYears} tuổi` : null,
    crcl != null ? (crclUsable ? `CrCl ${crcl}` : `CrCl ${crcl} (không dùng được)`) : null,
    patient.rrt !== "none" ? RRT_LABELS[patient.rrt] : null,
  ]
    .filter(Boolean)
    .join(" · ")

  return (
    <div className="mx-5 mb-3 rounded-2xl" style={{ background: "var(--c-surface)" }}>
      <div className="flex items-center gap-2 px-4 py-3">
        <button onClick={onToggle} className="flex-1 min-w-0 min-h-[44px] flex flex-col justify-center text-left">
          <p className="text-[12px] font-bold" style={{ color: "var(--c-primary)" }}>
            Bệnh nhân hiện tại
          </p>
          <p className="text-[12px] text-slate-600 truncate mt-0.5">{hasData ? summary : "Chưa nhập thông số — chạm để nhập"}</p>
        </button>
        {hasData && (
          <button
            onClick={() => {
              if (!confirmReset) {
                setConfirmReset(true)
                tickHaptic()
                confirmResetTimer.current = setTimeout(() => setConfirmReset(false), CONFIRM_ICON_RESET_MS)
                return
              }
              if (confirmResetTimer.current) clearTimeout(confirmResetTimer.current)
              setConfirmReset(false)
              resetPatient()
              tickHaptic()
            }}
            className="flex-none min-h-[44px] px-2.5 rounded-full text-[12px] font-bold border"
            style={
              confirmReset
                ? { background: "var(--c-danger)", borderColor: "var(--c-danger)", color: "var(--c-on-bright)" }
                : { background: "var(--c-surface)", borderColor: "var(--c-danger-line)", color: "var(--c-danger)" }
            }
          >
            {confirmReset
              ? `Xoá bệnh nhân${running.length > 0 ? ` + ${running.length} thuốc?` : "?"}`
              : "Xoá bệnh nhân"}
          </button>
        )}
        <button onClick={onToggle} className="flex-none w-11 h-11 rounded-full flex items-center justify-center" style={{ background: "var(--c-surface)", color: "var(--c-primary)" }} aria-label={open ? "Thu gọn" : "Mở rộng"}>
          <span style={{ transform: open ? "rotate(180deg)" : "none", transition: "transform .15s" }}>{icons.chevronDown()}</span>
        </button>
      </div>

      {/* Trước đây `{open && <div>}` — gấp/mở khối ~700px này NHẢY TỨC THÌ, đúng khoảnh khắc "chọn
          thuốc → panel gấp lại → cuộn tới thẻ" bị giật nhiều nhất màn hình. Dùng lại kỹ thuật
          .disc-body (grid-template-rows 0fr→1fr, xem Disclosure) để chiều cao co giãn mượt. */}
      <div className="disc-body disc-body--flush" data-open={open}>
        <div className="px-4 pb-4">
          {/* Mọi ô đều có hàng nhãn CAO BẰNG NHAU (PatientField) nên đáy các ô nhập thẳng một đường.
              Trước đây ô Creatinin có thêm bộ chọn đơn vị nằm chung hàng nhãn, đẩy ô nhập của nó
              tụt xuống so với ô Chiều cao bên cạnh — nay bộ chọn đơn vị nằm cạnh ô nhập. */}
          {/* Cân nặng lên ĐẦU: đây là trường DUY NHẤT mà hầu hết máy tính liều bắt buộc phải có
              (missingReason chỉ ra đúng nó) — tuổi/creatinin chỉ cần khi tính CrCl cho kháng sinh.
              Trước đây Tuổi/Giới tính đứng đầu, đẩy Cân nặng xuống hàng thứ hai dù nó quan trọng
              hơn hẳn cho phần lớn thuốc (vận mạch, an thần... không cần CrCl). */}
          <div className="grid grid-cols-2 gap-2 mb-2">
            <PatientField label="Cân nặng (kg)">
              <input value={patient.weight} onChange={(e) => setPatientField("weight", normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 65" className={FIELD} style={FIELD_STYLE} />
            </PatientField>
            <PatientField label="Chiều cao (cm)">
              <input value={patient.height} onChange={(e) => setPatientField("height", normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 165" className={FIELD} style={FIELD_STYLE} />
            </PatientField>
          </div>
          {/* Cân nặng và chiều cao có thể cùng lúc đều cảnh báo (vd trẻ em nhẹ cân, thấp) — xếp mỗi
              cảnh báo một dòng riêng, đủ rộng để đọc trọn câu thay vì bị bóp trong nửa cột. Ký tự lạ
              (vd "70abc") ưu tiên hiện trước cảnh báo độ lớn, vì lúc đó con số còn chưa xác định được. */}
          {(
            [
              weightInvalid
                ? { key: "w", message: `Cân nặng "${patient.weight.trim()}" có ký tự không phải số — app coi như CHƯA NHẬP.`, severity: "implausible" as const }
                : weightWarn && weightWarn.severity !== "ok"
                  ? { key: "w", message: weightWarn.message, severity: weightWarn.severity }
                  : null,
              heightInvalid
                ? { key: "h", message: `Chiều cao "${patient.height.trim()}" có ký tự không phải số — app coi như CHƯA NHẬP.`, severity: "implausible" as const }
                : heightWarn && heightWarn.severity !== "ok"
                  ? { key: "h", message: heightWarn.message, severity: heightWarn.severity }
                  : null,
            ] as ({ key: string; message: string; severity: "check" | "implausible" } | null)[]
          )
            .filter((w): w is { key: string; message: string; severity: "check" | "implausible" } => w != null)
            .map((w) => (
              <div key={w.key} className="mb-2">
                <InputWarning text={w.message} level={w.severity} />
              </div>
            ))}

          {/* Tuổi + Giới tính + Creatinin: chỉ cần cho CrCl (kháng sinh chỉnh theo chức năng thận) —
              nhóm lại thành cụm "để tính CrCl", đứng sau cụm cân nặng/chiều cao dùng chung cho mọi
              thuốc. */}
          <div className="grid grid-cols-2 gap-2 mb-2">
            <PatientField label="Tuổi">
              <input value={patient.age} onChange={(e) => setPatientField("age", normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 70" className={FIELD} style={FIELD_STYLE} />
            </PatientField>
            <PatientField label="Giới tính">
              <div className="flex gap-1.5">
                {(["male", "female"] as const).map((sVal) => (
                  <button
                    key={sVal}
                    onClick={() => {
                      setPatientField("sex", sVal)
                      tickHaptic()
                    }}
                    className={`flex-1 h-11 ${R.input} ${T.chip} border dose-press`}
                    style={
                      patient.sex === sVal
                        ? { background: C.primary, borderColor: C.primary, color: "var(--c-on-bright)" }
                        : { background: C.surface, borderColor: C.primaryLine, color: C.textSoft }
                    }
                  >
                    {sVal === "male" ? "Nam" : "Nữ"}
                  </button>
                ))}
              </div>
            </PatientField>
          </div>
          {ageInvalid ? (
            <div className="mb-2">
              <InputWarning text={`Tuổi "${patient.age.trim()}" có ký tự không phải số — app coi như CHƯA NHẬP, không tính CrCl từ đây.`} level="implausible" />
            </div>
          ) : (
            ageWarn && ageWarn.severity !== "ok" && (
              <div className="mb-2">
                <InputWarning text={ageWarn.message} level={ageWarn.severity} />
              </div>
            )
          )}

          {/* Creatinin/CrCl/chức năng thận chỉ có ý nghĩa cho liều kháng sinh theo CrCl — 9 nhóm
              thuốc truyền còn lại chỉ cần cân nặng/giới tính ở trên. Gấp lại theo mặc định để
              không chặn đường xuống danh sách thuốc trên các tab đó; tự mở khi đã có dữ liệu liên
              quan (đang tra kháng sinh hoặc đã khai chức năng thận) để không giấu mất giá trị đã
              nhập. */}
          <Disclosure
            label="Creatinin · CrCl · Chức năng thận"
            alert={!crclUsable}
            defaultOpen={patient.scr.trim() !== "" || patient.rrt !== "none" || patient.akiUnstable}
          >
            <PatientField label="Creatinin">
              {/* flex-1 min-w-0: flex item mặc định min-width:auto (theo nội dung), nên ô nhập đứng
                  cạnh khối chọn đơn vị flex-none sẽ không chịu co lại dưới độ rộng nội dung của nó —
                  trên máy hẹp (iPhone), cả hàng tràn ra ngoài thẻ thay vì ô nhập co lại. Cùng lỗi và
                  cùng cách sửa đã dùng cho ô "Đặt tên công thức" trong WardRecipeChips. */}
              <div className="flex gap-1.5">
                <input value={patient.scr} onChange={(e) => setPatientField("scr", normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 1.2" className={`${FIELD} flex-1 min-w-0`} style={FIELD_STYLE} />
                {/* h-11 trên chính khung viền, không phải trên các nút bên trong — nếu không, viền
                    1px cộng thêm làm khối này cao 46px và lệch 2px so với ô nhập bên cạnh. */}
                <div className={`flex h-11 ${R.input} overflow-hidden border flex-none`} style={{ borderColor: C.primaryLine }}>
                  {(["mgdl", "umol"] as const).map((u) => (
                    <button
                      key={u}
                      onClick={() => {
                        switchScrUnit(u)
                        tickHaptic()
                      }}
                      className={`px-3 h-full ${T.chip} leading-none dose-press`}
                      style={patient.scrUnit === u ? { background: C.primary, color: "var(--c-on-bright)" } : { background: C.surface, color: "var(--c-text-muted)" }}
                    >
                      {u === "mgdl" ? "mg/dL" : "µmol/L"}
                    </button>
                  ))}
                </div>
              </div>
            </PatientField>
            {scrInvalid && (
              <div className="mt-2">
                <InputWarning text={`Creatinin "${patient.scr.trim()}" có ký tự không phải số — app coi như CHƯA NHẬP, không tính CrCl từ đây.`} level="implausible" />
              </div>
            )}

          {/* Kết quả CrCl gói trong MỘT dải thay vì con số lớn + hai đoạn chú thích rời như trước.
              mt-3 để tách hẳn khỏi ô Creatinin phía trên — trước đây dính sát nhau vì cả hai chỉ có
              margin-bottom, không có khoảng trên. */}
          <div
            className={`flex items-center gap-3 px-3 h-14 ${R.box} mt-3 mb-2`}
            style={{ background: crclUsable ? "var(--c-primary-soft)" : C.surface }}
            // Con số này tự tính lại mỗi khi gõ cân nặng/creatinin, và nó quyết định bậc liều — người
            // dùng trình đọc màn hình gõ xong một ô mà không có gì báo "CrCl vừa đổi" thì không biết
            // giá trị dùng để tính liều là bao nhiêu. aria-atomic để đọc lại TRỌN dải (số + nhãn),
            // không chỉ phần chữ vừa đổi — tránh đọc mỗi "53" trơn không rõ là số gì.
            aria-live="polite"
            aria-atomic="true"
          >
            {/* Trước đây khi crclUsable=false vẫn hiện to con số CrCl thật, chỉ đổi màu xám — quá
                yếu để nói "con số này KHÔNG được dùng chọn bậc liều". Đổi hẳn sang "—": im lặng
                còn an toàn hơn một con số đúng-về-mặt-tính-toán nhưng sai-về-mặt-lâm-sàng.
                Màu chữ dùng C.text (trung tính) chứ không phải C.primary khi dùng được — cùng lý do
                đã sửa cho SEVERITY_STYLE.ok trong lib/doseSafety.ts: con số 24px lớn nhất màn hình
                không nên bão hoà màu thương hiệu hơn một cảnh báo nguy hiểm đứng gần đó. */}
            <span className={`${T.metric} flex-none ${NUM_DOSE}`} style={{ color: crclUsable ? C.text : C.muted }}>
              {crclDisplay}
            </span>
            <div className="min-w-0">
              <p className={T.meta} style={{ color: C.textSoft }}>
                mL/phút · CrCl (Cockcroft-Gault)
                {!crclUsable && crcl != null && ` — tính được ${crcl} nhưng không dùng được`}
              </p>
              {/* Dấu "—" không bao giờ được đứng một mình — missingReason ở InfusionCalculator đã
                  làm đúng điều này (lý do + đường sửa), ô CrCl trước đây thì chưa: thiếu dữ liệu
                  chỉ hiện "—" trơn, không nói thiếu gì. */}
              {crclUsable && crcl == null && (
                // C.textSoft, không phải C.muted: đây là chữ hướng dẫn thật phải đọc được ("Cần nhập
                // X để tính"), không phải icon/placeholder — cùng lỗi và cùng cách sửa RunningPanel
                // đã tự áp dụng cho nhãn "Nòng" của chính nó (xem comment ở dưới).
                <p className={T.meta} style={{ color: C.textSoft }}>
                  {ageYears == null
                    ? "Cần nhập tuổi để tính"
                    : abwKg == null
                      ? "Cần nhập cân nặng để tính"
                      : parseStrictNumber(patient.scr) == null
                        ? "Cần nhập creatinin để tính"
                        : null}
                </p>
              )}
              {crclWeight.ibw != null && crclWeight.used != null && (
                <p className={`${T.meta} ${NUM} truncate`} style={{ color: C.textSoft }}>
                  IBW {crclWeight.ibw.toFixed(0)} kg · tính theo {crclWeight.usedLabel} {crclWeight.used.toFixed(1)} kg
                </p>
              )}
            </div>
          </div>

          {/* Chức năng thận: cờ tổn thương thận cấp và phương thức lọc gộp về MỘT hàng chip.
              "Không lọc" đứng đầu (trạng thái mặc định/phổ biến nhất) rồi mới tới AKI và các
              phương thức lọc máu — trước đây AKI đứng đầu khiến hàng chip đọc lộn thứ tự ưu tiên. */}
          <SectionLabel>Chức năng thận</SectionLabel>
          <div className="flex flex-wrap gap-1.5 mb-2">
            <button
              onClick={() => {
                setPatientField("rrt", "none")
                tickHaptic()
              }}
              className={`${CHIP} dose-press`}
              style={
                patient.rrt === "none"
                  ? { background: C.primary, borderColor: "transparent", color: "var(--c-on-bright)" }
                  : { background: "transparent", borderColor: "transparent", color: C.textSoft }
              }
            >
              {RRT_SHORT.none}
            </button>
            <button
              onClick={() => {
                setPatientField("akiUnstable", !patient.akiUnstable)
                tickHaptic()
              }}
              className={`${CHIP} dose-press`}
              style={
                patient.akiUnstable
                  ? { background: C.warnIcon, borderColor: C.warnIcon, color: "var(--c-on-bright)" }
                  : { background: "transparent", borderColor: "transparent", color: C.textSoft }
              }
            >
              AKI
            </button>
            {(Object.keys(RRT_LABELS) as RrtMode[])
              .filter((m) => m !== "none")
              .map((m) => (
                <button
                  key={m}
                  onClick={() => {
                    setPatientField("rrt", m)
                    tickHaptic()
                  }}
                  className={`${CHIP} dose-press`}
                  style={
                    patient.rrt === m
                      ? { background: C.danger, borderColor: "transparent", color: "var(--c-on-bright)" }
                      : { background: "transparent", borderColor: "transparent", color: C.textSoft }
                  }
                >
                  {RRT_SHORT[m]}
                </button>
              ))}
          </div>

          {/* Chức năng thận đã xác nhận lâu rồi mà chưa ai chạm lại — lọc máu có thể đã bắt đầu/kết
              thúc giữa ca mà tra cứu sau đó vẫn âm thầm dùng bậc liều cũ. Chỉ hiện khi đã từng được
              xác nhận ít nhất một lần (isRenalStatusStale loại bệnh nhân mới, chưa ai chạm tới). */}
          {isRenalStatusStale(patient) && (
            <div className="flex items-center gap-2 mb-2 px-2.5 py-2 rounded-xl fade-in" style={{ background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }}>
              <p className="flex-1 text-[12px] font-bold leading-[1.4]" style={{ color: "var(--c-warn)" }}>
                Chức năng thận chưa được xác nhận lại từ đầu ca — còn đúng không?
              </p>
              <button
                onClick={() => setPatientField("rrt", patient.rrt)}
                className={`flex-none h-7 px-2.5 ${R.pill} dose-press text-[12px] font-bold`}
                style={{ background: "var(--c-warn)", color: "var(--c-on-bright)" }}
              >
                Vẫn đúng
              </button>
            </div>
          )}

          {/* Tốc độ dịch thải: thiếu con số này thì mọi khuyến cáo "liều CRRT" đều thiếu vế điều kiện */}
          {needsCrrtFlow(patient.rrt) && (
            <div className="mb-2 fade-in">
              <PatientField label="Tốc độ dịch thải Qeff (L/giờ)">
                <input
                  value={patient.crrtFlowLPerH}
                  onChange={(e) => setPatientField("crrtFlowLPerH", normalizeDecimalInput(e.target.value))}
                  inputMode="decimal"
                  placeholder="VD: 2 — dịch lọc + siêu lọc"
                  className={FIELD}
                  style={FIELD_STYLE}
                />
              </PatientField>
              <p className={`${T.meta} mt-1`} style={{ color: C.textSoft }}>
                {abwKg != null && (parseStrictNumber(patient.crrtFlowLPerH) ?? 0) > 0
                  ? `Tương đương ${(((parseStrictNumber(patient.crrtFlowLPerH) as number) * 1000) / abwKg).toFixed(0)} mL/kg/giờ — so với điều kiện Qeff ghi trong liều CRRT của từng thuốc.`
                  : "Cộng tốc độ dịch lọc và tốc độ siêu lọc — liều kháng sinh trong CRRT thay đổi theo con số này."}
              </p>
            </div>
          )}

          {!crclUsable && (
            <div className={`fade-in px-3 py-2 ${R.box} flex items-start gap-2`} style={{ background: C.dangerSoft, border: `1px solid ${C.dangerLine}` }}>
              <span className="mt-0.5 flex-none" style={{ color: C.dangerIcon }}>{icons.alert()}</span>
              <p className={`${T.meta} font-semibold`} style={{ color: C.danger }}>
                {CRCL_RELIABILITY_TEXT[crclReliability(patient) as "aki" | "rrt"]}
              </p>
            </div>
          )}
          </Disclosure>
        </div>
      </div>
    </div>
  )
}

// ─── Bảng "Đang truyền" — xem nhiều thuốc cạnh nhau + tương hợp Y-site ────────
//
// Quy tắc an toàn: app CHỈ kết luận "không tương hợp"/"thận trọng". Cặp nào không có trong bảng thì
// nói rõ là chưa có dữ liệu — im lặng không bao giờ được hiểu thành "chạy chung được".

// Từng cặp một phải tự khai đã đối chiếu tài liệu gốc hay chưa — nếu chỉ có một dòng miễn trừ
// chung ở cuối bảng thì người đọc không phân biệt được mục nào chắc, mục nào còn phải kiểm.
function CompatSource({ verified, source, color }: { verified: boolean; source?: string; color: string }) {
  return (
    <p className="text-[12px] leading-[1.45] mt-1" style={{ color, opacity: 0.85 }}>
      {verified && source ? `Đã đối chiếu — nguồn: ${source}` : "CHƯA đối chiếu tài liệu gốc — dữ liệu khởi tạo của app, cần xác nhận với dược lâm sàng."}
    </p>
  )
}

function RunningPanel() {
  const { running, unpinRunning, setRunningLine, abwKg } = useDosing()
  // Đồng hồ chạy mỗi phút để dòng "3 giờ trước" không đứng yên trong suốt ca trực.
  const [now, setNow] = useState(() => Date.now())
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 60_000)
    return () => clearInterval(t)
  }, [])
  // Bỏ ghim một thuốc làm mất luôn kết quả rà tương hợp Y-site/tương tác cho cặp đó, mà người dùng
  // không hề được báo. Bấm "×" chỉ ĐÁNH DẤU chờ xoá (hàng mờ đi + nút đổi thành "Hoàn tác") — xoá
  // thật sự chỉ xảy ra sau 5 giây, đủ để bấm nhầm còn kịp sửa.
  const [pendingRemove, setPendingRemove] = useState<Record<string, true>>({})
  // Đổi nòng là thao tác HIẾM (hầu hết thuốc không bao giờ đổi nòng suốt ca), nhưng trước đây 4 chip
  // nòng luôn mở sẵn trên MỌI dòng — 4×44px + nút xoá 44px = 236/375px, tên thuốc phải truncate.
  // Nay mặc định chỉ hiện MỘT chip báo nòng hiện tại; chạm vào mới mở 4 lựa chọn, chọn xong tự đóng.
  // Chỉ một dòng mở rộng cùng lúc — mở dòng khác thì dòng cũ tự đóng, không cần nhớ đóng tay.
  const [expandedLineId, setExpandedLineId] = useState<string | null>(null)
  const pendingTimers = useRef<Record<string, ReturnType<typeof setTimeout>>>({})
  useEffect(() => () => { Object.values(pendingTimers.current).forEach(clearTimeout) }, [])
  function requestUnpin(id: string) {
    setPendingRemove((prev) => ({ ...prev, [id]: true }))
    pendingTimers.current[id] = setTimeout(() => {
      delete pendingTimers.current[id]
      setPendingRemove((prev) => {
        const { [id]: _drop, ...rest } = prev
        return rest
      })
      unpinRunning(id)
    }, 5000)
  }
  function cancelUnpin(id: string) {
    if (pendingTimers.current[id]) {
      clearTimeout(pendingTimers.current[id])
      delete pendingTimers.current[id]
    }
    setPendingRemove((prev) => {
      const { [id]: _drop, ...rest } = prev
      return rest
    })
  }
  if (running.length === 0) return null

  const lines = Array.from({ length: MAX_LINES }, (_, i) => i).filter((l) => running.some((r) => r.line === l))
  // Một mục cần xem lại khi: ghim đã lâu, HOẶC cân nặng bệnh nhân đã đổi kể từ lúc ghim (mọi tốc độ
  // mL/giờ đều tính từ cân nặng đó nên con số đang hiện không còn đúng).
  function staleReason(r: RunningDrug): string | null {
    if (r.weightKgAtPin != null && abwKg != null && Math.abs(r.weightKgAtPin - abwKg) > 0.05) {
      return `Cân nặng đã đổi ${r.weightKgAtPin} → ${abwKg} kg từ lúc ghim — tính lại tốc độ`
    }
    if (now - r.at > STALE_AFTER_MS) return "Ghim đã lâu — đối chiếu lại với bơm thật"
    return null
  }

  const ysiteFindings: { line: number; a: RunningDrug; b: RunningDrug; rule: CompatRule }[] = []
  lines.forEach((line) => {
    const onLine = running.filter((r) => r.line === line)
    for (let i = 0; i < onLine.length; i++) {
      for (let j = i + 1; j < onLine.length; j++) {
        const rule = findYsiteRule(onLine[i].compatKey, onLine[j].compatKey)
        if (rule) ysiteFindings.push({ line, a: onLine[i], b: onLine[j], rule })
      }
    }
  })

  const interactionFindings: { a: RunningDrug; b: RunningDrug; rule: InteractionRule }[] = []
  for (let i = 0; i < running.length; i++) {
    for (let j = i + 1; j < running.length; j++) {
      const rule = findInteractionRule(running[i].compatKey, running[j].compatKey)
      if (rule) interactionFindings.push({ a: running[i], b: running[j], rule })
    }
  }

  return (
    <div className="mx-5 mb-3 rounded-2xl border p-4" style={{ borderColor: "var(--c-line)", background: "var(--c-surface)" }}>
      <p className={`${T.label} mb-2`} style={{ color: "var(--c-accent)" }}>
        {/* Trước đây tên là "Đang truyền", nhưng kháng sinh mỗi 8 giờ cũng nằm trong bảng này —
            gọi một liều ngắt quãng là "đang truyền" là mô tả sai thứ đang xảy ra trên người bệnh.
            Số đếm nảy một nhịp mỗi khi đổi — ghim/bỏ ghim là hành động "thành công" chính của
            màn hình này, trước đây không có phản hồi thị giác nào khi con số đổi. */}
        Bệnh nhân đang dùng · <span key={running.length} className="pop-value inline-block">{running.length}</span> thuốc
      </p>

      {lines.map((line) => (
        <div key={line} className="mb-2.5">
          {/* text-slate-500 (→ --c-text-muted, ~5,8:1) chứ không phải -400 (→ --c-muted, ~3,1:1) —
              đây là NHÃN MỤC thật phải đọc được ("Nòng 2"...), không phải icon/placeholder. Cùng
              lỗi mà SectionLabel đã tự sửa cho chính nó nhưng chưa lan sang nhãn này. */}
          <p className="text-[12px] font-bold text-slate-500 mb-1">{lineLabel(line)}</p>
          {running
            .filter((r) => r.line === line)
            .map((r) => (
              <div
                key={r.id}
                className="rise-in flex items-start gap-2 px-2.5 py-2 rounded-xl mb-1"
                style={{ background: C.surfaceAlt, opacity: pendingRemove[r.id] ? 0.45 : 1, transition: "opacity .2s ease" }}
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5 min-w-0">
                    <p className={`${T.critical} truncate`} style={{ color: C.text }}>{r.name}</p>
                    {r.kind === "intermittent" && (
                      <span className={`${T.meta} font-bold px-1.5 rounded-full flex-none`} style={{ background: C.primarySoft, color: C.primary }}>
                        ngắt quãng
                      </span>
                    )}
                  </div>
                  <p className={T.meta} style={{ color: C.textSoft }}>
                    {r.doseText}
                    {r.rateText ? ` · ${r.rateText}` : ""}
                  </p>
                  {r.concText && <p className={T.meta} style={{ color: C.textSoft }}>{r.concText}</p>}
                  {/* Con số này CŨ tới mức nào — thiếu dòng này thì bảng trông như đang phản ánh
                      thời gian thực, trong khi nó chỉ là ảnh chụp lúc bấm ghim. */}
                  <p className={`${T.meta} ${NUM}`} style={{ color: C.textSoft }}>
                    Ghim {formatClock(r.at)} · {formatAgo(r.at, now)}
                  </p>
                  {staleReason(r) && (
                    <p className={`${T.meta} font-semibold mt-1 px-2 py-1 ${R.box}`} style={{ background: C.warnSoft, color: C.warn }}>
                      {staleReason(r)}
                    </p>
                  )}
                </div>
                <div className="flex items-center flex-none">
                  {/* Trước đây 4 chip nòng LUÔN mở trên mọi dòng — 4×44px chiếm gần 2/3 bề ngang
                      hàng, đẩy tên thuốc phải truncate dù đổi nòng là thao tác hiếm. Mặc định chỉ
                      hiện MỘT chip báo nòng hiện tại (vẫn đủ 44px, vẫn tách khỏi nút xoá bằng
                      khoảng trống rõ ràng — đeo găng/buồng tối không chạm hụt sang nút xoá đỏ);
                      chạm vào mới bung 4 lựa chọn, chọn xong tự đóng lại. */}
                  {expandedLineId === r.id ? (
                    <div className="flex items-center gap-1">
                      {Array.from({ length: MAX_LINES }, (_, i) => i).map((l) => (
                        <button
                          key={l}
                          onClick={() => {
                            setRunningLine(r.id, l)
                            setExpandedLineId(null)
                          }}
                          className="w-11 h-11 rounded-full text-[12px] font-bold border"
                          style={
                            r.line === l
                              ? { background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }
                              : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
                          }
                          aria-label={`Chuyển sang ${lineLabel(l)}`}
                        >
                          {l === 0 ? "NB" : l}
                        </button>
                      ))}
                    </div>
                  ) : (
                    <button
                      onClick={() => setExpandedLineId(r.id)}
                      className="w-11 h-11 rounded-full text-[12px] font-bold border"
                      style={{ background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }}
                      aria-label={`Đang ở ${lineLabel(r.line)} — chạm để đổi nòng`}
                    >
                      {r.line === 0 ? "NB" : r.line}
                    </button>
                  )}
                  <div className="w-4 flex-none" aria-hidden="true" />
                  {pendingRemove[r.id] ? (
                    <button
                      onClick={() => cancelUnpin(r.id)}
                      className="h-11 px-3 rounded-full flex items-center justify-center flex-none text-[12px] font-bold"
                      style={{ background: "var(--c-primary)", color: "var(--c-on-bright)" }}
                    >
                      Hoàn tác
                    </button>
                  ) : (
                    <button onClick={() => requestUnpin(r.id)} className="w-11 h-11 rounded-full flex items-center justify-center flex-none" style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }} aria-label="Bỏ khỏi bảng">
                      {icons.x()}
                    </button>
                  )}
                </div>
              </div>
            ))}
        </div>
      ))}

      {/* Khi KHÔNG có xung đột nào, cả khối này trước đây vẫn chiếm sáu dòng chữ để nói "không tìm
          thấy gì" — nay thu về một dải xanh một dòng. Có xung đột thì khối tự bung ra. */}
      {ysiteFindings.length === 0 && interactionFindings.length === 0 ? (
        <div className="pt-2 border-t" style={{ borderColor: C.lineSoft }}>
          <Disclosure label="Tương hợp · Tương tác">
            <p className={T.meta} style={{ color: C.textSoft }}>{COMPAT_DISCLAIMER}</p>
          </Disclosure>
          <p className={`${T.meta} flex items-center gap-1.5 mt-2 px-2.5 py-1.5 ${R.box}`} style={{ background: C.accentSoft, color: C.accent }}>
            <span className="flex-none scale-90">{icons.check()}</span>
            Chưa thấy xung đột nào trong bảng dữ liệu của app
          </p>
        </div>
      ) : (
      <div className="pt-2 border-t" style={{ borderColor: "var(--c-line-soft)" }}>
        <p className="text-[12px] font-bold mb-1.5 text-slate-500">Chạy chung nòng (Y-site)</p>
        {ysiteFindings.length === 0 ? (
          <p className="text-[12px] text-slate-500 leading-[1.45]">Không tìm thấy cặp nào trong bảng dữ liệu của app.</p>
        ) : (
          ysiteFindings.map((f, i) => {
            const danger = f.rule.verdict === "incompatible"
            const fg = danger ? "var(--c-danger-deep)" : "var(--c-warn)"
            return (
              <div
                key={i}
                className="fade-in flex items-start gap-2 px-2.5 py-2 rounded-xl mb-1.5"
                style={danger ? { background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-line)" } : { background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }}
              >
                <span className="mt-0.5 flex-none" style={{ color: danger ? "var(--c-danger-icon)" : "var(--c-warn-icon)" }}>{icons.alert()}</span>
                <div>
                  <p className={T.critical} style={{ color: fg }}>
                    {danger ? "KHÔNG tương hợp" : "Thận trọng"} — {f.a.name} + {f.b.name} ({lineLabel(f.line)})
                  </p>
                  <p className={`${T.meta} mt-0.5`} style={{ color: fg }}>{f.rule.text}</p>
                  <CompatSource verified={f.rule.verified} source={f.rule.source} color={fg} />
                </div>
              </div>
            )
          })
        )}

        <p className="text-[12px] font-bold mb-1.5 mt-2.5 text-slate-500">Tương tác thuốc</p>
        {interactionFindings.length === 0 ? (
          <p className="text-[12px] text-slate-500 leading-[1.45]">Không tìm thấy cặp nào trong bảng dữ liệu của app.</p>
        ) : (
          interactionFindings.map((f, i) => {
            const danger = f.rule.severity === "cao"
            const fg = danger ? "var(--c-danger-deep)" : "var(--c-warn)"
            return (
              <div
                key={i}
                className="fade-in flex items-start gap-2 px-2.5 py-2 rounded-xl mb-1.5"
                style={danger ? { background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-line)" } : { background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }}
              >
                <span className="mt-0.5 flex-none" style={{ color: danger ? "var(--c-danger-icon)" : "var(--c-warn-icon)" }}>{icons.alert()}</span>
                <div>
                  <p className="text-[12px] font-bold leading-[1.45]" style={{ color: fg }}>
                    {f.a.name} + {f.b.name}
                  </p>
                  <p className="text-[12px] leading-[1.45] mt-0.5" style={{ color: fg }}>{f.rule.text}</p>
                  <CompatSource verified={f.rule.verified} source={f.rule.source} color={fg} />
                </div>
              </div>
            )
          })
        )}

        <p className="text-[12px] leading-[1.45] mt-2 px-2 py-1.5 rounded-lg" style={{ background: "var(--c-surface-alt)", color: "var(--c-text-muted)" }}>
          {COMPAT_DISCLAIMER}
        </p>
      </div>
      )}
    </div>
  )
}

// ─── Nhật ký tính toán ────────────────────────────────────────────────────────

// Chọn được TỪNG mục. Trước đây chỉ có hai nút "Sao chép" và "Xoá nhật ký", cả hai đều tác động
// lên toàn bộ 200 mục: muốn dán một phép tính vào bệnh án thì phải dán cả nhật ký rồi cắt tay, và
// muốn bỏ một phép tính nháp thì phải xoá sạch lịch sử của cả ca trực.
//
// Mặc định là KHÔNG chọn gì; lúc đó hai nút tác động lên toàn bộ như cũ, nên người chỉ cần thao tác
// nhanh không phải học thêm gì. Chạm vào một mục là bật chế độ chọn.
function CalcLogSheet({ entries, onClear, onRemove, onClose }: { entries: CalcLogEntry[]; onClear: () => void; onRemove: (ids: Set<string>) => void; onClose: () => void }) {
  const [copied, setCopied] = useState(false)
  const [selected, setSelected] = useState<Set<string>>(() => new Set())
  const [confirmDelete, setConfirmDelete] = useState(false)
  const panelRef = useRef<HTMLDivElement | null>(null)
  // Sheet này CÓ đường thoát rõ ràng (nút "Đóng" + chạm ra ngoài) nên Esc hợp lý ở đây, khác
  // DisclaimerGate — bẫy Tab để không lọt ra danh sách thuốc đang bị che phía sau.
  useDialogFocus(panelRef, { onEscape: onClose })

  // Mục đã chọn có thể bị xoá khỏi danh sách (hoặc rơi khỏi mốc 200) — bỏ id "mồ côi" khỏi vùng
  // chọn, nếu không số đếm trên nút sẽ nói dối.
  useEffect(() => {
    setSelected((prev) => {
      const alive = new Set(entries.map((e) => e.id))
      const next = new Set([...prev].filter((id) => alive.has(id)))
      return next.size === prev.size ? prev : next
    })
  }, [entries])
  useEffect(() => setConfirmDelete(false), [selected])

  const hasSelection = selected.size > 0
  const target = hasSelection ? entries.filter((e) => selected.has(e.id)) : entries
  const allSelected = entries.length > 0 && selected.size === entries.length

  function toggle(id: string) {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
    tickHaptic()
  }

  return (
    <div className="absolute inset-0 z-40 flex flex-col fade-in" style={{ background: "var(--c-scrim)" }}>
      <button className="flex-1" onClick={onClose} aria-label="Đóng nhật ký" />
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="calclog-title"
        className="mind-sheet rounded-t-3xl flex flex-col"
        style={{ background: "var(--c-surface)", maxHeight: "78%" }}
      >
        <div className="flex items-center justify-between px-5 pt-4 pb-2">
          <p id="calclog-title" className="text-[13px] font-bold text-slate-900">Nhật ký tính toán</p>
          <button onClick={onClose} className="w-11 h-11 rounded-full flex items-center justify-center" style={{ background: "var(--c-line-soft)", color: "var(--c-text-soft)" }} aria-label="Đóng">
            {icons.x()}
          </button>
        </div>
        <div className="flex items-center gap-2 px-5 pb-2">
          <p className={`${T.meta} flex-1`} style={{ color: C.textSoft }}>
            {hasSelection
              ? `Đã chọn ${selected.size}/${entries.length} — hai nút bên dưới chỉ tác động lên phần đã chọn.`
              : "Chạm vào một mục để chọn riêng. Chưa chọn gì thì nút bên dưới áp dụng cho toàn bộ."}
          </p>
          {entries.length > 0 && (
            <button
              onClick={() => {
                setSelected(allSelected ? new Set() : new Set(entries.map((e) => e.id)))
                tickHaptic()
              }}
              className={`${BTN_SM} flex-none`}
              style={{ borderColor: C.line, color: C.primary }}
            >
              {allSelected ? "Bỏ chọn" : "Chọn tất cả"}
            </button>
          )}
        </div>
        <div className="scroll-ios flex-1 px-5 pb-3">
          {entries.length === 0 ? (
            <p className="text-[13px] text-slate-400 text-center py-8">Chưa có phép tính nào được lưu.</p>
          ) : (
            entries.map((e) => {
              const on = selected.has(e.id)
              return (
                <button
                  key={e.id}
                  onClick={() => toggle(e.id)}
                  aria-pressed={on}
                  className="w-full text-left p-3 rounded-2xl border mb-2 flex gap-2.5 items-start"
                  style={on ? { borderColor: C.primary, background: C.primarySoft } : { borderColor: C.line }}
                >
                  {/* Ô đánh dấu vẽ tay thay vì <input type=checkbox>: cả thẻ đã là vùng chạm 44px,
                      thêm một ô bấm được nữa bên trong chỉ tạo ra hai đích chạm chồng nhau. */}
                  <span
                    className="flex-none w-5 h-5 mt-0.5 rounded-md border flex items-center justify-center"
                    style={on ? { background: C.primary, borderColor: C.primary, color: "var(--c-on-bright)" } : { borderColor: C.line }}
                  >
                    {on && <span className="scale-[0.6]">{icons.check()}</span>}
                  </span>
                  <span className="flex-1 min-w-0">
                    <span className="flex items-baseline justify-between gap-2">
                      <span className={`${T.meta} font-bold truncate`} style={{ color: C.text }}>{e.drug}</span>
                      <span className={`${T.meta} flex-none`} style={{ color: C.textSoft }}>{formatLogTime(e.at)}</span>
                    </span>
                    <span className={`${T.meta} block`} style={{ color: C.textSoft }}>
                      {CALC_KIND_LABELS[e.kind]}
                      {e.patient ? ` · ${e.patient}` : ""}
                      {e.weightKg != null ? ` · ${e.weightKg} kg` : ""}
                    </span>
                    {e.inputs.map((line, i) => (
                      <span key={i} className={`${T.meta} block`} style={{ color: C.textSoft }}>
                        {line}
                      </span>
                    ))}
                    <span className={`${T.meta} font-bold block mt-0.5`} style={{ color: C.primary }}>
                      → {e.output}
                    </span>
                    {e.flag && (
                      <span className={`${T.meta} font-semibold block mt-1 px-2 py-1 ${R.box}`} style={{ background: C.dangerSoft, color: C.danger }}>
                        {e.flag}
                      </span>
                    )}
                  </span>
                </button>
              )
            })
          )}
        </div>
        <div className="flex-none flex gap-2 px-5 pt-2 border-t" style={{ borderColor: "var(--c-line)", paddingBottom: "var(--nav-pad-bottom)" }}>
          <button
            onClick={async () => {
              try {
                await navigator.clipboard.writeText(calcLogToText(target))
                setCopied(true)
                setTimeout(() => setCopied(false), 1500)
              } catch {
                // Trình duyệt chặn clipboard: không làm gì, nút vẫn giữ nguyên nhãn.
              }
            }}
            disabled={target.length === 0}
            className="flex-1 py-3 rounded-2xl font-semibold text-[13px] border"
            style={{ borderColor: C.line, color: target.length === 0 ? C.muted : C.primary }}
          >
            {copied ? "Đã sao chép" : hasSelection ? `Sao chép ${selected.size} mục` : "Sao chép tất cả"}
          </button>
          {/* Xoá cần một nhịp xác nhận, nhưng KHÔNG dùng hộp thoại: nút tự đổi thành "Chắc chắn xoá?"
              rồi mới thực hiện ở lần chạm thứ hai — bỏ tay ra khỏi nút là quên (xem useEffect trên). */}
          <button
            onClick={() => {
              if (!confirmDelete) {
                setConfirmDelete(true)
                return
              }
              if (hasSelection) {
                onRemove(selected)
                setSelected(new Set())
              } else {
                onClear()
              }
              setConfirmDelete(false)
              tickHaptic()
            }}
            onBlur={() => setConfirmDelete(false)}
            disabled={target.length === 0}
            className="flex-1 py-3 rounded-2xl font-semibold text-[13px] border"
            style={
              target.length === 0
                ? { borderColor: C.dangerLine, color: "var(--c-disabled-fg)" }
                : confirmDelete
                  ? { borderColor: C.dangerIcon, background: C.dangerSoft, color: C.danger }
                  : { borderColor: C.dangerLine, color: C.danger }
            }
          >
            {confirmDelete ? "Chắc chắn xoá?" : hasSelection ? `Xoá ${selected.size} mục` : "Xoá tất cả"}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── Antibiotics — chỉnh liều theo độ lọc cầu thận ────────────────────────────

// Cảnh báo/tương tác của một thuốc — dùng chung cho AntibioticDoseCard và InfusionDrugCard.
// Trước đây "cao" và "trung bình" chỉ khác nhau ở màu một chấm tròn 1.5px — rất dễ lướt qua và
// bỏ sót cảnh báo mức cao. Giờ mức "cao" có khung nền đỏ nhạt + icon cảnh báo + chữ đậm màu đỏ,
// tách hẳn khỏi mức "trung bình" (vẫn giữ kiểu chấm nhỏ, không cần nổi bật bằng).
// `bare` = đã có tiêu đề mục ở ngoài (khối gấp/mở) nên không vẽ lại đường kẻ và tiêu đề riêng.
function DrugWarnings({ warnings, bare }: { warnings?: AntibioticWarning[]; bare?: boolean }) {
  if (!warnings || warnings.length === 0) return null
  return (
    <div className={bare ? "space-y-1.5" : "mt-3 pt-3 border-t space-y-1.5"} style={bare ? undefined : { borderColor: "var(--c-line-soft)" }}>
      {!bare && <p className="text-[12px] font-bold" style={{ color: "var(--c-warn-icon)" }}>Lưu ý / tương tác</p>}
      {warnings.map((w, i) =>
        w.severity === "cao" ? (
          <div key={i} className="flex items-start gap-2 px-2.5 py-2 rounded-xl" style={{ background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-line)" }}>
            <span className="mt-0.5 flex-none" style={{ color: "var(--c-danger-icon)" }}>{icons.alert()}</span>
            {/* Cảnh báo mức CAO dùng cỡ chữ chính (13px), không phải cỡ chú thích 11px như phần còn
                lại: đây là dòng chữ mà việc bỏ sót gây hại nhất, nó không được nhỏ hơn chữ mô tả. */}
            <p className={`${T.bodyStrong}`} style={{ color: "var(--c-danger-deep)" }}>{w.text}</p>
          </div>
        ) : (
          <div key={i} className="flex items-start gap-1.5">
            <span className="mt-1.5 w-1.5 h-1.5 rounded-full flex-none" style={{ background: "var(--c-warn-icon)" }} />
            <p className="text-[12px] text-slate-600 leading-[1.45]">{w.text}</p>
          </div>
        ),
      )}
    </div>
  )
}

// Gộp danh sách dựng sẵn với các bản người dùng tự lưu (cùng khoá lưu trữ dùng cho cả mục tự
// thêm mới VÀ mục "sửa" một thuốc dựng sẵn — cả hai đều nằm trong cùng collection tự nhập, phân
// biệt bằng việc id có trùng với một mục dựng sẵn hay không). Mục có id trùng với dựng sẵn sẽ
// THAY THẾ mục dựng sẵn tại đúng vị trí cũ (hiển thị bản đã sửa, không hiện cả hai bản); mục có id
// mới hoàn toàn được thêm vào cuối, như một thuốc tự nhập bình thường.
function mergeWithOverrides<T extends { id: string }>(staticList: T[], stored: T[]): T[] {
  const storedById = new Map(stored.map((d) => [d.id, d]))
  const merged = staticList.map((d) => storedById.get(d.id) ?? d)
  const staticIds = new Set(staticList.map((d) => d.id))
  // Lọc theo id đã thấy, không chỉ theo staticIds: nếu `stored` lỡ chứa hai bản ghi cùng id (id sinh
  // theo Date.now() nên hai lần thêm trong cùng một mili-giây là trùng, và một file nhập vào cũng có
  // thể tự trùng bên trong nó), vòng lặp cũ đẩy CẢ HAI vào danh sách — người dùng thấy hai thẻ thuốc
  // y hệt nhau, và React nhận hai phần tử cùng `key` nên sửa thẻ này lại đổi thẻ kia.
  const seen = new Set(staticIds)
  const newOnly: T[] = []
  stored.forEach((d) => {
    if (seen.has(d.id)) return
    seen.add(d.id)
    newOnly.push(d)
  })
  return [...merged, ...newOnly]
}

// Id của các kháng sinh dựng sẵn — dùng để nhận biết một mục trong collection tự lưu là bản "sửa
// lại" của thuốc dựng sẵn (id trùng) hay là thuốc hoàn toàn mới do người dùng tự thêm (id không trùng).
const STATIC_ANTIBIOTIC_IDS = new Set(ANTIBIOTICS.map((d) => d.id))

function tierFor(tiers: DoseTier[], crcl: number | null): DoseTier {
  const sorted = [...tiers].sort((a, b) => b.min - a.min)
  // Chưa có CrCl: luôn lấy mức có CrCl tối thiểu CAO NHẤT (liều chuẩn/thận bình thường) làm mặc định,
  // bất kể thứ tự người dùng nhập các mức — quan trọng vì "Chỉ định riêng theo bệnh lý" cho phép
  // thêm mức liều tự do, không đảm bảo luôn nhập theo thứ tự CrCl giảm dần.
  if (crcl == null) return sorted[0]
  return sorted.find((t) => crcl >= t.min) ?? sorted[sorted.length - 1]
}

// ─── Bảng pha kháng sinh ───────────────────────────────────────────────────────
// Kháng sinh không có tốc độ truyền để chỉnh — liều là một con số cố định mỗi lần dùng, không
// titrate như thuốc vận mạch — nên câu hỏi lúc pha khác hẳn: không phải "đặt bơm bao nhiêu", mà là
// "hoàn nguyên/pha loãng thế nào ra đúng nồng độ, có vượt ngưỡng trên không, và truyền trong bao
// lâu". Dùng lại đúng bộ hàm tính + kiểm tra vật lý của lib/mixing.ts (cùng bản chất phép tính, chỉ
// khác chỗ dùng), và dùng lại kho "công thức của bạn" (wardRecipes) — antibiotic.id cũng là một
// drugId hợp lệ trong kho đó.

// Một thuốc giờ có NHIỀU công thức đã lưu + một công thức HỆ THỐNG (mặc định dựng sẵn của app) —
// ba nơi hiển thị công thức pha (AntibioticDoseCard, AntibioticMixPanel, InfusionCalculator) đều
// cần cùng một khái niệm "công thức nào đang được xem/áp dụng" để chuyển đổi qua lại. Trước đây
// mỗi nơi tự suy "công thức đang áp dụng" = công thức lưu GẦN NHẤT (wardList[wardList.length-1]) —
// không có chỗ nào nhớ người dùng vừa BẤM chọn công thức nào, nên bấm sang một công thức cũ hơn chỉ
// nạp giá trị vào form chứ không có gì đánh dấu nó đang "đang chọn", và không có cách nào quay lại
// công thức hệ thống mà không XOÁ hẳn công thức đã lưu. `activeId` ở đây có thể là id một công thức
// đã lưu, hoặc chuỗi "system" — undefined `active` nghĩa là công thức hệ thống đang được chọn.
function useActiveWardRecipe(wardList: WardRecipe[]): {
  activeId: string
  setActiveId: (id: string) => void
  active: WardRecipe | undefined
} {
  // Công thức ĐƯỢC GHIM (nếu có) thắng "lưu gần nhất" khi chọn công thức mở mặc định — xem
  // setPinnedWardRecipe trong lib/wardRecipes.ts. Không có công thức nào được ghim thì hành vi y hệt
  // trước đây (lưu gần nhất thắng).
  const fallbackId = (list: WardRecipe[]) => list.find((w) => w.pinned)?.id ?? list[list.length - 1]?.id ?? "system"
  const [activeId, setActiveId] = useState<string>(() => fallbackId(wardList))
  // Theo dõi id của lần render trước để phát hiện: (a) vừa có công thức MỚI được lưu (id chưa từng
  // thấy) → tự chuyển sang xem công thức đó luôn, khỏi bấm thêm một lần nữa; (b) công thức đang xem
  // vừa bị xoá (id không còn nằm trong danh sách) → rơi về công thức được ghim, hoặc mới nhất còn
  // lại, hoặc hệ thống nếu danh sách rỗng — tránh treo activeId trỏ vào một công thức không còn tồn tại.
  const prevIdsRef = useRef<string[]>(wardList.map((w) => w.id))
  useEffect(() => {
    const prevIds = prevIdsRef.current
    const newlyAdded = wardList.find((w) => !prevIds.includes(w.id))
    if (newlyAdded) {
      setActiveId(newlyAdded.id)
    } else if (activeId !== "system" && !wardList.some((w) => w.id === activeId)) {
      setActiveId(fallbackId(wardList))
    }
    prevIdsRef.current = wardList.map((w) => w.id)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wardList])
  const active = activeId === "system" ? undefined : wardList.find((w) => w.id === activeId)
  return { activeId, setActiveId, active }
}

// Hàng chip "công thức pha" dùng chung ở ba chỗ (AntibioticDoseCard, AntibioticMixPanel,
// InfusionCalculator) — mỗi chỗ đều cần: chip "Công thức hệ thống" để chuyển về, chip mỗi công thức
// đã lưu (bấm để nạp), sao ghim (mặc định cố định, thắng "lưu gần nhất" — xem useActiveWardRecipe),
// và nút xoá hai chạm. Khi một thuốc có nhiều công thức đã lưu (dùng chung máy giữa nhiều khoa), hàng
// chip dễ dài tràn — thêm ô lọc theo tên khi vượt quá một ngưỡng, thay vì bắt cuộn ngang dò cả dãy.
function WardRecipeChips({
  wardList,
  activeId,
  onSelectSystem,
  onSelectWard,
  onDelete,
  onPin,
}: {
  wardList: WardRecipe[]
  activeId: string
  onSelectSystem: () => void
  onSelectWard: (w: WardRecipe) => void
  onDelete: (recipeId: string) => void
  onPin: (recipeId: string) => void
}) {
  const [filter, setFilter] = useState("")
  const q = normalizeSearch(filter)
  const shown = q ? wardList.filter((w) => normalizeSearch(w.title || "công thức đã lưu").includes(q)) : wardList
  const pill = (on: boolean) =>
    on
      ? { background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }
      : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }

  return (
    <div className="mb-2">
      <label className={`${T.label} text-slate-500 mb-1 block`}>Công thức pha — bấm để chuyển đổi</label>
      {wardList.length > 6 && (
        <input
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          placeholder="Lọc theo tên công thức..."
          className="w-full h-11 px-2.5 mb-1.5 rounded-full text-[12px] border outline-none"
          style={{ borderColor: "var(--c-line)", background: "var(--c-surface)" }}
        />
      )}
      <div className="flex flex-wrap gap-2">
        {/* Công thức HỆ THỐNG luôn là một lựa chọn để chuyển VỀ, không chỉ để xoá hẳn công thức đã
            lưu mới quay lại được — không lọc theo ô tìm ở trên vì nó không có tên để so khớp. */}
        <button onClick={onSelectSystem} className="h-11 px-3 rounded-full text-[12px] font-semibold border" style={pill(activeId === "system")}>
          Công thức hệ thống
        </button>
        {shown.map((w) => (
          <span
            key={w.id}
            // h-11 (không phải h-9): pill này gộp BA vùng chạm (chọn/ghim/xoá) trên cùng một chiều
            // cao — chiều cao cha thấp thì hai nút phụ (ghim/xoá, chỉ rộng px-1.5/px-2.5) co xuống
            // dưới 44px trên cả hai chiều, chạm nhầm dễ nhất trong cả cụm.
            className="inline-flex items-center h-11 rounded-full border overflow-hidden"
            style={{ borderColor: activeId === w.id ? "var(--c-accent)" : "var(--c-accent-line)" }}
          >
            <button
              onClick={() => onSelectWard(w)}
              className="h-full pl-3 pr-1.5 text-[12px] font-semibold max-w-[140px] truncate"
              style={activeId === w.id ? { color: "var(--c-on-bright)", background: "var(--c-accent)" } : { color: "var(--c-accent-deep)", background: "var(--c-surface)" }}
            >
              {w.title || "Công thức đã lưu"}
            </button>
            {/* Ghim làm mặc định cố định — độc lập với "lưu gần nhất". Chỉ một công thức được ghim
                mỗi thuốc, bấm sao đang sáng để gỡ ghim (xem setPinnedWardRecipe). */}
            <button
              onClick={() => onPin(w.id)}
              aria-label={w.pinned ? `Gỡ ghim công thức ${w.title}` : `Ghim công thức ${w.title} làm mặc định`}
              className="h-full px-1.5 flex-none flex items-center justify-center"
              style={activeId === w.id ? { background: "var(--c-accent)" } : { background: "var(--c-surface)" }}
            >
              <span style={{ opacity: w.pinned ? 1 : 0.3 }}>{icons.star()}</span>
            </button>
            {/* Đây là công thức ĐÃ LƯU từ phiên trước, không phải một dòng đang soạn dở — nên xoá
                cần xác nhận hai chạm giống xoá kháng sinh/bài viết tự nhập, không phải nút "×" tức
                thì (nút đó dành cho dòng nháp chưa lưu, xem chú thích ConfirmIconButton phía trên:
                trước đây liệt "công thức pha" nhầm vào nhóm đó). */}
            <ConfirmIconButton
              onConfirm={() => onDelete(w.id)}
              ariaLabel={`Xoá công thức ${w.title}`}
              className="h-full px-2.5 flex-none flex items-center justify-center"
              style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }}
            />
          </span>
        ))}
        {shown.length === 0 && <p className="text-[12px] text-slate-400 py-1.5">Không có công thức nào khớp "{filter}".</p>}
      </div>
    </div>
  )
}

// Cảnh báo tương kỵ Y-site/tương tác NGAY LÚC ĐANG PHA — trước đây bảng tương hợp chỉ chạy ở màn
// "Bệnh nhân đang dùng" (RunningPanel), so hai thuốc ĐÃ ghim cùng nòng. Vô dụng đúng lúc cần nhất:
// người đang đứng pha Noradrenaline chưa ghim gì cả, nên không có "hai thuốc cùng nòng" nào để so —
// phải tự nhớ ra rồi mở màn khác kiểm tra. Ở đây so compatKey của thuốc đang xem với TỪNG thuốc đã
// ghim (bất kể đang ở nòng nào — người dùng tự quyết định chọn nòng nào sau khi thấy cảnh báo), không
// đợi đến lúc ghim xong mới biết.
function CompatWarningForDrug({ compatKey, ownDrugId }: { compatKey?: string; ownDrugId: string }) {
  const { running } = useDosing()
  if (!compatKey) return null
  const others = running.filter((r) => r.drugId !== ownDrugId)
  const ysite = others
    .map((r) => ({ r, rule: findYsiteRule(compatKey, r.compatKey) }))
    .filter((x): x is { r: RunningDrug; rule: CompatRule } => x.rule != null)
  const interactions = others
    .map((r) => ({ r, rule: findInteractionRule(compatKey, r.compatKey) }))
    .filter((x): x is { r: RunningDrug; rule: InteractionRule } => x.rule != null)
  if (ysite.length === 0 && interactions.length === 0) return null

  const danger = ysite.some((x) => x.rule.verdict === "incompatible") || interactions.some((x) => x.rule.severity === "cao")
  const style = danger
    ? { bg: "var(--c-danger-soft)", border: "var(--c-danger-line)", text: "var(--c-danger-deep)" }
    : { bg: "var(--c-warn-soft)", border: "var(--c-warn-line)", text: "var(--c-warn)" }

  return (
    <div className="fade-in mt-2 px-3 py-2.5 rounded-xl" style={{ background: style.bg, border: `1px solid ${style.border}` }}>
      <div className="flex items-start gap-2">
        <span className="mt-0.5 flex-none" style={{ color: style.text }}>{icons.alert()}</span>
        <div className="flex-1 min-w-0">
          <p className="text-[12px] font-extrabold leading-[1.3]" style={{ color: style.text }}>
            {danger ? "KHÔNG TƯƠNG HỢP VỚI THUỐC ĐANG DÙNG" : "THẬN TRỌNG VỚI THUỐC ĐANG DÙNG"} — kiểm tra nòng trước khi ghim
          </p>
          {ysite.map(({ r, rule }, i) => (
            <p key={`y-${i}`} className="text-[12px] leading-[1.45] mt-1" style={{ color: style.text }}>
              <b>{r.name}</b> ({lineLabel(r.line)}){rule.verdict === "incompatible" ? " — KHÔNG tương hợp Y-site" : " — thận trọng Y-site"}: {rule.text}
              {!rule.verified && " (chưa đối chiếu tài liệu gốc)"}
            </p>
          ))}
          {interactions.map(({ r, rule }, i) => (
            <p key={`i-${i}`} className="text-[12px] leading-[1.45] mt-1" style={{ color: style.text }}>
              <b>{r.name}</b> — tương tác mức {rule.severity}: {rule.text}
              {!rule.verified && " (chưa đối chiếu tài liệu gốc)"}
            </p>
          ))}
        </div>
      </div>
    </div>
  )
}

function AntibioticMixPanel({
  drug,
  doseTargetMg,
  routeShort,
  setRouteShort,
}: {
  drug: Antibiotic
  doseTargetMg?: CappedDose | null
  // "Đường dùng" (TTM/TMC/IM/SC) — TRƯỚC ĐÂY panel này tự giữ state riêng và hiện chip chọn ở đây
  // (sau cả mục Dung môi), lấn át mục "Đường dùng" ngoài thẻ AntibioticDoseCard. Nay panel chỉ
  // ĐỌC/GHI state của cha (nhấc lên AntibioticDoseCard) để cả thẻ dùng chung đúng một đường dùng.
  routeShort: AdminRoute
  setRouteShort: (r: AdminRoute) => void
}) {
  const { logCalc, wardRecipes, saveWard, clearWard, pinWard } = useDosing()
  const wardList = wardRecipes[drug.id] ?? []
  // Công thức ĐANG XEM — có thể là một công thức đã lưu, hoặc công thức HỆ THỐNG (xem
  // useActiveWardRecipe phía trên) — bấm chip tương ứng để nạp lại giá trị của nó vào form đang mở
  // (xem loadWard()/loadSystemDefault() bên dưới).
  const { activeId: activeRecipeId, setActiveId: setActiveRecipeId, active: ward } = useActiveWardRecipe(wardList)
  const mix = drug.mix
  const concUnit = mix?.concUnit ?? "mg/mL"
  const concMass = massOfConcUnit(concUnit)
  const vialLabel = mix?.vialLabel ?? "lọ"
  // Đường dùng mặc định của thuốc — chỉ dùng khi CHƯA có công thức đã lưu nào tự khai đường riêng
  // (xem loadWard()/loadSystemDefault() bên dưới, vẫn cần hằng số này để reset khi đổi công thức).
  const defaultRoute: AdminRoute = inferAdminRoutes(drug.route)[0] ?? "TTM"

  const [vialAmount, setVialAmount] = useState(String(ward?.vialAmount ?? mix?.vialAmount ?? ""))
  const [vialUnit, setVialUnit] = useState(ward?.vialUnit ?? mix?.vialUnit ?? concMass)
  const [vials, setVials] = useState(String(ward?.vials ?? 1))
  const [vialForm, setVialForm] = useState<VialForm>(ward?.vialForm ?? mix?.vialForm ?? "powder")
  const [vialVolume, setVialVolume] = useState(
    ward?.vialVolumeMl != null ? String(ward.vialVolumeMl) : mix?.vialVolumeMl != null ? String(mix.vialVolumeMl) : "",
  )
  const [reconstitute, setReconstitute] = useState(
    ward?.reconstituteMl != null ? String(ward.reconstituteMl) : mix?.reconstituteMl != null ? String(mix.reconstituteMl) : "",
  )
  const [displacement, setDisplacement] = useState(
    ward?.displacementMl != null ? String(ward.displacementMl) : mix?.displacementMl != null ? String(mix.displacementMl) : "",
  )
  const [volume, setVolume] = useState(String(ward?.volumeMl ?? 100))
  const [diluent, setDiluent] = useState(ward?.diluent ?? mix?.diluents?.[0] ?? "NaCl 0,9%")
  // Chai cố định hàm lượng: liều cần LẤY (bỏ trống = dùng trọn chai) — không pha loãng thêm nên
  // không dùng chung ô "Pha loãng tới"/"Dung môi" của hai dạng kia.
  const [fixedDoseAmount, setFixedDoseAmount] = useState("")
  // Giọt/phút: máy tính sống, không thuộc dữ liệu thuốc — nhập thời gian truyền dự kiến là ra ngay.
  const [infuseMinutes, setInfuseMinutes] = useState("")
  const [dropFactor, setDropFactor] = useState(DEFAULT_DROP_FACTOR)
  // Đường TTM có hai thiết bị truyền: dây thường (đếm giọt) hoặc bơm tiêm điện/bơm thể tích (đặt
  // mL/giờ) — vancomycin và một số kháng sinh khác BẮT BUỘC chạy bơm vì tốc độ quá chậm để đếm giọt
  // chính xác (vd 1 g/60 phút ở 100 mL chỉ ~33 giọt/phút, sai số đếm tay đáng kể). Xem lib/mixing.ts.
  const [deliveryDevice, setDeliveryDevice] = useState<"drip" | "pump">(ward?.deliveryDevice ?? "drip")
  // Vài khoa hoàn nguyên/gộp nhiều lọ-chai rồi RÚT BỚT dung dịch dư ra (cho phép số lọ lẻ như 1,5),
  // vài khoa chỉ dùng NGUYÊN số lọ/chai đã mở (bắt buộc số nguyên) — mặc định KHÔNG cho rút, vì "1,5
  // lọ" chỉ hợp lý khi khoa thật sự làm thao tác đó. Xem WardRecipe.allowWithdraw.
  const [allowWithdraw, setAllowWithdraw] = useState(ward?.allowWithdraw ?? false)
  const [saveTitle, setSaveTitle] = useState("")

  // Không khai `diluents` riêng (đa số kháng sinh tự nhập, chưa ai điền công thức pha chuẩn) thì cho
  // chọn cả ba dung môi thường gặp nhất — trước đây chỉ có NaCl 0,9%/Glucose 5%, thiếu hẳn Nước cất
  // pha tiêm (dung môi hoàn nguyên rất phổ biến cho lọ bột trước khi pha loãng tiếp).
  const allowedDiluents = mix?.diluents ?? ["NaCl 0,9%", "Glucose 5%", "Nước cất pha tiêm"]
  const avoidDiluents = mix?.avoidDiluents ?? []
  const diluentBlocked = avoidDiluents.includes(diluent)
  const unitChoices = useMemo(() => MIX_UNIT_CHOICES.filter((u) => massFactor(u, concMass) != null), [concMass])

  const va = parseFloat(vialAmount)
  const nv = parseFloat(vials)
  const vol = parseFloat(volume)
  const num = (s: string) => {
    const n = parseFloat(s)
    return isNaN(n) || n < 0 ? null : n
  }
  const spec: VialSpec = useMemo(
    () => ({
      form: vialForm,
      volumeMl: vialForm !== "powder" ? num(vialVolume) : null,
      reconstituteMl: vialForm === "powder" ? num(reconstitute) : null,
      displacementMl: vialForm === "powder" ? num(displacement) : null,
    }),
    [vialForm, vialVolume, reconstitute, displacement],
  )

  const isFixed = vialForm === "fixed"
  const fixedDoseNum = num(fixedDoseAmount)
  const fixedVialVolume = num(vialVolume)
  // Chai cố định hàm lượng có thể cần GỘP NHIỀU CHAI khi liều cần vượt một chai (xem
  // applyFixedSuggestion bên dưới) — dùng chung ô "Số {vialLabel}" (nv/vials) với hai dạng kia thay
  // vì thêm state riêng, vì WardRecipe.vials vốn đã là "số đơn vị đã dùng" chung cho mọi dạng chế
  // phẩm. Công thức tỉ lệ trên TỔNG lượng đã gộp bên dưới cho kết quả giống hệt drawFromFixedVial()
  // khi fixedBottleCount = 1 (trường hợp một chai — vẫn thường gặp nhất, không đổi hành vi cũ).
  const fixedBottleCount = isFixed ? (nv > 0 ? nv : 1) : 1
  const fixedPoolAmount = isFixed && va > 0 ? fixedBottleCount * va : null
  const fixedPoolVolume = isFixed && fixedVialVolume != null ? fixedBottleCount * fixedVialVolume : null
  const fixedDrawMl =
    isFixed && fixedDoseNum != null && fixedPoolAmount != null && fixedPoolVolume != null
      ? fixedDoseNum > fixedPoolAmount + 1e-9
        ? null
        : (fixedDoseNum / fixedPoolAmount) * fixedPoolVolume
      : null
  const fixedImpossible = isFixed && fixedDoseNum != null && fixedPoolAmount != null && fixedDrawMl == null

  const conc = isFixed ? (fixedVialVolume != null && va > 0 ? va / fixedVialVolume : null) : concentrationFromVials(va, nv, vol, vialUnit, concUnit)
  const grade = isFixed ? CONC_OK : gradeConcentration(conc, ward?.concValue, mix?.maxConc, concUnit, ward ? "công thức của bạn" : "công thức chuẩn")
  const drugVolume = vialsTotalVolume(nv, spec)
  const dil = diluentVolume(vol, drugVolume)
  const impossible = !isFixed && dil != null && dil < -1e-9
  const [confirmed, setConfirmed] = useState(false)
  useEffect(() => setConfirmed(false), [conc, vol, nv])
  const blocked = grade.requiresConfirm && !confirmed

  // Thể tích thực sự sẽ truyền — dùng để tính giọt/phút: chai cố định thì là mL rút ra, hoặc TOÀN BỘ
  // thể tích đã GỘP nếu dùng trọn (không phải thể tích một chai — sai khi gộp nhiều chai, giọt/phút
  // sẽ tính ra như thể chỉ có một chai trong khi thực tế truyền cả 2-3 chai), hai dạng kia là thể
  // tích pha loãng tới.
  const infuseVolumeMl = isFixed ? (fixedDoseNum != null ? fixedDrawMl : fixedPoolVolume) : vol
  const minutes = num(infuseMinutes)
  const usePump = routeShort === "TTM" && deliveryDevice === "pump"
  const dropsPerMin = routeShort === "TTM" && !usePump ? dropsPerMinute(infuseVolumeMl ?? NaN, minutes ?? NaN, dropFactor) : null
  // Làm tròn theo bước đặt tốc độ nhỏ nhất của bơm — 166.666... ml/h không phải con số đặt được thật
  // trên bơm tiêm điện (bước 0,1 ml/h), giống cách InfusionCalculator làm tròn roundedRate.
  const rateMlPerHourRaw = usePump ? pumpRateMlPerHour(infuseVolumeMl ?? NaN, minutes ?? NaN) : null
  const rateMlPerHour = rateMlPerHourRaw != null ? roundToStep(rateMlPerHourRaw, DEFAULT_PUMP_STEP) : null

  // ─── Tự tính số lọ/ống (hoặc số chai) khớp khoảng liều ────────────────────────
  // Chỉ cần nhập hàm lượng — dựa vào khoảng liều đã tính theo CrCl/AdjBW (doseTargetMg, truyền từ
  // AntibioticDoseCard), app tự điền số lọ VÀ thể tích pha loãng (hai dạng lọ bột/ống dung dịch),
  // hoặc số chai VÀ liều cần rút (dạng chai cố định). Áp dụng cho MỌI đường dùng/thiết bị truyền —
  // TTM lẫn TMC, dây thường lẫn bơm tiêm điện — không riêng gì bơm, vì "làm tròn ống/lọ theo khoảng
  // liều" là nhu cầu chung của mọi cách pha kháng sinh. Không có lựa chọn nào rơi đúng trong khoảng
  // thì làm tròn LÊN (thà dư nhẹ còn hơn thiếu liều — xem pickEasiestVialCount/bottleCountForDose).
  //
  // Cố ý KHÔNG dùng useEffect phản ứng theo doseTargetMg/vialAmount: một effect như vậy sẽ ĐÈ LÊN
  // công thức đã lưu ngay khi vừa nạp lại (loadWard đổi vialAmount cùng lúc, effect sẽ tính lại và
  // ghi đè mất số lọ/thể tích đã lưu). Thay vào đó, hai hàm dưới đây chỉ chạy khi NGƯỜI DÙNG chủ
  // động gõ hàm lượng — xem các onChange gọi tới chúng. Kết quả vẫn là Ô SỐ LỌ/THỂ TÍCH bình
  // thường, sửa tay lại được như mọi ô khác.
  function applySolutionSuggestion(vaValue: number, allow: boolean = allowWithdraw) {
    if (!doseTargetMg || !(vaValue > 0)) return
    const toVialUnit = massFactor(doseTargetMg.unit, vialUnit)
    const toConcMass = massFactor(vialUnit, concMass)
    if (toVialUnit == null) return
    const loInVialUnit = doseTargetMg.low * toVialUnit
    const hiInVialUnit = (doseTargetMg.high ?? doseTargetMg.low) * toVialUnit
    const count = pickEasiestVialCount(loInVialUnit, hiInVialUnit, vaValue, allow)
    if (count == null) return
    setVials(String(count))
    if (toConcMass == null) return
    // Thể tích pha loãng mặc định: quy ước 100 mL/lọ đã dùng ở autoUsage, trừ khi nồng độ đó vượt
    // ngưỡng trên (mix.maxConc) — khi đó nâng lên mốc 50 mL gần nhất để về lại nồng độ an toàn.
    const totalInConcMass = count * vaValue * toConcMass
    let vol = count * 100
    if (mix?.maxConc != null) {
      const minSafeVol = totalInConcMass / mix.maxConc
      if (minSafeVol > vol) vol = Math.ceil(minSafeVol / 50 - 1e-9) * 50
    }
    setVolume(String(vol))
  }

  function applyFixedSuggestion(vaValue: number, volValue: number, allow: boolean = allowWithdraw) {
    if (!doseTargetMg || !(vaValue > 0) || !(volValue > 0)) return
    const toVialUnit = massFactor(doseTargetMg.unit, vialUnit)
    if (toVialUnit == null) return
    const loInVialUnit = doseTargetMg.low * toVialUnit
    const hiInVialUnit = (doseTargetMg.high ?? doseTargetMg.low) * toVialUnit
    const result = resolveFixedDraw(loInVialUnit, hiInVialUnit, vaValue, volValue, allow)
    if (result == null) return
    setVials(String(result.bottleCount))
    // Không rút được (drawMl null) — dùng TRỌN số chai, xoá "Liều cần lấy" để hiển thị "dùng trọn".
    if (result.drawMl == null) {
      setFixedDoseAmount("")
      return
    }
    const concPerMl = vaValue / volValue
    setFixedDoseAmount(String(Math.round(result.drawMl * concPerMl * 100) / 100))
  }

  // Chỉ để HIỂN THỊ lý do (dòng "Đã tự tính..." dưới ô) — phép tính giống hệt applySolutionSuggestion
  // nhưng không ghi state, nên an toàn gọi lại mỗi lần render. Áp dụng cho MỌI đường dùng/thiết bị
  // truyền (TTM lẫn TMC, dây thường lẫn bơm) — không riêng gì bơm tiêm điện, vì "làm tròn ống/lọ
  // theo khoảng liều" là nhu cầu chung của mọi cách pha kháng sinh, không phải chỉ lúc chạy bơm.
  const vialCountSuggestion = useMemo(() => {
    if (isFixed || !doseTargetMg || !(va > 0)) return null
    const toVialUnit = massFactor(doseTargetMg.unit, vialUnit)
    const toDoseUnit = massFactor(vialUnit, doseTargetMg.unit)
    if (toVialUnit == null || toDoseUnit == null) return null
    const loInVialUnit = doseTargetMg.low * toVialUnit
    const hiInVialUnit = (doseTargetMg.high ?? doseTargetMg.low) * toVialUnit
    const count = pickEasiestVialCount(loInVialUnit, hiInVialUnit, va, allowWithdraw)
    if (count == null) return null
    // Không rút được VÀ không có số nguyên nào khớp hẳn khoảng liều — có hai phương án hợp lý (thấp
    // hơn/cao hơn), hiện cả hai để người dùng tự chọn thay vì chỉ đưa phương án app tự thiên vị chọn
    // (xem wholeCountOptions — cùng triết lý "Giữ nồng độ"/"Giữ thể tích" ở MixPanel).
    const alt = !allowWithdraw
      ? wholeCountOptions(loInVialUnit, hiInVialUnit, va).find((o) => o.count !== count)
      : undefined
    return {
      count,
      totalInDoseUnit: count * va * toDoseUnit,
      alt: alt ? { count: alt.count, totalInDoseUnit: alt.totalAmount * toDoseUnit } : undefined,
    }
  }, [isFixed, doseTargetMg, va, vialUnit, allowWithdraw])

  const fixedPoolSuggestion = useMemo(() => {
    if (!isFixed || !doseTargetMg || !(va > 0) || !(fixedVialVolume != null && fixedVialVolume > 0)) return null
    const toVialUnit = massFactor(doseTargetMg.unit, vialUnit)
    if (toVialUnit == null) return null
    const loInVialUnit = doseTargetMg.low * toVialUnit
    const hiInVialUnit = (doseTargetMg.high ?? doseTargetMg.low) * toVialUnit
    const result = resolveFixedDraw(loInVialUnit, hiInVialUnit, va, fixedVialVolume, allowWithdraw)
    if (result == null) return null
    const alt = !allowWithdraw
      ? wholeCountOptions(loInVialUnit, hiInVialUnit, va).find((o) => o.count !== result.bottleCount)
      : undefined
    return { count: result.bottleCount, drawMl: result.drawMl, alt: alt ? { count: alt.count } : undefined }
  }, [isFixed, doseTargetMg, va, vialUnit, fixedVialVolume, allowWithdraw])

  const pill = (on: boolean) =>
    on
      ? { background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }
      : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }

  function outcome(): MixOutcome {
    return { concValue: conc as number, volumeMl: vol, vials: nv, vialsOpened: Math.max(1, Math.ceil(nv - 1e-9)), drawMl: null, vialAmount: va, vialUnit, spec, diluent }
  }

  // Câu "Cách dùng" theo mẫu chuẩn — dòng đầu của khối kết quả, xem lib/usageText.ts.
  const usageLine =
    conc == null
      ? null
      : isFixed
        ? formatFixedUsage({
            name: drug.name,
            vialAmount: va,
            vialUnit,
            vialVolumeMl: fixedVialVolume ?? 0,
            vialsUsed: fixedBottleCount,
            doseAmount: fixedDoseNum ?? undefined,
            doseUnit: vialUnit,
            route: routeShort,
            dropsPerMin,
            rateMlPerHour,
          })
        : formatVialUsage({ name: drug.name, vialAmount: va * nv, vialUnit, diluentName: diluent, route: routeShort, dropsPerMin, rateMlPerHour })

  function loadWard(w: WardRecipe) {
    setVialAmount(String(w.vialAmount))
    setVialUnit(w.vialUnit)
    setVials(String(w.vials))
    setVialForm(w.vialForm ?? "powder")
    setVialVolume(w.vialVolumeMl != null ? String(w.vialVolumeMl) : "")
    setReconstitute(w.reconstituteMl != null ? String(w.reconstituteMl) : "")
    setDisplacement(w.displacementMl != null ? String(w.displacementMl) : "")
    setVolume(String(w.volumeMl))
    setDiluent(w.diluent ?? allowedDiluents[0] ?? "NaCl 0,9%")
    setRouteShort(w.route ?? defaultRoute)
    setInfuseMinutes(w.infuseMinutes != null ? String(w.infuseMinutes) : "")
    setDropFactor(w.dropFactor ?? DEFAULT_DROP_FACTOR)
    setDeliveryDevice(w.deliveryDevice ?? "drip")
    setAllowWithdraw(w.allowWithdraw ?? false)
    // Liều rút riêng của chai cố định không được lưu trong công thức (WardRecipe không có trường
    // này) — không xoá thì con số RÚT của công thức trước đó (thường không khớp hàm lượng/số chai
    // vừa nạp) tiếp tục nằm lại, có thể vượt hẳn tổng hàm lượng mới và làm cả khối "Cách dùng" biến
    // mất (xem fixedImpossible bên dưới).
    setFixedDoseAmount("")
    setActiveRecipeId(w.id)
    tickHaptic()
  }

  // Quay lại công thức DỰNG SẴN của app — không xoá công thức đã lưu nào cả, chỉ đổi giá trị form
  // đang mở về đúng như lúc chưa lưu công thức nào (xem các useState phía trên dùng cùng fallback
  // `mix?.xxx`). Trước đây muốn "quay lại hệ thống" chỉ có một cách: XOÁ hẳn công thức đã lưu.
  function loadSystemDefault() {
    setVialAmount(String(mix?.vialAmount ?? ""))
    setVialUnit(mix?.vialUnit ?? concMass)
    setVials("1")
    setVialForm(mix?.vialForm ?? "powder")
    setVialVolume(mix?.vialVolumeMl != null ? String(mix.vialVolumeMl) : "")
    setReconstitute(mix?.reconstituteMl != null ? String(mix.reconstituteMl) : "")
    setDisplacement(mix?.displacementMl != null ? String(mix.displacementMl) : "")
    setVolume("100")
    setDiluent(mix?.diluents?.[0] ?? "NaCl 0,9%")
    setRouteShort(defaultRoute)
    setInfuseMinutes("")
    setDropFactor(DEFAULT_DROP_FACTOR)
    setDeliveryDevice("drip")
    setAllowWithdraw(false)
    setFixedDoseAmount("")
    setActiveRecipeId("system")
    tickHaptic()
  }

  function saveWardFrom() {
    if (conc == null) return
    saveWard({
      drugId: drug.id,
      title: saveTitle.trim() || `${diluent} · ${vialForm === "powder" ? "lọ bột" : vialForm === "fixed" ? "chai cố định" : "ống dung dịch"} · ${routeShort}`,
      concValue: conc,
      vialAmount: va,
      vialUnit,
      vials: nv,
      volumeMl: vol,
      vialForm: spec.form,
      vialVolumeMl: spec.volumeMl ?? undefined,
      reconstituteMl: spec.reconstituteMl ?? undefined,
      displacementMl: spec.displacementMl ?? undefined,
      diluent,
      route: routeShort,
      infuseMinutes: minutes ?? undefined,
      dropFactor,
      deliveryDevice: routeShort === "TTM" ? deliveryDevice : undefined,
      allowWithdraw,
    })
    setSaveTitle("")
    tickHaptic()
  }

  function saveLog() {
    if (conc == null) return
    logCalc({
      drug: drug.name,
      kind: "mix",
      inputs: [usageLine ?? describeComposition(outcome(), vialLabel)],
      output: isFixed ? usageLine ?? "" : `Nồng độ ${formatDoseNumber(conc)} ${concUnit} trong ${trim(vol)} mL`,
    })
    tickHaptic()
  }

  return (
    <div className="mt-2.5 p-3 rounded-xl fade-in" style={{ background: "var(--c-surface-alt)", border: "1px solid var(--c-line)" }}>
      {wardList.length > 0 && (
        <WardRecipeChips
          wardList={wardList}
          activeId={activeRecipeId}
          onSelectSystem={loadSystemDefault}
          onSelectWard={loadWard}
          onDelete={(id) => clearWard(drug.id, id)}
          onPin={(id) => pinWard(drug.id, id)}
        />
      )}

      {!isFixed && (
        <>
          <label className={`${T.label} text-slate-500 mb-1 block`}>Dung môi</label>
          <div className="flex flex-wrap gap-1.5 mb-1.5">
            {allowedDiluents.map((d) => (
              <button key={d} onClick={() => setDiluent(d)} className={CHIP} style={pill(diluent === d)}>
                {d}
              </button>
            ))}
            {avoidDiluents.map((d) => (
              <button
                key={d}
                onClick={() => setDiluent(d)}
                className={CHIP}
                style={
                  diluent === d
                    ? { background: "var(--c-danger-icon)", borderColor: "var(--c-danger-icon)", color: "var(--c-on-bright)" }
                    : { background: "var(--c-surface)", borderColor: "var(--c-danger-line)", color: "var(--c-danger-deep)" }
                }
              >
                {d}
              </button>
            ))}
          </div>
          {diluentBlocked && (
            <p className="text-[12px] font-bold leading-[1.45] mb-2 px-2.5 py-2 rounded-xl" style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-deep)" }}>
              {mix?.diluentWarning ?? `Không pha ${drug.name} với ${diluent}.`}
            </p>
          )}
        </>
      )}

      {/* Chỉ TTM mới cần chọn thiết bị truyền — TMC là tiêm nhanh một lần, không có tốc độ. Một số
          kháng sinh (vancomycin liều cao, một số kháng sinh truyền kéo dài khác) BẮT BUỘC chạy bơm
          tiêm điện/bơm thể tích vì tốc độ quá chậm để đếm giọt cho chính xác — xem lib/mixing.ts
          (pumpRateMlPerHour) và lib/usageText.ts. */}
      {routeShort === "TTM" && (
        <>
          <label className={`${T.label} text-slate-500 mb-1 block`}>Thiết bị truyền</label>
          <div className="flex flex-wrap gap-1.5 mb-2">
            {(
              [
                { v: "drip" as const, label: "Dây thường (giọt/phút)" },
                { v: "pump" as const, label: "Bơm tiêm điện (mL/giờ)" },
              ]
            ).map((opt) => (
              <button
                key={opt.v}
                onClick={() => {
                  setDeliveryDevice(opt.v)
                  tickHaptic()
                }}
                className={CHIP}
                style={pill(deliveryDevice === opt.v)}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </>
      )}

      {/* Vài khoa hoàn nguyên/gộp nhiều lọ-chai rồi rút bớt dung dịch dư ra (cho phép số lọ lẻ như
          1,5 lọ), vài khoa chỉ dùng NGUYÊN số lọ/chai đã mở — quyết định này ảnh hưởng thẳng tới gợi
          ý số lọ/chai bên dưới, nên đặt ngay trước "Dạng chế phẩm". */}
      <label className={`${T.label} text-slate-500 mb-1 block`}>Cho phép rút dung dịch sau pha?</label>
      <div className="flex flex-wrap gap-1.5 mb-2">
        {(
          [
            { v: false, label: "Không — bắt buộc số nguyên" },
            { v: true, label: "Có — được lấy số lẻ" },
          ]
        ).map((opt) => (
          <button
            key={String(opt.v)}
            onClick={() => {
              setAllowWithdraw(opt.v)
              // Tính lại ngay bằng giá trị MỚI vừa bấm — closure của applySolutionSuggestion/
              // applyFixedSuggestion còn giữ allowWithdraw CŨ tới khi component render lại, nên
              // phải truyền tay opt.v thay vì dựa vào state (chưa kịp cập nhật ở lượt render này).
              if (va > 0) {
                if (isFixed) {
                  if (fixedVialVolume != null) applyFixedSuggestion(va, fixedVialVolume, opt.v)
                } else {
                  applySolutionSuggestion(va, opt.v)
                }
              }
              tickHaptic()
            }}
            className={CHIP}
            style={pill(allowWithdraw === opt.v)}
          >
            {opt.label}
          </button>
        ))}
      </div>

      <label className={`${T.label} text-slate-500 mb-1 block`}>Dạng chế phẩm</label>
      <div className="flex flex-wrap gap-1.5 mb-2">
        {(
          [
            { v: "powder" as VialForm, label: "Lọ bột" },
            { v: "solution" as VialForm, label: "Ống dung dịch" },
            { v: "fixed" as VialForm, label: "Chai cố định hàm lượng" },
          ]
        ).map((opt) => (
          <button key={opt.v} onClick={() => setVialForm(opt.v)} className={CHIP} style={pill(vialForm === opt.v)}>
            {opt.label}
          </button>
        ))}
      </div>

      {isFixed ? (
        <>
          {/* Chai cố định hàm lượng: KHÔNG pha loãng thêm — chỉ khai hàm lượng/thể tích cả chai rồi
              hoặc dùng trọn, hoặc rút một phần theo liều cần. Liều cần có thể vượt một chai — GỘP
              NHIỀU CHAI thay vì rút lẻ trong một chai duy nhất; ô "Số chai" dùng chung state với "Số
              lọ/ống" ở hai dạng kia (WardRecipe.vials), mặc định 1 nên không đổi hành vi cũ. Tự tính
              số chai + thể tích rút (làm tròn tới hàng trăm mL) khi biết khoảng liều — áp dụng cho
              MỌI đường dùng/thiết bị truyền, không riêng bơm tiêm điện. */}
          {/* min-h-[2.8em] trên nhãn (issue "bảng pha không ngay hàng"): "Hàm lượng 1 chai" và "Thể
              tích 1 chai (mL)" dài ngắn khác nhau nên xuống dòng khác nhau ở cột hẹp — nhãn dài 2 dòng
              đẩy ô nhập tụt xuống so với ô cạnh bên chỉ có nhãn 1 dòng. Đặt trước chiều cao cho ĐÚNG 2
              dòng (12px × 1.4 × 2, xem T.label) trên mọi nhãn cùng hàng để ô nhập luôn ngang hàng dù
              nhãn dài ngắn khác nhau. */}
          <div className="grid grid-cols-2 gap-2 mb-2">
            <div>
              <label className={`${T.label} text-slate-500 mb-1 block min-h-[2.8em]`}>Hàm lượng 1 chai</label>
              <input
                value={vialAmount}
                onChange={(e) => {
                  const v = normalizeDecimalInput(e.target.value)
                  setVialAmount(v)
                  const parsed = parseFloat(v)
                  if (parsed > 0 && fixedVialVolume != null) applyFixedSuggestion(parsed, fixedVialVolume)
                }}
                inputMode="decimal"
                placeholder="750"
                className={FIELD}
                style={FIELD_STYLE}
              />
            </div>
            <div>
              <label className={`${T.label} text-slate-500 mb-1 block min-h-[2.8em]`}>Thể tích 1 chai (mL)</label>
              <input
                value={vialVolume}
                onChange={(e) => {
                  const v = normalizeDecimalInput(e.target.value)
                  setVialVolume(v)
                  const parsed = parseFloat(v)
                  if (va > 0 && parsed > 0) applyFixedSuggestion(va, parsed)
                }}
                inputMode="decimal"
                placeholder="150"
                className={FIELD}
                style={FIELD_STYLE}
              />
            </div>
          </div>
          <div className="mb-2">
            <label className={`${T.label} text-slate-500 mb-1 block`}>Số chai</label>
            <input value={vials} onChange={(e) => setVials(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="1" className={FIELD} style={FIELD_STYLE} />
          </div>
          {/* Gợi ý số chai (+ thể tích rút gộp nếu khoa cho rút) — bấm để áp dụng lại nếu vừa sửa tay
              lệch khỏi gợi ý. Thể tích rút làm tròn tới mốc trăm/năm mươi mL (khác thang với thể
              tích pha loãng nhỏ ở hai dạng kia) — xem poolDrawVolume trong lib/mixing.ts. Không cho
              rút thì không có "rút X mL" nào cả — dùng TRỌN số chai, và có thể có phương án thay thế
              (thấp hơn/cao hơn) để tự chọn thay vì chỉ một đáp án app tự thiên vị. */}
          {fixedPoolSuggestion && doseTargetMg && (
            <div className="flex flex-wrap gap-1.5 mb-2">
              <button
                onClick={() => {
                  setVials(String(fixedPoolSuggestion.count))
                  if (fixedPoolSuggestion.drawMl == null) {
                    setFixedDoseAmount("")
                  } else {
                    const concPerMl = va / (fixedVialVolume as number)
                    setFixedDoseAmount(String(Math.round(fixedPoolSuggestion.drawMl * concPerMl * 100) / 100))
                  }
                  tickHaptic()
                }}
                className="text-left text-[12px] leading-[1.45] font-semibold px-2.5 py-2 rounded-xl underline decoration-dotted"
                style={{ background: "var(--c-accent-soft)", color: "var(--c-accent-deep)" }}
              >
                {fixedPoolSuggestion.drawMl == null
                  ? `Gợi ý dùng trọn ${trim(fixedPoolSuggestion.count, 0)} chai`
                  : `Gợi ý ${trim(fixedPoolSuggestion.count, 0)} chai — rút ${trim(fixedPoolSuggestion.drawMl)} mL`}
                {" "}(khớp khoảng liều {formatDoseNumber(doseTargetMg.low)}
                {doseTargetMg.high != null ? `–${formatDoseNumber(doseTargetMg.high)}` : ""} {doseTargetMg.unit})
              </button>
              {fixedPoolSuggestion.alt && (
                <button
                  onClick={() => {
                    setVials(String(fixedPoolSuggestion.alt!.count))
                    setFixedDoseAmount("")
                    tickHaptic()
                  }}
                  className="text-left text-[12px] leading-[1.45] font-semibold px-2.5 py-2 rounded-xl underline decoration-dotted"
                  style={{ background: "var(--c-line-soft)", color: "var(--c-text-soft)" }}
                >
                  Hoặc {trim(fixedPoolSuggestion.alt.count, 0)} chai
                </button>
              )}
            </div>
          )}
          {unitChoices.length > 1 && (
            <div className="flex flex-wrap gap-1.5 mb-2.5">
              {unitChoices.map((u) => (
                <button key={u} onClick={() => setVialUnit(u)} className={CHIP} style={pill(vialUnit === u)}>
                  {u}
                </button>
              ))}
            </div>
          )}
        </>
      ) : (
        <>
          {/* Ống dung dịch: 3 ô ngắn vừa khít một hàng. Lọ bột thì KHÔNG dùng chung hàng đó — nhãn "Pha
              ban đầu với (mL/lọ)" dài hơn hẳn "Thể tích 1 ống (mL)", nhét vào 1/3 hàng sẽ xuống dòng và
              đẩy ô nhập tụt xuống so với hai ô bên cạnh (không còn ngang hàng). Tách thành hàng riêng để
              nhãn dài có đủ chỗ, không phải đứng cạnh nhãn ngắn.
              `min-h-[2.8em]` trên cả ba nhãn: ở cột hẹp (grid-cols-3), "Hàm lượng 1 {vialLabel}" và
              "Thể tích 1 {vialLabel} (mL)" xuống 2 dòng còn "Số {vialLabel}" chỉ 1 dòng — đặt trước
              chiều cao ĐÚNG 2 dòng (12px × 1.4 × 2, xem T.label) trên mọi nhãn cùng hàng để ba ô nhập
              luôn ngang hàng bất kể nhãn dài ngắn khác nhau theo từng thuốc. */}
          <div className={`grid ${vialForm === "solution" ? "grid-cols-3" : "grid-cols-2"} gap-2 mb-2`}>
            <div>
              <label className={`${T.label} text-slate-500 mb-1 block min-h-[2.8em]`}>Hàm lượng 1 {vialLabel}</label>
              <input
                value={vialAmount}
                onChange={(e) => {
                  const v = normalizeDecimalInput(e.target.value)
                  setVialAmount(v)
                  const parsed = parseFloat(v)
                  if (parsed > 0) applySolutionSuggestion(parsed)
                }}
                inputMode="decimal"
                placeholder="1000"
                className={FIELD}
                style={FIELD_STYLE}
              />
            </div>
            {vialForm === "solution" && (
              <div>
                <label className={`${T.label} text-slate-500 mb-1 block min-h-[2.8em]`}>Thể tích 1 {vialLabel} (mL)</label>
                <input value={vialVolume} onChange={(e) => setVialVolume(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="2" className={FIELD} style={FIELD_STYLE} />
              </div>
            )}
            <div>
              <label className={`${T.label} text-slate-500 mb-1 block min-h-[2.8em]`}>Số {vialLabel}</label>
              <input value={vials} onChange={(e) => setVials(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="1" className={FIELD} style={FIELD_STYLE} />
            </div>
          </div>

          {/* Đã tự điền số {vialLabel} + thể tích pha loãng ngay khi gõ hàm lượng ở trên (xem
              applySolutionSuggestion, áp dụng cho mọi đường dùng/thiết bị truyền) — dòng này chỉ để
              BẤM ÁP DỤNG LẠI nếu vừa sửa tay lệch khỏi gợi ý, vẫn sửa tay ô "Số {vialLabel}"/"Pha
              loãng tới" bình thường sau đó. */}
          {vialCountSuggestion && doseTargetMg && (
            <div className="flex flex-wrap gap-1.5 mb-2">
              <button
                onClick={() => {
                  applySolutionSuggestion(va)
                  tickHaptic()
                }}
                className="text-left text-[12px] leading-[1.45] font-semibold px-2.5 py-2 rounded-xl underline decoration-dotted"
                style={{ background: "var(--c-accent-soft)", color: "var(--c-accent-deep)" }}
              >
                Gợi ý {trim(vialCountSuggestion.count)} {vialLabel} (≈ {formatDoseNumber(vialCountSuggestion.totalInDoseUnit)} {doseTargetMg.unit} — khớp khoảng liều{" "}
                {formatDoseNumber(doseTargetMg.low)}
                {doseTargetMg.high != null ? `–${formatDoseNumber(doseTargetMg.high)}` : ""} {doseTargetMg.unit})
              </button>
              {/* Không cho rút dung dịch VÀ không có số nguyên nào khớp hẳn — có 2 phương án hợp lý
                  (thấp hơn/cao hơn khoảng liều), hiện cả hai để tự chọn thay vì chỉ app tự quyết. */}
              {vialCountSuggestion.alt && (
                <button
                  onClick={() => {
                    setVials(String(vialCountSuggestion.alt!.count))
                    tickHaptic()
                  }}
                  className="text-left text-[12px] leading-[1.45] font-semibold px-2.5 py-2 rounded-xl underline decoration-dotted"
                  style={{ background: "var(--c-line-soft)", color: "var(--c-text-soft)" }}
                >
                  Hoặc {trim(vialCountSuggestion.alt.count)} {vialLabel} (≈ {formatDoseNumber(vialCountSuggestion.alt.totalInDoseUnit)} {doseTargetMg.unit})
                </button>
              )}
            </div>
          )}

          {/* Xếp dọc, mỗi ô một hàng riêng — không ghép ngang: "Thể tích bột tăng sau pha" luôn dài hơn
              hẳn "Pha ban đầu với", và độ dài {vialLabel} (lọ/ống/chai) đổi theo từng thuốc nên không
              thể tin là hai nhãn sẽ luôn xuống dòng đối xứng nhau ở mọi cỡ chữ. */}
          {vialForm === "powder" && (
            <div className="space-y-2 mb-2">
              <div>
                <label className={`${T.label} text-slate-500 mb-1 block`}>Pha ban đầu với (mL/{vialLabel})</label>
                <input value={reconstitute} onChange={(e) => setReconstitute(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="10" className={FIELD} style={FIELD_STYLE} />
              </div>
              <div>
                <label className={`${T.label} text-slate-500 mb-1 block`}>Thể tích bột tăng sau pha (mL/{vialLabel})</label>
                <input value={displacement} onChange={(e) => setDisplacement(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="0,5" className={FIELD} style={FIELD_STYLE} />
              </div>
            </div>
          )}

          <div className="mb-2">
            <label className={`${T.label} text-slate-500 mb-1 block`}>Pha loãng tới (mL)</label>
            <input value={volume} onChange={(e) => setVolume(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="100" className={FIELD} style={FIELD_STYLE} />
          </div>

          {unitChoices.length > 1 && (
            <div className="flex flex-wrap gap-1.5 mb-2.5">
              {unitChoices.map((u) => (
                <button key={u} onClick={() => setVialUnit(u)} className={CHIP} style={pill(vialUnit === u)}>
                  {u}
                </button>
              ))}
            </div>
          )}
        </>
      )}

      {/* Tốc độ truyền — chỉ có ý nghĩa với đường TTM, không áp dụng cho TMC (tiêm thẳng). Bộ dây
          (giọt/mL) chỉ hiện khi dùng dây thường; bơm tiêm điện đặt thẳng mL/giờ, không đếm giọt. */}
      {routeShort === "TTM" && infuseVolumeMl != null && infuseVolumeMl > 0 && (
        <div className="grid grid-cols-2 gap-2 mb-2">
          <div>
            <label className={`${T.label} text-slate-500 mb-1 block`}>Truyền trong (phút)</label>
            <input value={infuseMinutes} onChange={(e) => setInfuseMinutes(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="60" className={FIELD} style={FIELD_STYLE} />
          </div>
          {usePump ? (
            // Luôn chiếm đúng một ô của lưới 2 cột, kể cả khi CHƯA nhập số phút — trước đây ô này
            // biến mất hoàn toàn lúc rateMlPerHour còn null, để lại một hàng lệch (chỉ "Truyền trong
            // (phút)" một mình, nửa lưới bên phải trống trơn) thay vì đứng cân đối như phía dây thường.
            <div className="flex flex-col justify-end">
              <label className={`${T.label} text-slate-500 mb-1 block`}>Tốc độ bơm</label>
              <p className={`${FIELD} flex items-center font-bold`} style={{ ...FIELD_STYLE, color: rateMlPerHour != null ? "var(--c-accent-deep)" : "var(--c-muted)" }}>
                {rateMlPerHour != null ? `BTĐ ${trim(rateMlPerHour)} ml/h` : "Nhập số phút để tính"}
              </p>
            </div>
          ) : (
            <div>
              <label className={`${T.label} text-slate-500 mb-1 block`}>Bộ dây (giọt/mL)</label>
              <div className="flex h-11 rounded-2xl overflow-hidden border" style={{ borderColor: "var(--c-line)" }}>
                {[DEFAULT_DROP_FACTOR, MICRO_DROP_FACTOR].map((f) => (
                  <button
                    key={f}
                    onClick={() => setDropFactor(f)}
                    className="flex-1 text-[12px] font-semibold"
                    style={dropFactor === f ? { background: "var(--c-accent)", color: "var(--c-on-bright)" } : { background: "var(--c-surface)", color: "var(--c-text-soft)" }}
                  >
                    {f}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {fixedImpossible && (
        <div className="px-3 py-2.5 rounded-xl flex items-start gap-2 mb-2" style={{ background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-icon)" }}>
          <span className="mt-0.5 flex-none" style={{ color: "var(--c-danger-icon)" }}>{icons.alert()}</span>
          <p className="text-[12px] leading-[1.45]" style={{ color: "var(--c-danger-deep)" }}>
            LIỀU CẦN LẤY VƯỢT HÀM LƯỢNG CẢ CHAI — kiểm tra lại liều cần lấy hoặc hàm lượng chai.
          </p>
        </div>
      )}

      {conc != null && (isFixed ? !fixedImpossible : !isNaN(nv)) && (
        impossible ? (
          <div className="px-3 py-2.5 rounded-xl flex items-start gap-2" style={{ background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-icon)" }}>
            <span className="mt-0.5 flex-none" style={{ color: "var(--c-danger-icon)" }}>{icons.alert()}</span>
            <p className="text-[12px] leading-[1.45]" style={{ color: "var(--c-danger-deep)" }}>
              KHÔNG PHA ĐƯỢC — thể tích thuốc đã nhiều hơn thể tích pha loãng. Kiểm tra lại số {vialLabel}, thể tích 1 {vialLabel} hoặc thể tích pha loãng.
            </p>
          </div>
        ) : (
          <div className="px-3 py-2.5 rounded-xl" style={{ background: "var(--c-surface)", border: "1px solid var(--c-line-strong)" }}>
            {usageLine && <p className="text-[13px] font-bold text-slate-800 leading-[1.45]">{usageLine}</p>}
            {!isFixed && <p className="text-[12px] leading-[1.45] mt-1" style={{ color: "var(--c-text-soft)" }}>Nồng độ {formatDoseNumber(conc)} {concUnit}</p>}
            <p className="text-[12px] font-semibold leading-[1.45] mt-1" style={{ color: "var(--c-accent-deep)" }}>
              {isFixed
                ? fixedDoseNum != null
                  ? // Luôn nói rõ SỐ CHAI đã gộp — "rút 300 mL từ chai 750 mg/150 mL" đọc như đang rút
                    // từ MỘT chai duy nhất, dễ hiểu lầm là lỗi khi con số rút ra lớn hơn cả một chai
                    // (vd rút 300 mL từ chai chỉ có 150 mL). Phải nói "2 chai gộp lại" ngay tại đây.
                    fixedBottleCount > 1
                    ? `Rút ${formatDoseNumber(fixedDrawMl as number)} mL từ ${trim(fixedBottleCount, 0)} chai ${trim(va)} ${vialUnit}/${trim(fixedVialVolume ?? 0)} mL gộp lại (tổng ${formatDoseNumber(fixedPoolAmount as number)} ${vialUnit}/${trim(fixedPoolVolume as number)} mL)`
                    : `Rút ${formatDoseNumber(fixedDrawMl as number)} mL từ chai ${trim(va)} ${vialUnit}/${trim(fixedVialVolume ?? 0)} mL`
                  : fixedBottleCount > 1
                    ? `Dùng trọn ${trim(fixedBottleCount, 0)} chai ${trim(va)} ${vialUnit}/${trim(fixedVialVolume ?? 0)} mL`
                    : `Dùng trọn 1 chai ${trim(va)} ${vialUnit}/${trim(fixedVialVolume ?? 0)} mL`
                : describeComposition(outcome(), vialLabel)}
            </p>
            {mix?.infuseNote && <p className="text-[12px] leading-[1.45] mt-2" style={{ color: "var(--c-text-soft)" }}>Truyền: {mix.infuseNote}</p>}

            {/* Chỉ còn HAI mức màu, không phải ba: nguy hiểm (đỏ) / thận trọng (hổ phách). Trước đây
                "warn" tô cam riêng tách khỏi "note" tô hổ phách — trong buồng tối cam #c2410c và
                hổ phách #92400e gần như không phân biệt được, mà lại đang mang hai mức nghiêm
                trọng khác nhau mà chỉ dựa vào màu để phân biệt. Chữ (headline/detail) vẫn nói rõ
                mức độ; màu chỉ còn giữ hai bậc thật sự phân biệt được. */}
            {grade.severity !== "ok" && (
              <div
                className="mt-2 px-2.5 py-2 rounded-xl flex items-start gap-2"
                style={
                  grade.severity === "danger"
                    ? { background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-icon)" }
                    : { background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }
                }
              >
                <span className="mt-0.5 flex-none" style={{ color: grade.severity === "danger" ? "var(--c-danger-icon)" : "var(--c-warn-icon)" }}>
                  {icons.alert()}
                </span>
                <div>
                  {grade.headline && (
                    <p className="text-[12px] font-extrabold leading-[1.3]" style={{ color: grade.severity === "danger" ? "var(--c-danger-deep)" : "var(--c-warn)" }}>
                      {grade.headline}
                    </p>
                  )}
                  {grade.detail && (
                    <p className="text-[12px] leading-[1.45] mt-0.5" style={{ color: grade.severity === "danger" ? "var(--c-danger-deep)" : "var(--c-warn)" }}>
                      {grade.detail}
                    </p>
                  )}
                </div>
              </div>
            )}

            {blocked ? (
              <button
                onClick={() => {
                  setConfirmed(true)
                  tickHaptic()
                }}
                className={`${BTN_TALL} mt-2 border-transparent`}
                style={{ background: grade.severity === "danger" ? "var(--c-danger-deep)" : "var(--c-warn)", color: "var(--c-on-bright)" }}
              >
                Tôi đã kiểm tra lại — vẫn dùng công thức này
              </button>
            ) : (
              <>
                <div className="flex flex-wrap gap-1.5 mt-2">
                  <button onClick={saveLog} className="h-9 px-3 rounded-full text-[12px] font-bold dose-press" style={{ background: "var(--c-accent)", color: "var(--c-on-bright)" }}>
                    Lưu vào nhật ký
                  </button>
                </div>
                <div className="flex gap-1.5 mt-1.5">
                  {/* `min-w-0` là bắt buộc: flex item mặc định min-width:auto (theo nội dung), nên
                      một input flex-1 đứng cạnh nút flex-none sẽ không chịu co lại dưới độ rộng nội
                      dung của nó — trên màn hình hẹp, cả hàng tràn ra ngoài thẻ thay vì input co lại. */}
                  <input
                    value={saveTitle}
                    onChange={(e) => setSaveTitle(e.target.value)}
                    placeholder="Đặt tên công thức (tuỳ chọn, vd: Khoa Hồi sức)"
                    maxLength={40}
                    className="flex-1 min-w-0 h-11 px-2.5 rounded-full text-[12px] border outline-none"
                    style={FIELD_STYLE}
                  />
                  {/* h-11, không phải h-9: đứng cùng hàng với ô nhập "Đặt tên công thức" (buộc phải
                      cao 44px theo quy tắc sàn 16px/44px cho input) — hai chiều cao khác nhau trên
                      cùng một hàng sẽ lệch đường đáy, trông như hai khối không liên quan. */}
                  <button onClick={saveWardFrom} className="h-11 px-3 rounded-full text-[12px] font-bold border flex-none dose-press" style={{ borderColor: "var(--c-accent-line)", color: "var(--c-accent-deep)" }}>
                    Lưu công thức mới
                  </button>
                </div>
              </>
            )}
          </div>
        )
      )}
      {conc == null && (
        <p className="text-[12px] leading-[1.45] text-slate-400">
          {isFixed ? `Nhập hàm lượng và thể tích cả chai để tính.` : `Nhập hàm lượng ${vialLabel}, số ${vialLabel} và thể tích pha loãng để tính nồng độ.`}
        </p>
      )}
    </div>
  )
}

function AntibioticDoseCard({
  drug,
  disease,
  isOverride,
  onEdit,
  onDelete,
}: {
  drug: Antibiotic
  disease?: DiseaseEntry | null
  isOverride?: boolean
  onEdit?: (drug: Antibiotic) => void
  onDelete?: (id: string) => void
}) {
  const { patient, abwKg, heightCm, crcl, crclUsable, openPatientPanel, pinRunning, wardRecipes, clearWard, pinWard } = useDosing()
  const wardList = wardRecipes[drug.id] ?? []
  const { activeId: activeRecipeId, setActiveId: setActiveRecipeId, active: ward } = useActiveWardRecipe(wardList)
  const [showMix, setShowMix] = useState(false)
  const [confirmClearWard, setConfirmClearWard] = useState(false)
  // Đường uống không cần hoàn nguyên/pha loãng — bảng pha chỉ có ý nghĩa với đường tiêm/truyền.
  const injectable = !drug.route.includes("Uống")
  const indication = disease ? drug.indications?.find((i) => i.diseaseId === disease.id) : undefined
  const tiers = indication?.tiers ?? drug.tiers
  const standardDose = indication?.standardDose ?? drug.standardDose
  // Nguồn hiện ra: bệnh lý có tự khai nguồn riêng thì dùng nguồn đó (xem IndicationDose.source),
  // không thì rơi về nguồn của thuốc — không còn gộp cứng một nguồn cho mọi bệnh lý như trước.
  const sourceItem: SourceInfo = indication && (indication.source || indication.reviewedOn) ? indication : drug
  // Khi bệnh nhân lọc máu hoặc creatinin chưa ổn định thì KHÔNG được chọn bậc liều theo CrCl —
  // app quay về liều chuẩn (bậc thận bình thường) và nói rõ vì sao, thay vì đưa ra một bậc liều
  // trông chắc chắn mà thực ra không áp dụng được.
  const effectiveCrcl = crclUsable ? crcl : null
  const tier = tierFor(tiers, effectiveCrcl)
  // Chưa nhập đủ thông số để ra CrCl thì tierFor() trả về bậc THẬN BÌNH THƯỜNG. Trước đây app im
  // lặng hiển thị bậc đó như một câu trả lời chắc chắn — đúng kiểu sai nguy hiểm nhất, vì người
  // dùng không có dấu hiệu nào để biết con số đang giả định thận bình thường. Chỉ nhắc khi thuốc
  // THẬT SỰ có nhiều bậc liều; thuốc một bậc (metronidazole, azithromycin) thì CrCl không đổi gì.
  const missingCrcl = crcl == null && patient.rrt === "none" && !patient.akiUnstable && tiers.length > 1
  const dosingWeight = useMemo(
    () => resolveDosingWeight(abwKg, heightCm, patient.sex, drug.doseWeightBasis ?? "actual"),
    [abwKg, heightCm, patient.sex, drug.doseWeightBasis],
  )
  // Cân nặng gõ nhầm (vd 5000 kg) đã bị checkWeight() gắn cờ "implausible" ở khung Bệnh nhân, nhưng
  // trước đây cờ đó không truyền xuống đây — app vẫn nhân 20–25 mg/kg × 5000 kg ra một liều Vancomycin
  // trông chắc chắn (100–125 g). Chặn NGAY TẠI NGUỒN (doseTargetMg) để mọi chỗ đọc từ nó (perKgDoses,
  // autoUsage/bảng pha) đều không tính ra số khi cân nặng vô lý, thay vì phải nhớ chặn từng chỗ hiển thị.
  const weightImplausible = checkWeight(dosingWeight.used)?.severity === "implausible"
  // Nhân sẵn liều mg/kg: app đã có cân nặng và đã có chuỗi "15–20 mg/kg mỗi 8–12h" thì không có lý
  // do gì bắt người dùng tự nhẩm — đó đúng là chỗ dễ sai nhất lúc 2 giờ sáng.
  const perKgDoses = useMemo(() => findPerKgDoses(tier.dose), [tier.dose])
  // Tự tính "Cách dùng" theo mức liều CrCl hiện tại: đọc con số liều (mg/kg × cân nặng, hoặc liều
  // tuyệt đối đứng đầu chuỗi) rồi quy đổi ra mL/chai theo công thức pha đã lưu (hoặc mặc định của
  // thuốc) — xem lib/perKgDose.ts (findFixedDose) và lib/mixing.ts (drawFromFixedVial/pickEasiestVolume).
  // Không tự bịa công thức pha: chỉ tính khi thuốc CÓ `mix`/công thức đã lưu, ngược lại im lặng.
  // "Đường dùng" (TTM/TMC/IM/SC) — TRƯỚC ĐÂY nằm sâu bên trong bảng pha thuốc (sau cả mục Dung môi),
  // giờ nhấc lên đây làm STATE DUY NHẤT của cả thẻ: vừa hiện ở mục "Đường dùng" ngay bên dưới, vừa
  // quyết định nút "Bảng pha thuốc" có hiện hay không (chỉ hiện với bốn đường tiêm/truyền — uống,
  // nhỏ mắt... không có gì để pha), vừa truyền xuống AntibioticMixPanel thay cho state riêng của nó.
  // `mixableRoutes` đọc THẲNG từ câu chữ `route` của thuốc (xem inferAdminRoutes trong lib/ui.ts):
  // route ghi CHỈ "(TTM)" hay CHỈ "(TMC)" thì thuốc đó CHỈ được dùng đúng một đường — không cho đổi
  // qua đường còn lại, vì nhiều thuốc bắt buộc truyền chậm (TTM), tiêm nhanh (TMC) là sai lầm nguy
  // hiểm (vd Vancomycin gây hội chứng người đỏ). Chỉ khi route ghi chung chung "(IV)" (chưa phân biệt
  // trong dữ liệu) mới thật sự có hai lựa chọn để bác sĩ tự chọn.
  const mixableRoutes = useMemo(() => inferAdminRoutes(drug.route), [drug.route])
  // Công thức đã lưu (ward) có thể tự khai đường dùng riêng (khoa A truyền TTM, khoa B tiêm TMC cùng
  // một thuốc) — ưu tiên đường đó, chỉ suy từ `drug.route` khi chưa có công thức nào được lưu. Nếu
  // đường đã lưu không còn nằm trong `mixableRoutes` (vd dữ liệu thuốc vừa được sửa lại) thì bỏ qua,
  // tránh khoá thẻ vào một đường không còn hợp lệ.
  const [routeShort, setRouteShort] = useState<AdminRoute>(
    (ward?.route && mixableRoutes.includes(ward.route) ? ward.route : undefined) ?? mixableRoutes[0] ?? "TTM",
  )
  const pill = (on: boolean) =>
    on
      ? { background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }
      : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
  // Chỉ có gì để "pha" khi câu chữ route thật sự là một trong bốn đường tiêm/truyền — uống, nhỏ
  // mắt... không có bảng pha kiểu này, hiện ra sẽ sai vì áp công thức pha lên đường dùng không liên quan.
  const hasMixPanel = mixableRoutes.length > 0
  const mixCfg = useMemo(() => {
    // `vials`/`volumeMl` là null khi CHƯA có công thức đã lưu — tự tính số lọ cần dùng ở autoUsage
    // bên dưới thay vì giả định cứng "đúng 1 lọ" như trước (khiến Amikacin/Vancomycin liều theo
    // cân nặng — đa số cần nhiều hơn 1 lọ — không bao giờ ra được gợi ý).
    if (ward)
      return {
        vialAmount: ward.vialAmount,
        vialUnit: ward.vialUnit,
        vialForm: ward.vialForm ?? "powder",
        vialVolumeMl: ward.vialVolumeMl,
        vials: ward.vials,
        volumeMl: ward.volumeMl,
        diluent: ward.diluent ?? "NaCl 0,9%",
        // Chỉ công thức ĐÃ LƯU mới có cơ sở thật để tính giọt/phút — drug.mix tĩnh không có, nên
        // nhánh dưới vẫn ẩn phần giọt/phút thay vì bịa thời gian truyền.
        infuseMinutes: ward.infuseMinutes,
        dropFactor: ward.dropFactor,
        // Bơm tiêm điện chỉ áp dụng được khi có công thức đã lưu khai rõ — công thức hệ thống dựng
        // sẵn (nhánh drug.mix bên dưới) không biết khoa nào chạy bơm nên luôn coi là dây thường.
        deliveryDevice: ward.deliveryDevice ?? "drip",
        // Mặc định KHÔNG cho rút (số nguyên) khi công thức cũ chưa từng khai — xem WardRecipe.allowWithdraw.
        allowWithdraw: ward.allowWithdraw ?? false,
      }
    const mix = drug.mix
    if (mix != null && mix.vialAmount != null)
      return {
        vialAmount: mix.vialAmount,
        vialUnit: mix.vialUnit ?? "mg",
        vialForm: mix.vialForm ?? "powder",
        vialVolumeMl: mix.vialVolumeMl,
        vials: null as number | null,
        volumeMl: null as number | null,
        diluent: mix.diluents?.[0] ?? "NaCl 0,9%",
        infuseMinutes: undefined as number | undefined,
        dropFactor: undefined as number | undefined,
        deliveryDevice: "drip" as "drip" | "pump",
        allowWithdraw: false,
      }
    return null
  }, [ward, drug.mix])
  // Một số mức liều viết dạng "Liều nạp 20–25 mg/kg, sau đó theo nồng độ đáy" — con số mg/kg ở đây
  // là liều NẠP một lần, còn liều DUY TRÌ (thứ cần tính lặp lại mỗi lần pha) được nói thẳng là
  // "theo nồng độ đo được", tức KHÔNG có con số cố định. Nếu cứ lấy đại con số mg/kg đứng trước rồi
  // tính ra mL thì sẽ đưa ra một "Cách dùng" trông chắc chắn cho một liều thực ra phải cá thể hoá —
  // đúng kiểu tự suy diễn nguy hiểm mà app tránh ở mọi chỗ khác. Chỉ cần bỏ qua tier đó là đủ an toàn.
  const notComputableDose = /theo nồng độ|cá thể hoá|giãn khoảng liều/i.test(tier.dose)
  // Trần liều một lần dùng của thuốc (nếu có khai báo) — áp NGAY TẠI ĐÂY, cùng chỗ với chặn cân
  // nặng vô lý, để mọi thứ đọc từ doseTargetMg (bảng pha, "Cách dùng", số mL phải rút) đều đã nằm
  // dưới trần. Xem applyDoseCap trong lib/perKgDose.ts.
  const doseTargetMg = useMemo(() => {
    if (notComputableDose) return null
    const perKg = perKgDoses[0]
    if (perKg && dosingWeight.used != null) {
      // Cân nặng bất thường (vd 5000 kg gõ nhầm) → không nhân ra một con số trông chắc chắn, xem
      // weightImplausible ở trên.
      if (weightImplausible) return null
      return applyDoseCap(
        perKg.low * dosingWeight.used,
        perKg.high != null ? perKg.high * dosingWeight.used : null,
        perKg.unit,
        drug.maxSingleDose,
      )
    }
    if (perKg) return null // liều mg/kg mà chưa có cân nặng thì không đoán được
    const fixed = findFixedDose(tier.dose)
    return fixed ? applyDoseCap(fixed.amount, null, fixed.unit, drug.maxSingleDose) : null
  }, [notComputableDose, perKgDoses, dosingWeight.used, weightImplausible, tier.dose, drug.maxSingleDose])
  const doseCapText = doseTargetMg ? describeDoseCap(doseTargetMg) : null
  const autoUsage = useMemo(() => {
    if (!mixCfg || !doseTargetMg) return null
    if (mixCfg.vialForm === "fixed") {
      if (mixCfg.vialVolumeMl == null) return null
      const toVialUnit = massFactor(doseTargetMg.unit, mixCfg.vialUnit)
      const toDoseUnit = massFactor(mixCfg.vialUnit, doseTargetMg.unit)
      if (toVialUnit == null || toDoseUnit == null) return null
      const loInVialUnit = doseTargetMg.low * toVialUnit
      const hiInVialUnit = (doseTargetMg.high ?? doseTargetMg.low) * toVialUnit
      // Liều cần có thể vượt MỘT chai — resolveFixedDraw tự gộp thêm chai khi cần (giữ nguyên thang
      // làm tròn mịn 5/1/0,5/0,1 mL cho trường hợp một chai thường gặp nhất, chỉ chuyển sang thang
      // trăm/năm mươi mL khi thật sự phải gộp — xem lib/mixing.ts). Không cho rút (allowWithdraw
      // false) thì drawMl null — dùng TRỌN thể tích đã gộp, không có "lấy X mg" riêng.
      const result = resolveFixedDraw(loInVialUnit, hiInVialUnit, mixCfg.vialAmount, mixCfg.vialVolumeMl, mixCfg.allowWithdraw)
      if (result == null) return null
      const { bottleCount } = result
      const pooledVolume = bottleCount * mixCfg.vialVolumeMl
      const pickedMl = result.drawMl ?? pooledVolume
      const pickedDose = pickedMl * (mixCfg.vialAmount / mixCfg.vialVolumeMl) * toDoseUnit
      // Liều tính ra đúng bằng (các) chai gộp lại (vd Levofloxacin 750 mg = trọn chai 750 mg/150 mL)
      // → nói "N chai" đúng mẫu, không nói "lấy 750 mg" (đúng số nhưng sai câu chữ thực tế dùng).
      const isWholeVial = result.drawMl == null || pickedMl >= pooledVolume - 1e-6
      // Chỉ tính tốc độ khi công thức ĐÃ LƯU có khai thời gian truyền dự kiến — không có thì ẩn hẳn
      // phần này thay vì bịa một thời gian truyền không ai xác nhận. Bơm tiêm điện thì ra mL/giờ,
      // dây thường thì ra giọt/phút — không tính cả hai cùng lúc (xem mixCfg.deliveryDevice).
      const onPump = routeShort === "TTM" && mixCfg.deliveryDevice === "pump"
      const dropsPerMin =
        routeShort === "TTM" && !onPump && mixCfg.infuseMinutes != null ? dropsPerMinute(pickedMl, mixCfg.infuseMinutes, mixCfg.dropFactor ?? DEFAULT_DROP_FACTOR) : null
      const rateMlPerHourRaw = onPump && mixCfg.infuseMinutes != null ? pumpRateMlPerHour(pickedMl, mixCfg.infuseMinutes) : null
      const rateMlPerHour = rateMlPerHourRaw != null ? roundToStep(rateMlPerHourRaw, DEFAULT_PUMP_STEP) : null
      return formatFixedUsage({
        name: drug.name,
        vialAmount: mixCfg.vialAmount,
        vialUnit: mixCfg.vialUnit,
        vialVolumeMl: mixCfg.vialVolumeMl,
        vialsUsed: bottleCount,
        doseAmount: isWholeVial ? undefined : pickedDose,
        doseUnit: doseTargetMg.unit,
        route: routeShort,
        dropsPerMin,
        rateMlPerHour,
      })
    }
    const f = massFactor(doseTargetMg.unit, mixCfg.vialUnit)
    if (f == null) return null
    const neededHigh = (doseTargetMg.high ?? doseTargetMg.low) * f // đơn vị vialUnit
    const neededLow = doseTargetMg.low * f

    let vials: number
    let volumeMl: number
    if (mixCfg.vials != null && mixCfg.volumeMl != null) {
      // Có công thức đã lưu (ward) — dùng ĐÚNG số lọ/ống và thể tích đã pha thật, không tự đoán
      // lại. Liều cần vượt quá tổng lượng thuốc thật có trong bơm/chai đã pha thì dừng — không tự
      // ý cộng thêm lọ ngoài công thức người dùng đã xác nhận.
      vials = mixCfg.vials
      volumeMl = mixCfg.volumeMl
      if (neededHigh > vials * mixCfg.vialAmount + 1e-9) return null
    } else {
      // Không có công thức đã lưu — tự tính số lọ/ống cần dùng (làm tròn LÊN) thay vì giả định cứng
      // "đúng 1 lọ" như trước (khiến liều theo cân nặng vượt 1 lọ luôn bị bỏ qua), pha theo tỉ lệ
      // mặc định 100 mL cho mỗi lọ khi chưa biết quy cách pha thật của khoa.
      vials = Math.max(1, Math.ceil(neededHigh / mixCfg.vialAmount - 1e-9))
      volumeMl = vials * 100
    }
    const conc = (vials * mixCfg.vialAmount) / volumeMl
    if (!(conc > 0)) return null
    const loMl = neededLow / conc
    const hiMl = neededHigh / conc
    if (hiMl > volumeMl + 1e-9) return null
    const pickedMl = doseTargetMg.high != null ? pickEasiestVolume(loMl, hiMl) : loMl
    // Liều tính ra dùng ĐÚNG trọn lượng vừa pha (không cần rút riêng một phần) → câu gọn như mẫu
    // 3b, không lặp lại "đủ X ml lấy Y ml" một cách thừa thãi.
    const isWholeBatch = pickedMl >= volumeMl - 1e-6
    // Chỉ tính tốc độ khi công thức ĐÃ LƯU có khai thời gian truyền dự kiến — không có thì ẩn hẳn
    // phần này thay vì bịa một thời gian truyền không ai xác nhận (xem mixCfg ở trên). Bơm tiêm điện
    // thì ra mL/giờ, dây thường thì ra giọt/phút.
    const onPump = routeShort === "TTM" && mixCfg.deliveryDevice === "pump"
    const dropsPerMin =
      routeShort === "TTM" && !onPump && mixCfg.infuseMinutes != null ? dropsPerMinute(pickedMl, mixCfg.infuseMinutes, mixCfg.dropFactor ?? DEFAULT_DROP_FACTOR) : null
    const rateMlPerHourRaw = onPump && mixCfg.infuseMinutes != null ? pumpRateMlPerHour(pickedMl, mixCfg.infuseMinutes) : null
    const rateMlPerHour = rateMlPerHourRaw != null ? roundToStep(rateMlPerHourRaw, DEFAULT_PUMP_STEP) : null
    return formatVialUsage({
      name: drug.name,
      vialAmount: mixCfg.vialAmount,
      vialUnit: mixCfg.vialUnit,
      vialsUsed: vials,
      vialLabel: drug.mix?.vialLabel ?? (mixCfg.vialForm === "solution" ? "ống" : "lọ"),
      // Chỉ ống dung dịch mới có thể tích riêng đáng nói kiểu "1 g/4 ml" (mẫu 4b) — lọ bột chưa có
      // thể tích tới khi hoàn nguyên, thể tích đó đã nằm trong "đủ X ml" bên dưới rồi.
      vialVolumeMl: mixCfg.vialForm === "solution" ? mixCfg.vialVolumeMl ?? undefined : undefined,
      diluentName: mixCfg.diluent,
      route: routeShort,
      finalVolumeMl: isWholeBatch ? undefined : volumeMl,
      drawMl: isWholeBatch ? undefined : pickedMl,
      dropsPerMin,
      rateMlPerHour,
    })
  }, [mixCfg, doseTargetMg, drug.name, drug.mix?.vialLabel, routeShort])
  const highWarnings = (drug.warnings ?? []).filter((w) => w.severity === "cao")
  const otherWarnings = (drug.warnings ?? []).filter((w) => w.severity !== "cao")
  const rrtDoseText =
    patient.rrt !== "none" && drug.rrt ? (drug.rrt as Record<string, string | undefined>)[patient.rrt] : undefined
  const weightLabelVi: Record<"ABW" | "IBW" | "AdjBW", string> = {
    ABW: "cân nặng thực tế (ABW)",
    IBW: "cân nặng lý tưởng (IBW)",
    AdjBW: "cân nặng hiệu chỉnh (AdjBW)",
  }
  return (
    <div className="p-4 rounded-2xl border" style={{ borderColor: "var(--c-line)", background: "var(--c-surface)" }}>
      <div className="flex items-center justify-between mb-0.5 gap-2">
        <div className="flex items-center gap-1.5 min-w-0">
          <p className="font-bold text-slate-900 text-[13px] truncate">{drug.name}</p>
          {drug.isCustom && (
            <span
              className="text-[12px] font-bold px-1.5 py-0.5 rounded-full flex-none"
              style={isOverride ? { background: "var(--c-primary-soft)", color: "var(--c-primary)" } : { background: "var(--c-green-soft)", color: "var(--c-green)" }}
            >
              {isOverride ? "Đã chỉnh sửa" : "Tự nhập"}
            </span>
          )}
        </div>
        <div className="flex items-center gap-1.5 flex-none">
          {/* Nhãn bậc liều hiện cả khi CHƯA có CrCl (màu vàng = đang giả định), thay vì biến mất —
              biến mất khiến bậc "thận bình thường" trông giống liều duy nhất của thuốc. */}
          {tiers.length > 1 && (
            <span
              className={`${T.meta} font-semibold px-2 py-0.5 ${R.pill}`}
              style={
                effectiveCrcl != null
                  ? { background: C.primarySoft, color: C.primary }
                  : { background: C.warnSoft, color: C.warn }
              }
            >
              {effectiveCrcl != null ? tier.label : `${tier.label} (giả định)`}
            </span>
          )}
          {onEdit && (
            <button onClick={() => onEdit(drug)} className="w-11 h-11 rounded-full flex items-center justify-center" style={{ background: "var(--c-primary-soft)", color: "var(--c-primary)" }} aria-label="Sửa">
              {icons.edit()}
            </button>
          )}
          {drug.isCustom && onDelete && (isOverride ? (
            <button
              onClick={() => onDelete(drug.id)}
              className="w-11 h-11 rounded-full flex items-center justify-center"
              style={{ background: "var(--c-line-soft)", color: "var(--c-text-soft)" }}
              aria-label="Khôi phục mặc định"
            >
              {icons.undo()}
            </button>
          ) : (
            <ConfirmIconButton
              onConfirm={() => onDelete(drug.id)}
              ariaLabel="Xoá"
              className="w-11 h-11 rounded-full flex items-center justify-center"
              style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-icon)" }}
            />
          ))}
        </div>
      </div>
      {/* drug.route và chip "Chỉ định" là CHÚ THÍCH TĨNH, không bấm được — trước đây tô cùng màu
          teal với nút hành động/chip đang chọn khiến người dùng học nhầm "teal = bấm được" rồi
          gặp ngay một chỗ teal không phản hồi gì khi chạm. Đổi sang --c-text-soft (chữ) / nền
          trung tính (chip), giữ teal cho đúng vai trò hành động + trạng thái chọn. */}
      <p className={`${T.meta} font-semibold mb-1.5`} style={{ color: "var(--c-text-soft)" }}>{drug.route}</p>
      {/* Chọn TTM/TMC/IM/SC ngay tại "Đường dùng" — TRƯỚC ĐÂY nằm sâu trong bảng pha thuốc (sau cả
          mục Dung môi), khiến bảng pha "lấn át" luôn cả việc chọn đường dùng. CHỈ hiện chip khi thật
          sự có nhiều hơn một đường hợp lệ (route ghi chung chung "(IV)") — route đã ghi rõ đúng MỘT
          đường (vd Vancomycin "Truyền tĩnh mạch (TTM)") thì KHOÁ CỨNG, không hiện chip để đổi, tránh
          đổi nhầm sang đường tiêm không phù hợp với thuốc đó (xem mixableRoutes ở trên). */}
      {mixableRoutes.length > 1 && (
        <div className="flex flex-wrap gap-2 mb-1.5">
          {mixableRoutes.map((r) => (
            <button key={r} type="button" onClick={() => setRouteShort(r)} className={CHIP} style={pill(routeShort === r)}>
              {adminRouteLabel(r)}
            </button>
          ))}
        </div>
      )}
      {disease && (
        <p className={`${T.meta} font-semibold mb-1.5 px-2 py-0.5 rounded-full inline-block`} style={{ background: "var(--c-line-soft)", color: "var(--c-text-soft)" }}>
          Chỉ định: {disease.name}
        </p>
      )}
      {drug.doseWeightBasis && drug.doseWeightBasis !== "actual" && (
        <div className="mb-1.5 px-2.5 py-2 rounded-xl" style={{ background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }}>          {dosingWeight.used != null && dosingWeight.usedLabel ? (
            <>
              <p className="text-[12px] font-bold" style={{ color: "var(--c-warn)" }}>
                Liều mg/kg dùng {weightLabelVi[dosingWeight.usedLabel]}: {dosingWeight.used.toFixed(1)} kg
              </p>
              <p className="text-[12px] mt-0.5" style={{ color: "var(--c-warn-icon)" }}>
                ABW {dosingWeight.abw?.toFixed(1)} kg
                {dosingWeight.ibw != null && ` · IBW ${dosingWeight.ibw.toFixed(1)} kg`}
                {dosingWeight.adjBw != null && ` · AdjBW ${dosingWeight.adjBw.toFixed(1)} kg`}
              </p>
            </>
          ) : (
            <p className="text-[12px] font-bold" style={{ color: "var(--c-warn)" }}>
              Thuốc này cần cân nặng lý tưởng/hiệu chỉnh — nhập cân nặng và chiều cao ở trên để tính chính xác.
            </p>
          )}
        </div>
      )}
      {/* Lọc máu / CRRT: đây chính là nhóm bệnh nhân cần app nhất, và cũng là nhóm app dễ im lặng
          nhất. Bậc liều theo CrCl bị vô hiệu hoá, và nếu app không có dữ liệu thì phải nói thẳng. */}
      {patient.rrt !== "none" && (
        <div className="mb-1.5 px-2.5 py-2 rounded-xl" style={{ background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-line)" }}>
          <p className="text-[12px] font-bold leading-[1.45]" style={{ color: "var(--c-danger-deep)" }}>
            {RRT_LABELS[patient.rrt]} — bậc liều theo CrCl KHÔNG áp dụng.
          </p>
          {rrtDoseText ? (
            <>
              <p className="text-[13px] font-bold leading-[1.45] mt-1" style={{ color: "var(--c-danger-deep)" }}>{rrtDoseText}</p>
              {/* Liều CRRT là con số CÓ ĐIỀU KIỆN — thiếu Qeff thì chưa đọc được nó thuộc cột nào */}
              {needsCrrtFlow(patient.rrt) && !((parseStrictNumber(patient.crrtFlowLPerH) ?? 0) > 0) && (
                <button onClick={openPatientPanel} className="text-[12px] font-bold underline text-left leading-[1.45] mt-1" style={{ color: "var(--c-danger)" }}>
                  Chưa nhập tốc độ dịch thải (Qeff) — nhập ở khung "Bệnh nhân hiện tại" để biết khuyến cáo trên ứng với mức lọc nào.
                </button>
              )}
            </>
          ) : (
            <p className="text-[12px] leading-[1.45] mt-0.5" style={{ color: "var(--c-danger-deep)" }}>
              App CHƯA có dữ liệu liều cho phương thức lọc này với {drug.name}. Tra phác đồ lọc máu của cơ sở hoặc hỏi dược lâm sàng — liều và thời điểm dùng phụ thuộc phương thức lọc, liều lọc và lịch buổi lọc. Nhập được vào app qua nút Sửa để lần sau khỏi tra lại.
            </p>
          )}
          {drug.rrt?.note && <p className="text-[12px] leading-[1.45] mt-1" style={{ color: "var(--c-danger-deep)" }}>{drug.rrt.note}</p>}
          {(drug.rrt?.source || drug.rrt?.reviewedOn) && (
            <p className="text-[12px] leading-[1.45] mt-1" style={{ color: "var(--c-danger)" }}>
              {drug.rrt.source && <>Nguồn liều lọc máu: {drug.rrt.source}</>}
              {drug.rrt.source && drug.rrt.reviewedOn && " · "}
              {drug.rrt.reviewedOn && <>Rà soát: {formatReviewedOn(drug.rrt.reviewedOn)}</>}
            </p>
          )}
        </div>
      )}
      {patient.rrt === "none" && patient.akiUnstable && (
        <div className="mb-1.5 px-2.5 py-2 rounded-xl" style={{ background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }}>
          <p className="text-[12px] font-bold leading-[1.45]" style={{ color: "var(--c-warn)" }}>
            Tổn thương thận cấp (creatinin chưa ổn định) — Cockcroft-Gault không dùng được, app đang hiển thị liều bậc thận bình thường. Chỉnh liều theo lâm sàng, nồng độ thuốc đo được và ý kiến dược lâm sàng.
          </p>
        </div>
      )}

      {/* Chưa có CrCl: nói thẳng con số bên dưới đang giả định điều gì, và mở sẵn đường đi nhập */}
      {missingCrcl && (
        <button
          onClick={openPatientPanel}
          className={`w-full text-left mb-1.5 px-2.5 py-2 ${R.box} flex items-start gap-2`}
          style={{ background: C.warnSoft, border: `1px solid ${C.warnLine}` }}
        >
          <span className="mt-0.5 flex-none" style={{ color: C.warnIcon }}>{icons.alert()}</span>
          <span>
            <span className={`${T.meta} font-bold block`} style={{ color: C.warn }}>
              Chưa có CrCl — đang hiện liều bậc THẬN BÌNH THƯỜNG
            </span>
            <span className={`${T.meta} block mt-0.5`} style={{ color: "var(--c-warn-icon)" }}>
              Thuốc này có {tiers.length} bậc liều theo chức năng thận. Nhập tuổi, cân nặng và creatinin ở khung "Bệnh nhân hiện tại" để app chọn đúng bậc.
            </span>
          </span>
        </button>
      )}

      <p className={T.body} style={{ color: "var(--c-text-2)" }}>{tier.dose}</p>

      {/* Nhân sẵn mg/kg × cân nặng — phần trước đây bắt người dùng tự nhẩm */}
      {perKgDoses.length > 0 && (
        <div
          className="mt-1.5 px-2.5 py-2 rounded-xl"
          style={
            weightImplausible
              ? { background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-icon)" }
              : { background: "var(--c-accent-soft)", border: "1px solid var(--c-accent-line)" }
          }
        >
          {weightImplausible ? (
            <>
              {/* CHẶN hẳn con số nhân sẵn — cân nặng cỡ này gần như chắc chắn gõ nhầm, không được
                  in ra một liều gam trông chắc chắn rồi để bác sĩ tự tin dùng luôn lúc gấp. */}
              <p className="text-[12px] font-bold leading-[1.45]" style={{ color: "var(--c-danger-deep)" }}>
                Không tính liều mg/kg: {checkWeight(dosingWeight.used)?.message}
              </p>
              <button onClick={openPatientPanel} className="text-[12px] font-bold underline text-left leading-[1.45] mt-0.5" style={{ color: "var(--c-danger)" }}>
                Sửa lại cân nặng ở khung "Bệnh nhân hiện tại"
              </button>
            </>
          ) : dosingWeight.used != null ? (
            <>
              {perKgDoses.map((d, i) => (
                <p key={i} className="text-[12px] leading-[1.45]" style={{ color: "var(--c-accent-deep)" }}>
                  <b>{d.raw}</b> × {dosingWeight.used?.toFixed(1)} kg
                  {dosingWeight.usedLabel && dosingWeight.usedLabel !== "ABW" ? ` (${dosingWeight.usedLabel})` : ""} = <b>{computePerKgText(d, dosingWeight.used)}</b> mỗi lần dùng
                </p>
              ))}
              {/* Trần liều một lần dùng đã cắt vào khoảng liều vừa nhân — phải nói ngay cạnh con số,
                  không để dưới đáy thẻ: chỗ người dùng đang nhìn là dòng mg/kg này. */}
              {doseCapText && (
                <p className="text-[12px] font-bold leading-[1.45] mt-1 px-2 py-1.5 rounded-lg" style={{ background: "var(--c-warn-soft)", color: "var(--c-warn)" }}>
                  {doseCapText}
                </p>
              )}
              <p className="text-[12px] leading-[1.45] mt-0.5" style={{ color: "var(--c-accent)" }}>
                {doseCapText
                  ? "Còn phải làm tròn theo hàm lượng lọ/ống thực tế."
                  : "Còn phải làm tròn theo hàm lượng lọ/ống thực tế và ngưỡng liều tối đa của thuốc."}
              </p>
            </>
          ) : (
            <button onClick={openPatientPanel} className="text-[12px] font-bold text-left leading-[1.45]" style={{ color: "var(--c-accent-deep)" }}>
              Nhập cân nặng ở khung "Bệnh nhân hiện tại" để app nhân sẵn liều mg/kg.
            </button>
          )}
        </div>
      )}

      {/* Cách dùng tự tính theo mức liều CrCl hiện tại — chỉ hiện khi đọc được cả con số liều lẫn
          công thức pha, xem autoUsage ở trên. */}
      {autoUsage && (
        <div className="mt-1.5 px-2.5 py-2 rounded-xl" style={{ background: "var(--c-primary-soft)", border: "1px solid var(--c-primary)" }}>
          <p className="text-[12px] font-bold leading-[1.45]" style={{ color: "var(--c-primary)" }}>{autoUsage}</p>
          <p className="text-[12px] leading-[1.45] mt-0.5" style={{ color: "var(--c-text-soft)" }}>
            Tự tính theo {tier.label} {ward ? "và công thức pha của bạn" : "và công thức pha mặc định"} — kiểm tra lại trước khi dùng.
          </p>
        </div>
      )}

      {/* Chỉ hiện "Liều chuẩn" khi nó KHÁC dòng liều ở trên — trước đây meropenem in ra "1 g mỗi 8h"
          rồi ngay dưới lại "Liều chuẩn: 1 g mỗi 8h (IV)", đọc như hai thông tin khác nhau. */}
      {standardDose && effectiveCrcl == null && !standardDose.startsWith(tier.dose) && (
        <p className={`${T.meta} mt-1`} style={{ color: C.textSoft }}>Liều chuẩn: {standardDose}</p>
      )}

      {/* Cảnh báo mức cao luôn hiện; phần còn lại gấp lại giống thẻ thuốc truyền */}
      {highWarnings.length > 0 && (
        <div className="mt-2 space-y-1.5">
          {highWarnings.map((w, i) => (
            <div key={i} className={`flex items-start gap-2 px-2.5 py-2 ${R.box}`} style={{ background: C.dangerSoft, border: `1px solid ${C.dangerLine}` }}>
              <span className="mt-0.5 flex-none" style={{ color: C.dangerIcon }}>{icons.alert()}</span>
              <p className={T.bodyStrong} style={{ color: C.danger }}>{w.text}</p>
            </div>
          ))}
        </div>
      )}

      <CompatWarningForDrug compatKey={drug.compatKey} ownDrugId={drug.id} />

      <button
        onClick={() => {
          pinRunning({
            drugId: drug.id,
            name: drug.name,
            compatKey: drug.compatKey,
            line: 1,
            doseText: tier.dose,
            rateText: "",
            concText: drug.route,
            kind: "intermittent",
            weightKgAtPin: abwKg,
          })
          tickHaptic()
        }}
        className={`${BTN_BLOCK} mt-3`}
        style={{ borderColor: C.accentLine, background: C.accentSoft, color: C.accent }}
      >
        Thêm vào danh sách đang dùng
      </button>

      {(drug.boluses?.length ?? 0) > 0 && (
        <Disclosure label="Liều nạp / bolus" count={drug.boluses?.length}>
          <BolusList boluses={drug.boluses} drugName={drug.name} doseWeightBasis={drug.doseWeightBasis} />
        </Disclosure>
      )}

      {/* Cách dùng gộp chung với bảng pha, và nội dung ĐỘNG theo công thức đã lưu — giống bên thuốc
          truyền: trước đây "Cách dùng · Ghi chú" chỉ đọc câu chữ dựng sẵn, còn "Bảng pha thuốc" là
          nút riêng — cùng nói về một việc nhưng tách hai chỗ. */}
      {(injectable || drug.preparation || indication?.note || drug.note) && (
        <Disclosure label="Cách dùng · Ghi chú">
          {/* Chuyển đổi qua lại giữa các công thức đã lưu VÀ công thức hệ thống ngay ở đây — không
              còn phải mở hẳn "Bảng pha thuốc" bên dưới mới đổi được, và không cần XOÁ một công thức
              đã lưu chỉ để tạm xem lại công thức hệ thống (xem useActiveWardRecipe). */}
          {wardList.length > 0 && (
            <WardRecipeChips
              wardList={wardList}
              activeId={activeRecipeId}
              onSelectSystem={() => setActiveRecipeId("system")}
              onSelectWard={(w) => setActiveRecipeId(w.id)}
              onDelete={(id) => clearWard(drug.id, id)}
              onPin={(id) => pinWard(drug.id, id)}
            />
          )}
          {ward ? (
            <div className="flex items-start gap-2">
              <span className="mt-0.5 flex-none" style={{ color: "var(--c-accent)" }}>{icons.edit()}</span>
              <div className="flex-1 min-w-0">
                <p className={`${T.meta} font-bold`} style={{ color: "var(--c-accent-deep)" }}>
                  {ward.title || "Công thức của bạn"} (lưu {formatSavedAt(ward.savedAt)}) — khác công thức hệ thống
                </p>
                <p className={`${T.body} mt-0.5`} style={{ color: C.textSoft }}>
                  {ward.vials} {ward.vialForm === "powder" ? "lọ" : "ống"} × {formatMass(ward.vialAmount, ward.vialUnit)} vừa đủ {trim(ward.volumeMl)} mL
                  {ward.diluent ? `, dung môi ${ward.diluent}` : ""}.
                </p>
                {/* Đây là XOÁ THẬT (mất hẳn công thức đã lưu) — chuyển VỀ công thức hệ thống mà
                    không mất dữ liệu thì dùng chip "Công thức hệ thống" ở trên. Nên cần xác nhận hai
                    chạm giống mọi chỗ xoá dữ liệu đã lưu khác trong app, không phải một chạm "hoàn
                    tác" như trước (dễ bấm nhầm mất công thức chỉ để xem lại công thức hệ thống). */}
                <button
                  onClick={() => {
                    if (!confirmClearWard) {
                      setConfirmClearWard(true)
                      tickHaptic()
                      return
                    }
                    clearWard(drug.id, ward.id)
                    setConfirmClearWard(false)
                    tickHaptic()
                  }}
                  onBlur={() => setConfirmClearWard(false)}
                  className="flex items-center gap-1.5 text-[12px] font-bold mt-1.5"
                  style={{ color: confirmClearWard ? "var(--c-on-bright)" : "var(--c-danger)", background: confirmClearWard ? "var(--c-danger-icon)" : "transparent", padding: confirmClearWard ? "4px 8px" : 0, borderRadius: 999 }}
                >
                  <span className="scale-90">{confirmClearWard ? icons.alert() : icons.trash()}</span>
                  {confirmClearWard ? "Chắc chắn xoá?" : "Xoá công thức này"}
                </button>
              </div>
            </div>
          ) : (
            drug.preparation && <p className={T.body} style={{ color: C.textSoft }}>{drug.preparation}</p>
          )}
          {indication?.note && <p className={`${T.meta} mt-2`} style={{ color: C.textSoft }}>{indication.note}</p>}
          {drug.note && <p className={`${T.meta} mt-2`} style={{ color: C.textSoft }}>{drug.note}</p>}

          {/* Hiện bảng pha cho CẢ BỐN đường tiêm/truyền (TTM/TMC/IM/SC, xem mixableRoutes) — trước đây
              chỉ hiện cho TTM/TMC, khiến tiêm bắp/tiêm dưới da không có gì để pha dù cũng cần hoàn
              nguyên/pha loãng như hai đường kia (chỉ khác là không có tốc độ truyền). Đường uống thì
              mixableRoutes rỗng nên vẫn không hiện. */}
          {hasMixPanel && (
            <>
              <button
                onClick={() => setShowMix((v) => !v)}
                className={`${BTN_BLOCK} mt-3`}
                style={{ borderColor: C.accentLine, background: C.accentSoft, color: C.accent }}
              >
                {showMix ? "Đóng bảng pha thuốc" : "Bảng pha thuốc"}
              </button>
              {showMix && <AntibioticMixPanel drug={drug} doseTargetMg={doseTargetMg} routeShort={routeShort} setRouteShort={setRouteShort} />}
            </>
          )}
        </Disclosure>
      )}

      {otherWarnings.length > 0 && (
        <Disclosure label="Lưu ý khác" count={otherWarnings.length} alert>
          <DrugWarnings warnings={otherWarnings} bare />
        </Disclosure>
      )}

      {/* Nguồn dữ liệu: ưu tiên nguồn RIÊNG của bệnh lý đang chọn (indication.source/reviewedOn) —
          liều theo bệnh lý cụ thể (vd viêm màng não) thường lấy từ một khuyến cáo khác hẳn nguồn
          chung của thuốc, nên không thể gộp chung một nguồn cho mọi bệnh lý như trước. Bệnh lý nào
          CHƯA tự khai nguồn riêng thì rơi về nguồn của thuốc, không bắt buộc điền lại toàn bộ dữ
          liệu cũ. `alert` khi mục đang hiện chưa ghi nguồn: trước đây phải MỞ khối này ra mới biết,
          nên trên thực tế không ai biết. Nay tình trạng nằm ngay trên tiêu đề. */}
      <Disclosure label={sourceItem.source || sourceItem.reviewedOn ? "Nguồn dữ liệu" : "Nguồn dữ liệu — chưa ghi nguồn"} alert={!sourceItem.source && !sourceItem.reviewedOn}>
        {indication && (indication.source || indication.reviewedOn) && (
          <p className={`${T.meta} mb-1.5`} style={{ color: C.textSoft }}>Nguồn riêng cho chỉ định {disease?.name}:</p>
        )}
        <SourceLine item={sourceItem} bare />
        {indication && !(indication.source || indication.reviewedOn) && (drug.source || drug.reviewedOn) && (
          <p className={`${T.meta} mt-1.5`} style={{ color: C.textSoft }}>Bệnh lý này chưa tự khai nguồn riêng — đang hiện nguồn chung của thuốc.</p>
        )}
      </Disclosure>
    </div>
  )
}

const DISEASE_SKIP = "__skip__"

function AntibioticsScreen({
  customDrugs,
  diseases,
  onAddNew,
  onEdit,
  onDelete,
}: {
  customDrugs: Antibiotic[]
  diseases: DiseaseEntry[]
  onAddNew: () => void
  onEdit: (drug: Antibiotic) => void
  onDelete: (id: string) => void
}) {
  const { running, collapsePatientPanel } = useDosing()
  // Cả bốn bước chọn đều giữ lại khi rời màn hình rồi quay lại: đi tra một thứ khác rồi về mà phải
  // bấm lại từ hoạt chất → bệnh lý → đường dùng là mất đúng công đoạn dài nhất của màn này.
  const [query, setQuery] = useStickyState("abx.query", "")
  const [selectedGroupName, setSelectedGroupName] = useStickyState<string | null>("abx.group", null)
  const [diseaseChoice, setDiseaseChoice] = useStickyState<string | null>("abx.disease", null) // disease id, DISEASE_SKIP, hoặc null (chưa chọn)
  const [selectedEntryId, setSelectedEntryId] = useStickyState<string | null>("abx.entry", null)

  // Tuổi/cân nặng/chiều cao/creatinin và cả phép tính CrCl nay nằm ở khung "Bệnh nhân hiện tại"
  // dùng chung cho mọi tab của Dùng thuốc (xem PatientPanel) — mỗi thẻ thuốc tự đọc từ context.
  const allAntibiotics = useMemo(() => mergeWithOverrides(ANTIBIOTICS, customDrugs), [customDrugs])

  // Nhóm các bản ghi theo hoạt chất (name) — cùng hoạt chất có thể có nhiều đường dùng (route)
  // khác nhau, mỗi đường dùng là một Antibiotic riêng (id riêng) để tránh đè dữ liệu lên nhau.
  // Sắp theo alphabet (thứ tự nhập liệu trong antibiotics.ts không mang ý nghĩa ưu tiên lâm sàng nào
  // — xác nhận trực tiếp, không phải suy đoán) để 22 mục đọc ra như một danh sách có trật tự thay vì
  // một khối tên thuốc ngẫu nhiên; xem thêm nhãn chữ cái ở chỗ render (chỉ hiện khi chưa gõ tìm).
  const groups = useMemo(() => {
    const map = new Map<string, Antibiotic[]>()
    allAntibiotics.forEach((d) => {
      const arr = map.get(d.name) ?? []
      arr.push(d)
      map.set(d.name, arr)
    })
    return Array.from(map.entries())
      .map(([name, entries]) => ({ name, entries }))
      .sort((a, b) => a.name.localeCompare(b.name, "vi", { sensitivity: "base" }))
  }, [allAntibiotics])

  const filteredGroups = useMemo(() => {
    const q = normalizeSearch(query)
    return q ? groups.filter((g) => normalizeSearch(g.name).includes(q)) : groups
  }, [groups, query])
  // Gõ tới khi chỉ còn một hoạt chất thì chọn luôn — giống bên các tab thuốc truyền.
  const effectiveGroupName = selectedGroupName ?? (query.trim() && filteredGroups.length === 1 ? filteredGroups[0].name : null)
  const selectedGroup = effectiveGroupName ? groups.find((g) => g.name === effectiveGroupName) ?? null : null

  // Kháng sinh bệnh nhân đang dùng (đã thêm vào bảng Đang truyền) — thứ cần xem lại trước tiên,
  // thay vì phải tìm lại trong danh mục mỗi lần đổi ca.
  const onPatient = useMemo(() => {
    const byId = new Map(allAntibiotics.map((d) => [d.id, d]))
    return running.map((r) => byId.get(r.drugId)).filter((d): d is Antibiotic => d != null)
  }, [allAntibiotics, running])

  // Bệnh lý liên quan tới NHÓM (hoạt chất) đang chọn, gộp từ mọi đường dùng của hoạt chất đó.
  // Gồm cả 2 chiều: bệnh lý có sẵn tham chiếu tới thuốc (DISEASES.antibiotics) VÀ bệnh lý mà
  // chính thuốc (thường là kháng sinh tự nhập) tự khai qua `indications` — để "Bệnh lý áp dụng"
  // chọn khi thêm kháng sinh tự nhập đồng bộ với Bước 2 ở đây.
  const diseasesForGroup = useMemo(() => {
    if (!selectedGroup) return []
    const ids = new Set(selectedGroup.entries.map((e) => e.id))
    const indicationDiseaseIds = new Set(selectedGroup.entries.flatMap((e) => e.indications?.map((ind) => ind.diseaseId) ?? []))
    return diseases.filter((d) => d.antibiotics.some((id) => ids.has(id)) || indicationDiseaseIds.has(d.id))
  }, [selectedGroup, diseases])
  const hasDiseaseStep = diseasesForGroup.length > 0

  const selectedDisease =
    diseaseChoice && diseaseChoice !== DISEASE_SKIP ? diseases.find((d) => d.id === diseaseChoice) ?? null : null

  // Đường dùng còn phù hợp: nếu đã chọn bệnh lý cụ thể, chỉ giữ đường dùng được bệnh lý đó tham chiếu
  // (kể cả tham chiếu ngược qua `indications` của chính thuốc); nếu không tìm thấy đường dùng nào khớp
  // (dữ liệu chưa gán) thì rơi về toàn bộ đường dùng của hoạt chất.
  const qualifyingEntries = useMemo(() => {
    if (!selectedGroup) return []
    if (selectedDisease) {
      const filtered = selectedGroup.entries.filter(
        (e) => selectedDisease.antibiotics.includes(e.id) || e.indications?.some((ind) => ind.diseaseId === selectedDisease.id),
      )
      return filtered.length > 0 ? filtered : selectedGroup.entries
    }
    return selectedGroup.entries
  }, [selectedGroup, selectedDisease])

  const readyForEntry = !hasDiseaseStep || diseaseChoice !== null
  const autoEntry = readyForEntry && qualifyingEntries.length === 1 ? qualifyingEntries[0] : null
  const selectedEntry = autoEntry ?? (selectedEntryId ? qualifyingEntries.find((e) => e.id === selectedEntryId) ?? null : null)
  const showRouteStep = readyForEntry && qualifyingEntries.length > 1

  function selectGroup(name: string | null) {
    setSelectedGroupName(name)
    setDiseaseChoice(null)
    setSelectedEntryId(null)
  }

  function chooseDisease(id: string) {
    setDiseaseChoice(id)
    setSelectedEntryId(null)
  }

  function chooseEntry(id: string) {
    setSelectedEntryId(id)
  }

  // Giống bên thuốc truyền: cuộn thẳng tới thẻ liều thay vì bỏ nó dưới hai màn hình cuộn.
  const cardRef = useRef<HTMLDivElement | null>(null)
  useEffect(() => {
    if (!selectedEntry) return
    collapsePatientPanel()
    const t = setTimeout(() => scrollElementIntoView(cardRef.current), 0)
    return () => clearTimeout(t)
  }, [selectedEntry?.id, selectedDisease?.id])

  return (
    <div className="px-5 pb-6">
      {onPatient.length > 0 && (
        <div className="mb-4">
          <SectionLabel tone="accent">Đang dùng cho bệnh nhân · {onPatient.length}</SectionLabel>
          <div className="grid grid-cols-2 gap-2">
            {onPatient.map((d) => {
              const on = selectedEntry?.id === d.id
              return (
                <button
                  key={d.id}
                  onClick={() => {
                    setQuery("")
                    setSelectedGroupName(d.name)
                    setDiseaseChoice(DISEASE_SKIP)
                    setSelectedEntryId(d.id)
                  }}
                  className={`text-left px-3 py-2.5 ${R.box} border ${TAP}`}
                  style={on ? { background: C.accentSoft, borderColor: C.accent } : { background: C.surface, borderColor: C.line }}
                >
                  <p className={`${T.bodyStrong} truncate`} style={{ color: C.text }}>
                    {shortDrugName(d.name)}
                  </p>
                  <p className={`${T.meta} truncate`} style={{ color: C.textSoft }}>
                    {shortRoute(d.route)}
                  </p>
                </button>
              )
            })}
          </div>
        </div>
      )}

      <SectionLabel>Chọn kháng sinh</SectionLabel>
      <SearchField
        value={query}
        onChange={(v) => {
          setQuery(v)
          setSelectedGroupName(null)
          setDiseaseChoice(null)
          setSelectedEntryId(null)
        }}
        placeholder="Tìm kháng sinh..."
      />
      <div className="flex flex-wrap gap-2 mb-3 items-center">
        {/* index chỉ truyền khi CHƯA lọc (mới vào tab) — nếu không, mỗi lần gõ vào ô tìm là một lần
            các chip khớp mới chạy lại stagger, làm cả hàng nhấp nháy trong lúc gõ.
            Nhãn chữ cái: 22 kháng sinh xếp phẳng đọc như một khối tên thuốc liền mạch — chia theo
            chữ cái đầu (tên đã sắp alphabet ở `groups`) cho mắt có điểm dừng, giống danh bạ điện
            thoại. Chỉ hiện khi đang DUYỆT toàn bộ danh sách; ẩn lúc gõ tìm vì kết quả lọc không còn
            liên tục theo alphabet nên nhãn sẽ đọc sai. `basis-full` ép mỗi nhãn xuống dòng riêng
            trong hàng flex-wrap, không cần đổi sang layout dạng lưới/cột. */}
        {filteredGroups.flatMap((g, i) => {
          const letter = g.name.charAt(0).toUpperCase()
          const prevLetter = i > 0 ? filteredGroups[i - 1].name.charAt(0).toUpperCase() : null
          const nodes: React.ReactNode[] = []
          if (!query.trim() && letter !== prevLetter) {
            nodes.push(
              <span key={`letter-${letter}`} className="basis-full text-[12px] font-bold uppercase tracking-wide mt-1 first:mt-0" style={{ color: "var(--c-text-muted)" }}>
                {letter}
              </span>,
            )
          }
          nodes.push(
            <Chip key={g.name} index={query.trim() ? undefined : i} active={effectiveGroupName === g.name} onClick={() => selectGroup(effectiveGroupName === g.name ? null : g.name)}>
              {g.name}
              {g.entries.length > 1 && <span className="opacity-60"> · {g.entries.length}</span>}
            </Chip>,
          )
          return nodes
        })}
      </div>

      {/* Chỉ định — chỉ hiện khi hoạt chất có liều riêng theo bệnh lý, và luôn TRƯỚC bước đường dùng.
          KHÔNG còn chip "Liều chung": liều mặc định của thuốc không đại diện cho một bệnh lý cụ thể
          nào, để chọn được coi như liều đúng cho MỌI bệnh lý là nguồn sai liều nguy hiểm nhất — bắt
          buộc chọn đúng bệnh lý trong danh sách bên dưới. */}
      {selectedGroup && hasDiseaseStep && (
        <div key={selectedGroup.name} className="fade-in mb-3">
          <SectionLabel>Chỉ định</SectionLabel>
          <div className="flex flex-wrap gap-2">
            {diseasesForGroup.map((ds) => (
              <Chip key={ds.id} active={diseaseChoice === ds.id} onClick={() => chooseDisease(ds.id)}>
                {ds.name}
              </Chip>
            ))}
          </div>
        </div>
      )}

      {/* Đường dùng — chỉ hiện khi còn nhiều hơn một lựa chọn phù hợp */}
      {selectedGroup && showRouteStep && (
        <div key={`${selectedGroup.name}-${diseaseChoice ?? "none"}`} className="fade-in mb-3">
          <SectionLabel>Đường dùng</SectionLabel>
          <div className="flex flex-wrap gap-2">
            {qualifyingEntries.map((entry) => (
              <Chip key={entry.id} tone="accent" active={selectedEntryId === entry.id} onClick={() => chooseEntry(entry.id)}>
                {shortRoute(entry.route)}
              </Chip>
            ))}
          </div>
        </div>
      )}

      <div ref={cardRef} style={{ scrollMarginTop: 8 }}>
      {selectedGroup && selectedEntry ? (
        // `key` chỉ theo selectedEntry.id — KHÔNG kèm selectedDisease.id như trước. Kèm theo disease
        // khiến CẢ THẺ (và AntibioticMixPanel bên trong) bị GỠ RỒI DỰNG LẠI TỪ ĐẦU mỗi khi đổi "Chỉ
        // định" dù vẫn cùng một thuốc — mất sạch đường dùng (TTM/TMC) và công thức pha đang gõ dở chỉ
        // vì bấm sang một chip chỉ định khác để so sánh. Đổi thuốc (entry.id đổi) mới thật sự cần dựng
        // lại thẻ; đổi chỉ định trên CÙNG một thuốc thì thẻ phải giữ nguyên trạng thái đang có.
        <div key={selectedEntry.id} className="fade-in">
          <AntibioticDoseCard
            drug={selectedEntry}
            disease={selectedDisease}
            isOverride={Boolean(selectedEntry.isCustom) && STATIC_ANTIBIOTIC_IDS.has(selectedEntry.id)}
            onEdit={onEdit}
            onDelete={onDelete}
          />
        </div>
      ) : (
        <p className={`${T.body} text-center px-4 py-6 ${R.card}`} style={{ background: C.surfaceAlt, color: C.textSoft }}>
          {filteredGroups.length === 0
            ? "Không tìm thấy kháng sinh phù hợp."
            : !selectedGroup
              ? "Chọn một kháng sinh ở trên để xem liều theo CrCl."
              : hasDiseaseStep && diseaseChoice === null
                ? "Chọn chỉ định ở trên để tiếp tục."
                : "Chọn đường dùng ở trên để xem liều."}
        </p>
      )}
      </div>

      <button
        onClick={onAddNew}
        className={`w-full flex items-center justify-center gap-2 h-11 ${R.box} border border-dashed mt-3 ${T.bodyStrong}`}
        style={{ borderColor: C.primaryLine, color: C.primary }}
      >
        <span className="scale-90">{icons.plus()}</span>
        Thêm kháng sinh tự nhập
      </button>
    </div>
  )
}

// ─── Thuốc co bóp cơ tim / Thuốc vận mạch ─────────────────────────────────────

// Tính tốc độ truyền (mL/h) từ cân nặng (nếu thuốc chỉnh theo cân nặng), nồng độ pha, và liều mong muốn.
// unitScale quy đổi nồng độ về cùng đơn vị với liều (vd. mg/mL -> mcg/mL nhân 1000; đơn vị/mL giữ nguyên).
// doseTimeBasis: đa số thuốc nhập liều theo phút (mcg/kg/phút, mg/phút...) nên cần nhân 60 để ra liều/giờ;
// một số thuốc (vd. Nicardipine tính mg/giờ) đã nhập liều theo giờ sẵn nên không nhân 60 nữa.
// Máy tính pha thuốc: đổi được đơn vị liều và chạy được cả HAI CHIỀU.
// - "Liều → Tốc độ": biết muốn truyền bao nhiêu liều, cần đặt bơm mấy mL/giờ.
// - "Tốc độ → Liều": nhìn bơm đang chạy mấy mL/giờ, suy ra bệnh nhân đang nhận liều bao nhiêu
//   (tình huống rất hay gặp khi nhận bàn giao ca hoặc kiểm tra lại y lệnh).
// Toàn bộ quy đổi nằm trong lib/infusion.ts, không phụ thuộc hệ số khai báo sẵn theo từng thuốc.
// ─── Liều nạp / bolus ─────────────────────────────────────────────────────────
// Amiodarone, magie, lidocaine, esmolol... đều phải nạp trước rồi mới duy trì. Trước đây liều nạp
// chỉ nằm trong câu chữ "Cách pha" và không được tính giúp — dù đây đúng là chỗ dễ nhẩm sai nhất
// (liều theo mg/kg, nhân nhẩm lúc cấp cứu).
function BolusList({
  boluses,
  drugName,
  doseWeightBasis,
}: {
  boluses: BolusDose[] | undefined
  drugName: string
  doseWeightBasis?: WeightBasis
}) {
  const { abwKg, heightCm, patient, openPatientPanel, logCalc } = useDosing()
  const dosingWeight = useMemo(
    () => resolveDosingWeight(abwKg, heightCm, patient.sex, doseWeightBasis ?? "actual"),
    [abwKg, heightCm, patient.sex, doseWeightBasis],
  )
  const weightKg = dosingWeight.used
  // Liều nạp/bolus nhân trực tiếp mg/kg × cân nặng, giống hệt bảng liều mg/kg — cân nặng gõ nhầm
  // (vd 5000 kg) phải chặn ở đây luôn, không chỉ ở khung "Bệnh nhân hiện tại".
  const weightWarn = checkWeight(weightKg)
  const weightImplausible = weightWarn?.severity === "implausible"
  const list = boluses ?? []
  if (list.length === 0) return null

  function describe(b: BolusDose): { text: string; needWeight: boolean; blocked: boolean; perKgText: string | null } {
    if (b.perKgLow != null) {
      const perKgText = b.perKgHigh != null ? `${b.perKgLow}–${b.perKgHigh} ${b.unit}/kg` : `${b.perKgLow} ${b.unit}/kg`
      if (weightKg == null) return { text: "—", needWeight: true, blocked: false, perKgText }
      if (weightImplausible) return { text: "—", needWeight: false, blocked: true, perKgText }
      const lo = b.perKgLow * weightKg
      const hi = b.perKgHigh != null ? b.perKgHigh * weightKg : null
      const base = hi != null ? `${formatMass(lo, b.unit)} – ${formatMass(hi, b.unit)}` : formatMass(lo, b.unit)
      const withCap = b.maxSingle != null && (hi ?? lo) > b.maxSingle ? `${base} — nhưng không vượt quá ${formatMass(b.maxSingle, b.unit)}` : base
      return { text: withCap, needWeight: false, blocked: false, perKgText }
    }
    if (b.fixedLow != null) {
      const base = b.fixedHigh != null ? `${formatMass(b.fixedLow, b.unit)} – ${formatMass(b.fixedHigh, b.unit)}` : formatMass(b.fixedLow, b.unit)
      return { text: base, needWeight: false, blocked: false, perKgText: null }
    }
    return { text: "—", needWeight: false, blocked: false, perKgText: null }
  }

  // Tiêu đề mục do khối gấp/mở ở ngoài lo, ở đây chỉ vẽ danh sách.
  return (
    <div>
      {list.map((b, i) => {
        const info = describe(b)
        return (
          <div
            key={i}
            className="px-3 py-2.5 rounded-xl mb-1.5"
            style={
              info.blocked
                ? { background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-icon)" }
                : { background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }
            }
          >
            <p className="text-[12px] font-bold leading-[1.45]" style={{ color: info.blocked ? "var(--c-danger-deep)" : "var(--c-warn)" }}>{b.label}</p>
            {info.perKgText && <p className="text-[12px]" style={{ color: info.blocked ? "var(--c-danger-deep)" : "var(--c-warn-icon)" }}>Theo cân nặng: {info.perKgText}</p>}
            {info.needWeight ? (
              <button onClick={openPatientPanel} className="text-[12px] font-bold underline mt-0.5" style={{ color: "var(--c-warn-icon)" }}>
                Nhập cân nặng ở khung "Bệnh nhân hiện tại" để tính ra số mg
              </button>
            ) : info.blocked ? (
              <>
                <p className="text-[12px] font-bold leading-[1.45] mt-0.5" style={{ color: "var(--c-danger-deep)" }}>
                  Không tính liều nạp: {weightWarn?.message}
                </p>
                <button onClick={openPatientPanel} className="text-[12px] font-bold underline mt-0.5" style={{ color: "var(--c-danger)" }}>
                  Sửa lại cân nặng ở khung "Bệnh nhân hiện tại"
                </button>
              </>
            ) : (
              <p className={`${T.title} ${NUM} mt-0.5`} style={{ color: C.warn }}>{info.text}</p>
            )}
            {b.over && <p className="text-[12px] leading-[1.45]" style={{ color: "var(--c-warn-icon)" }}>Cách dùng: {b.over}</p>}
            {b.note && <p className="text-[12px] leading-[1.45] mt-0.5" style={{ color: "var(--c-warn-icon)" }}>{b.note}</p>}
            {!info.needWeight && !info.blocked && (
              <button
                onClick={() => {
                  logCalc({
                    drug: drugName,
                    kind: "bolus",
                    inputs: [b.label, ...(info.perKgText ? [`Liều theo cân nặng: ${info.perKgText}`] : []), ...(b.over ? [`Cách dùng: ${b.over}`] : [])],
                    output: info.text,
                  })
                  tickHaptic()
                }}
                className="text-[12px] font-bold mt-1.5"
                style={{ color: "var(--c-warn-icon)" }}
              >
                Lưu vào nhật ký
              </button>
            )}
          </div>
        )
      })}
    </div>
  )
}

// ─── Bảng pha thuốc ───────────────────────────────────────────────────────────
// Chiều tính mà lúc đứng cạnh giường mới thực sự cần: "tôi có ống 250 mg, pha vừa đủ 50 mL" →
// nồng độ; và chiều ngược lại "tôi cần nồng độ này" → lấy mấy ống, rút bao nhiêu mL.
//
// Màn này dùng lúc gấp nên chỉ giữ những dòng dẫn thẳng tới một thao tác. Phần tra cứu (bảo quản
// sau pha, ngưỡng nồng độ cho đường ngoại biên) đã bỏ khỏi đây: mười dòng chữ quanh một con số thì
// lúc cần nhanh không ai đọc, mà chúng còn làm loãng đúng cái cảnh báo phải đọc. Dữ liệu vẫn còn
// trong data/*.ts để tra khi cần.
const MIX_UNIT_CHOICES = ["mcg", "mg", "g", "đơn vị", "mEq"]

// Một phương án pha đã tính xong — dùng chung cho cả hai chiều tính, để chiều nào cũng đi qua đúng
// một đường kiểm tra.
interface MixOutcome {
  concValue: number
  volumeMl: number
  // Số ống/lọ dùng thật — có thể lẻ khi rút một phần ống.
  vials: number
  // Số ống/lọ phải bóc ra. Chỉ khác `vials` ở phương án rút lẻ (phần thừa bỏ đi).
  vialsOpened: number
  // Thể tích thuốc phải rút, khi phương án là rút lẻ ống. null = dùng trọn ống.
  drawMl: number | null
  vialAmount: number
  vialUnit: string
  spec: VialSpec
  diluent: string
}

// Thể tích thuốc chiếm chỗ trong bơm/chai cuối cùng.
function outcomeDrugVolume(o: MixOutcome): number | null {
  return o.drawMl ?? vialsTotalVolume(o.vials, o.spec)
}

// Câu duy nhất người đứng cạnh bàn pha thực sự thao tác. Ba dạng, vì ba thao tác khác hẳn nhau:
// rút trọn ống dung dịch, hoàn nguyên lọ bột, và rút lẻ một phần ống.
function describeComposition(o: MixOutcome, vialLabel: string): string {
  const drugVolume = outcomeDrugVolume(o)
  const dil = diluentVolume(o.volumeMl, drugVolume)
  const mass = formatMass(o.vials * o.vialAmount, o.vialUnit)
  const finalText = `${trim(o.volumeMl)} mL`

  if (o.drawMl != null) {
    // Rút lẻ: con số phải nhớ là số mL rút ra, không phải số ống.
    const source =
      o.spec.form === "powder"
        ? `${o.vialsOpened} ${vialLabel} × ${formatMass(o.vialAmount, o.vialUnit)} đã pha ban đầu với ${trim(o.spec.reconstituteMl as number)} mL/${vialLabel}`
        : `${o.vialsOpened} ${vialLabel} × ${formatMass(o.vialAmount, o.vialUnit)}`
    const base = `Rút ${formatDoseNumber(o.drawMl)} mL (= ${mass}) từ ${source}`
    return dil != null ? `${base} + ${formatDoseNumber(dil)} mL ${o.diluent} = ${finalText}` : `${base}, pha vừa đủ ${finalText}`
  }

  const amount = `${trim(o.vials)} ${vialLabel} × ${formatMass(o.vialAmount, o.vialUnit)} = ${mass}`
  if (drugVolume == null || dil == null) return `${amount}, pha vừa đủ ${finalText}`

  if (o.spec.form === "powder") {
    const displaced = (o.spec.displacementMl ?? 0) > 0
    return `Pha ban đầu ${trim(o.vials)} ${vialLabel} với ${trim(o.spec.reconstituteMl as number)} mL → rút ${formatDoseNumber(drugVolume)} mL${displaced ? " (đã cộng thể tích bột tăng sau pha)" : ""} (${amount}) + ${formatDoseNumber(dil)} mL ${o.diluent} = ${finalText}`
  }
  return `Rút ${formatDoseNumber(drugVolume)} mL thuốc (${amount}) + ${formatDoseNumber(dil)} mL ${o.diluent} = ${finalText}`
}

// ─── Bơm này chạy được bao lâu ────────────────────────────────────────────────
// Câu quyết định "pha 50 hay 100 mL" — và trước đây phải đóng bảng pha, quay về máy tính liều mới
// trả lời được. Một dòng, ngay dưới công thức, ở đúng lúc đang chọn thể tích.
function MixRunTime({ drug, calc, concValue, volumeMl }: { drug: InfusionDrug; calc: InfusionCalcConfig; concValue: number; volumeMl: number }) {
  const { abwKg, heightCm, patient } = useDosing()
  const unit = useMemo(() => parseDoseUnit(calc.doseUnit), [calc.doseUnit])
  const weightKg = useMemo(
    () => resolveDosingWeight(abwKg, heightCm, patient.sex, drug.doseWeightBasis ?? "actual").used,
    [abwKg, heightCm, patient.sex, drug.doseWeightBasis],
  )
  if (!unit || !(concValue > 0) || !(volumeMl > 0)) return null

  const lo = doseToRate(calc.doseMin, unit, weightKg, concValue, calc.concUnit)
  const hi = doseToRate(calc.doseMax, unit, weightKg, concValue, calc.concUnit)
  if (lo == null || hi == null) {
    if (unit.perWeight && weightKg == null) {
      return (
        <p className={`${T.meta} mt-1`} style={{ color: C.textSoft }}>
          Nhập cân nặng ở khung Bệnh nhân để biết bơm này chạy được bao lâu.
        </p>
      )
    }
    return null
  }

  const slowest = infusionDurationHours(volumeMl, lo)
  const fastest = infusionDurationHours(volumeMl, hi)
  return (
    <p className={`${T.meta} ${NUM} mt-1`} style={{ color: C.textSoft }}>
      Liều thường dùng {calc.doseMin}–{calc.doseMax} {calc.doseUnit} → <b>{formatDoseNumber(lo)}–{formatDoseNumber(hi)} mL/giờ</b>
      {slowest != null && fastest != null && <> · {trim(volumeMl)} mL chạy được {formatDuration(fastest)} – {formatDuration(slowest)}</>}
    </p>
  )
}

function MixResultCard({
  drug,
  calc,
  outcome,
  vialLabel,
  refConc,
  refLabel,
  headline,
  subline,
  onUse,
  onSaveWard,
}: {
  drug: InfusionDrug
  calc: InfusionCalcConfig
  outcome: MixOutcome
  vialLabel: string
  refConc: number | undefined
  refLabel: string
  headline: string
  subline?: string
  onUse: () => void
  onSaveWard: () => void
}) {
  const [confirmed, setConfirmed] = useState(false)

  const drugVolume = outcomeDrugVolume(outcome)
  const dil = diluentVolume(outcome.volumeMl, drugVolume)
  // Kiểm tra vật lý: riêng thể tích thuốc đã vượt thể tích cuối thì công thức không pha được.
  const impossible = dil != null && dil < -1e-9

  const grade = gradeConcentration(outcome.concValue, refConc, calc.mix?.maxConc, calc.concUnit, refLabel)
  useEffect(() => setConfirmed(false), [outcome.concValue, outcome.volumeMl, outcome.vials])
  const blocked = grade.requiresConfirm && !confirmed

  if (impossible) {
    const per = volumePerVial(outcome.spec)
    return (
      <div className="px-3 py-2.5 rounded-xl mb-1 flex items-start gap-2" style={{ background: "var(--c-danger-soft)", border: "1px solid var(--c-danger-icon)" }}>
        <span className="mt-0.5 flex-none" style={{ color: "var(--c-danger-icon)" }}>{icons.alert()}</span>
        <div>
          <p className={T.critical} style={{ color: "var(--c-danger-deep)" }}>Không pha được</p>
          <p className={`${T.meta} mt-0.5`} style={{ color: "var(--c-danger-deep)" }}>
            {trim(outcome.vials)} {vialLabel} × {trim(per as number)} mL = {formatDoseNumber(drugVolume as number)} mL thuốc, đã nhiều hơn thể tích cuối {trim(outcome.volumeMl)} mL. Kiểm tra lại số {vialLabel}, thể tích 1 {vialLabel} hoặc thể tích cuối.
          </p>
        </div>
      </div>
    )
  }

  const gradeStyle =
    grade.severity === "danger"
      ? { bg: "var(--c-danger-soft)", border: "var(--c-danger-icon)", fg: "var(--c-danger-deep)" }
      : { bg: "var(--c-warn-soft)", border: "var(--c-warn-line)", fg: "var(--c-warn)" }

  return (
    <div className="px-3 py-2.5 rounded-xl mb-1" style={{ background: "var(--c-surface)", border: "1px solid var(--c-line-strong)" }}>
      <p className="text-[13px] font-bold text-slate-800 leading-[1.45]">{headline}</p>
      {subline && <p className="text-[12px] text-slate-500 leading-[1.45] mt-0.5">{subline}</p>}
      {/* Câu duy nhất người đứng cạnh bàn pha thực sự thao tác */}
      <p className="text-[12px] font-semibold leading-[1.45] mt-1" style={{ color: "var(--c-accent-deep)" }}>
        {describeComposition(outcome, vialLabel)}
      </p>
      {drugVolume == null && (
        <p className="text-[12px] text-slate-500 leading-[1.45] mt-0.5">
          {outcome.spec.form === "powder"
            ? `Nhập thể tích pha ban đầu 1 ${vialLabel} ở trên để app tính ra số mL dung môi phải thêm.`
            : `Nhập thể tích 1 ${vialLabel} ở trên để app tính ra số mL dung môi phải thêm.`}
        </p>
      )}

      <MixRunTime drug={drug} calc={calc} concValue={outcome.concValue} volumeMl={outcome.volumeMl} />

      {grade.severity !== "ok" && (
        <div className="mt-2 px-2.5 py-2 rounded-xl flex items-start gap-2" style={{ background: gradeStyle.bg, border: `1px solid ${gradeStyle.border}` }}>
          <span className="mt-0.5 flex-none" style={{ color: gradeStyle.fg }}>{icons.alert()}</span>
          <div>
            {grade.headline && <p className="text-[12px] font-extrabold leading-[1.3]" style={{ color: gradeStyle.fg }}>{grade.headline}</p>}
            {grade.detail && <p className="text-[12px] leading-[1.45] mt-0.5" style={{ color: gradeStyle.fg }}>{grade.detail}</p>}
          </div>
        </div>
      )}

      {blocked ? (
        <button
          onClick={() => {
            setConfirmed(true)
            tickHaptic()
          }}
          className={`${BTN_TALL} mt-2 border-transparent`}
          style={{ background: gradeStyle.fg, color: "var(--c-on-bright)" }}
        >
          Tôi đã kiểm tra lại — vẫn dùng công thức này
        </button>
      ) : (
        <div className="flex flex-wrap gap-1.5 mt-2">
          <button onClick={onUse} className="h-9 px-3 rounded-full text-[12px] font-bold dose-press" style={{ background: "var(--c-accent)", color: "var(--c-on-bright)" }}>
            Dùng nồng độ này
          </button>
          <button
            onClick={onSaveWard}
            className="h-9 px-3 rounded-full text-[12px] font-bold border dose-press"
            style={{ borderColor: "var(--c-accent-line)", color: "var(--c-accent-deep)" }}
          >
            Lưu công thức mới của bạn
          </button>
        </div>
      )}
    </div>
  )
}

// Ba cách xử lý khi số ống tính ra không tròn. Cách thứ ba (rút lẻ ống) mới là cách hay làm nhất
// với ống dung dịch: cần 200 mg từ ống 250 mg/20 mL thì rút 16 mL là xong, không việc gì phải đổ cả
// ống rồi nâng thể tích cuối lên cho khớp.
type MixRoundMode = "keepConc" | "keepVolume" | "partial"

function MixPanel({
  drug,
  calc,
  wardRecipe,
  onUseConc,
  onSaveWard,
}: {
  drug: InfusionDrug
  calc: InfusionCalcConfig
  wardRecipe?: WardRecipe
  onUseConc: (concValue: number, volumeMl: number) => void
  onSaveWard: (recipe: Omit<WardRecipe, "savedAt" | "id"> & { id?: string }) => void
}) {
  const { logCalc } = useDosing()
  const concMass = massOfConcUnit(calc.concUnit)
  const mix = calc.mix
  const vialLabel = mix?.vialLabel ?? "ống"

  // Công thức đã lưu (nếu có) được ưu tiên làm giá trị khởi tạo — đó là điểm khác biệt giữa một app
  // dùng hằng ngày và một app phải khai báo lại từ đầu mỗi lần mở.
  const [vialAmount, setVialAmount] = useState(String(wardRecipe?.vialAmount ?? mix?.vialAmount ?? ""))
  const [vialUnit, setVialUnit] = useState(wardRecipe?.vialUnit ?? mix?.vialUnit ?? concMass)
  const [vials, setVials] = useState(String(wardRecipe?.vials ?? mix?.vials ?? 1))
  // MỘT ô thể tích duy nhất cho cả hai chiều tính.
  const [volume, setVolume] = useState(String(wardRecipe?.volumeMl ?? mix?.volumeMl ?? 50))
  const [vialForm, setVialForm] = useState<VialForm>(wardRecipe?.vialForm ?? mix?.vialForm ?? "solution")
  const [vialVolume, setVialVolume] = useState(
    wardRecipe?.vialVolumeMl != null ? String(wardRecipe.vialVolumeMl) : mix?.vialVolumeMl != null ? String(mix.vialVolumeMl) : "",
  )
  const [reconstitute, setReconstitute] = useState(
    wardRecipe?.reconstituteMl != null ? String(wardRecipe.reconstituteMl) : mix?.reconstituteMl != null ? String(mix.reconstituteMl) : "",
  )
  const [displacement, setDisplacement] = useState(
    wardRecipe?.displacementMl != null ? String(wardRecipe.displacementMl) : mix?.displacementMl != null ? String(mix.displacementMl) : "",
  )
  const [diluent, setDiluent] = useState(wardRecipe?.diluent ?? mix?.diluents?.[0] ?? "NaCl 0,9%")
  const [target, setTarget] = useState("")
  const [roundMode, setRoundMode] = useState<MixRoundMode>("keepConc")
  const [saveTitle, setSaveTitle] = useState("")

  const unitChoices = useMemo(() => MIX_UNIT_CHOICES.filter((u) => massFactor(u, concMass) != null), [concMass])
  const allowedDiluents = mix?.diluents ?? ["NaCl 0,9%", "Glucose 5%"]
  const avoidDiluents = mix?.avoidDiluents ?? []
  // Cảnh báo dung môi chỉ nổ khi người dùng thực sự chọn dung môi cấm. Trước đây nó hiện thường
  // trực, nên chọn ĐÚNG Glucose 5% cho amiodarone vẫn thấy một khối đỏ — kiểu cảnh báo dạy người ta
  // bỏ qua màu đỏ.
  const diluentBlocked = avoidDiluents.includes(diluent)

  const va = parseFloat(vialAmount)
  const nv = parseFloat(vials)
  const vol = parseFloat(volume)
  const num = (s: string) => {
    const n = parseFloat(s)
    return isNaN(n) || n < 0 ? null : n
  }
  const spec = useMemo<VialSpec>(
    () => ({
      form: vialForm,
      volumeMl: vialForm === "solution" ? (num(vialVolume) || null) : null,
      reconstituteMl: vialForm === "powder" ? (num(reconstitute) || null) : null,
      displacementMl: vialForm === "powder" ? num(displacement) : null,
    }),
    [vialForm, vialVolume, reconstitute, displacement],
  )

  const mixedConc = concentrationFromVials(va, nv, vol, vialUnit, calc.concUnit)

  const tgt = parseFloat(target)
  const neededVialsRaw = vialsForConcentration(tgt, va, vol, vialUnit, calc.concUnit)
  const neededVials = neededVialsRaw != null ? Math.max(1, Math.ceil(neededVialsRaw - 1e-9)) : null
  const concIfRounded = neededVials != null ? concentrationFromVials(va, neededVials, vol, vialUnit, calc.concUnit) : null
  // Giữ ĐÚNG nồng độ mong muốn bằng cách chỉnh thể tích cuối thay vì chịu lệch nồng độ.
  const volForExact = neededVials != null ? volumeForConcentration(tgt, va, neededVials, vialUnit, calc.concUnit) : null
  const draw = useMemo(() => partialDraw(tgt, vol, va, vialUnit, calc.concUnit, spec), [tgt, vol, va, vialUnit, calc.concUnit, spec])
  const needsRounding = neededVialsRaw != null && neededVials != null && Math.abs(neededVialsRaw - neededVials) > 1e-6
  // Rút lẻ chỉ có nghĩa khi biết thể tích rút ra từ một ống. Không đủ số liệu thì không đưa lựa
  // chọn ra rồi để nó chết ở giữa — quay về phương án giữ nồng độ.
  const canDrawPartial = draw != null
  const mode: MixRoundMode = roundMode === "partial" && !canDrawPartial ? "keepConc" : roundMode

  const fieldClass = FIELD
  const fieldStyle = FIELD_STYLE

  // Mốc so sánh nồng độ: công thức người dùng đã lưu, nếu chưa lưu thì công thức dựng sẵn của app.
  const refConc = wardRecipe?.concValue ?? calc.concDefault
  const refLabel = wardRecipe ? "công thức của bạn" : "công thức chuẩn"

  function outcomeFor(concValue: number, volumeMl: number, vialsCount: number, opened?: number, drawMl?: number): MixOutcome {
    return {
      concValue,
      volumeMl,
      vials: vialsCount,
      vialsOpened: opened ?? Math.max(1, Math.ceil(vialsCount - 1e-9)),
      drawMl: drawMl ?? null,
      vialAmount: va,
      vialUnit,
      spec,
      diluent,
    }
  }

  function useOutcome(o: MixOutcome, inputs: string[]) {
    onUseConc(o.concValue, o.volumeMl)
    logCalc({
      drug: drug.name,
      kind: "mix",
      inputs: [...inputs, describeComposition(o, vialLabel)],
      output: `Nồng độ ${formatDoseNumber(o.concValue)} ${calc.concUnit} trong ${trim(o.volumeMl)} mL`,
    })
    tickHaptic()
  }

  function saveWardFrom(o: MixOutcome) {
    onSaveWard({
      drugId: drug.id,
      title: saveTitle.trim() || `${o.diluent} · ${o.vials} ${vialLabel}`,
      concValue: o.concValue,
      vialAmount: o.vialAmount,
      vialUnit: o.vialUnit,
      vials: o.vials,
      volumeMl: o.volumeMl,
      vialForm: o.spec.form,
      vialVolumeMl: o.spec.volumeMl ?? undefined,
      reconstituteMl: o.spec.reconstituteMl ?? undefined,
      displacementMl: o.spec.displacementMl ?? undefined,
      diluent: o.diluent,
    })
    setSaveTitle("")
    tickHaptic()
  }

  const pill = (on: boolean) =>
    on
      ? { background: "var(--c-accent)", borderColor: "var(--c-accent)", color: "var(--c-on-bright)" }
      : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }

  return (
    <div className="mt-2.5 p-3 rounded-xl fade-in" style={{ background: "var(--c-surface-alt)", border: "1px solid var(--c-line)" }}>
      {/* Dung môi — thông tin sống còn với thuốc kén dung môi */}
      <label className={`${T.label} text-slate-500 mb-1 block`}>Dung môi</label>
      <div className="flex flex-wrap gap-1.5 mb-1.5">
        {allowedDiluents.map((d) => (
          <button key={d} onClick={() => setDiluent(d)} className={CHIP} style={pill(diluent === d)}>
            {d}
          </button>
        ))}
        {/* Dung môi cấm vẫn bấm được: "dùng NaCl có sao không" là câu người ta hỏi, và bấm vào để
            nhận câu trả lời đỏ rõ ràng thì tốt hơn là không tìm thấy nút nào để hỏi. */}
        {avoidDiluents.map((d) => (
          <button
            key={d}
            onClick={() => setDiluent(d)}
            className={CHIP}
            style={
              diluent === d
                ? { background: "var(--c-danger-icon)", borderColor: "var(--c-danger-icon)", color: "var(--c-on-bright)" }
                : { background: "var(--c-surface)", borderColor: "var(--c-danger-line)", color: "var(--c-danger-deep)" }
            }
          >
            {d}
          </button>
        ))}
      </div>
      {diluentBlocked && (
        <p className="text-[12px] font-bold leading-[1.45] mb-2 px-2.5 py-2 rounded-xl" style={{ background: "var(--c-danger-soft)", color: "var(--c-danger-deep)" }}>
          {mix?.diluentWarning ?? `Không pha ${drug.name} với ${diluent}.`}
        </p>
      )}

      {/* Ống dung dịch hay lọ bột — hai thao tác khác hẳn nhau, và chọn sai thì con số mL dung môi
          in ra bên dưới sai theo. */}
      <label className={`${T.label} text-slate-500 mb-1 block`}>Dạng chế phẩm</label>
      <div className="flex flex-wrap gap-1.5 mb-2">
        {([
          { v: "solution" as VialForm, label: `Ống dung dịch` },
          { v: "powder" as VialForm, label: `Lọ bột` },
        ]).map((opt) => (
          <button key={opt.v} onClick={() => setVialForm(opt.v)} className={CHIP} style={pill(vialForm === opt.v)}>
            {opt.label}
          </button>
        ))}
      </div>

      <div className="mb-2">
        <label className={`${T.label} text-slate-500 mb-1 block`}>Tên công thức khi lưu (tuỳ chọn, vd: Khoa Hồi sức)</label>
        <input value={saveTitle} onChange={(e) => setSaveTitle(e.target.value)} placeholder="Đặt tên để bấm nhanh đổi lại sau này" maxLength={40} className={fieldClass} style={fieldStyle} />
      </div>

      {/* Ống dung dịch: 3 ô ngắn vừa khít một hàng. Lọ bột thì tách "Pha ban đầu với (mL/lọ)" ra
          hàng riêng — nhãn này dài hơn hẳn "Thể tích 1 ống (mL)", nhét vào 1/3 hàng sẽ xuống dòng và
          đẩy ô nhập tụt xuống so với hai ô bên cạnh (không còn ngang hàng). */}
      <div className={`grid ${vialForm === "solution" ? "grid-cols-3" : "grid-cols-2"} gap-2 mb-2`}>
        <div>
          <label className={`${T.label} text-slate-500 mb-1 block`}>Hàm lượng 1 {vialLabel}</label>
          <input value={vialAmount} onChange={(e) => setVialAmount(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="250" className={fieldClass} style={fieldStyle} />
        </div>
        {vialForm === "solution" && (
          <div>
            <label className={`${T.label} text-slate-500 mb-1 block`}>Thể tích 1 {vialLabel} (mL)</label>
            <input value={vialVolume} onChange={(e) => setVialVolume(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="5" className={fieldClass} style={fieldStyle} />
          </div>
        )}
        <div>
          <label className={`${T.label} text-slate-500 mb-1 block`}>Số {vialLabel}</label>
          <input value={vials} onChange={(e) => setVials(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="1" className={fieldClass} style={fieldStyle} />
        </div>
      </div>

      {/* Xếp dọc, mỗi ô một hàng riêng — không ghép ngang: "Thể tích bột tăng sau pha" luôn dài hơn
          hẳn "Pha ban đầu với", và độ dài {vialLabel} (lọ/ống/chai) đổi theo từng thuốc nên không
          thể tin là hai nhãn sẽ luôn xuống dòng đối xứng nhau ở mọi cỡ chữ. */}
      {vialForm === "powder" && (
        <div className="space-y-2 mb-2">
          <div>
            <label className={`${T.label} text-slate-500 mb-1 block`}>Pha ban đầu với (mL/{vialLabel})</label>
            <input value={reconstitute} onChange={(e) => setReconstitute(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="10" className={fieldClass} style={fieldStyle} />
          </div>
          <div>
            {/* Bột tan ra làm thể tích tăng thật: vancomycin 1 g tăng thêm ~0,7 mL. Bỏ qua là sai hệ
                thống theo một chiều — nồng độ thực luôn loãng hơn con số in ra. */}
            <label className={`${T.label} text-slate-500 mb-1 block`}>Thể tích bột tăng sau pha (mL/{vialLabel})</label>
            <input value={displacement} onChange={(e) => setDisplacement(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="0,7" className={fieldClass} style={fieldStyle} />
          </div>
        </div>
      )}

      <div className="mb-2">
        <label className={`${T.label} text-slate-500 mb-1 block`}>Thể tích cuối sau pha (mL)</label>
        <input value={volume} onChange={(e) => setVolume(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="50" className={fieldClass} style={fieldStyle} />
      </div>

      {unitChoices.length > 1 && (
        <div className="flex flex-wrap gap-1.5 mb-2.5">
          {unitChoices.map((u) => (
            <button key={u} onClick={() => setVialUnit(u)} className={CHIP} style={pill(vialUnit === u)}>
              {u}
            </button>
          ))}
        </div>
      )}

      <p className="text-[12px] font-bold mb-1.5 text-slate-500">Tôi có {vialLabel} thuốc → nồng độ bao nhiêu</p>
      {mixedConc != null && !isNaN(nv) && (
        <MixResultCard
          drug={drug}
          calc={calc}
          vialLabel={vialLabel}
          refConc={refConc}
          refLabel={refLabel}
          outcome={outcomeFor(mixedConc, vol, nv)}
          headline={`Nồng độ ${formatDoseNumber(mixedConc)} ${calc.concUnit}`}
          onUse={() => useOutcome(outcomeFor(mixedConc, vol, nv), [`${vials} ${vialLabel} × ${formatMass(va, vialUnit)}`, `Pha vừa đủ ${vol} mL`])}
          onSaveWard={() => saveWardFrom(outcomeFor(mixedConc, vol, nv))}
        />
      )}

      <p className="text-[12px] font-bold mb-1.5 mt-3 text-slate-500">Tôi cần nồng độ này → lấy mấy {vialLabel}</p>
      <div className="mb-2">
        <label className={`${T.label} text-slate-500 mb-1 block`}>Nồng độ mong muốn ({calc.concUnit})</label>
        <input value={target} onChange={(e) => setTarget(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder={calc.concDefault != null ? String(calc.concDefault * 2) : ""} className={fieldClass} style={fieldStyle} />
      </div>
      {needsRounding && (
        <div className="flex p-0.5 rounded-xl mb-2" style={{ background: "var(--c-line)" }}>
          {([
            { v: "keepConc" as MixRoundMode, label: "Giữ nồng độ", on: true },
            { v: "keepVolume" as MixRoundMode, label: "Giữ thể tích", on: true },
            { v: "partial" as MixRoundMode, label: `Rút lẻ ${vialLabel}`, on: canDrawPartial },
          ]).map((opt) => (
            <button
              key={opt.v}
              onClick={() => opt.on && setRoundMode(opt.v)}
              disabled={!opt.on}
              className="flex-1 h-9 rounded-[10px] text-[12px] font-bold leading-[1.3]"
              style={
                mode === opt.v
                  ? { background: "var(--c-surface)", color: "var(--c-accent-deep)" }
                  : { background: "transparent", color: opt.on ? "var(--c-text-muted)" : "var(--c-muted)", opacity: opt.on ? 1 : 0.5 }
              }
            >
              {opt.label}
            </button>
          ))}
        </div>
      )}
      {neededVials != null && neededVialsRaw != null && concIfRounded != null && (
        mode === "partial" && draw != null ? (
          <MixResultCard
            drug={drug}
            calc={calc}
            vialLabel={vialLabel}
            refConc={refConc}
            refLabel={refLabel}
            outcome={outcomeFor(tgt, vol, draw.vialsUsed, draw.vialsOpened, draw.drawMl)}
            headline={`Rút ${formatDoseNumber(draw.drawMl)} mL, pha vừa đủ ${trim(vol)} mL`}
            subline={`Bóc ${draw.vialsOpened} ${vialLabel}, rút đúng lượng cần rồi bỏ phần thừa — giữ nguyên cả nồng độ ${formatDoseNumber(tgt)} ${calc.concUnit} lẫn thể tích ${trim(vol)} mL.`}
            onUse={() =>
              useOutcome(outcomeFor(tgt, vol, draw.vialsUsed, draw.vialsOpened, draw.drawMl), [
                `Nồng độ mong muốn ${target} ${calc.concUnit}`,
                `Rút lẻ ${formatDoseNumber(draw.drawMl)} mL, thể tích cuối ${vol} mL`,
              ])
            }
            onSaveWard={() => saveWardFrom(outcomeFor(tgt, vol, draw.vialsUsed, draw.vialsOpened, draw.drawMl))}
          />
        ) : mode === "keepConc" && volForExact != null ? (
          <MixResultCard
            drug={drug}
            calc={calc}
            vialLabel={vialLabel}
            refConc={refConc}
            refLabel={refLabel}
            outcome={outcomeFor(tgt, volForExact, neededVials)}
            headline={`Lấy ${neededVials} ${vialLabel}, pha vừa đủ ${trim(volForExact)} mL`}
            subline={
              needsRounding
                ? `Cần chính xác ${formatDoseNumber(neededVialsRaw)} ${vialLabel} cho ${trim(vol)} mL; lấy tròn ${neededVials} ${vialLabel} rồi nâng thể tích lên ${trim(volForExact)} mL thì giữ ĐÚNG nồng độ ${formatDoseNumber(tgt)} ${calc.concUnit}.`
                : undefined
            }
            onUse={() =>
              useOutcome(outcomeFor(tgt, volForExact, neededVials), [
                `Nồng độ mong muốn ${target} ${calc.concUnit}`,
                `Giữ đúng nồng độ, chỉnh thể tích cuối thành ${trim(volForExact)} mL`,
              ])
            }
            onSaveWard={() => saveWardFrom(outcomeFor(tgt, volForExact, neededVials))}
          />
        ) : (
          <MixResultCard
            drug={drug}
            calc={calc}
            vialLabel={vialLabel}
            refConc={refConc}
            refLabel={refLabel}
            outcome={outcomeFor(concIfRounded, vol, neededVials)}
            headline={`Lấy ${neededVials} ${vialLabel}, pha vừa đủ ${trim(vol)} mL`}
            subline={
              needsRounding
                ? `Cần chính xác ${formatDoseNumber(neededVialsRaw)} ${vialLabel}; lấy tròn ${neededVials} ${vialLabel} thì nồng độ thực là ${formatDoseNumber(concIfRounded)} ${calc.concUnit} (mong muốn ${formatDoseNumber(tgt)}).`
                : undefined
            }
            onUse={() =>
              useOutcome(outcomeFor(concIfRounded, vol, neededVials), [
                `Nồng độ mong muốn ${target} ${calc.concUnit}`,
                `Thể tích cuối ${vol} mL`,
              ])
            }
            onSaveWard={() => saveWardFrom(outcomeFor(concIfRounded, vol, neededVials))}
          />
        )
      )}
    </div>
  )
}

function InfusionCalculator({ drug, calc }: { drug: InfusionDrug; calc: InfusionCalcConfig }) {
  const { abwKg, heightCm, patient, openPatientPanel, pinRunning, logCalc, wardRecipes, saveWard, clearWard, pinWard } = useDosing()
  const wardList = wardRecipes[drug.id] ?? []
  // Công thức đã lưu GẦN NHẤT là mặc định thật sự của thuốc này lúc MỞ THẺ — không bắt gõ lại mỗi
  // lần mở (chỉ dùng để khởi tạo `conc`/`bagVolume` bên dưới). Sau đó `ward` đổi theo chip người dùng
  // BẤM chọn (kể cả "Công thức hệ thống") — xem useActiveWardRecipe và hàng chip trong "Cách dùng ·
  // Pha thuốc".
  const { activeId: activeRecipeId, setActiveId: setActiveRecipeId, active: ward } = useActiveWardRecipe(wardList)
  const unitOptions = useMemo(() => doseUnitOptions(calc.doseUnit, calc.concUnit), [calc.doseUnit, calc.concUnit])
  const [unitId, setUnitId] = useState(calc.doseUnit)
  const [mode, setMode] = useState<"doseToRate" | "rateToDose">("doseToRate")
  const [conc, setConc] = useState(ward ? String(ward.concValue) : calc.concDefault != null ? String(calc.concDefault) : "")
  const [dose, setDose] = useState("")
  const [rateInput, setRateInput] = useState("")
  const [bagVolume, setBagVolume] = useState(ward ? String(ward.volumeMl) : calc.mix ? String(calc.mix.volumeMl) : "")
  const [showMix, setShowMix] = useState(false)
  // Cảnh báo ngoại biên trước đây LUÔN vẽ đủ 2 câu (~257px) ngay khi vượt ngưỡng, đẩy khung kết quả
  // ra xa ô nhập liều gần nửa màn hình. Mặc định chỉ hiện một dòng khẳng định + nút xem chi tiết —
  // vẫn không bao giờ im lặng (đây là cảnh báo an toàn), chỉ không còn chiếm chỗ cố định.
  const [showPeripheralDetail, setShowPeripheralDetail] = useState(false)
  // "Xoá công thức này" xoá dữ liệu ĐÃ LƯU (không phải dòng nháp) nên cần xác nhận hai chạm giống
  // ConfirmIconButton — nhãn tự đổi thành "Chắc chắn xoá?" ở chạm đầu, rời tay khỏi nút (blur) thì
  // huỷ, chạm lần hai mới thật sự xoá.
  const [confirmClearWard, setConfirmClearWard] = useState(false)
  // Chỉ hiện con số tốc độ sau khi người dùng xác nhận, với các liều vượt xa khoảng khuyến cáo.
  const [confirmed, setConfirmed] = useState(false)
  // usageLine là câu chuẩn để chép vào bệnh án — gần như chắc chắn là tính năng dùng nhiều nhất
  // trong ngày, nhưng trước đây muốn lấy nó phải mở Nhật ký rồi sao chép cả mục. Nút chép nhỏ ngay
  // cạnh câu, không cần rời khỏi thẻ thuốc.
  const [usageCopied, setUsageCopied] = useState(false)
  const [savedNote, setSavedNote] = useState("")
  // Đếm số lần lưu, để dải xác nhận chạy lại hoạt ảnh kể cả khi chữ không đổi.
  const [savedTick, setSavedTick] = useState(0)
  // Dải xác nhận tự biến mất sau khi mờ đi, chứ không nằm lại dưới dạng ô trong suốt vẫn chiếm chỗ
  // — nếu để lại, thẻ thuốc dài thêm một dòng vĩnh viễn sau lần lưu đầu tiên.
  const savedTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const confirmSaved = (msg: string) => {
    setSavedNote(msg)
    setSavedTick((n) => n + 1)
    if (savedTimer.current) clearTimeout(savedTimer.current)
    savedTimer.current = setTimeout(() => setSavedNote(""), 2000)
  }
  useEffect(() => () => {
    if (savedTimer.current) clearTimeout(savedTimer.current)
  }, [])

  const unit = useMemo(() => parseDoseUnit(unitId), [unitId])
  const ownUnit = useMemo(() => parseDoseUnit(calc.doseUnit), [calc.doseUnit])
  // Cân nặng lấy từ "Bệnh nhân hiện tại" — không còn ô nhập riêng cho từng thẻ thuốc.
  const dosingWeight = useMemo(
    () => resolveDosingWeight(abwKg, heightCm, patient.sex, drug.doseWeightBasis ?? "actual"),
    [abwKg, heightCm, patient.sex, drug.doseWeightBasis],
  )
  const weightKg = dosingWeight.used
  const c = parseFloat(conc)
  const concValue = isNaN(c) ? null : c
  const pumpStep = calc.pumpStep ?? DEFAULT_PUMP_STEP

  const result = useMemo(() => {
    if (!unit || concValue == null) return null
    if (mode === "doseToRate") {
      const d = parseFloat(dose)
      if (isNaN(d)) return null
      return doseToRate(d, unit, weightKg, concValue, calc.concUnit)
    }
    const r = parseFloat(rateInput)
    if (isNaN(r)) return null
    return rateToDose(r, unit, weightKg, concValue, calc.concUnit)
  }, [unit, mode, dose, rateInput, concValue, weightKg, calc.concUnit])

  // Kiểm tra khoảng liều ở CẢ HAI CHIỀU: chiều "Liều → Tốc độ" kiểm tra liều vừa nhập; chiều
  // "Tốc độ → Liều" kiểm tra liều suy ra từ tốc độ bơm đang chạy — đúng tình huống nhận bàn giao ca
  // và phát hiện bơm đang đặt sai.
  const doseUnderCheck = mode === "doseToRate" ? (isNaN(parseFloat(dose)) ? null : parseFloat(dose)) : result
  const check: DoseCheck | null = useMemo(() => {
    if (!unit || !ownUnit || doseUnderCheck == null) return null
    return checkInfusionDose(doseUnderCheck, unit, ownUnit, calc.doseMin, calc.doseMax, weightKg, calc.doseAbsMax)
  }, [unit, ownUnit, doseUnderCheck, calc.doseMin, calc.doseMax, calc.doseAbsMax, weightKg])

  // Con số này chạy thẳng lên bơm thật — số lẻ khi đếm chạy phải khớp CHÍNH XÁC số lẻ mà
  // formatDoseNumber() sẽ chốt lại lúc nghỉ, không tự bịa một quy tắc làm tròn riêng.
  const resultFinalText = result != null ? formatDoseNumber(result) : "—"
  const resultDecimals = result != null ? (formatDoseNumber(result).split(".")[1]?.length ?? 0) : 0
  const resultDisplay = useCountUp(result, resultDecimals, resultFinalText)

  // Đổi bất kỳ đầu vào nào là phải xác nhận lại — không để một lần bấm xác nhận che cho mọi con số
  // gõ sau đó.
  useEffect(() => {
    setConfirmed(false)
    setSavedNote("")
  }, [dose, rateInput, conc, unitId, mode])

  // Ô "Nồng độ" là đường vào phổ biến hơn bảng pha rất nhiều, nên nó phải được canh bằng ĐÚNG bộ
  // luật đã dùng cho bảng pha. Trước đây gõ 50 thay vì 5 mg/mL thì bảng pha chặn đỏ còn ô này chỉ
  // hiện một dòng xanh dịu — cùng một sai lầm, hai phản ứng ngược nhau.
  // Mốc so sánh là công thức BẠN đã lưu khi có — xem lib/wardRecipes.ts.
  const concGrade = useMemo(
    () => gradeConcentration(concValue, ward?.concValue ?? calc.concDefault, calc.mix?.maxConc, calc.concUnit, ward ? "công thức của bạn" : "công thức chuẩn"),
    [concValue, ward, calc.concDefault, calc.mix?.maxConc, calc.concUnit],
  )

  const blocked = (Boolean(check?.requiresConfirm) || concGrade.requiresConfirm) && !confirmed
  const doseSeverity = check?.severity ?? "ok"
  // Ô kết quả lấy màu theo mức nặng hơn giữa "liều sai" và "nồng độ sai".
  const concAsDoseSeverity: DoseCheck["severity"] =
    concGrade.severity === "danger" ? "extreme" : concGrade.severity === "warn" ? "above" : "ok"
  const RANK: Record<string, number> = { ok: 0, unknown: 0, below: 1, "far-below": 2, above: 2, high: 3, extreme: 4 }
  const severity = RANK[concAsDoseSeverity] > RANK[doseSeverity] ? concAsDoseSeverity : doseSeverity
  const severityStyle = SEVERITY_STYLE[severity === "unknown" && result != null ? "ok" : severity]
  // Cảnh báo đi kèm mọi dòng nhật ký của phép tính này — gồm cả cảnh báo liều lẫn cảnh báo nồng độ.
  const activeFlag = [check?.headline, concGrade.headline].filter(Boolean).join(" + ") || undefined

  // Bơm tiêm điện chỉ đặt được theo bước 0,1 mL/giờ — phải nói rõ đặt bao nhiêu và khi đó liều thực
  // nhận là bao nhiêu.
  const roundedRate = mode === "doseToRate" && result != null ? roundToStep(result, pumpStep) : null
  const deliveredDose =
    roundedRate != null && unit && concValue != null ? rateToDose(roundedRate, unit, weightKg, concValue, calc.concUnit) : null

  const effectiveRate = mode === "doseToRate" ? roundedRate : isNaN(parseFloat(rateInput)) ? null : parseFloat(rateInput)
  const bagVol = parseFloat(bagVolume)
  const duration = !isNaN(bagVol) && effectiveRate != null ? infusionDurationHours(bagVol, effectiveRate) : null
  const bagAmount = !isNaN(bagVol) && concValue != null ? totalAmountInBag(bagVol, concValue) : null

  const needWeight = unit?.perWeight ?? false

  // ─── Vì sao ô kết quả đang trống ───────────────────────────────────────────
  // Lỗi cũ: gõ liều xong, ô kết quả hiện "—" và KHÔNG nói gì thêm. Lời nhắc "thuốc này tính theo
  // cân nặng" thì có, nhưng nằm cách đó gần một màn hình phía trên (sau ô nồng độ, cảnh báo ngoại
  // biên, nút bảng pha, ô thể tích...), nên người dùng nhìn thẳng vào chỗ đáng lẽ có con số và chỉ
  // thấy một dấu gạch ngang câm. Từ nay lý do nằm NGAY TRONG ô kết quả, kèm đường đi để sửa.
  const missingReason: { text: string; fix?: () => void } | null = (() => {
    if (result != null) return null
    if (concValue == null || !(concValue > 0)) return { text: "Nhập nồng độ pha ở ô bên trên để tính được." }
    if (mode === "doseToRate" && !(parseFloat(dose) > 0)) return { text: "Nhập liều muốn truyền để app tính ra tốc độ bơm." }
    if (mode === "rateToDose" && !(parseFloat(rateInput) > 0)) return { text: "Nhập tốc độ bơm đang chạy để app suy ra liều." }
    if (needWeight && weightKg == null) {
      return {
        text: `Thiếu cân nặng — ${unitId} tính theo kg nên chưa ra được con số. Chạm để nhập ở khung "Bệnh nhân hiện tại".`,
        fix: openPatientPanel,
      }
    }
    // Đơn vị liều và đơn vị nồng độ không cùng họ (vd liều "đơn vị/giờ" với nồng độ "mg/mL") —
    // không có hệ số quy đổi nào đúng, và đoán bừa một hệ số ở đây là kiểu sai tệ nhất.
    if (unit && massFactor(unit.mass, massOfConcUnit(calc.concUnit)) == null) {
      return { text: `Không quy đổi được ${unit.mass} sang ${massOfConcUnit(calc.concUnit)} — chọn đơn vị liều khác hoặc sửa đơn vị nồng độ.` }
    }
    return { text: "Chưa đủ dữ liệu để tính — kiểm tra lại các ô phía trên." }
  })()
  const rateDecimals = pumpStep >= 1 ? 0 : 1
  // Ô nồng độ điền sẵn là con dao hai lưỡi: tiện, nhưng nếu chỗ bạn pha khác chuẩn mà quên sửa thì
  // app im lặng tính ra một con số sai trông hoàn toàn hợp lý. Vì vậy khi con số đã bị sửa khác mốc
  // thì phải nói rõ nó đang so với cái gì.
  const concIsDefault = calc.concDefault != null && concValue != null && Math.abs(concValue - calc.concDefault) < 1e-9
  const concIsWard = ward != null && concValue != null && Math.abs(concValue - ward.concValue) < 1e-9
  // Nồng độ đang dùng có vượt ngưỡng còn truyền được qua đường ngoại biên hay không. Chỉ tính khi
  // thuốc có khai ngưỡng — thiếu dữ liệu thì im lặng, không đoán một ngưỡng nào đó.
  const peripheralWarn = useMemo(() => {
    const max = calc.mix?.maxPeripheralConc
    if (max == null || !(max > 0) || concValue == null || !(concValue > max + 1e-9)) return null
    return { conc: concValue, max, factor: concValue / max, note: calc.mix?.peripheralNote }
  }, [calc.mix?.maxPeripheralConc, calc.mix?.peripheralNote, concValue])
  const fieldClass = FIELD
  const fieldStyle = FIELD_STYLE

  const doseText = mode === "doseToRate" ? `${dose} ${unitId}` : result != null ? `${formatDoseNumber(result)} ${unitId}` : "—"
  const rateText =
    mode === "doseToRate"
      ? roundedRate != null
        ? `${roundedRate.toFixed(rateDecimals)} mL/giờ`
        : "—"
      : `${rateInput} mL/giờ`

  // Câu "Cách dùng" theo mẫu chuẩn (vd "Noradrenalin 4 mg/4 ml 2 ống với NaCl 0,9% đủ 50 ml BTĐ
  // 5 ml/h") — chỉ ra được khi đã có đủ hàm lượng/thể tích 1 ống (từ công thức đã lưu hoặc mặc định
  // của thuốc) VÀ đã tính ra tốc độ bơm cụ thể. Xem lib/usageText.ts.
  const usageVialRaw = ward ?? calc.mix
  const usageLine = (() => {
    if (mode !== "doseToRate" || roundedRate == null || usageVialRaw == null) return null
    const usageVial = usageVialRaw
    if (usageVial.vialAmount == null || usageVial.vialVolumeMl == null) return null
    return formatAmpouleUsage({
      name: drug.name,
      vialAmount: usageVial.vialAmount,
      vialUnit: usageVial.vialUnit ?? massOfConcUnit(calc.concUnit),
      vialVolumeMl: usageVial.vialVolumeMl,
      vialsUsed: usageVial.vials ?? 1,
      // `diluent` (WardRecipe, một chuỗi) và `diluents` (MixRecipe, một mảng) đều là optional — dò
      // riêng từng khoá thay vì suy luận "không có diluent thì chắc là MixRecipe", vì một WardRecipe
      // chưa từng gán `diluent` cũng trông giống hệt vậy dưới mắt TypeScript.
      diluentName: ("diluent" in usageVial ? usageVial.diluent : "diluents" in usageVial ? usageVial.diluents?.[0] : undefined) ?? "NaCl 0,9%",
      finalVolumeMl: !isNaN(bagVol) ? bagVol : usageVial.volumeMl,
      rateMlPerHour: roundedRate,
    })
  })()

  function logCurrent(flag?: string) {
    logCalc({
      drug: drug.name,
      kind: mode,
      inputs: [
        `Nồng độ ${conc} ${calc.concUnit}${concIsDefault ? " (công thức pha chuẩn của app)" : calc.concDefault != null ? ` (khác chuẩn ${calc.concDefault})` : ""}`,
        mode === "doseToRate" ? `Liều đặt ${dose} ${unitId}` : `Tốc độ bơm ${rateInput} mL/giờ`,
      ],
      output: mode === "doseToRate" ? `${rateText}${deliveredDose != null ? ` → thực nhận ${formatDoseNumber(deliveredDose)} ${unitId}` : ""}` : doseText,
      flag,
    })
  }

  return (
    <div className="mt-3 pt-3 border-t" style={{ borderColor: "var(--c-line-soft)" }}>
      {/* Chọn chiều tính */}
      <div className="flex p-0.5 rounded-xl mb-2.5" style={{ background: "var(--c-line-soft)" }}>
        {([
          { id: "doseToRate" as const, label: "Liều → Tốc độ" },
          { id: "rateToDose" as const, label: "Tốc độ → Liều" },
        ]).map((m) => (
          <button
            key={m.id}
            onClick={() => {
              setMode(m.id)
              tickHaptic()
            }}
            className="dose-press flex-1 h-9 rounded-[10px] text-[12px] font-bold"
            aria-pressed={mode === m.id}
            style={
              mode === m.id
                ? { background: "var(--c-surface)", color: "var(--c-primary)", boxShadow: "0 1px 3px var(--c-shadow)" }
                : { background: "transparent", color: "var(--c-text-soft)" }
            }
          >
            {m.label}
          </button>
        ))}
      </div>

      {/* Chọn đơn vị liều — cuộn ngang vì có nhiều lựa chọn, không vừa một hàng chia đều */}
      <div className="scroll-ios overflow-x-auto flex gap-1.5 mb-2.5 -mx-0.5 px-0.5">
        {unitOptions.map((u) => (
          <button
            key={u}
            onClick={() => {
              setUnitId(u)
              tickHaptic()
            }}
            className={CHIP}
            style={
              unitId === u
                ? { background: "var(--c-primary)", borderColor: "var(--c-primary)", color: "var(--c-on-bright)" }
                : { background: "var(--c-surface)", borderColor: "var(--c-line)", color: "var(--c-text-soft)" }
            }
          >
            {u}
          </button>
        ))}
      </div>

      {/* Cân nặng lấy từ khung "Bệnh nhân hiện tại" — không gõ lại cho từng thuốc nữa. Chỉ nói khi
          ĐÃ có cân nặng (xác nhận đang dùng số nào); lúc thiếu thì không nhắc ở đây nữa — lý do và
          đường sửa đã nằm ngay trong ô kết quả bên dưới (xem missingReason), đúng chỗ người dùng
          đang nhìn khi thấy "—" mà không hiểu vì sao. */}
      {needWeight && weightKg != null && (
        <p className="text-[12px] mb-2 px-2.5 py-1.5 rounded-lg leading-[1.45]" style={{ background: "var(--c-accent-soft)", color: "var(--c-accent-deep)" }}>
          Cân nặng dùng để tính: <b>{weightKg.toFixed(1)} kg</b>
          {dosingWeight.usedLabel && dosingWeight.usedLabel !== "ABW" ? ` (${dosingWeight.usedLabel})` : ""} — lấy từ khung "Bệnh nhân hiện tại".
        </p>
      )}

      <div className="grid grid-cols-2 gap-2 mb-1.5">
        <div>
          <label className={`${T.label} text-slate-500 mb-1 block`}>Nồng độ ({calc.concUnit})</label>
          <input value={conc} onChange={(e) => setConc(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder={calc.concUnit} className={fieldClass} style={fieldStyle} />
        </div>
        {mode === "doseToRate" ? (
          <div>
            <label className={`${T.label} text-slate-500 mb-1 block`}>Liều</label>
            <input value={dose} onChange={(e) => setDose(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder={unitId} className={fieldClass} style={fieldStyle} />
          </div>
        ) : (
          <div>
            <label className={`${T.label} text-slate-500 mb-1 block`}>Tốc độ (mL/giờ)</label>
            <input value={rateInput} onChange={(e) => setRateInput(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="mL/giờ" className={fieldClass} style={fieldStyle} />
          </div>
        )}
      </div>

      {/* Ô nồng độ đang giả định điều gì — dòng này không bao giờ được vắng mặt */}
      {concGrade.severity === "danger" || concGrade.severity === "warn" ? (
        // Nồng độ lệch nhiều thì cảnh báo này thay chỗ dòng ghi chú nhẹ nhàng bên dưới — hai thứ
        // cùng lúc chỉ làm loãng cái quan trọng.
        <div
          className={`flex items-start gap-2 px-3 py-2.5 ${R.box} mb-2`}
          style={
            concGrade.severity === "danger"
              ? { background: C.dangerSoft, border: `1px solid ${C.dangerIcon}` }
              : { background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }
          }
        >
          <span className="mt-0.5 flex-none" style={{ color: concGrade.severity === "danger" ? C.dangerIcon : "var(--c-warn-icon)" }}>{icons.alert()}</span>
          <div>
            <p className={`${T.bodyStrong} font-extrabold leading-[1.3]`} style={{ color: concGrade.severity === "danger" ? C.danger : "var(--c-warn)" }}>
              {concGrade.headline}
            </p>
            {concGrade.detail && (
              <p className={`${T.meta} mt-0.5`} style={{ color: concGrade.severity === "danger" ? C.danger : "var(--c-warn)" }}>{concGrade.detail}</p>
            )}
          </div>
        </div>
      ) : concIsWard ? null : calc.concDefault == null ? (
        <Note tone="warn">App không điền sẵn nồng độ cho thuốc này — nhập theo chai/bơm thực tế rồi lưu lại trong bảng pha.</Note>
      ) : concIsDefault ? null : (
        // Con số dựng sẵn thì không cần nói gì: nó đã là mặc định hiển nhiên, và một dòng nhắc lặp
        // lại ở mọi thuốc chỉ làm loãng những dòng thật sự phải đọc. Chỉ nói khi nồng độ đã bị SỬA
        // khác mốc — lúc đó mới có thông tin mới.
        <Note tone="info">
          Nồng độ tự nhập {conc} {calc.concUnit} — {ward ? `công thức của bạn là ${formatDoseNumber(ward.concValue)}` : `chuẩn của app là ${calc.concDefault}`} {calc.concUnit}.
        </Note>
      )}

      {/* ─── Đường truyền và hạn dùng sau pha ───────────────────────────────────
          Hai thông tin này đã có sẵn trong dữ liệu từ lâu (MixRecipe.maxPeripheralConc / .stability)
          nhưng bị ẩn hẳn khỏi giao diện cho gọn. Kết quả: công thức noradrenaline 0,08 mg/mL của
          chính app đặc gấp 5 lần ngưỡng ngoại biên mà không có dòng nào nói ra — dữ liệu đúng nằm
          sai chỗ. Nay chỉ hiện khi nồng độ ĐANG DÙNG thực sự vượt ngưỡng, nên nó không phải một
          dòng chữ thường trực để người ta học cách lướt qua. */}
      {peripheralWarn && (
        <div className={`${R.box} mb-2 overflow-hidden`} style={{ background: "var(--c-warn-soft)", border: "1px solid var(--c-warn-line)" }}>
          <button
            type="button"
            onClick={() => setShowPeripheralDetail((v) => !v)}
            className="w-full flex items-center gap-2 px-3 py-2.5 text-left"
            aria-expanded={showPeripheralDetail}
          >
            <span className="flex-none" style={{ color: "var(--c-warn-icon)" }}>{icons.alert()}</span>
            <span className={`${T.bodyStrong} font-extrabold leading-[1.3] flex-1`} style={{ color: "var(--c-warn)" }}>
              Đặc hơn ngưỡng cho đường ngoại biên
            </span>
            <span className="flex-none" style={{ color: "var(--c-warn)", transform: showPeripheralDetail ? "rotate(180deg)" : "none", transition: "transform .15s" }}>
              {icons.chevronDown()}
            </span>
          </button>
          {showPeripheralDetail && (
            <p className={`${T.meta} px-3 pb-2.5`} style={{ color: "var(--c-warn)" }}>
              Đang pha {formatDoseNumber(peripheralWarn.conc)} {calc.concUnit}, gấp {formatDoseNumber(peripheralWarn.factor)} lần ngưỡng{" "}
              {formatDoseNumber(peripheralWarn.max)} {calc.concUnit} — nồng độ này thuộc nhóm ưu tiên tĩnh mạch trung tâm.
              {peripheralWarn.note ? ` ${peripheralWarn.note}` : ""}
            </p>
          )}
        </div>
      )}
      {/* Cảnh báo vượt/thấp hơn khoảng liều — đổi màu, in hoa, và với mức nguy hiểm thì CHẶN kết quả
          cho tới khi người dùng xác nhận. */}
      {check?.headline && (
        <div
          className="flex items-start gap-2 px-3 py-2.5 rounded-xl mb-2"
          style={{ background: severityStyle.bg, border: `1px solid ${severityStyle.border}` }}
        >
          <span className="mt-0.5 flex-none" style={{ color: severityStyle.text }}>{icons.alert()}</span>
          <div>
            <p className="text-[13px] font-extrabold leading-[1.3]" style={{ color: severityStyle.text }}>{check.headline}</p>
            {check.detail && <p className="text-[12px] leading-[1.45] mt-0.5" style={{ color: severityStyle.text }}>{check.detail}</p>}
          </div>
        </div>
      )}

      {/* aria-live bọc CẢ HAI nhánh: trước đây chỉ nhánh "có kết quả" có aria-live, nên lúc kết quả
          bị CHE (chuyển sang nút xác nhận) trình đọc màn hình im lặng hoàn toàn — người dùng không
          biết con số vừa biến mất, chỉ có nút xác nhận thay vào đó. */}
      <div aria-live="polite" aria-atomic="true">
      {blocked ? (
        <button
          onClick={() => {
            const reason = [check?.requiresConfirm ? check.headline : null, concGrade.requiresConfirm ? concGrade.headline : null]
              .filter(Boolean)
              .join(" + ")
            setConfirmed(true)
            logCurrent(`${reason} — người dùng đã bấm xác nhận để xem kết quả`)
            confirmSaved("Đã ghi vào nhật ký kèm cảnh báo")
            tickHaptic()
          }}
          className={`${BTN_TALL} border-transparent`}
          style={{ background: severityStyle.text, color: "var(--c-on-bright)" }}
        >
          Tôi đã kiểm tra lại — vẫn muốn xem kết quả
        </button>
      ) : (
        // Con số duy nhất cần nhìn thấy từ xa. Đặt to hẳn một bậc so với mọi chữ khác trong thẻ,
        // dùng chữ số đều bề ngang (tabular) để hàng "đặt bơm" và hàng "thực nhận" thẳng cột nhau.
        <div
          className={`px-3 py-3 ${R.box}`}
          style={{ background: severityStyle.bg, border: `1px solid ${severityStyle.border}` }}
          role={severity === "extreme" ? "alert" : undefined}
        >
          {usageLine && (
            <div className="flex items-start gap-1.5 mb-1.5">
              <p className={`${T.bodyStrong} flex-1`} style={{ color: severityStyle.text }}>{usageLine}</p>
              <button
                type="button"
                onClick={async () => {
                  try {
                    await navigator.clipboard.writeText(usageLine)
                    setUsageCopied(true)
                    setTimeout(() => setUsageCopied(false), 1500)
                    tickHaptic()
                  } catch {
                    // Trình duyệt chặn clipboard: không làm gì, nút vẫn giữ nguyên nhãn.
                  }
                }}
                aria-label={usageCopied ? "Đã chép" : "Chép câu Cách dùng"}
                className="flex-none w-11 h-11 -m-2 rounded-lg flex items-center justify-center"
                style={{ color: severityStyle.text, opacity: 0.75 }}
              >
                {usageCopied ? icons.check() : icons.copy()}
              </button>
            </div>
          )}
          <div className="flex items-baseline gap-2">
            {/* Đếm chạy từ số cũ sang số mới (useCountUp) thay vì bật thẳng vào số mới — số này
                chạy lên bơm thật nên "đổi tăng hay giảm, đổi bao nhiêu" đáng nhìn thấy rõ hơn cả
                "đã đổi". Khoá cứng về đúng formatDoseNumber() ngay khi đếm xong. */}
            <span className={`${T.metric} ${NUM_DOSE}`} style={{ color: severityStyle.text }}>
              {resultDisplay}
            </span>
            <span className={T.body} style={{ color: C.textSoft }}>{mode === "doseToRate" ? "mL/giờ" : unitId}</span>
            {/* Xác nhận tích cực: liều nằm đúng khoảng thì nói ra, không chỉ im lặng khi không sai */}
            {severity === "ok" && result != null && check != null && (
              <span className={`${T.meta} ml-auto flex items-center gap-1 flex-none`} style={{ color: C.accent }}>
                <span className="scale-75">{icons.check()}</span>
                Trong khoảng
              </span>
            )}
          </div>
          {mode === "doseToRate" && roundedRate != null && (
            // Con số 24px bên trên là kết quả TÍNH; đây mới là con số thật sự đem đi đặt máy —
            // nên đứng ở bậc T.critical (15px), không phải T.meta như một dòng chú thích phụ.
            <p className={`${T.critical} ${NUM} mt-1.5`} style={{ color: severityStyle.text }}>
              Đặt bơm <b className={NUM_DOSE}>{roundedRate.toFixed(rateDecimals)} mL/giờ</b> (bước {pumpStep})
              {deliveredDose != null && ` → thực nhận ${formatDoseNumber(deliveredDose)} ${unitId}`}
            </p>
          )}
          {duration != null && (
            <p className={`${T.meta} ${NUM} mt-0.5`} style={{ color: C.textSoft }}>
              {trim(bagVol)} mL ở {effectiveRate?.toFixed(rateDecimals)} mL/giờ → hết sau <b>{formatDuration(duration)}</b>
            </p>
          )}
          {check?.severity === "unknown" && check.detail && (
            <p className={`${T.meta} mt-0.5`} style={{ color: C.textSoft }}>{check.detail}</p>
          )}
          {/* Dấu "—" không bao giờ được đứng một mình: luôn kèm lý do và cách sửa. */}
          {missingReason &&
            (missingReason.fix ? (
              <button onClick={missingReason.fix} className={`${T.meta} font-semibold text-left mt-1 underline`} style={{ color: C.warn }}>
                {missingReason.text}
              </button>
            ) : (
              <p className={`${T.meta} mt-1`} style={{ color: C.textSoft }}>{missingReason.text}</p>
            ))}
        </div>
      )}
      </div>

      {/* Hai hành động này KHÔNG ngang hàng nhau về tầm quan trọng, nên không còn vẽ thành hai nút
          bằng nhau cạnh nhau nữa — cách cũ (flex-1 flex-1) chỉ chừa ~147px mỗi nút trên máy 375px,
          đủ để "Thêm vào danh sách đang dùng" vỡ thành 3 dòng chữ chồng lên nhau, và người dùng
          không có cách nào phân biệt hành động nào là chính giữa hai ô trông y hệt nhau.
          Nay: MỘT nút chính (ghim thuốc — đặc màu, có icon, chiếm trọn hàng, luôn đủ chỗ cho một
          dòng chữ) và một hành động phụ bên dưới (chỉ ghi nhật ký, không ghim — nhạt hơn hẳn về
          màu sắc nhưng vẫn đủ 44px chiều cao để bấm được khi đeo găng). */}
      {!blocked && result != null && (
        <div className="flex flex-col gap-1.5 mt-2">
          <button
            onClick={() => {
              pinRunning({
                drugId: drug.id,
                name: drug.name,
                compatKey: drug.compatKey,
                line: 1,
                doseText,
                rateText,
                concText: `${conc} ${calc.concUnit}`,
                kind: "infusion",
                weightKgAtPin: weightKg,
                concAtPin: conc,
              })
              logCurrent(activeFlag ? `${activeFlag} — vẫn ghim vào bảng đang dùng` : undefined)
              confirmSaved("Đã thêm vào danh sách đang dùng")
              tickHaptic()
            }}
            className={`${BTN_TALL} border-transparent flex items-center justify-center gap-1.5`}
            style={{ background: C.accent, color: "var(--c-on-bright)" }}
          >
            <span className="flex-none scale-90">{icons.plus()}</span>
            Thêm vào danh sách đang dùng
          </button>
          <button
            onClick={() => {
              logCurrent(activeFlag)
              confirmSaved("Đã lưu vào nhật ký")
              tickHaptic()
            }}
            className={`w-full min-h-[44px] px-3 py-2 ${R.box} ${T.chip} flex items-center justify-center gap-1.5 dose-press`}
            style={{ background: C.lineSoft, color: C.textSoft }}
          >
            <span className="flex-none scale-90">{icons.doc()}</span>
            Chỉ lưu vào nhật ký, không ghim
          </button>
        </div>
      )}

      {/* ─── Tham khảo pha thuốc — đứng SAU khung kết quả ─────────────────────────
          Trước đây khối này (công thức đã lưu, bảng pha, thể tích bơm) nằm GIỮA ô nhập liều và
          khung kết quả, đẩy chúng cách nhau tới 439px đo được trên máy 375px — gõ liều xong, bàn
          phím ảo che nốt phần còn lại, không thấy con số. Không khối nào trong đây là INPUT bắt
          buộc để tính tốc độ bơm (nồng độ đã có ô riêng ở trên); chúng chỉ hỗ trợ TRA CỨU/PHA
          thuốc và tính thêm "hết sau bao lâu" — hợp lý đứng sau khi đã thấy câu trả lời chính. */}
      {calc.mix?.stability && (
        <p className={`${T.meta} mb-2 px-2.5 py-1.5 ${R.box}`} style={{ background: C.lineSoft, color: C.textSoft }}>
          Sau khi pha: {calc.mix.stability}
        </p>
      )}

      {/* Trả về mốc chuẩn sau khi đã sửa lung tung */}
      {(!concIsWard || !ward) && (calc.concDefault != null || ward) && !(concIsDefault && !ward) && (
        <div className="flex flex-wrap gap-1.5 mb-2">
          {ward && (
            <button
              onClick={() => {
                setActiveRecipeId(ward.id)
                setConc(String(ward.concValue))
                setBagVolume(String(ward.volumeMl))
                tickHaptic()
              }}
              className="px-2.5 py-1 rounded-full text-[12px] font-bold border"
              style={{ borderColor: "var(--c-accent-line)", color: "var(--c-accent-deep)" }}
            >
              Dùng lại công thức của bạn
            </button>
          )}
          {calc.concDefault != null && (
            <button
              onClick={() => {
                setActiveRecipeId("system")
                setConc(String(calc.concDefault))
                if (calc.mix) setBagVolume(String(calc.mix.volumeMl))
                tickHaptic()
              }}
              className="px-2.5 py-1 rounded-full text-[12px] font-bold border"
              style={{ borderColor: "var(--c-line)", color: "var(--c-text-soft)" }}
            >
              Dùng lại công thức chuẩn
            </button>
          )}
        </div>
      )}
      {/* Cách dùng gộp chung với bảng pha, và nội dung ĐỘNG theo công thức đã lưu — giống hệt cách ô
          kết quả bên trên đổi theo dữ liệu thật thay vì đứng yên. Trước đây "Cách dùng" là một khối
          tĩnh tách rời (luôn đọc câu chữ dựng sẵn của app dù bạn đã lưu công thức khác từ lâu), còn
          "Bảng pha thuốc" là một nút riêng nằm giữa dòng — hai thứ cùng nói về MỘT việc (pha thuốc
          thế nào) nhưng lại ở hai chỗ khác nhau. */}
      <Disclosure label="Cách dùng · Pha thuốc">
        {wardList.length > 0 && (
          <WardRecipeChips
            wardList={wardList}
            activeId={activeRecipeId}
            onSelectSystem={() => {
              setActiveRecipeId("system")
              setConc(calc.concDefault != null ? String(calc.concDefault) : "")
              setBagVolume(calc.mix ? String(calc.mix.volumeMl) : "")
              tickHaptic()
            }}
            onSelectWard={(w) => {
              setActiveRecipeId(w.id)
              setConc(String(w.concValue))
              setBagVolume(String(w.volumeMl))
              tickHaptic()
            }}
            onDelete={(id) => clearWard(drug.id, id)}
            onPin={(id) => pinWard(drug.id, id)}
          />
        )}
        {ward ? (
          <div className="flex items-start gap-2">
            <span className="mt-0.5 flex-none" style={{ color: "var(--c-accent)" }}>{icons.edit()}</span>
            <div className="flex-1 min-w-0">
              <p className={`${T.meta} font-bold`} style={{ color: "var(--c-accent-deep)" }}>
                {ward.title || "Công thức của bạn"} (lưu {formatSavedAt(ward.savedAt)}) — khác công thức hệ thống
              </p>
              <p className={`${T.body} mt-0.5`} style={{ color: C.textSoft }}>
                {ward.vials} {calc.mix?.vialLabel ?? "ống"} × {formatMass(ward.vialAmount, ward.vialUnit)} vừa đủ {trim(ward.volumeMl)} mL
                {ward.diluent ? `, dung môi ${ward.diluent}` : ""}.
              </p>
              <button
                onClick={() => {
                  if (!confirmClearWard) {
                    setConfirmClearWard(true)
                    tickHaptic()
                    return
                  }
                  clearWard(drug.id, ward.id)
                  // Xoá xong thì rơi về công thức đã lưu MỚI NHẤT còn lại (nếu có), chứ không nhảy
                  // thẳng về công thức hệ thống khi vẫn còn công thức khác — khớp với cách
                  // useActiveWardRecipe tự chọn lại khi công thức đang xem biến mất.
                  const remaining = wardList.filter((w) => w.id !== ward.id)
                  const next = remaining[remaining.length - 1]
                  if (next) {
                    setConc(String(next.concValue))
                    setBagVolume(String(next.volumeMl))
                  } else {
                    setConc(calc.concDefault != null ? String(calc.concDefault) : "")
                    setBagVolume(calc.mix ? String(calc.mix.volumeMl) : "")
                  }
                  setConfirmClearWard(false)
                  tickHaptic()
                }}
                onBlur={() => setConfirmClearWard(false)}
                className="flex items-center gap-1.5 text-[12px] font-bold mt-1.5"
                style={{ color: confirmClearWard ? "var(--c-on-bright)" : "var(--c-danger)", background: confirmClearWard ? "var(--c-danger-icon)" : "transparent", padding: confirmClearWard ? "4px 8px" : 0, borderRadius: 999 }}
              >
                <span className="scale-90">{confirmClearWard ? icons.alert() : icons.trash()}</span>
                {confirmClearWard ? "Chắc chắn xoá?" : "Xoá công thức này"}
              </button>
            </div>
          </div>
        ) : (
          <p className={T.body} style={{ color: C.textSoft }}>{drug.preparation}</p>
        )}
        {drug.note && <p className={`${T.meta} mt-2`} style={{ color: C.textSoft }}>{drug.note}</p>}

        <button
          onClick={() => setShowMix((v) => !v)}
          className={`${BTN_BLOCK} mt-3`}
          style={{ borderColor: C.accentLine, background: C.accentSoft, color: C.accent }}
        >
          {showMix ? "Đóng bảng pha thuốc" : "Bảng pha thuốc"}
        </button>
        {showMix && (
          <MixPanel
            drug={drug}
            calc={calc}
            wardRecipe={ward}
            onSaveWard={saveWard}
            onUseConc={(value, volumeMl) => {
              setConc(String(Math.round(value * 1e6) / 1e6))
              setBagVolume(String(Math.round(volumeMl * 100) / 100))
              setShowMix(false)
            }}
          />
        )}
      </Disclosure>

      <div className="grid grid-cols-2 gap-2 mb-2 mt-2">
        <div>
          <label className={`${T.label} text-slate-500 mb-1 block`}>Thể tích bơm/chai (mL)</label>
          <input value={bagVolume} onChange={(e) => setBagVolume(normalizeDecimalInput(e.target.value))} inputMode="decimal" placeholder="VD: 50" className={fieldClass} style={fieldStyle} />
        </div>
        {bagAmount != null && (
          <div className="flex items-end">
            <p className="text-[12px] text-slate-500 leading-[1.45] pb-2">
              Trong bơm có {formatMass(bagAmount, massOfConcUnit(calc.concUnit))}
            </p>
          </div>
        )}
      </div>

      {/* Xác nhận việc vừa làm đã xong — dải xanh có dấu tích, tự mờ đi sau ~1,8s. `key` để mỗi
          lần lưu lại là một lần hiện mới, kể cả khi nội dung không đổi. */}
      {savedNote && (
        <p
          key={`${savedNote}-${savedTick}`}
          className={`${T.meta} flex items-center gap-1.5 mt-1.5 px-2.5 py-1.5 ${R.box} flash-ok`}
          style={{ background: C.accentSoft, color: C.accent }}
        >
          <span className="flex-none scale-90">{icons.check()}</span>
          {savedNote}
        </p>
      )}
    </div>
  )
}

function InfusionDrugCard({
  drug: baseDrug,
  disease,
  isOverride,
  onEdit,
  onDelete,
}: {
  drug: InfusionDrug
  disease?: DiseaseEntry | null
  isOverride?: boolean
  onEdit?: (drug: InfusionDrug) => void
  onDelete?: (id: string) => void
}) {
  const { pinRunning } = useDosing()
  // Bệnh lý áp dụng đè (override) doseRange/calc/boluses/note lên dữ liệu gốc — giống hệt cách
  // IndicationDose đè lên Antibiotic.tiers ở AntibioticDoseCard. Phần nào chỉ định không khai báo
  // thì giữ nguyên dữ liệu gốc của thuốc.
  const indication = disease ? baseDrug.indications?.find((i) => i.diseaseId === disease.id) : undefined
  const drug: InfusionDrug = indication
    ? {
        ...baseDrug,
        doseRange: indication.doseRange ?? baseDrug.doseRange,
        note: indication.note ?? baseDrug.note,
        calc: indication.calc ?? baseDrug.calc,
        boluses: indication.boluses ?? baseDrug.boluses,
      }
    : baseDrug
  // Nguồn hiện ra: bệnh lý có tự khai nguồn riêng thì ưu tiên nguồn đó — cùng lý do với
  // AntibioticDoseCard (liều theo bệnh lý cụ thể thường lấy từ nguồn khác hẳn nguồn chung).
  const sourceItem: SourceInfo = indication && (indication.source || indication.reviewedOn) ? indication : baseDrug
  // Cảnh báo mức "cao" là thứ duy nhất không được phép gấp lại; mức trung bình và mọi nội dung
  // tham khảo khác đều nằm sau tiêu đề gấp/mở để phần máy tính luôn nằm trong tầm mắt.
  const highWarnings = (drug.warnings ?? []).filter((w) => w.severity === "cao")
  const otherWarnings = (drug.warnings ?? []).filter((w) => w.severity !== "cao")
  const boluses = drug.boluses ?? []

  return (
    <div className={`p-4 ${R.card} border mb-3`} style={{ borderColor: C.line, background: C.surface }}>
      {/* Đầu thẻ: tên thuốc và hai nút cùng nằm trên một đường, cao bằng nhau */}
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5 min-w-0">
            <p className={`${T.title} truncate`} style={{ color: C.text }}>{drug.name}</p>
            {drug.isCustom && (
              <span
                className={`${T.label} px-1.5 py-0.5 ${R.pill} flex-none`}
                style={isOverride ? { background: C.primarySoft, color: C.primary } : { background: "var(--c-green-soft)", color: "var(--c-green)" }}
              >
                {isOverride ? "Đã sửa" : "Tự nhập"}
              </span>
            )}
          </div>
          <p className={`${T.meta} mt-0.5`} style={{ color: C.textSoft }}>{drug.route}</p>
          {disease && (
            <p className={`${T.meta} font-semibold mt-1 px-2 py-0.5 ${R.pill} inline-block`} style={{ background: "var(--c-line-soft)", color: C.textSoft }}>
              Chỉ định: {disease.name}
            </p>
          )}
        </div>
        <div className="flex items-center gap-1.5 flex-none">
          {onEdit && (
            <button onClick={() => onEdit(drug)} className={`w-11 h-11 ${R.pill} flex items-center justify-center`} style={{ background: C.primarySoft, color: C.primary }} aria-label="Sửa thuốc">
              {icons.edit()}
            </button>
          )}
          {drug.isCustom && onDelete && (isOverride ? (
            <button
              onClick={() => onDelete(drug.id)}
              className={`w-11 h-11 ${R.pill} flex items-center justify-center`}
              style={{ background: C.lineSoft, color: C.textSoft }}
              aria-label="Khôi phục mặc định"
            >
              {icons.undo()}
            </button>
          ) : (
            <ConfirmIconButton
              onConfirm={() => onDelete(drug.id)}
              ariaLabel="Xoá thuốc"
              className={`w-11 h-11 ${R.pill} flex items-center justify-center`}
              style={{ background: C.dangerSoft, color: C.dangerIcon }}
            />
          ))}
        </div>
      </div>

      <p className={`${T.body} mt-2`} style={{ color: "var(--c-text-2)" }}>{drug.doseRange}</p>

      {/* Cảnh báo mức cao — luôn hiện, ngay dưới khoảng liều */}
      {highWarnings.length > 0 && (
        <div className="mt-2 space-y-1.5">
          {highWarnings.map((w, i) => (
            <div key={i} className={`flex items-start gap-2 px-2.5 py-2 ${R.box}`} style={{ background: C.dangerSoft, border: `1px solid ${C.dangerLine}` }}>
              <span className="mt-0.5 flex-none" style={{ color: C.dangerIcon }}>{icons.alert()}</span>
              <p className={T.bodyStrong} style={{ color: C.danger }}>{w.text}</p>
            </div>
          ))}
        </div>
      )}

      <CompatWarningForDrug compatKey={drug.compatKey} ownDrugId={drug.id} />

      {drug.calc && <InfusionCalculator drug={drug} calc={drug.calc} />}

      {/* Thuốc không có máy tính tốc độ (Adenosine, Calci gluconat) vẫn phải ghim được: chúng nằm
          trong đúng những cặp tương hợp quan trọng nhất (calci + bicarbonat...). */}
      {!drug.calc && (
        <button
          onClick={() => {
            pinRunning({ drugId: drug.id, name: drug.name, compatKey: drug.compatKey, line: 1, doseText: drug.doseRange, rateText: "", concText: drug.route, kind: "intermittent" })
            tickHaptic()
          }}
          className={`w-full h-11 ${R.box} ${T.bodyStrong} border mt-3`}
          style={{ borderColor: C.accentLine, background: C.accentSoft, color: C.accent }}
        >
          Thêm vào danh sách đang dùng
        </button>
      )}

      {boluses.length > 0 && (
        <Disclosure label="Liều nạp / bolus" count={boluses.length}>
          <BolusList boluses={drug.boluses} drugName={drug.name} doseWeightBasis={drug.doseWeightBasis} />
        </Disclosure>
      )}

      {/* Thuốc CÓ máy tính tốc độ đã tự vẽ khối "Cách dùng · Pha thuốc" của riêng nó bên trong
          InfusionCalculator (bản ĐỘNG, đổi theo công thức đã lưu) — vẽ lại tĩnh ở đây thành ra có
          hai khối "Cách dùng" trên cùng một thẻ. Chỉ thuốc KHÔNG có máy tính (Adenosine, Calci
          gluconat...) mới cần khối tĩnh này. */}
      {!drug.calc && (
        <Disclosure label="Cách dùng · Pha thuốc">
          <p className={T.body} style={{ color: C.textSoft }}>{drug.preparation}</p>
          {drug.note && <p className={`${T.meta} mt-2`} style={{ color: C.textSoft }}>{drug.note}</p>}
        </Disclosure>
      )}

      {otherWarnings.length > 0 && (
        <Disclosure label="Lưu ý khác" count={otherWarnings.length} alert>
          <DrugWarnings warnings={otherWarnings} bare />
        </Disclosure>
      )}

      {/* Nguồn dữ liệu: ưu tiên nguồn riêng của bệnh lý đang chọn, rơi về nguồn chung của thuốc nếu
          bệnh lý chưa tự khai — xem chú thích ở AntibioticDoseCard. `alert` khi mục đang hiện chưa
          ghi nguồn: trước đây phải MỞ khối này ra mới biết, nên trên thực tế không ai biết. */}
      <Disclosure label={sourceItem.source || sourceItem.reviewedOn ? "Nguồn dữ liệu" : "Nguồn dữ liệu — chưa ghi nguồn"} alert={!sourceItem.source && !sourceItem.reviewedOn}>
        {indication && (indication.source || indication.reviewedOn) && (
          <p className={`${T.meta} mb-1.5`} style={{ color: C.textSoft }}>Nguồn riêng cho chỉ định {disease?.name}:</p>
        )}
        <SourceLine item={sourceItem} bare />
        {indication && !(indication.source || indication.reviewedOn) && (baseDrug.source || baseDrug.reviewedOn) && (
          <p className={`${T.meta} mt-1.5`} style={{ color: C.textSoft }}>Bệnh lý này chưa tự khai nguồn riêng — đang hiện nguồn chung của thuốc.</p>
        )}
      </Disclosure>
    </div>
  )
}

// Trước đây màn này đổ TOÀN BỘ thuốc trong nhóm ra dưới dạng thẻ mở sẵn, mỗi thẻ kèm máy tính,
// bảng pha, liều nạp, cảnh báo và nguồn — bốn thuốc là bốn màn hình cuộn, trong khi một bệnh nhân
// cụ thể thường chỉ dùng một hai thứ. Nay đảo lại thứ tự ưu tiên cho đúng nhịp ICU:
//   1. Thuốc bệnh nhân ĐANG dùng (chạm là mở thẳng máy tính)
//   2. Ô tìm + chip chọn thuốc cần thêm
//   3. Chỉ thuốc đang chọn mới bung thẻ đầy đủ
function InfusionCategoryScreen({
  staticDrugs,
  customDrugs,
  diseases,
  categoryLabel,
  onAddNew,
  onEdit,
  onDelete,
}: {
  staticDrugs: InfusionDrug[]
  customDrugs: InfusionDrug[]
  diseases: DiseaseEntry[]
  categoryLabel: string
  onAddNew: () => void
  onEdit: (drug: InfusionDrug) => void
  onDelete: (id: string) => void
}) {
  const { running, collapsePatientPanel } = useDosing()
  const allDrugs = useMemo(() => mergeWithOverrides(staticDrugs, customDrugs), [staticDrugs, customDrugs])
  const staticIds = useMemo(() => new Set(staticDrugs.map((d) => d.id)), [staticDrugs])
  // Khoá theo từng nhóm thuốc để tab "Vận mạch" và tab "Co bóp" nhớ riêng thuốc đang mở.
  const [query, setQuery] = useStickyState(`infusion.query.${categoryLabel}`, "")
  const [selectedId, setSelectedId] = useStickyState<string | null>(`infusion.sel.${categoryLabel}`, null)
  // Chỉ định — giống hệt bước "Chỉ định" ở AntibioticsScreen: chỉ hiện khi thuốc đang chọn CÓ khai
  // báo `indications` (vd Adrenaline: ngừng tim / phản vệ / sốc nhiễm khuẩn dùng liều khác hẳn nhau).
  const [diseaseChoice, setDiseaseChoice] = useStickyState<string | null>(`infusion.disease.${categoryLabel}`, null)

  const activeIds = useMemo(() => new Set(running.map((r) => r.drugId)), [running])
  const onPatient = useMemo(() => allDrugs.filter((d) => activeIds.has(d.id)), [allDrugs, activeIds])

  const filtered = useMemo(() => {
    const q = normalizeSearch(query)
    return q ? allDrugs.filter((d) => normalizeSearch(d.name).includes(q)) : allDrugs
  }, [allDrugs, query])

  // Gõ tới khi chỉ còn một kết quả thì mở luôn — bớt được một lần chạm.
  const effectiveId = selectedId ?? (query.trim() && filtered.length === 1 ? filtered[0].id : null)
  const selected = effectiveId ? allDrugs.find((d) => d.id === effectiveId) ?? null : null

  const diseasesForDrug = useMemo(() => {
    if (!selected?.indications?.length) return []
    const ids = new Set(selected.indications.map((i) => i.diseaseId))
    return diseases.filter((d) => ids.has(d.id))
  }, [selected, diseases])
  const hasDiseaseStep = diseasesForDrug.length > 0
  const selectedDisease =
    hasDiseaseStep && diseaseChoice && diseaseChoice !== DISEASE_SKIP ? diseases.find((d) => d.id === diseaseChoice) ?? null : null

  function selectDrug(id: string | null) {
    setSelectedId(id)
    setDiseaseChoice(null)
  }

  // Chọn xong thuốc mà thẻ kết quả nằm dưới hai màn hình cuộn thì thao tác chưa xong. Gấp khung
  // bệnh nhân rồi cuộn thẳng tới thẻ — đây là lý do duy nhất người dùng bấm vào chip thuốc.
  const cardRef = useRef<HTMLDivElement | null>(null)
  const readyForCard = !hasDiseaseStep || diseaseChoice !== null
  useEffect(() => {
    if (!effectiveId || !readyForCard) return
    collapsePatientPanel()
    // Hoãn một nhịp để khung bệnh nhân gấp xong, nếu không vị trí cuộn tính theo chiều cao cũ.
    // Dùng setTimeout chứ KHÔNG dùng requestAnimationFrame: rAF không chạy khi trang đang bị ẩn
    // (chuyển sang app khác rồi quay lại), lúc đó cú cuộn im lặng không bao giờ xảy ra.
    const t = setTimeout(() => scrollElementIntoView(cardRef.current), 0)
    return () => clearTimeout(t)
  }, [effectiveId, readyForCard])

  return (
    <div className="px-5 pb-6">
      {onPatient.length > 0 && (
        <div className="mb-4">
          <SectionLabel tone="accent">Đang dùng cho bệnh nhân · {onPatient.length}</SectionLabel>
          <div className="grid grid-cols-2 gap-2">
            {onPatient.map((d) => {
              const r = running.find((x) => x.drugId === d.id)
              const on = effectiveId === d.id
              return (
                <button
                  key={d.id}
                  onClick={() => {
                    selectDrug(on ? null : d.id)
                    setQuery("")
                  }}
                  className={`text-left px-3 py-2.5 ${R.box} border ${TAP}`}
                  style={on ? { background: C.accentSoft, borderColor: C.accent } : { background: C.surface, borderColor: C.line }}
                >
                  <p className={`${T.bodyStrong} truncate`} style={{ color: C.text }}>
                    {shortDrugName(d.name)}
                  </p>
                  <p className={`${T.meta} ${NUM} truncate`} style={{ color: C.textSoft }}>
                    {r?.rateText || r?.doseText || "—"}
                  </p>
                </button>
              )
            })}
          </div>
        </div>
      )}

      <SectionLabel>Chọn thuốc</SectionLabel>
      <SearchField
        value={query}
        onChange={(v) => {
          setQuery(v)
          selectDrug(null)
        }}
        placeholder={`Tìm ${categoryLabel.toLowerCase()}...`}
      />
      <div className="flex flex-wrap gap-2 mb-3">
        {/* index chỉ truyền khi CHƯA lọc — xem ghi chú tương tự ở AntibioticsScreen. */}
        {filtered.map((d, i) => (
          <Chip key={d.id} index={query.trim() ? undefined : i} tone="accent" active={effectiveId === d.id} onClick={() => selectDrug(effectiveId === d.id ? null : d.id)}>
            {shortDrugName(d.name)}
          </Chip>
        ))}
      </div>

      {/* Chỉ định — chỉ hiện khi thuốc đang chọn có khai báo liều riêng theo bệnh lý, giống hệt bước
          "Chỉ định" ở AntibioticsScreen. KHÔNG còn chip "Liều chung" — cùng lý do: liều mặc định
          không đại diện cho một bệnh lý cụ thể, bắt buộc chọn đúng bệnh lý. */}
      {selected && hasDiseaseStep && (
        <div key={selected.id} className="fade-in mb-3">
          <SectionLabel>Chỉ định</SectionLabel>
          <div className="flex flex-wrap gap-2">
            {diseasesForDrug.map((ds) => (
              <Chip key={ds.id} active={diseaseChoice === ds.id} onClick={() => setDiseaseChoice(ds.id)}>
                {ds.name}
              </Chip>
            ))}
          </div>
        </div>
      )}

      <div ref={cardRef} style={{ scrollMarginTop: 8 }}>
        {selected && readyForCard ? (
          <div key={`${selected.id}-${selectedDisease?.id ?? "none"}`} className="fade-in">
            <InfusionDrugCard drug={selected} disease={selectedDisease} isOverride={Boolean(selected.isCustom) && staticIds.has(selected.id)} onEdit={onEdit} onDelete={onDelete} />
          </div>
        ) : (
          <p className={`${T.body} text-center px-4 py-6 ${R.card}`} style={{ background: C.surfaceAlt, color: C.textSoft }}>
            {filtered.length === 0
              ? "Không tìm thấy thuốc phù hợp."
              : !selected
                ? "Chọn một thuốc ở trên để mở máy tính pha và liều."
                : "Chọn chỉ định ở trên để tiếp tục."}
          </p>
        )}
      </div>

      <button
        onClick={onAddNew}
        className={`w-full flex items-center justify-center gap-2 h-11 ${R.box} border border-dashed mt-3 ${T.bodyStrong}`}
        style={{ borderColor: C.accentLine, color: C.accent }}
      >
        <span className="scale-90">{icons.plus()}</span>
        Thêm thuốc tự nhập
      </button>
    </div>
  )
}

// ─── Nút chọn chủ đề sáng/tối ─────────────────────────────────────────────────
// Xoay vòng Tự động → Sáng → Tối. Nhãn hiện thẳng trên nút thay vì chỉ một icon mặt trời/mặt trăng:
// với ba trạng thái thì icon đơn không nói được đang ở trạng thái nào (icon mặt trăng nghĩa là
// "đang tối" hay "chạm để chuyển sang tối"?).
// Nút tròn 36px, CHỈ hình mặt trời/mặt trăng — bằng đúng chiều cao nút chọn chuyên khoa đứng cạnh
// nên hai cái nằm khít một hàng ngang. Bản chữ trước đây ("TỰ ĐỘNG"/"SÁNG"/"TỐI") rộng tới 81px,
// vừa chiếm chỗ vừa buộc phải đọc mới hiểu.
function ThemeToggle() {
  const [mode, setMode] = useState<ThemeMode>(loadTheme)
  const next: Record<ThemeMode, ThemeMode> = { auto: "light", light: "dark", dark: "auto" }
  const glyph = mode === "light" ? icons.sun() : mode === "dark" ? icons.moon() : icons.sunMoon()
  return (
    <button
      onClick={() => {
        const m = next[mode]
        setMode(m)
        saveTheme(m)
        tickHaptic()
      }}
      className="flex-none w-9 h-9 rounded-full flex items-center justify-center active:scale-95"
      style={{
        // Cùng bộ nền/viền/đổ bóng với nút chọn chuyên khoa bên cạnh — hai nút đọc thành một cụm.
        background: "var(--c-float-bg)",
        backdropFilter: "blur(20px) saturate(1.6)",
        WebkitBackdropFilter: "blur(20px) saturate(1.6)",
        border: "1px solid var(--c-line)",
        boxShadow: "0 2px 10px var(--c-shadow)",
        color: C.textSoft,
        transition: "background .25s ease, color .25s ease, transform .12s ease",
      }}
      aria-label={`Chủ đề: ${THEME_LABELS[mode]}. Chạm để đổi.`}
      title={`Chủ đề: ${THEME_LABELS[mode]}`}
    >
      {glyph}
    </button>
  )
}

// ─── Dùng thuốc — màn hình cha chứa Kháng sinh / Co bóp cơ tim / Vận mạch / Giãn mạch / Rối loạn nhịp / Điện giải ──────

// Hàng tab: kháng sinh đứng đầu, phần còn lại đọc thẳng từ danh mục nhóm thuốc truyền
// (data/categories.ts) nên thêm một nhóm mới không phải sửa ở đây.
// Nhãn tab cố ý ngắn (một từ nếu được) để hàng tab không phải cuộn xa; nhãn dài hơn chỉ dùng trong
// câu "Tìm <...>" của ô tìm kiếm.
const MIXING_TABS: { id: MixingTab; label: string; search: string }[] = [
  { id: "antibiotics", label: "Kháng sinh", search: "kháng sinh" },
  ...INFUSION_CATEGORIES.map((c) => ({ id: c.id as MixingTab, label: c.tabLabel, search: c.categoryLabel })),
]

// Tiêu đề một dòng, bỏ hẳn dòng mô tả phụ: dòng đó không giúp gì lúc trực mà lại đẩy nội dung
// xuống thấp và là nguồn gốc của mấy chỗ xuống dòng lệch nhau giữa các tab.
const MIXING_TITLES: Record<MixingTab, string> = {
  antibiotics: "Kháng sinh theo CrCl",
  ...(Object.fromEntries(INFUSION_CATEGORIES.map((c) => [c.id, c.title])) as Record<InfusionCategory, string>),
}

// Gợi ý MỘT LẦN DUY NHẤT cho nút "Tìm" xuyên tab — hàng 10 tab không tự dạy người dùng lần đầu rằng
// lối tắt này tồn tại (họ chỉ thấy 10 nhãn viết tắt cuộn ngang). Khác DisclaimerBar (dải nhắc THƯỜNG
// TRỰC), gợi ý này biến mất VĨNH VIỄN ngay khi người dùng mở ô tìm lần đầu — dù mở bằng cách bấm
// đúng nút được gợi ý hay tự mình bấm trước khi đọc gợi ý — nên không vi phạm nguyên tắc "không thêm
// một hàng thường trực" đã đặt ra cho nút Tìm (xem comment tại nút "Tìm" trong DungThuocScreen).
const TAB_SEARCH_HINT_KEY = "drtrong:tabSearchHintSeen"

function DungThuocScreen({
  customAntibiotics,
  diseases,
  customInfusions,
  onAddAntibiotic,
  onAddInfusion,
  onEditAntibiotic,
  onEditInfusion,
  onDeleteAntibiotic,
  onDeleteInfusion,
}: {
  customAntibiotics: Antibiotic[]
  diseases: DiseaseEntry[]
  // Danh sách thuốc TỰ NHẬP của từng nhóm, tra theo id nhóm. Trước đây mỗi nhóm là một prop riêng
  // kèm ba prop thao tác (thêm/sửa/xoá) — 4 prop × số nhóm, tức là thêm một nhóm phải sửa đúng 4
  // chỗ trong chữ ký, 4 chỗ ở nơi gọi và 1 chỗ khi vẽ. Nay mọi nhóm đi qua đúng một đường.
  customInfusions: Record<InfusionCategory, InfusionDrug[]>
  onAddAntibiotic: () => void
  onAddInfusion: (category: InfusionCategory) => void
  onEditAntibiotic: (drug: Antibiotic) => void
  onEditInfusion: (category: InfusionCategory, drug: InfusionDrug) => void
  onDeleteAntibiotic: (id: string) => void
  onDeleteInfusion: (category: InfusionCategory, id: string) => void
}) {
  // Tab đang mở phải sống sót qua việc rời màn hình rồi quay lại — xem lib/uiState.ts.
  const [tab, setTab] = useStickyState<MixingTab>("dungthuoc.tab", "antibiotics")
  const { patient, setField, reset, restore } = usePatientVitals()
  const [patientOpen, setPatientOpen] = useState(() => !patientHasData(patient))
  const [running, setRunning] = useState<RunningDrug[]>(loadRunning)
  const [log, setLog] = useState<CalcLogEntry[]>(loadCalcLog)
  // Số cạnh nút "Nhật ký" trước đây là TỔNG số mục lưu từ trước tới nay (tối đa 200) — chỉ tăng
  // dần qua nhiều ca trực, không nói gì về ca trực NÀY. Đổi sang số mục trong 12 giờ gần nhất.
  const recentLogCount = useMemo(() => {
    const cutoff = Date.now() - 12 * 60 * 60 * 1000
    return log.filter((e) => e.at >= cutoff).length
  }, [log])
  const [showLog, setShowLog] = useState(false)
  const [wardRecipes, setWardRecipes] = useState<Record<string, WardRecipe[]>>(loadWardRecipes)
  // Bản sao 10 giây cho "Hoàn tác" sau "Bệnh nhân mới" — xoá bệnh nhân xoá LUÔN cả bảng đang dùng,
  // là hành động phá huỷ nhất màn hình này nên phải có đường lùi lại.
  const [resetUndo, setResetUndo] = useState<{ patient: PatientVitals; running: RunningDrug[] } | null>(null)
  const resetUndoTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => () => { if (resetUndoTimer.current) clearTimeout(resetUndoTimer.current) }, [])
  const scrollRef = useRef<HTMLDivElement | null>(null)
  const tabRowRef = useRef<HTMLDivElement | null>(null)
  const activeTabRef = useRef<HTMLButtonElement | null>(null)
  // Tab đang nhớ qua useStickyState có thể đứng thứ 7-8 trong 10 tab — mở app lên mà hàng tab vẫn
  // đứng ở đầu thì không thấy tab nào đang chọn. Cuộn NGAY (không mượt) đúng một lần khi vào màn,
  // không cuộn lại mỗi lần đổi tab bằng tay (người dùng tự thấy tab họ vừa bấm).
  useEffect(() => {
    activeTabRef.current?.scrollIntoView({ behavior: "auto", inline: "center", block: "nearest" })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // ─── Tìm kiếm xuyên tab ────────────────────────────────────────────────────
  // Mỗi tab vốn có ô tìm riêng, chỉ tìm trong đúng tab đang mở: gõ "adrenaline" ở tab Kháng sinh
  // thì không ra gì, mà lúc cấp cứu không ai nhớ adrenaline nằm ở tab "Co bóp" hay "Vận mạch" —
  // nó nằm ở CẢ HAI, dưới hai bản ghi khác nhau. Ô này tìm qua toàn bộ 10 nhóm cùng lúc.
  //
  // Mở bằng nút kính lúp trên tiêu đề chứ không chiếm sẵn một hàng: màn này cố ý giữ nội dung sát
  // lên trên, thêm một hàng thường trực là đẩy phần máy tính xuống thấp ở mọi lần dùng.
  const [searchOpen, setSearchOpen] = useState(false)
  const [globalQuery, setGlobalQuery] = useState("")
  // Tăng lên mỗi lần nhảy tới một thuốc, để cây con được dựng lại KỂ CẢ khi thuốc đó nằm ngay
  // trong tab đang mở — nếu không, giá trị sticky vừa ghi sẽ không được đọc lại.
  const [jumpKey, setJumpKey] = useState(0)
  // Gợi ý một lần cho nút Tìm — mặc định ẨN nếu không đọc được localStorage (ngược với
  // DisclaimerGate: một gợi ý lặp lại mãi vì lỗi đọc storage gây khó chịu hơn là mất một lần gợi ý).
  const [showTabHint, setShowTabHint] = useState(() => {
    try {
      return localStorage.getItem(TAB_SEARCH_HINT_KEY) !== "1"
    } catch {
      return false
    }
  })
  function dismissTabHint() {
    try {
      localStorage.setItem(TAB_SEARCH_HINT_KEY, "1")
    } catch {
      // Không lưu được thì gợi ý có thể hiện lại lần sau — chấp nhận được, không chặn việc dùng app.
    }
    setShowTabHint(false)
  }

  const searchResults = useMemo(() => {
    const q = normalizeSearch(globalQuery)
    if (!q) return []
    const out: { tab: MixingTab; tabLabel: string; id: string; name: string; route: string }[] = []
    mergeWithOverrides(ANTIBIOTICS, customAntibiotics).forEach((d) => {
      if (normalizeSearch(d.name).includes(q)) out.push({ tab: "antibiotics", tabLabel: "Kháng sinh", id: d.id, name: d.name, route: d.route })
    })
    INFUSION_CATEGORIES.forEach((c) => {
      mergeWithOverrides(c.staticDrugs, customInfusions[c.id] ?? []).forEach((d) => {
        if (normalizeSearch(d.name).includes(q)) out.push({ tab: c.id, tabLabel: c.tabLabel, id: d.id, name: d.name, route: d.route })
      })
    })
    // Cắt ngắn: danh sách dài hơn một màn hình thì không còn là kết quả tìm kiếm nữa mà là danh mục.
    return out.slice(0, 30)
  }, [globalQuery, customAntibiotics, customInfusions])

  // Mở thẳng thuốc vừa chọn ở tab của nó. Đặt sẵn các bước chọn của tab đích (hoạt chất / bệnh lý /
  // đường dùng) rồi mới đổi tab — xem writeStickyState trong lib/uiState.ts.
  function openSearchResult(r: { tab: MixingTab; id: string; name: string }) {
    if (r.tab === "antibiotics") {
      writeStickyState("abx.query", "")
      writeStickyState<string | null>("abx.group", r.name)
      // Bỏ qua bước chọn bệnh lý: người dùng vừa gọi đích danh một thuốc, bắt chọn thêm một bước
      // nữa mới thấy liều là làm hỏng chính thao tác họ đang cố rút ngắn.
      writeStickyState<string | null>("abx.disease", DISEASE_SKIP)
      writeStickyState<string | null>("abx.entry", r.id)
    } else {
      const cat = infusionCategory(r.tab)
      writeStickyState(`infusion.query.${cat.categoryLabel}`, "")
      writeStickyState<string | null>(`infusion.sel.${cat.categoryLabel}`, r.id)
      writeStickyState<string | null>(`infusion.disease.${cat.categoryLabel}`, null)
    }
    setTab(r.tab)
    setJumpKey((n) => n + 1)
    setSearchOpen(false)
    setGlobalQuery("")
    tickHaptic()
  }

  // parseStrictNumber (không phải parseFloat) — "70abc"/"1.2.9" phải thành CHƯA NHẬP, không được
  // âm thầm rớt xuống 70/1.2 rồi chạy thẳng vào CrCl và liều mg/kg như một số sạch.
  const abwKg = useMemo(() => {
    const v = parseStrictNumber(patient.weight)
    return v == null || v <= 0 ? null : v
  }, [patient.weight])
  const heightCm = useMemo(() => {
    const v = parseStrictNumber(patient.height)
    return v == null || v <= 0 ? null : v
  }, [patient.height])
  const ageYears = useMemo(() => {
    const v = parseStrictNumber(patient.age)
    return v == null || v <= 0 ? null : v
  }, [patient.age])

  // CrCl dùng cân nặng hiệu chỉnh khi béo phì, theo cùng quy tắc áp dụng cho liều thuốc.
  const crcl = useMemo(() => {
    const w = resolveDosingWeight(abwKg, heightCm, patient.sex, "adjusted").used
    const s = parseStrictNumber(patient.scr)
    if (ageYears == null || w == null || s == null || s <= 0) return null
    return estimateCrCl(ageYears, w, scrToMgDl(s, patient.scrUnit), patient.sex)
  }, [abwKg, heightCm, ageYears, patient.scr, patient.scrUnit, patient.sex])
  const crclUsable = crclReliability(patient) === "ok"

  const dosingCtx = useMemo<DosingContextValue>(
    () => ({
      patient,
      setPatientField: setField,
      // "Bệnh nhân mới" phải xoá SẠCH: thông số cũ nằm nguyên đó là kiểu sai nguy hiểm nhất vì nhìn
      // vẫn "có số". Bảng Đang truyền cũng thuộc về bệnh nhân cũ nên xoá cùng lúc. Giữ lại một bản
      // sao 10 giây để "Hoàn tác" — đây là hành động phá huỷ nhất màn hình, không phải chỗ để im
      // lặng mất dữ liệu nếu bấm nhầm.
      resetPatient: () => {
        setResetUndo({ patient, running })
        if (resetUndoTimer.current) clearTimeout(resetUndoTimer.current)
        // Hoàn tác 10 giây trước đây không để lại dấu vết nào sau khi hết hạn — người dùng bị gián
        // đoạn quá 10 giây (chuyện thường lúc trực) mất hẳn khả năng biết mình vừa xoá gì, lúc nào.
        // Ghi vào Nhật ký ĐÚNG LÚC hết hạn (không phải lúc bấm xoá), để một lần bấm nhầm rồi bấm
        // "Hoàn tác" ngay sau đó không tạo ra một dòng nhật ký thừa cho việc chưa từng thật sự xảy ra.
        const clearedSummary =
          [abwKg != null ? `${abwKg} kg` : null, heightCm != null ? `${heightCm} cm` : null, patient.sex === "male" ? "Nam" : "Nữ", ageYears != null ? `${ageYears} tuổi` : null]
            .filter(Boolean)
            .join(" · ") || "Chưa có thông số"
        const clearedRunningCount = running.length
        resetUndoTimer.current = setTimeout(() => {
          setResetUndo(null)
          setLog(
            appendCalcLog({
              drug: "Bệnh nhân hiện tại",
              kind: "patientReset",
              inputs: [clearedSummary],
              output: `Đã xoá${clearedRunningCount > 0 ? ` bệnh nhân và ${clearedRunningCount} thuốc đang dùng` : " bệnh nhân"} — không hoàn tác kịp trong 10 giây`,
              weightKg: abwKg,
            }),
          )
        }, 10_000)
        reset()
        setRunning([])
        saveRunning([])
        setPatientOpen(true)
      },
      resetUndo,
      undoResetPatient: () => {
        if (!resetUndo) return
        if (resetUndoTimer.current) clearTimeout(resetUndoTimer.current)
        restore(resetUndo.patient)
        setRunning(resetUndo.running)
        saveRunning(resetUndo.running)
        setResetUndo(null)
      },
      abwKg,
      heightCm,
      ageYears,
      crcl,
      crclUsable,
      openPatientPanel: () => {
        setPatientOpen(true)
        scrollRef.current?.scrollTo({ top: 0, behavior: "smooth" })
      },
      // Chỉ tự gấp khi đã có thông số — nếu chưa nhập gì mà gấp lại thì người dùng mới vào không
      // thấy chỗ nhập cân nặng ở đâu.
      collapsePatientPanel: () => setPatientOpen((open) => (open && patientHasData(patient) ? false : open)),
      running,
      // Chống trùng nằm trong lib/runningDrugs.ts (upsertRunning) — cùng thuốc thật thì cập nhật
      // chứ không thêm bản thứ hai, kể cả khi hai bản ghi có drugId khác nhau.
      pinRunning: (item) =>
        setRunning((prev) => {
          const next = upsertRunning(prev, item)
          saveRunning(next)
          return next
        }),
      unpinRunning: (id) =>
        setRunning((prev) => {
          const next = prev.filter((r) => r.id !== id)
          saveRunning(next)
          return next
        }),
      setRunningLine: (id, line) =>
        setRunning((prev) => {
          const next = prev.map((r) => (r.id === id ? { ...r, line } : r))
          saveRunning(next)
          return next
        }),
      // Nhật ký neo theo cân nặng và thời điểm, KHÔNG theo tên người bệnh — app cố ý không lưu
      // thông tin định danh (xem lib/patient.ts).
      logCalc: (entry) => setLog(appendCalcLog({ ...entry, weightKg: abwKg })),
      wardRecipes,
      saveWard: (recipe) =>
        // Trước đây id mới chỉ là `${drugId}-${Date.now()}` — độ phân giải mili-giây, nên bấm
        // "Lưu công thức" hai lần liên tiếp thật nhanh (double-tap trên điện thoại là chuyện
        // thường) có thể ra CÙNG một id, và công thức lưu sau âm thầm đè mất công thức lưu trước
        // thay vì tạo thêm một công thức mới. Thêm hậu tố ngẫu nhiên để luôn phân biệt được.
        setWardRecipes(
          saveWardRecipe({ ...recipe, id: recipe.id ?? `${recipe.drugId}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, savedAt: Date.now() }),
        ),
      clearWard: (drugId, recipeId) => setWardRecipes(removeWardRecipe(drugId, recipeId)),
      pinWard: (drugId, recipeId) => setWardRecipes(setPinnedWardRecipe(drugId, recipeId)),
    }),
    [patient, setField, reset, restore, abwKg, heightCm, ageYears, crcl, crclUsable, running, wardRecipes, resetUndo],
  )

  return (
    <DosingContext.Provider value={dosingCtx}>
    <div className="scr-dose h-full flex flex-col relative">
      <ScreenHeader
        title={MIXING_TITLES[tab]}
        actions={
          <>
            <button
              onClick={() => {
                setSearchOpen((v) => !v)
                setGlobalQuery("")
                if (showTabHint) dismissTabHint()
              }}
              // Trước đây chỉ là một vòng tròn icon-only 32px — nút nhanh nhất tới hơn 100 thuốc mà
              // không có chữ nào gọi tên nó, người lần đầu dùng không biết nó làm gì cho tới khi lỡ
              // bấm. Giờ có chữ "Tìm" đi kèm icon, khớp hình dạng pill với "Nhật ký" đứng cạnh — một
              // hàng nút phụ nhất quán thay vì một icon lẻ loi.
              //
              // Pill NHÌN THẤY vẫn cao 36px (bằng "Nhật ký", không phá hàng tiêu đề min-h-9 cố định)
              // nhưng vùng CHẠM của chính button là 44px nhờ đệm dọc vô hình — dưới 44px là trượt khỏi
              // ngưỡng chạm đã áp cho các nút khác trong màn.
              className="flex-none flex items-center justify-center py-1"
              aria-label="Tìm thuốc trong mọi nhóm"
            >
              <span
                className={`h-9 pl-2.5 pr-3 ${R.pill} ${T.label} border flex items-center gap-1.5`}
                style={searchOpen ? { borderColor: C.primary, background: C.primarySoft, color: C.primary } : { borderColor: C.line, color: C.textSoft }}
              >
                {/* Icon luôn ở dạng nét (không tô đặc): path này vẽ cho outline, tô đặc theo `active`
                    làm phần tay cầm (một nét thẳng không khép kín) biến mất — chỉ còn vòng tròn đặc,
                    trông như ảnh vỡ. icons.search() vẽ cỡ 24px cố định (w-6 h-6) — thu nhỏ bằng `scale`
                    ở đây thay vì sửa icon dùng chung: chỗ khác gọi icons.search() vẫn cần đúng cỡ gốc. */}
                <span className="flex items-center justify-center" style={{ transform: "scale(0.7)" }}>
                  {icons.search(false)}
                </span>
                Tìm
              </span>
            </button>
            {/* Cùng kỹ thuật đệm dọc vô hình với nút "Tìm" cạnh nó: pill nhìn thấy vẫn cao 36px
                (khớp hàng tiêu đề min-h-9), nhưng vùng CHẠM của chính button là 44px. */}
            <button
              onClick={() => setShowLog(true)}
              className="flex-none flex items-center justify-center py-1"
              aria-label={`Nhật ký${recentLogCount > 0 ? ` · ${recentLogCount} mục gần đây` : ""}`}
            >
              <span className={`h-9 px-3 ${R.pill} ${T.label} border flex items-center`} style={{ borderColor: C.line, color: C.textSoft }}>
                Nhật ký{recentLogCount > 0 ? ` · ${recentLogCount}` : ""}
              </span>
            </button>
          </>
        }
      />

      {/* Ô tìm chung — chỉ hiện khi bấm kính lúp, tìm qua kháng sinh và cả 9 nhóm thuốc truyền. */}
      {searchOpen && (
        <div className="fade-in flex-none px-5 pb-3">
          <SearchField value={globalQuery} onChange={setGlobalQuery} placeholder="Tìm thuốc trong mọi nhóm..." autoFocus />
          {globalQuery.trim() !== "" && (
            <div className={`${R.box} border overflow-hidden`} style={{ borderColor: C.line, background: C.surface }}>
              {searchResults.length === 0 ? (
                <p className={`${T.body} px-3 py-3`} style={{ color: C.textSoft }}>
                  Không có thuốc nào khớp "{globalQuery.trim()}" trong danh mục.
                </p>
              ) : (
                <div
                  className="max-h-64 overflow-y-auto scroll-ios"
                  role="group"
                  aria-label={`${searchResults.length} kết quả tìm kiếm`}
                  // Danh sách vốn chỉ Tab-qua-từng-nút được (đúng nhưng chậm khi có tới 30 kết quả) —
                  // thêm mũi tên lên/xuống di chuyển giữa các nút mà không đổi hành vi kích hoạt của
                  // chính nút (Enter/Space/chạm vẫn nguyên vẹn, không thay bằng vai trò option tự chế).
                  onKeyDown={(e) => {
                    if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return
                    const container = e.currentTarget
                    const items = Array.from(container.querySelectorAll<HTMLButtonElement>("button"))
                    const idx = items.indexOf(document.activeElement as HTMLButtonElement)
                    if (idx === -1) return
                    e.preventDefault()
                    const next = e.key === "ArrowDown" ? Math.min(idx + 1, items.length - 1) : Math.max(idx - 1, 0)
                    items[next]?.focus()
                  }}
                >
                  {searchResults.map((r, i) => (
                    <button
                      key={`${r.tab}-${r.id}`}
                      onClick={() => openSearchResult(r)}
                      className={`rise-in w-full text-left px-3 py-2.5 border-b ${TAP}`}
                      style={{ borderColor: C.lineSoft, "--i": i } as React.CSSProperties}
                    >
                      <div className="flex items-center gap-2">
                        <p className={`${T.bodyStrong} truncate flex-1`} style={{ color: C.text }}>
                          {r.name}
                        </p>
                        <span className={`${T.meta} font-semibold px-2 py-0.5 ${R.pill} flex-none`} style={{ background: C.primarySoft, color: C.primary }}>
                          {r.tabLabel}
                        </span>
                      </div>
                      <p className={`${T.meta} truncate`} style={{ color: C.textSoft }}>
                        {shortRoute(r.route)}
                      </p>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Hàng tab — cùng chiều cao với mọi chip khác trong màn (44px vùng chạm). 10 tab cuộn ngang;
          tab đang nhớ (useStickyState) có thể là tab thứ 7-8, mở app lên thấy hàng tab đứng ở đầu
          và KHÔNG thấy tab nào đang chọn — trông như chưa chọn gì. Cuộn tab đang chọn vào khung
          nhìn ngay khi mount, và hai dải mờ hai mép báo hàng còn cuộn được. */}
      <div className="flex-none pb-3 relative">
        <div
          ref={tabRowRef}
          // gap-3 (12px, trước là gap-2/8px): mỗi tab đã cao đủ 44px nhưng đứng SÁT nhau thì ngón
          // tay run/vuốt một tay vẫn dễ trượt sang tab kế bên — 10 tab dồn trên một điện thoại 375px
          // là đúng tình huống đó. Thêm khoảng trống thay vì phóng to từng tab để không đẩy hàng tab
          // cuộn xa hơn.
          className="scroll-ios flex gap-3 px-5 overflow-x-auto"
          style={{ scrollbarWidth: "none" }}
          role="tablist"
          aria-label="Nhóm thuốc"
        >
          {MIXING_TABS.map((t) => (
            <button
              key={t.id}
              id={`mixing-tab-${t.id}`}
              ref={tab === t.id ? activeTabRef : null}
              onClick={() => setTab(t.id)}
              // pulse-scale chỉ đặt khi CHÍNH tab này vừa thành active — remount qua key riêng để
              // hoạt ảnh chạy lại mỗi lần chuyển tab, không chỉ lần đầu mount.
              className={`${CHIP} border-transparent${tab === t.id ? " pulse-scale" : ""}`}
              // --c-text-muted trên --c-line-soft chỉ ~4,1:1 ở 12px đậm — dưới ngưỡng AA 4,5:1.
              // Đổi sang --c-text-soft cho tab CHƯA chọn (đọc nhiều, phải rõ).
              style={tab === t.id ? { background: C.primary, color: "var(--c-on-bright)" } : { background: C.lineSoft, color: C.textSoft }}
              role="tab"
              aria-selected={tab === t.id}
              aria-controls="mixing-tabpanel"
            >
              {t.label}
            </button>
          ))}
        </div>
        <div className="absolute left-0 top-0 bottom-3 w-6 pointer-events-none" style={{ background: "linear-gradient(to right, var(--c-page), transparent)" }} />
        <div className="absolute right-0 top-0 bottom-3 w-6 pointer-events-none" style={{ background: "linear-gradient(to left, var(--c-page), transparent)" }} />
      </div>
      {/* Gợi ý MỘT LẦN cho nút Tìm — 10 tab là quá nhiều để quét bằng mắt lúc vội, và bản thân hàng
          tab không dạy người dùng lần đầu rằng lối tắt "Tìm xuyên nhóm" tồn tại. Biến mất vĩnh viễn
          ngay khi mở ô tìm lần đầu (xem onClick nút Tìm) hoặc bấm "Đã hiểu" — không phải một hàng
          thường trực, nên không phá nguyên tắc "không thêm hàng cố định" đã đặt cho nút Tìm. */}
      {showTabHint && (
        <div
          className="fade-in flex-none mx-5 mb-3 flex items-center gap-2 px-3 py-2 rounded-xl"
          style={{ background: C.primarySoft, border: `1px solid ${C.primaryLine}` }}
        >
          <p className={`${T.meta} flex-1`} style={{ color: C.primary }}>
            Không thấy thuốc cần tìm trong {MIXING_TABS.length} nhóm? Bấm "Tìm" ở trên để tìm xuyên tất cả.
          </p>
          <button onClick={dismissTabHint} className={`flex-none h-11 px-3 ${R.pill} dose-press text-[12px] font-bold`} style={{ background: C.primary, color: "var(--c-on-bright)" }}>
            Đã hiểu
          </button>
        </div>
      )}
      {/* Một vùng cuộn duy nhất cho cả khung bệnh nhân, bảng Đang truyền và danh sách thuốc —
          để khung bệnh nhân cuộn đi được thay vì chiếm chỗ cố định trên màn hình điện thoại. */}
      <div ref={scrollRef} className="scroll-ios flex-1">
        <DisclaimerBar />
        <PatientPanel open={patientOpen} onToggle={() => setPatientOpen((v) => !v)} />
        <RunningPanel />
        <div
          key={`${tab}-${jumpKey}`}
          className="fade-in"
          role="tabpanel"
          id="mixing-tabpanel"
          aria-labelledby={`mixing-tab-${tab}`}
        >
          {tab === "antibiotics" ? (
            <AntibioticsScreen customDrugs={customAntibiotics} diseases={diseases} onAddNew={onAddAntibiotic} onEdit={onEditAntibiotic} onDelete={onDeleteAntibiotic} />
          ) : (
            (() => {
              const cat = infusionCategory(tab)
              return (
                <InfusionCategoryScreen
                  staticDrugs={cat.staticDrugs}
                  customDrugs={customInfusions[cat.id] ?? []}
                  diseases={diseases}
                  categoryLabel={cat.categoryLabel}
                  onAddNew={() => onAddInfusion(cat.id)}
                  onEdit={(drug) => onEditInfusion(cat.id, drug)}
                  onDelete={(id) => onDeleteInfusion(cat.id, id)}
                />
              )
            })()
          )}
        </div>
      </div>

      {showLog && (
        <CalcLogSheet
          entries={log}
          onClear={() => setLog(clearCalcLog())}
          onRemove={(ids) => setLog(removeCalcLogEntries(ids))}
          onClose={() => setShowLog(false)}
        />
      )}
      {resetUndo && (
        <div
          className="toast-in-full absolute left-4 right-4 z-50 rounded-2xl px-4 py-3 flex items-center gap-3"
          // --c-pill-dark/--c-shadow (không phải rgba viết tay): pill này cố ý LUÔN tối bất kể theme
          // (đọc được ở mọi vị trí trên màn, không phải một lớp phủ mờ). Trước đây viết rgba(9,32,33,…)
          // trùng khớp giá trị --c-pill-dark nhưng lại ghép với `color: var(--c-on-bright)` — token đó
          // đổi thành GẦN ĐEN ở bản tối (dành cho chữ trên nền primary/accent sáng lên), nên chữ trên
          // nền pill tối luôn-tối này thành gần như vô hình đúng lúc báo tin quan trọng nhất màn hình.
          // Chữ ở đây dùng trắng cố định, khớp với nền cố định tối của chính nó, không đi theo theme.
          style={{ bottom: "calc(var(--nav-body-h) + 18px)", background: "var(--c-pill-dark)", boxShadow: "0 8px 24px var(--c-shadow)" }}
        >
          <p className="flex-1 text-[13px] font-semibold" style={{ color: "#fff" }}>
            Đã xoá bệnh nhân{resetUndo.running.length > 0 ? ` và ${resetUndo.running.length} thuốc đang dùng` : ""}
          </p>
          <button
            onClick={() => dosingCtx.undoResetPatient()}
            className="flex-none h-8 px-3 rounded-full text-[12px] font-bold"
            style={{ background: "var(--c-primary)", color: "var(--c-on-bright)" }}
          >
            Hoàn tác
          </button>
        </div>
      )}
      <DisclaimerGate />
    </div>
    </DosingContext.Provider>
  )
}

// ─── Mindmap ───────────────────────────────────────────────────────────────────
// Toàn bộ bảng vẽ nằm trong components/MindmapBoard.tsx — xem ghi chú ở đầu file đó.
//
// Màn này có HAI trạng thái:
//   1. Danh sách bảng (mặc định) — thấy hết các bảng đã tạo, lọc theo chuyên khoa, đổi lưới/danh sách.
//   2. Một bảng đang mở — chạm vào một bảng ở danh sách thì vào đây, có nút quay lại.
//
// Trước đây vào tab là nhảy thẳng vào bảng đang mở gần nhất, còn các bảng khác nằm sau một dải chip
// cuộn ngang. Cách đó chỉ ổn khi có 2–3 bảng: nhiều hơn thì phải cuộn ngang mò từng cái, không thấy
// được bảng nào có gì, và không có chỗ nào cho biết bảng thuộc chuyên khoa nào.

const MINDMAP_VIEW_KEY = "drtrong:mindmap-gallery-view"
type GalleryView = "grid" | "list"

function readGalleryView(): GalleryView {
  try {
    return localStorage.getItem(MINDMAP_VIEW_KEY) === "list" ? "list" : "grid"
  } catch {
    return "grid"
  }
}

function writeGalleryView(v: GalleryView): void {
  try {
    localStorage.setItem(MINDMAP_VIEW_KEY, v)
  } catch {
    // Không lưu được thì lần sau về mặc định lưới — không đáng chặn việc gì.
  }
}

// "Hôm nay" / "Hôm qua" / "5 ngày trước" / "12/07/2026". Ngày tuyệt đối chỉ hiện khi đã đủ xa để
// con số tương đối mất nghĩa — "37 ngày trước" không nói được gì hơn một ngày tháng cụ thể.
function boardWhen(ts: number): string {
  const d = new Date(ts)
  const today = new Date()
  const startOf = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime()
  const days = Math.round((startOf(today) - startOf(d)) / 86400000)
  if (days <= 0) return "Hôm nay"
  if (days === 1) return "Hôm qua"
  if (days < 30) return `${days} ngày trước`
  return d.toLocaleDateString("vi-VN")
}

// Ảnh xem trước của một bảng — đọc dữ liệu thật rồi thu nhỏ cả bảng vào khung thẻ.
//
// Nhớ theo id ở cấp module: cuộn danh sách qua lại không đọc lại IndexedDB, và quay về danh sách sau
// khi đóng một bảng thì ảnh hiện ngay chứ không nháy trắng một nhịp.
const boardPreviewCache = new Map<string, MindmapData>()

function BoardThumb({ board, tick }: { board: MindBoard; tick: number }) {
  const [data, setData] = useState<MindmapData | null>(() => boardPreviewCache.get(board.id) ?? null)

  useEffect(() => {
    let cancelled = false
    // Bảng vừa được sửa (tick đổi) thì phải đọc lại — ảnh xem trước cũ là ảnh của nội dung cũ.
    ;(async () => {
      const d = await loadMindmap(board.id)
      if (cancelled) return
      boardPreviewCache.set(board.id, d)
      setData(d)
    })()
    return () => {
      cancelled = true
    }
  }, [board.id, tick])

  const box = useMemo(() => (data ? contentBounds(data, {}) : null), [data])
  // Bảng trống hoặc chưa đọc xong: vẽ mặt giấy trơn, không vẽ khung rỗng trông như ảnh lỗi.
  if (!data || !box) return null

  // Chừa lề quanh nội dung để nét ngoài cùng không dính sát mép thẻ.
  const pad = Math.max(12, Math.max(box.w, box.h) * 0.06)
  const vb = `${box.x - pad} ${box.y - pad} ${box.w + pad * 2} ${box.h + pad * 2}`
  const strokes = (data.strokes ?? []).slice(0, 600)

  return (
    // fade-in: cuộn một danh sách 20 bảng cho ra một loạt nét vẽ bật lên rời rạc khi mỗi ảnh xem
    // trước đọc xong IndexedDB không cùng lúc — mờ dần 0,18s thay vì bật cứng.
    <svg viewBox={vb} preserveAspectRatio="xMidYMid meet" className="absolute inset-0 w-full h-full fade-in">
      {strokes.map((s) => {
        const filled = !!s.widths && s.widths.length > 1 && !s.straight
        return (
          <path
            key={s.id}
            d={filled ? strokeOutline(s.points, s.widths!) : strokePath(s.points, s.straight)}
            fill={filled ? s.color : "none"}
            stroke={filled ? "none" : s.color}
            strokeWidth={filled ? undefined : s.width}
            strokeLinecap="round"
            strokeLinejoin="round"
            opacity={s.tool === "highlighter" ? 0.4 : 1}
          />
        )
      })}
      {/* Thẻ ghi chú vẽ thành khối màu đặc, KHÔNG in chữ: ở cỡ ảnh xem trước thì chữ chỉ còn vài
          pixel, thành một vệt xám bẩn chứ không đọc được gì. Khối màu lại cho nhận ra ngay hình
          dạng và màu sắc quen thuộc của bảng. */}
      {data.nodes.map((n) => (
        <rect
          key={n.id}
          x={n.x}
          y={n.y}
          width={NODE_FALLBACK.w}
          height={NODE_FALLBACK.h}
          rx={10}
          fill={n.color}
          opacity={0.9}
        />
      ))}
    </svg>
  )
}

// Số ghi chú của một bảng, hiện cạnh "Hôm qua" ở thẻ bảng trong danh sách — trước đây con số này
// (nodes.length) chỉ có bên TRONG bảng, ở dòng gần cuối một menu phải mở ra mới thấy. Đọc từ CÙNG
// `boardPreviewCache` mà BoardThumb đã dùng để tránh đọc IndexedDB hai lần cho cùng một bảng —
// bảng nào BoardThumb đã tải xong thì component này có ngay, không phải tải lại.
function BoardNoteCount({ board, tick }: { board: MindBoard; tick: number }) {
  const [data, setData] = useState<MindmapData | null>(() => boardPreviewCache.get(board.id) ?? null)
  useEffect(() => {
    let cancelled = false
    const cached = boardPreviewCache.get(board.id)
    if (cached) {
      setData(cached)
      return
    }
    void loadMindmap(board.id).then((d) => {
      if (cancelled) return
      boardPreviewCache.set(board.id, d)
      setData(d)
    })
    return () => {
      cancelled = true
    }
  }, [board.id, tick])
  if (!data) return null
  const count = data.nodes.length
  if (count === 0) return null
  return <span> · {count} ghi chú</span>
}

// Một thẻ khớp ô tìm xuyên-bảng: bảng nào, node nào, và đoạn trích đã bỏ dấu định dạng (**/{{...}})
// để đọc gọn trong danh sách kết quả.
interface MindmapSearchHit {
  board: MindBoard
  node: MindNode
  snippet: string
}

function MindmapGallery({
  boards,
  onOpen,
  onCreate,
  onEditBoard,
  previewTick,
  trashedBoards,
  onRestoreBoard,
  onPurgeBoard,
}: {
  boards: MindBoard[]
  // `rect` — khung của thẻ vừa chạm (nếu mở từ MỘT THẺ, không phải từ kết quả tìm xuyên bảng) — cho
  // MindmapScreen phóng khung xem trước lên đúng chỗ đó khi mở bảng (D3).
  onOpen: (id: string, query?: string, rect?: DOMRect) => void
  onCreate: () => void
  onEditBoard: (board: MindBoard) => void
  previewTick: number
  trashedBoards: MindBoard[]
  onRestoreBoard: (id: string) => void
  onPurgeBoard: (id: string) => void
}) {
  const [view, setView] = useState<GalleryView>(readGalleryView)
  const [specialty, setSpecialty] = useState<string>("all")
  const [filterOpen, setFilterOpen] = useState(false)
  const [trashOpen, setTrashOpen] = useState(false)

  // ─── Tìm xuyên suốt mọi bảng ──────────────────────────────────────────────
  // Trước đây ô tìm chỉ chạy TRONG một bảng đang mở — có hơn chục bảng thì nhớ "ghi chú đó nằm ở
  // bảng nào" là việc của người dùng, phải mở từng bảng dò tay. `loadAllMindmapNodes()` đọc TOÀN
  // BỘ node của mọi bảng trong đúng MỘT lần đọc IndexedDB (idbGetAll không lọc theo id), nên tìm
  // xuyên bảng không tốn hơn tìm một bảng bao nhiêu.
  const [query, setQuery] = useState("")
  const [searchHits, setSearchHits] = useState<MindmapSearchHit[] | null>(null)
  const [searching, setSearching] = useState(false)
  const searchSeq = useRef(0)

  useEffect(() => {
    const q = normalizeSearch(query)
    if (!q) {
      setSearchHits(null)
      setSearching(false)
      return
    }
    setSearching(true)
    const seq = ++searchSeq.current
    const timer = setTimeout(() => {
      void loadAllMindmapNodes().then((rows) => {
        // Phản hồi của một lượt gõ CŨ hơn tới sau lượt gõ MỚI hơn (mạng máy chậm/lag hiếm gặp) thì bỏ
        // qua — không để kết quả cũ đè lên kết quả của từ khoá người dùng đang gõ dở.
        if (seq !== searchSeq.current) return
        const byId = new Map(boards.map((b) => [b.id, b]))
        const hits: MindmapSearchHit[] = []
        rows.forEach(({ boardId, node }) => {
          const board = byId.get(boardId)
          if (!board) return
          const plain = stripInlineMarkers(node.text)
          if (!normalizeSearch(plain).includes(q)) return
          hits.push({ board, node, snippet: plain.length > 90 ? `${plain.slice(0, 90)}…` : plain })
        })
        setSearchHits(hits)
        setSearching(false)
      })
    }, 200)
    return () => clearTimeout(timer)
  }, [query, boards])

  // Kết quả nhóm theo bảng, bảng mới sửa gần đây lên trước — cùng thứ tự với danh sách bảng thường.
  const groupedHits = useMemo(() => {
    if (!searchHits) return []
    const byBoard = new Map<string, { board: MindBoard; hits: MindmapSearchHit[] }>()
    searchHits.forEach((h) => {
      const g = byBoard.get(h.board.id)
      if (g) g.hits.push(h)
      else byBoard.set(h.board.id, { board: h.board, hits: [h] })
    })
    return [...byBoard.values()].sort((a, b) => b.board.updatedAt - a.board.updatedAt)
  }, [searchHits])

  // Chỉ đưa vào bộ lọc những chuyên khoa THẬT SỰ có bảng. Một danh sách 10 khoa mà 8 khoa bấm vào
  // ra màn trống thì bộ lọc thành thứ phải thử mới biết, thay vì nhìn là biết.
  const usedSpecialties = useMemo(() => {
    const ids = new Set(boards.map((b) => b.specialtyId).filter((s): s is string => !!s))
    return SPECIALTIES.filter((s) => ids.has(s.id))
  }, [boards])
  const hasUnassigned = boards.some((b) => !b.specialtyId)

  const shown = useMemo(() => {
    const list =
      specialty === "all"
        ? boards
        : specialty === "none"
          ? boards.filter((b) => !b.specialtyId)
          : boards.filter((b) => b.specialtyId === specialty)
    // Mới sửa gần đây nhất lên trước — bảng đang làm dở là bảng cần mở lại nhiều nhất.
    return [...list].sort((a, b) => b.updatedAt - a.updatedAt)
  }, [boards, specialty])

  const filterLabel =
    specialty === "all"
      ? "Tất cả"
      : specialty === "none"
        ? "Chưa gắn khoa"
        : (SPECIALTIES.find((s) => s.id === specialty)?.name ?? "Tất cả")

  function pick(id: string) {
    setSpecialty(id)
    setFilterOpen(false)
    tickHaptic()
  }

  return (
    <div className="h-full flex flex-col">
      <ScreenHeader title="Mindmap" />

      {/* Tìm chữ trong ghi chú xuyên suốt MỌI bảng — trước đây ô tìm chỉ nằm trong từng bảng, phải
          nhớ đúng bảng nào mới mở ra tìm được. */}
      <div className="flex-none px-5">
        <SearchField value={query} onChange={setQuery} placeholder="Tìm ghi chú trong mọi bảng…" />
      </div>

      {query.trim() ? (
        <div className="scroll-ios flex-1 px-5 pb-6">
          {/* Trước đây `searching` thay CẢ vùng kết quả bằng một dòng "Đang tìm…" — một thao tác
              200ms mà thay hết nội dung cho ra cảm giác nháy liên tục khi gõ. Giữ kết quả CŨ
              (searchHits không bị xoá khi lượt tìm mới bắt đầu — xem effect phía trên), chỉ giảm
              opacity trong lúc chờ; "Đang tìm…" chỉ còn dành cho lượt tìm ĐẦU TIÊN chưa có gì. */}
          {searching && groupedHits.length === 0 ? (
            <p className={`${T.body} text-center mt-10`} style={{ color: C.textSoft }}>
              Đang tìm…
            </p>
          ) : groupedHits.length === 0 ? (
            <p className={`${T.body} text-center mt-10`} style={{ color: C.textSoft }}>
              Không tìm thấy "{query.trim()}" trong bất kỳ bảng nào.
            </p>
          ) : (
            <div className="flex flex-col gap-2" style={{ opacity: searching ? 0.5 : 1, transition: "opacity .15s ease" }}>
              {groupedHits.map(({ board, hits }) => (
                <button
                  key={board.id}
                  onClick={() => onOpen(board.id, query.trim())}
                  className={`w-full text-left flex items-center gap-3 p-3 ${R.card} border ${TAP}`}
                  style={{ borderColor: C.line, background: C.surface }}
                >
                  <span className="flex-none w-1.5 self-stretch rounded-full" style={{ background: board.color }} />
                  <div className="flex-1 min-w-0">
                    <p className={`${T.bodyStrong} truncate`} style={{ color: C.text }}>
                      {board.name} · {hits.length} kết quả
                    </p>
                    <p className={`${T.meta} truncate`} style={{ color: C.textSoft }}>
                      {hits[0].snippet || "(ghi chú trống)"}
                    </p>
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>
      ) : (
      <>
      {/* Hàng điều khiển: lọc bên trái, thêm mới và đổi kiểu xem bên phải */}
      <div className="flex-none px-5 pb-3 flex items-center gap-2 relative">
        <button
          onClick={() => setFilterOpen((v) => !v)}
          className={`flex-none h-9 pl-2.5 pr-3 ${R.pill} ${T.bodyStrong} flex items-center gap-1.5`}
          style={
            specialty === "all"
              ? { color: C.textSoft, background: "transparent" }
              : { color: C.primary, background: C.primarySoft }
          }
        >
          {icons.filter()}
          <span className="truncate max-w-[140px]">{filterLabel}</span>
        </button>

        <span className="flex-1" />

        <button
          onClick={() => {
            onCreate()
            tickHaptic()
          }}
          className={`flex-none h-9 pl-3 pr-4 ${R.pill} ${T.bodyStrong} flex items-center gap-1`}
          style={{ background: C.primary, color: "var(--c-on-bright)" }}
        >
          {icons.plus()}
          Mới
        </button>

        <button
          onClick={() => {
            const next: GalleryView = view === "grid" ? "list" : "grid"
            setView(next)
            writeGalleryView(next)
            tickHaptic()
          }}
          aria-label={view === "grid" ? "Xem dạng danh sách" : "Xem dạng lưới"}
          title={view === "grid" ? "Xem dạng danh sách" : "Xem dạng lưới"}
          className="flex-none w-9 h-9 flex items-center justify-center"
          style={{ color: "var(--c-text-soft)" }}
        >
          {view === "grid" ? icons.listView() : icons.gridView()}
        </button>

        {/* Thùng rác. Chỉ hiện khi trong đó CÓ thứ gì — một cái thùng rác rỗng thường trực chỉ tốn
            chỗ và làm người dùng tưởng mình vừa lỡ xoá cái gì đó. */}
        {trashedBoards.length > 0 && (
          <button
            onClick={() => setTrashOpen(true)}
            aria-label={`Thùng rác, ${trashedBoards.length} bảng`}
            title="Thùng rác"
            className={`flex-none h-9 pl-2 pr-2.5 ${R.pill} flex items-center gap-1`}
            style={{ color: C.textSoft, background: "transparent" }}
          >
            {icons.trash()}
            <span className={T.meta}>{trashedBoards.length}</span>
          </button>
        )}

        {filterOpen && (
          <>
            <div className="fixed inset-0 z-30" onClick={() => setFilterOpen(false)} />
            {/* Mọi popover trong bảng vẽ đều mind-pop bung ra từ nút — bảng này (ở danh sách gallery,
                không phải trong MindmapBoard) trước đây hiện tức thì, khác hẳn phần còn lại. */}
            <div
              className={`mind-pop absolute left-5 top-full z-40 w-[210px] ${R.card} border p-1.5 max-h-[320px] overflow-y-auto scroll-ios`}
              style={{ borderColor: C.line, background: C.surface, boxShadow: "0 12px 30px var(--c-shadow)", transformOrigin: "top left" }}
            >
              <FilterRow label="Tất cả" count={boards.length} active={specialty === "all"} onClick={() => pick("all")} />
              {usedSpecialties.map((s) => (
                <FilterRow
                  key={s.id}
                  label={s.name}
                  color={s.color}
                  count={boards.filter((b) => b.specialtyId === s.id).length}
                  active={specialty === s.id}
                  onClick={() => pick(s.id)}
                />
              ))}
              {hasUnassigned && (
                <FilterRow
                  label="Chưa gắn khoa"
                  count={boards.filter((b) => !b.specialtyId).length}
                  active={specialty === "none"}
                  onClick={() => pick("none")}
                />
              )}
            </div>
          </>
        )}
      </div>

      <div className="scroll-ios flex-1 px-5 pb-6">
        {shown.length === 0 ? (
          <p className={`${T.body} text-center mt-10`} style={{ color: C.textSoft }}>
            Chưa có bảng nào trong mục này. Bấm "Mới" để tạo bảng đầu tiên.
          </p>
        ) : view === "grid" ? (
          // key={view} buộc React dựng lại khối này khi đổi view — bố cục trước đây nhảy tức thì
          // giữa lưới/danh sách; remount kích hoạt lại .fade-in cho cảm giác crossfade nhẹ.
          <div key="grid" className="grid grid-cols-2 gap-3 fade-in">
            {shown.map((b) => (
              <BoardCard key={b.id} board={b} previewTick={previewTick} onOpen={(rect) => onOpen(b.id, undefined, rect)} onEdit={() => onEditBoard(b)} />
            ))}
          </div>
        ) : (
          <div key="list" className="flex flex-col gap-2 fade-in">
            {shown.map((b) => (
              <BoardRow key={b.id} board={b} previewTick={previewTick} onOpen={(rect) => onOpen(b.id, undefined, rect)} onEdit={() => onEditBoard(b)} />
            ))}
          </div>
        )}
      </div>

      {trashOpen && (
        <TrashSheet
          boards={trashedBoards}
          onClose={() => setTrashOpen(false)}
          onRestore={onRestoreBoard}
          onPurge={onPurgeBoard}
        />
      )}
      </>
      )}
    </div>
  )
}

// Thùng rác. Bảng ở đây còn nguyên dữ liệu — khôi phục là về đúng chỗ cũ với đúng nội dung cũ.
// Xoá hẳn thì bắt xác nhận hai chạm ngay trên dòng đó: đây là thao tác duy nhất trong toàn bộ màn
// Mindmap thật sự không lấy lại được.
function TrashSheet({
  boards,
  onClose,
  onRestore,
  onPurge,
}: {
  boards: MindBoard[]
  onClose: () => void
  onRestore: (id: string) => void
  onPurge: (id: string) => void
}) {
  const [confirmId, setConfirmId] = useState<string | null>(null)
  return (
    // Trước đây `absolute inset-0` với rounded-t-3xl xuất hiện tức thì — trông như bottom sheet
    // nhưng không có động tác của bottom sheet, cùng lỗi với CalcLogSheet/DisclaimerGate ở màn
    // Dùng thuốc. `.mind-sheet` (đã có sẵn trong index.css) trượt lên từ đáy.
    <div className="absolute inset-0 z-40 flex flex-col fade-in" style={{ background: "var(--c-scrim)" }}>
      <button className="flex-1" onClick={onClose} aria-label="Đóng" />
      <div className="mind-sheet rounded-t-3xl flex flex-col" style={{ background: C.surface, maxHeight: "82%" }}>
        <div className="flex items-center justify-between px-5 pt-4 pb-2">
          <p className={T.bodyStrong} style={{ color: C.text }}>
            Thùng rác · {boards.length}
          </p>
          <button
            onClick={onClose}
            className="w-11 h-11 rounded-full flex items-center justify-center"
            style={{ background: C.lineSoft, color: C.textSoft }}
            aria-label="Đóng"
          >
            {icons.x()}
          </button>
        </div>
        <p className={`${T.meta} px-5 pb-2`} style={{ color: C.textSoft }}>
          Bảng trong đây không hiện ở danh sách nhưng dữ liệu vẫn còn nguyên. App không tự dọn thùng
          rác — xoá hẳn phải do bạn bấm.
        </p>
        <div className="scroll-ios px-5 pb-4 flex flex-col gap-2" style={{ paddingBottom: "var(--nav-pad-bottom)" }}>
          {boards.map((b) => (
            <div key={b.id} className={`p-3 ${R.card} border`} style={{ borderColor: C.line }}>
              <p className={`${T.bodyStrong} truncate`} style={{ color: C.text }}>
                {b.name}
              </p>
              <p className={`${T.meta} mb-2`} style={{ color: C.textSoft }}>
                Dời vào thùng rác {b.deletedAt ? boardWhen(b.deletedAt).toLowerCase() : ""}
              </p>
              <div className="flex gap-2">
                <button
                  onClick={() => onRestore(b.id)}
                  className={`flex-1 h-9 ${R.pill} ${T.bodyStrong} border`}
                  style={{ borderColor: C.primaryLine, color: C.primary, background: C.primarySoft }}
                >
                  Khôi phục
                </button>
                <button
                  onClick={() => {
                    if (confirmId !== b.id) {
                      setConfirmId(b.id)
                      return
                    }
                    onPurge(b.id)
                    setConfirmId(null)
                  }}
                  onBlur={() => setConfirmId(null)}
                  className={`flex-1 h-9 ${R.pill} ${T.bodyStrong} border`}
                  style={
                    confirmId === b.id
                      ? { borderColor: C.dangerIcon, background: C.dangerSoft, color: C.danger }
                      : { borderColor: C.dangerLine, color: C.danger }
                  }
                >
                  {confirmId === b.id ? "Chắc chắn xoá hẳn?" : "Xoá hẳn"}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

function FilterRow({
  label,
  color,
  count,
  active,
  onClick,
}: {
  label: string
  color?: string
  count: number
  active: boolean
  onClick: () => void
}) {
  return (
    <button
      onClick={onClick}
      className={`w-full flex items-center gap-2 px-2.5 py-2 ${R.box} ${T.body}`}
      style={active ? { background: C.primarySoft, color: C.primary } : { color: C.text }}
    >
      <span className="flex-none w-2.5 h-2.5 rounded-full" style={{ background: color ?? C.muted }} />
      <span className="flex-1 text-left truncate">{label}</span>
      <span className={T.meta} style={{ color: active ? C.primary : C.muted }}>
        {count}
      </span>
    </button>
  )
}

// Khung ảnh xem trước dùng chung cho cả thẻ lưới lẫn dòng danh sách — cùng một mặt giấy, cùng một
// cách vẽ, chỉ khác kích thước.
function BoardPreviewFrame({ board, previewTick, className }: { board: MindBoard; previewTick: number; className: string }) {
  return (
    <div
      className={`relative overflow-hidden ${className}`}
      style={{ background: PAPER_BG, border: `1px solid ${C.line}`, borderRadius: 12 }}
    >
      <BoardThumb board={board} tick={previewTick} />
      {/* Vạch màu của bảng ở mép trái — nhận ra bảng bằng màu trước cả khi đọc tên. */}
      <span className="absolute left-0 top-0 bottom-0 w-1" style={{ background: board.color }} />
    </div>
  )
}

// ─── Chuyển cảnh danh sách ↔ bảng (D3) ─────────────────────────────────────────
//
// Đổi cảnh ĐỘT NGỘT giữa một thẻ nhỏ trong lưới và cả một mặt bảng full-screen khiến người dùng mất
// một nhịp để định vị lại — "tôi đang ở đâu". Phóng khung xem trước từ ĐÚNG chỗ vừa chạm lên toàn
// khung (và ngược lại lúc rời bảng) giữ liên tục một MỐC THỊ GIÁC xuyên suốt cú chuyển cảnh.
//
// Đây là một khung ảnh xem trước (BoardPreviewFrame) NỔI ĐÈ LÊN MindmapScreen trong lúc chuyển,
// không phải bảng vẽ thật — bảng thật đã mount/unmount ngay bên dưới nó (tức thời, không đợi hoạt
// ảnh); lớp phủ chỉ có việc CHE cú đổi cảnh đó lại bằng một hình ảnh mượt mắt, và tự dẹp đi khi xong.
interface BoardTransition {
  board: MindBoard
  // Khung BẮT ĐẦU — khung thẻ (mở bảng) hoặc khung cả mặt bảng (rời bảng).
  from: { x: number; y: number; w: number; h: number }
  dir: "enter" | "exit"
}

// Máy đang xin giảm chuyển động (E) — bỏ hẳn lớp phủ phóng to/thu nhỏ, để lại đúng cú đổi cảnh
// mặc định (React tự thay nhánh JSX, không có gì thêm) — "chỉ còn mờ/hiện" theo đúng nghĩa không
// còn chuyển động vị trí/kích thước nào cả, chỉ còn việc nội dung mới xuất hiện.
function prefersReducedMotion(): boolean {
  try {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches
  } catch {
    return false
  }
}

function domRectToBox(r: DOMRect): { x: number; y: number; w: number; h: number } {
  return { x: r.left, y: r.top, w: r.width, h: r.height }
}

function BoardTransitionOverlay({
  transition,
  targetRect,
  onDone,
}: {
  transition: BoardTransition
  // null = đích chưa đo được (đang đợi khung MỚI dựng xong trong DOM) — cứ đứng yên ở `from` tới khi
  // có, không có gì để mà bắt đầu chạy tới.
  targetRect: { x: number; y: number; w: number; h: number } | null
  onDone: () => void
}) {
  const from = transition.from
  // Khung DOM đứng yên ở `from` suốt cả lượt chuyển cảnh — chỉ `transform` (translate + scale) chạy
  // hoạt ảnh. Trước đây animate thẳng left/top/width/height: mỗi khung hình trình duyệt phải tính
  // lại layout rồi vẽ lại toàn bộ SVG bên trong BoardThumb (có thể tới 600 nét) ở một kích thước
  // MỚI — vừa layout vừa paint lặp lại ~17 lần trong 0,28s là đúng lý do hiệu ứng phóng to/thu nhỏ bị
  // sượng. `transform` chỉ tốn compositor (GPU dán lại đúng lớp đã vẽ sẵn ở kích thước `from`, không
  // layout/paint lại), nên mượt bất kể bảng có bao nhiêu nét.
  const [transform, setTransform] = useState("translate(0px, 0px) scale(1, 1)")
  const doneRef = useRef(false)

  useEffect(() => {
    if (!targetRect) return
    // Đợi một nhịp rồi mới đổi (setTimeout, không phải requestAnimationFrame — xem ghi chú ở effect
    // đo `transitionTarget` trong MindmapScreen về lý do): phải để trình duyệt VẼ XONG khung BẮT ĐẦU
    // trước, nếu đổi ngay trong cùng một lượt vẽ thì CSS transition không có "trước" để so, chạy
    // thẳng tới đích luôn, không thấy phóng to/thu nhỏ gì cả.
    const t = setTimeout(() => {
      const dx = targetRect.x - from.x
      const dy = targetRect.y - from.y
      const sx = targetRect.w / from.w
      const sy = targetRect.h / from.h
      setTransform(`translate(${dx}px, ${dy}px) scale(${sx}, ${sy})`)
    }, 20)
    return () => clearTimeout(t)
  }, [targetRect, from])

  // Hết giờ dự phòng — quá thời lượng animation (0.28s) cộng một khoảng dư mà `transitionend` vẫn
  // chưa bắn (tab bị ẩn giữa chừng, hoặc trình duyệt bỏ lỡ sự kiện): tự dẹp lớp phủ, đừng để nó che
  // màn hình MÃI MÃI chỉ vì một hoạt ảnh trang trí trục trặc.
  useEffect(() => {
    const t = setTimeout(() => {
      if (!doneRef.current) {
        doneRef.current = true
        onDone()
      }
    }, 600)
    return () => clearTimeout(t)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return (
    <div
      className="fixed z-50 overflow-hidden"
      style={{
        left: from.x,
        top: from.y,
        width: from.w,
        height: from.h,
        borderRadius: 12,
        transformOrigin: "0 0",
        transform,
        willChange: "transform",
        transition: "transform .28s cubic-bezier(.22,1.1,.36,1)",
        pointerEvents: "none",
      }}
      onTransitionEnd={(e) => {
        if (e.propertyName !== "transform" || doneRef.current) return
        doneRef.current = true
        onDone()
      }}
    >
      <BoardPreviewFrame board={transition.board} previewTick={0} className="w-full h-full" />
    </div>
  )
}

// ─── Nhấn giữ để mở bảng tuỳ chọn ────────────────────────────────────────────
//
// Thay cho nút bút chì trên mỗi thẻ. Nút bút chì ăn mất chỗ của tên bảng (tên dài bị cắt sớm hơn),
// và nó là một đích chạm nhỏ nằm sát ngay cạnh vùng mở bảng — trên điện thoại thì chạm nhầm là
// chuyện thường. Nhấn giữ không tốn chỗ nào và không thể bấm nhầm với chạm thường.
const CARD_HOLD_MS = 450

function useHoldToEdit(onOpen: () => void, onEdit: () => void) {
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
  // Đã bắn sự kiện giữ thì lúc nhấc tay KHÔNG mở bảng nữa — nếu không, giữ xong sẽ vừa hiện bảng
  // tuỳ chọn vừa mở bảng ra sau lưng nó.
  const held = useRef(false)
  const start = useRef({ x: 0, y: 0 })

  const cancel = () => {
    if (timer.current) {
      clearTimeout(timer.current)
      timer.current = null
    }
  }

  return {
    onPointerDown: (e: ReactPointerEvent) => {
      held.current = false
      start.current = { x: e.clientX, y: e.clientY }
      cancel()
      timer.current = setTimeout(() => {
        timer.current = null
        held.current = true
        tickHaptic()
        onEdit()
      }, CARD_HOLD_MS)
    },
    // Nhúc nhích quá ngưỡng là đang CUỘN danh sách, không phải đang giữ.
    onPointerMove: (e: ReactPointerEvent) => {
      if (!timer.current) return
      if (Math.abs(e.clientX - start.current.x) > 8 || Math.abs(e.clientY - start.current.y) > 8) cancel()
    },
    onPointerUp: () => {
      const wasHeld = held.current
      cancel()
      if (!wasHeld) onOpen()
    },
    onPointerCancel: cancel,
    onPointerLeave: cancel,
    // Chặn menu chuột phải trên máy tính: giữ chuột lâu ở đó cũng phải ra bảng tuỳ chọn của app.
    onContextMenu: (e: React.MouseEvent) => e.preventDefault(),
  }
}

function BoardCard({
  board,
  previewTick,
  onOpen,
  onEdit,
}: {
  board: MindBoard
  previewTick: number
  // Nhận khung của chính thẻ lúc chạm — MindmapScreen dùng để phóng khung xem trước lên đúng chỗ
  // vừa chạm khi mở bảng (D3), thay vì đổi cảnh đột ngột.
  onOpen: (rect: DOMRect) => void
  onEdit: () => void
}) {
  const cardRef = useRef<HTMLDivElement>(null)
  const hold = useHoldToEdit(() => onOpen(cardRef.current?.getBoundingClientRect() ?? new DOMRect()), onEdit)
  return (
    <div
      ref={cardRef}
      // Để MindmapScreen dò lại ĐÚNG thẻ này khi phóng khung xem trước NGƯỢC lại (rời bảng về danh
      // sách) — lúc đó chỉ có id bảng trong tay, không có sẵn tham chiếu tới thẻ.
      data-board-id={board.id}
      className={`flex flex-col gap-1.5 ${TAP}`}
      {...hold}
      // Có role="button" + tabIndex nên Tab tới được và trình đọc màn hình đọc là "nút", nhưng
      // trước đây chỉ gắn handler con trỏ — Enter/Space không làm gì cả. Enter/Space giờ mở bảng,
      // giống hành vi mặc định của một <button> thật.
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault()
          onOpen(cardRef.current?.getBoundingClientRect() ?? new DOMRect())
        }
      }}
      aria-label={`Mở bảng ${board.name}`}
      role="button"
      tabIndex={0}
    >
      <BoardPreviewFrame board={board} previewTick={previewTick} className="w-full aspect-[4/3]" />
      <div className="min-w-0">
        <p className={`${T.bodyStrong} leading-snug line-clamp-2`} style={{ color: C.text }}>
          {board.name}
        </p>
        <p className={T.meta} style={{ color: C.textSoft }}>
          {boardWhen(board.updatedAt)}
          <BoardNoteCount board={board} tick={previewTick} />
        </p>
      </div>
    </div>
  )
}

function BoardRow({
  board,
  previewTick,
  onOpen,
  onEdit,
}: {
  board: MindBoard
  previewTick: number
  onOpen: (rect: DOMRect) => void
  onEdit: () => void
}) {
  const spec = board.specialtyId ? SPECIALTIES.find((s) => s.id === board.specialtyId) : undefined
  const rowRef = useRef<HTMLDivElement>(null)
  const hold = useHoldToEdit(() => onOpen(rowRef.current?.getBoundingClientRect() ?? new DOMRect()), onEdit)
  return (
    <div
      ref={rowRef}
      data-board-id={board.id}
      className={`flex items-center gap-3 p-2 ${R.card} border ${TAP}`}
      style={{ borderColor: C.line, background: C.surface }}
      {...hold}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault()
          onOpen(rowRef.current?.getBoundingClientRect() ?? new DOMRect())
        }
      }}
      aria-label={`Mở bảng ${board.name}`}
      role="button"
      tabIndex={0}
    >
      <BoardPreviewFrame board={board} previewTick={previewTick} className="flex-none w-[72px] h-[54px]" />
      <div className="flex-1 min-w-0">
        <p className={`${T.bodyStrong} truncate`} style={{ color: C.text }}>
          {board.name}
        </p>
        <p className={`${T.meta} truncate`} style={{ color: C.textSoft }}>
          {boardWhen(board.updatedAt)}
          {spec ? ` · ${spec.name}` : ""}
          <BoardNoteCount board={board} tick={previewTick} />
        </p>
      </div>
    </div>
  )
}

function MindmapScreen({
  boards,
  activeBoardId,
  onSwitchBoard,
  onCreateBoard,
  onUpdateBoard,
  onDeleteBoard,
  onDuplicateBoard,
  trashedBoards,
  onRestoreBoard,
  onPurgeBoard,
  pendingOpen,
  onConsumePendingOpen,
  ...boardProps
}: {
  data: MindmapData
  loading: boolean
  savedTick: number
  linkTargets: { target: string; label: string; group: string }[]
  onOpenLink: (target: string) => void
  updateNodes: (updater: (nodes: MindNode[]) => MindNode[]) => void
  updateEdges: (updater: (edges: MindEdge[]) => MindEdge[]) => void
  updateStrokes: (updater: (strokes: MindStroke[]) => MindStroke[]) => void
  updateImages: (updater: (images: MindImage[]) => MindImage[]) => void
  replaceAll: (next: MindmapData) => void
  undoStore: { undo: MindmapData[]; redo: MindmapData[] }
  boards: MindBoard[]
  activeBoardId: string
  onSwitchBoard: (id: string) => void
  onCreateBoard: (name: string, color: string, specialtyId?: string) => Promise<string>
  onUpdateBoard: (id: string, patch: Partial<Pick<MindBoard, "name" | "color" | "specialtyId">>) => void
  onDeleteBoard: (id: string) => void
  onDuplicateBoard: (id: string) => Promise<string | null>
  trashedBoards: MindBoard[]
  onRestoreBoard: (id: string) => void
  onPurgeBoard: (id: string) => void
  // Yêu cầu mở một bảng CỤ THỂ đến từ NGOÀI màn này (kết quả Mindmap trong ô tìm chung, hoặc mục
  // "Sơ đồ tư duy" trong màn chuyên khoa) — xem openMindmapNode() ở App(). null = không có yêu cầu
  // nào đang chờ.
  pendingOpen: { boardId: string; query?: string } | null
  onConsumePendingOpen: () => void
}) {
  const [sheetMode, setSheetMode] = useState<"create" | "edit" | null>(null)
  // Bảng đang MỞ. null = đang ở danh sách.
  //
  // Dùng useStickyState (sessionStorage) chứ không phải useState: chuyển sang tab khác là màn này
  // bị gỡ khỏi cây React, state thường mất sạch — quay lại thì rơi về danh sách và phải mở lại đúng
  // bảng đang làm dở. Khung nhìn (kéo/phóng) của từng bảng cũng được nhớ riêng, xem viewKey() trong
  // MindmapBoard.tsx, nên quay lại là thấy ĐÚNG chỗ đang vẽ chứ không chỉ đúng bảng.
  const [openId, setOpenId] = useStickyState<string | null>("mindmap.openBoard", null)
  // Mở TỪ một kết quả tìm xuyên-bảng (MindmapGallery) — truyền tiếp cho MindmapBoard để nó tự mở ô
  // tìm nội bộ với đúng từ khoá này, không phải state sticky (chỉ có ý nghĩa cho ĐÚNG một lần mở).
  const [openQuery, setOpenQuery] = useState<string | undefined>(undefined)
  // Bảng nào đang được sửa tên/màu ở bảng trượt — có thể là bảng trong danh sách chứ không nhất
  // thiết là bảng đang mở.
  const [sheetBoardId, setSheetBoardId] = useState<string | null>(null)
  // Tăng lên mỗi lần đóng một bảng, để ảnh xem trước của bảng vừa sửa được vẽ lại từ dữ liệu mới.
  const [previewTick, setPreviewTick] = useState(0)
  const activeBoard = boards.find((b) => b.id === (sheetBoardId ?? activeBoardId))

  // ─── Chuyển cảnh danh sách ↔ bảng (D3) ────────────────────────────────────
  // `rootRef` đo khung CẢ MÀN HÌNH này — đích lúc mở bảng (enter), điểm xuất phát lúc rời bảng
  // (exit). Không dùng window.innerWidth/Height: có thanh điều hướng dưới nằm NGOÀI component này,
  // full window sẽ lấn qua cả phần đó.
  const rootRef = useRef<HTMLDivElement>(null)
  const [transition, setTransition] = useState<BoardTransition | null>(null)
  const [transitionTarget, setTransitionTarget] = useState<{ x: number; y: number; w: number; h: number } | null>(null)

  useEffect(() => {
    if (!transition) {
      setTransitionTarget(null)
      return
    }
    // Đợi một nhịp: lúc effect này chạy, nhánh JSX mới (bảng vừa mount, hoặc danh sách vừa dựng lại)
    // có thể chưa kịp có kích thước thật trong lượt vẽ đầu tiên.
    //
    // setTimeout, không phải requestAnimationFrame: rAF chỉ chắc chắn chạy khi tab đang thật sự vẽ
    // khung hình (foreground, đang compositing) — tab bị ẩn/thu nhỏ đúng lúc này thì rAF có thể
    // treo vô thời hạn, kẹt luôn lớp phủ che màn hình mãi không tự dẹp. setTimeout luôn chạy qua
    // hàng đợi sự kiện bình thường, không phụ thuộc việc có đang vẽ khung hình hay không.
    const t = setTimeout(() => {
      if (transition.dir === "enter") {
        const r = rootRef.current?.getBoundingClientRect()
        if (r) setTransitionTarget(domRectToBox(r))
        return
      }
      // "exit": đích là khung của ĐÚNG thẻ bảng này trong danh sách vừa dựng lại. Không tìm thấy
      // (bộ lọc chuyên khoa đang ẩn nó, hoặc bảng vừa bị xoá) — dẹp lớp phủ ngay, khỏi treo màn.
      const el = document.querySelector(`[data-board-id="${transition.board.id}"]`)
      if (el) setTransitionTarget(domRectToBox(el.getBoundingClientRect()))
      else setTransition(null)
    }, 30)
    return () => clearTimeout(t)
  }, [transition])

  function finishTransition() {
    setTransition(null)
    setTransitionTarget(null)
  }

  function openBoard(id: string, query: string | undefined, rect?: DOMRect) {
    onSwitchBoard(id)
    setOpenQuery(query)
    const board = boards.find((b) => b.id === id)
    // Chỉ dựng lớp phủ khi mở TỪ MỘT THẺ (có rect) và máy không xin giảm chuyển động — mở từ kết
    // quả tìm xuyên bảng thì không có thẻ nào để phóng lên từ đó.
    if (rect && board && !prefersReducedMotion()) setTransition({ board, from: domRectToBox(rect), dir: "enter" })
    setOpenId(id)
  }

  // Có yêu cầu mở bảng từ NGOÀI màn này (xem khai báo pendingOpen) — tiêu thụ NGAY khi vào màn
  // (cũng chạy đúng một lần lúc mount, vì màn này chỉ tồn tại đúng lúc pendingOpen đã kịp đặt trước
  // đó ở App() rồi mới navigate("mindmap") tới đây). Báo lại đã tiêu thụ xong để App() xoá cờ, nếu
  // không lần SAU quay lại tab Mindmap bằng tay sẽ bị ép mở lại đúng bảng cũ một lần nữa.
  useEffect(() => {
    if (!pendingOpen) return
    openBoard(pendingOpen.boardId, pendingOpen.query)
    onConsumePendingOpen()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pendingOpen])

  function goHome() {
    const board = activeBoard
    const r = rootRef.current?.getBoundingClientRect()
    if (board && r && !prefersReducedMotion()) setTransition({ board, from: domRectToBox(r), dir: "exit" })
    setOpenId(null)
    setSheetBoardId(null)
    // Không mang từ khoá tìm sang lần mở TAY tiếp theo (mở bảng khác, hoặc mở lại đúng bảng này) —
    // chỉ có ý nghĩa cho đúng lượt mở từ kết quả tìm xuyên-bảng.
    setOpenQuery(undefined)
    // Vẽ lại ảnh xem trước: bảng vừa đóng gần như chắc chắn đã khác lúc mở ra.
    setPreviewTick((n) => n + 1)
  }

  return (
    <div ref={rootRef} className="h-full relative overflow-hidden">
      {openId == null ? (
        // ─── Danh sách bảng ───────────────────────────────────────────────
        <>
          <MindmapGallery
            boards={boards}
            previewTick={previewTick}
            trashedBoards={trashedBoards}
            onRestoreBoard={onRestoreBoard}
            onPurgeBoard={onPurgeBoard}
            onOpen={openBoard}
            onCreate={() => {
              setSheetBoardId(null)
              setSheetMode("create")
            }}
            onEditBoard={(b) => {
              setSheetBoardId(b.id)
              setSheetMode("edit")
            }}
          />
          {sheetMode && (
            <BoardEditSheet
              mode={sheetMode}
              board={sheetMode === "edit" ? activeBoard : undefined}
              canDelete={boards.length > 1}
              onClose={() => {
                setSheetMode(null)
                setSheetBoardId(null)
              }}
              onCreate={(name, color, specialtyId) => {
                setSheetMode(null)
                setSheetBoardId(null)
                // Tạo xong mở thẳng vào bảng mới — đó là việc người dùng định làm tiếp.
                void onCreateBoard(name, color, specialtyId).then(setOpenId)
              }}
              onSave={(patch) => {
                if (activeBoard) onUpdateBoard(activeBoard.id, patch)
                setSheetMode(null)
                setSheetBoardId(null)
              }}
              onDelete={() => {
                if (activeBoard) onDeleteBoard(activeBoard.id)
                setSheetMode(null)
                setSheetBoardId(null)
                setPreviewTick((n) => n + 1)
              }}
              onDuplicate={() => {
                const id = activeBoard?.id
                setSheetMode(null)
                setSheetBoardId(null)
                if (id) void onDuplicateBoard(id)
              }}
              onExport={() => {
                // Xuất file nằm ở thanh trên CỦA BẢNG (nó cần nội dung bảng đang mở để vẽ ra ảnh),
                // nên ở đây chỉ mở bảng ra rồi để người dùng chọn PNG/PDF tại đó.
                const id = activeBoard?.id
                setSheetMode(null)
                setSheetBoardId(null)
                if (id) {
                  onSwitchBoard(id)
                  setOpenId(id)
                }
              }}
            />
          )}
        </>
      ) : (
        // ─── Một bảng đang mở ─────────────────────────────────────────────
        // KHÔNG có ScreenHeader ở đây: thanh trên của bảng (nút về danh sách, tên bảng, công tắc
        // Chỉ đọc, xuất file, cài đặt) nằm trong chính MindmapBoard, vì nó điều khiển giấy
        // nền/màu nền/căn chỉnh vốn là state của component đó. Thêm một tiêu đề nữa ở đây là hai
        // thanh chồng nhau, ăn mất chiều cao của mặt vẽ trên màn hình điện thoại.
        <div className="h-full flex flex-col relative">
          <div className="flex-1 overflow-hidden relative">
            {/* key=boardId: đổi bảng phải là một lượt mount MỚI hoàn toàn — thẻ đang chọn/đang sửa,
                lasso đang khoanh... của bảng cũ không có ý nghĩa gì trên bảng khác. Ngăn xếp hoàn
                tác không mất theo vì nó không sống trong component này — xem undoStore ở
                useMindmap.ts. */}
            <MindmapBoard
              key={activeBoardId}
              {...boardProps}
              boardName={activeBoard?.name}
              boardId={activeBoardId}
              initialFindQuery={openQuery}
              onGoHome={goHome}
            />
          </div>
          {/* Không có tấm sửa bảng ở đây: đổi tên/màu/chuyên khoa làm từ DANH SÁCH (nút bút chì trên
              thẻ bảng). Thanh trên của bảng chỉ giữ những việc dùng ngay lúc đang xem/vẽ. */}
        </div>
      )}

      {transition && <BoardTransitionOverlay transition={transition} targetRect={transitionTarget} onDone={finishTransition} />}
    </div>
  )
}

// Tấm trượt lên tạo bảng mới / sửa bảng đang mở (tên, màu-chuyên khoa gắn thẻ, xoá bảng).
// Một dòng việc trong tấm sửa bảng. Gom thành component riêng vì cả ba dòng (nhân bản / xuất / dời
// vào thùng rác) phải cao bằng nhau và cùng một cách bấm — ba khối JSX chép tay là ba chỗ sẽ lệch.
function SheetAction({
  icon,
  label,
  hint,
  danger,
  disabled,
  onClick,
  onBlur,
}: {
  icon: React.ReactNode
  label: string
  hint: string
  danger?: boolean
  disabled?: boolean
  onClick: () => void
  onBlur?: () => void
}) {
  return (
    <button
      onClick={onClick}
      onBlur={onBlur}
      disabled={disabled}
      className="w-full flex items-center gap-3 px-3 py-3 text-left border-b last:border-b-0 disabled:opacity-45"
      style={{ borderColor: C.lineSoft }}
    >
      <span className="flex-none w-5 h-5" style={{ color: danger ? C.danger : C.textSoft }}>
        {icon}
      </span>
      <span className="flex-1 min-w-0">
        <span className={`block ${T.bodyStrong}`} style={{ color: danger ? C.danger : C.text }}>
          {label}
        </span>
        <span className={`block ${T.meta}`} style={{ color: C.textSoft }}>
          {hint}
        </span>
      </span>
    </button>
  )
}

function BoardEditSheet({
  mode,
  board,
  canDelete,
  onClose,
  onCreate,
  onSave,
  onDelete,
  onDuplicate,
  onExport,
}: {
  mode: "create" | "edit"
  board: MindBoard | undefined
  canDelete: boolean
  onClose: () => void
  onCreate: (name: string, color: string, specialtyId?: string) => void
  onSave: (patch: Partial<Pick<MindBoard, "name" | "color" | "specialtyId">>) => void
  onDelete: () => void
  onDuplicate: () => void
  onExport: () => void
}) {
  const [name, setName] = useState(board?.name ?? "")
  const [specialtyId, setSpecialtyId] = useState<string | undefined>(board?.specialtyId)
  const [color, setColor] = useState(board?.color ?? DEFAULT_BOARD_COLOR)
  const [confirmDelete, setConfirmDelete] = useState(false)

  const swatches: { id: string | undefined; name: string; color: string }[] = [
    { id: undefined, name: "Khác", color: "var(--c-text-muted)" },
    ...SPECIALTIES.map((s) => ({ id: s.id, name: s.name, color: s.color })),
  ]

  function pick(sw: { id: string | undefined; color: string }) {
    setSpecialtyId(sw.id)
    setColor(sw.color)
  }

  function submit() {
    const trimmed = name.trim()
    if (!trimmed) return
    if (mode === "create") onCreate(trimmed, color, specialtyId)
    else onSave({ name: trimmed, color, specialtyId })
  }

  return (
    <div className="absolute inset-0 z-40 flex flex-col fade-in" style={{ background: "var(--c-scrim)" }}>
      <button className="flex-1" onClick={onClose} aria-label="Đóng" />
      <div className="mind-sheet rounded-t-3xl flex flex-col" style={{ background: "var(--c-surface)", maxHeight: "82%" }}>
        <div className="flex items-center justify-between px-5 pt-4 pb-2">
          <p className="text-[13px] font-bold text-slate-900">{mode === "create" ? "Bảng mới" : "Sửa bảng"}</p>
          <button onClick={onClose} className="w-11 h-11 rounded-full flex items-center justify-center" style={{ background: "var(--c-line-soft)", color: "var(--c-text-soft)" }} aria-label="Đóng">
            {icons.x()}
          </button>
        </div>
        <div className="scroll-ios px-5 pb-4 space-y-4">
          <div>
            <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Tên bảng</label>
            <input
              autoFocus={mode === "create"}
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="VD: Tim mạch, Thận, ECG…"
              className={FIELD}
              style={FIELD_STYLE}
            />
          </div>
          <div>
            <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Gắn theo chuyên khoa (để đổi màu + icon)</label>
            <div className="grid grid-cols-4 gap-2">
              {swatches.map((sw) => {
                const on = sw.id === specialtyId
                return (
                  <button
                    key={sw.name}
                    onClick={() => pick(sw)}
                    className="flex flex-col items-center gap-1 py-2.5 rounded-xl border"
                    style={on ? { borderColor: sw.color, background: `${sw.color}14` } : { borderColor: "var(--c-line)" }}
                  >
                    <span className="w-5 h-5" style={{ color: sw.color }}>
                      {specialtyIcon(sw.id, "w-5 h-5")}
                    </span>
                    <span className="text-[10.5px] font-medium text-center leading-tight" style={{ color: on ? sw.color : "var(--c-text-soft)" }}>
                      {sw.name}
                    </span>
                  </button>
                )
              })}
            </div>
          </div>

          {/* Việc làm với cả bảng — chỉ có nghĩa khi đang SỬA một bảng đã tồn tại. */}
          {mode === "edit" && (
            <div>
              <label className="text-xs font-semibold text-slate-500 mb-1.5 block">Bảng này</label>
              <div className={`${R.card} border overflow-hidden`} style={{ borderColor: C.line }}>
                <SheetAction icon={icons.copy()} label="Nhân bản" hint="Tạo một bản sao đầy đủ cả nội dung" onClick={onDuplicate} />
                <SheetAction icon={icons.download()} label="Xuất file" hint="Mở bảng rồi chọn PNG hoặc PDF ở thanh trên" onClick={onExport} />
                {/* LUÔN hiện, kể cả khi đang là bảng cuối cùng — lúc đó chỉ mờ đi kèm lý do. Ẩn hẳn
                    thì người dùng chỉ có một bảng sẽ tìm mãi không thấy chỗ xoá và tưởng app thiếu
                    tính năng, thay vì hiểu là app đang giữ lại cho họ ít nhất một bảng để dùng. */}
                <SheetAction
                  icon={icons.trash()}
                  label={
                    !canDelete
                      ? "Dời vào thùng rác"
                      : confirmDelete
                        ? "Chắc chắn dời vào thùng rác?"
                        : "Dời vào thùng rác"
                  }
                  hint={
                    canDelete
                      ? "Bảng còn nguyên trong thùng rác, khôi phục lại được"
                      : "Đây là bảng cuối cùng — tạo thêm một bảng nữa rồi mới dời được bảng này đi"
                  }
                  danger={canDelete}
                  disabled={!canDelete}
                  onClick={() => {
                    if (!confirmDelete) {
                      setConfirmDelete(true)
                      return
                    }
                    onDelete()
                  }}
                  onBlur={() => setConfirmDelete(false)}
                />
              </div>
            </div>
          )}
        </div>
        <div className="flex-none flex gap-2 px-5 pt-2 border-t" style={{ borderColor: "var(--c-line)", paddingBottom: "var(--nav-pad-bottom)" }}>
          <button
            onClick={submit}
            disabled={!name.trim()}
            className="flex-1 py-3 rounded-2xl font-semibold text-[13px] disabled:opacity-50"
            style={{ background: "var(--c-primary)", color: "var(--c-on-bright)" }}
          >
            {mode === "create" ? "Tạo bảng" : "Lưu"}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── Dải "có bản cập nhật" ────────────────────────────────────────────────────
// Từ khi app chạy được offline (public/sw.js), một máy đã cài có thể chạy mãi từ bản đã cache. Với
// app tra liều thì im lặng dùng bảng liều cũ là rủi ro thật — nên có bản mới là phải nói ra.
// Dải mỏng trên đầu trang — xem vì sao cần ở lib/offline.ts (useOnlineStatus). Đặt ở ĐẦU khung app
// (trước mọi màn hình) để hiện được trên MỌI tab, không riêng Trang chủ, và không tranh chỗ với
// UpdateBanner/toast vốn neo ở đáy.
function OfflineBar() {
  const online = useOnlineStatus()
  if (online) return null
  return (
    <div
      className="flex-none fade-in flex items-center justify-center gap-2"
      style={{ height: 30, background: "var(--c-warn-soft)", borderBottom: "1px solid var(--c-warn-line)" }}
    >
      <span className="flex-none rounded-full" style={{ width: 6, height: 6, background: "var(--c-warn-icon)" }} />
      <span className="text-[12px] font-semibold" style={{ color: "var(--c-warn)" }}>
        Đang ngoại tuyến — xem dữ liệu đã lưu trên máy
      </span>
    </div>
  )
}

function UpdateBanner({ offsetBottom }: { offsetBottom: number | string }) {
  const [ready, setReady] = useState(false)
  useEffect(() => {
    const onUpdate = () => setReady(true)
    window.addEventListener(SW_UPDATE_EVENT, onUpdate)
    return () => window.removeEventListener(SW_UPDATE_EVENT, onUpdate)
  }, [])
  if (!ready) return null
  return (
    <div
      className="absolute left-1/2 z-40 flex items-center gap-3 px-4 py-2.5 rounded-full"
      style={{
        bottom: offsetBottom,
        transform: "translateX(-50%)",
        background: "rgba(15,23,42,.94)",
        boxShadow: "0 8px 24px rgba(15,23,42,.28)",
        whiteSpace: "nowrap",
      }}
    >
      <span className="text-[13px] font-semibold text-white">Có bản cập nhật dữ liệu</span>
      <button onClick={applyUpdate} className="text-[13px] font-bold px-3 py-1 rounded-full" style={{ background: "var(--c-surface)", color: "var(--c-primary)" }}>
        Tải lại
      </button>
    </div>
  )
}

// ─── Bottom Navigation ────────────────────────────────────────────────────────

const NAV_ITEMS: { id: Screen; navId?: string; label: string; icon: (active: boolean) => ReactElement }[] = [
  { id: "home", label: "Trang chủ", icon: icons.home },
  { id: "library", label: "Thư viện", icon: icons.library },
  { id: "guideline", label: "Hướng dẫn", icon: icons.guideline },
  { id: "mindmap", label: "Mindmap", icon: icons.mindmap },
  { id: "flashcard", label: "Thẻ ghi nhớ", icon: icons.cards },
]

// ─── App Shell ────────────────────────────────────────────────────────────────

export default function App() {
  // Lối tắt cài trên home screen (public/manifest.json → shortcuts) mở thẳng "/?screen=mixing" —
  // đọc MỘT lần lúc mount để vào thẳng tab đó, bỏ qua Trang chủ. Chỉ nhận giá trị khớp một trong
  // các tab thật của thanh nav dưới, giá trị lạ hoặc thiếu thì rơi về "home" như trước.
  const initialScreen = (): Screen => {
    const s = new URLSearchParams(window.location.search).get("screen")
    return s === "mixing" || s === "library" || s === "mindmap" || s === "flashcard" ? s : "home"
  }
  const [screen, setScreen] = useState<Screen>(initialScreen)
  const [activeTab, setActiveTab] = useState<Screen>(initialScreen)
  const [articleId, setArticleId] = useState<string>("mi")
  const [specialtyId, setSpecialtyId] = useState<string>("cardiology")
  const [viewCustomId, setViewCustomId] = useState<string | null>(null)
  const [viewEcgId, setViewEcgId] = useState<string | null>(null)
  // Tên tính năng đang xem ở màn "Sắp ra mắt" — id truyền qua navigate() khi bấm một thẻ Truy cập
  // nhanh chưa có màn thật.
  const [comingSoonFeature, setComingSoonFeature] = useState<string>("")
  // Bản nháp đang sửa của bài viết tự nhập / bài học ECG — null nghĩa là đang TẠO MỚI. Mang theo cả
  // object (không chỉ id) để màn soạn thảo mở ra với nội dung sẵn có, giống cách sửa thuốc bên dưới.
  const [editArticleDraft, setEditArticleDraft] = useState<Article | null>(null)
  const [editEcgDraft, setEditEcgDraft] = useState<EcgLesson | null>(null)
  // Dải xác nhận ngắn sau khi lưu/xoá — xem showToast bên dưới.
  const [toast, setToast] = useState<string | null>(null)
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  // Chỉ để né chỗ với dải toast — UpdateBanner tự đứng riêng, xem component đó. Trước đây cả hai
  // dải này cùng neo đúng một `bottom`/`z-40`, nên lúc trùng nhau (vừa có bản cập nhật vừa có thao
  // tác vừa lưu) dải này ĐÈ THẲNG lên dải kia thay vì xếp chồng lên nhau.
  const [updateBannerVisible, setUpdateBannerVisible] = useState(false)
  useEffect(() => {
    const onUpdate = () => setUpdateBannerVisible(true)
    window.addEventListener(SW_UPDATE_EVENT, onUpdate)
    return () => window.removeEventListener(SW_UPDATE_EVENT, onUpdate)
  }, [])
  const [editAntibioticDraft, setEditAntibioticDraft] = useState<Antibiotic | null>(null)
  const [editInfusionDraft, setEditInfusionDraft] = useState<{ category: InfusionCategory; drug: InfusionDrug } | null>(null)
  // Nhóm đang được thêm thuốc mới ở màn "addInfusion" — trước đây thông tin này nằm trong chính tên
  // màn hình ("addInotrope", "addVasoactive"...), nên mỗi nhóm mới lại phải thêm một nhánh Screen.
  const [addInfusionCategory, setAddInfusionCategory] = useState<InfusionCategory>("inotrope")
  const [history, setHistory] = useState<Screen[]>([])
  const [pulseKey, setPulseKey] = useState(0)
  // Những bài đã mở đọc, mới nhất trước (lưu trên máy — xem lib/recentReads.ts).
  const [recentReads, setRecentReads] = useState<ReadEntry[]>(loadRecentReads)

  // Các mục người dùng tự nhập — lưu trên máy (localStorage) nên còn nguyên qua các lần mở app.
  // Riêng bài viết: từ khi nội dung có thể chèn ảnh xen giữa các dòng, dữ liệu chuyển sang
  // IndexedDB (dung lượng lớn hơn nhiều localStorage) — bài viết cũ được tự động di trú một lần,
  // xem useIdbCollection.
  const customArticlesCol = useIdbCollection<Article>(IDB_STORES.articles, CUSTOM_COLLECTION_KEYS.articles)
  const customAntibioticsCol = useLocalCollection<Antibiotic>(CUSTOM_COLLECTION_KEYS.antibiotics)
  // Bệnh lý tự thêm — chủ yếu được tạo tự động khi sửa "Chỉ định riêng theo bệnh lý" của một kháng
  // sinh và gõ vào tên bệnh lý chưa có trong danh mục gốc (xem EditAntibioticScreen). `allDiseases`
  // gộp danh mục gốc với bản đã sửa/thêm, dùng thay cho DISEASES ở mọi nơi cần hiển thị hoặc chọn.
  const customDiseasesCol = useLocalCollection<DiseaseEntry>(CUSTOM_COLLECTION_KEYS.diseases)
  const allDiseases = useMemo(() => mergeWithOverrides(DISEASES, customDiseasesCol.items), [customDiseasesCol.items])
  // Mỗi nhóm thuốc truyền một collection, khoá lưu trữ lấy từ data/categories.ts. Danh sách nhóm là
  // hằng số ở cấp module (không đổi giữa các lần vẽ lại) nên số lượng và THỨ TỰ các lời gọi hook ở
  // đây luôn cố định — đúng điều kiện duy nhất mà React yêu cầu.
  const infusionCols: Record<InfusionCategory, ReturnType<typeof useLocalCollection<InfusionDrug>>> = {
    inotrope: useLocalCollection<InfusionDrug>(infusionCategory("inotrope").storageKey),
    vasoactive: useLocalCollection<InfusionDrug>(infusionCategory("vasoactive").storageKey),
    vasodilator: useLocalCollection<InfusionDrug>(infusionCategory("vasodilator").storageKey),
    arrhythmia: useLocalCollection<InfusionDrug>(infusionCategory("arrhythmia").storageKey),
    electrolyte: useLocalCollection<InfusionDrug>(infusionCategory("electrolyte").storageKey),
    sedation: useLocalCollection<InfusionDrug>(infusionCategory("sedation").storageKey),
    neuro: useLocalCollection<InfusionDrug>(infusionCategory("neuro").storageKey),
    other: useLocalCollection<InfusionDrug>(infusionCategory("other").storageKey),
    antidote: useLocalCollection<InfusionDrug>(infusionCategory("antidote").storageKey),
  }
  // Chỉ danh sách mục, dạng tra theo nhóm — thứ mà DungThuocScreen và màn Đồng bộ dữ liệu cần.
  // Không bọc useMemo: đây là phép gom 9 tham chiếu mảng có sẵn, rẻ hơn hẳn việc so sánh 9 phần tử
  // deps, và không có nơi nhận nào phụ thuộc vào việc object này giữ nguyên tham chiếu.
  const customInfusions = Object.fromEntries(INFUSION_CATEGORIES.map((c) => [c.id, infusionCols[c.id].items])) as Record<
    InfusionCategory,
    InfusionDrug[]
  >
  const customFlashcardsCol = useLocalCollection<FlashCard>(CUSTOM_COLLECTION_KEYS.flashcards)
  // Bài học ECG — lưu bằng IndexedDB (không phải localStorage) vì kèm ảnh, xem useIdbCollection.
  const ecgCol = useIdbCollection<EcgLesson>(IDB_STORES.ecgLessons)
  const allEcgLessons = [...ecgCol.items, ...ECG_LESSONS]
  // Sơ đồ tư duy — nhiều bảng (xem lib/boards.ts), mỗi bảng lưu riêng bằng IndexedDB (debounce, xem
  // useMindmap). Nâng lên cấp App() (thay vì để MindmapScreen tự giữ state riêng như trước) để
  // DataSyncScreen đọc/ghi được cùng dữ liệu.
  const {
    boards,
    trashedBoards,
    activeBoardId,
    setActiveBoardId,
    createBoard,
    duplicateBoard,
    updateBoard,
    trashBoard,
    restoreBoard,
    purgeBoard,
    upsertBoardLocal,
  } = useBoards()
  const mindmap = useMindmap(activeBoardId)
  // Mở MỘT bảng Mindmap CỤ THỂ (kèm sẵn từ khoá tìm) TỪ NGOÀI màn Mindmap — kết quả tìm kiếm chung
  // (SearchScreen) hoặc mục "Sơ đồ tư duy" trong Thư viện theo chuyên khoa (SpecialtyScreen) đều đi
  // qua đây. MindmapScreen tự đọc giá trị này lúc mount/đổi và gọi hàm mở bảng nội bộ của nó rồi báo
  // lại đã tiêu thụ xong (setPendingMindmapOpen(null)) — không đặt openId/openQuery thẳng từ đây vì
  // hai state đó thuộc về MindmapScreen (sessionStorage-backed, xem ghi chú ở đó).
  const [pendingMindmapOpen, setPendingMindmapOpen] = useState<{ boardId: string; query?: string } | null>(null)

  // Nhắc sao lưu — trước đây chỉ hiện khi đang MỞ một bảng Sơ đồ tư duy có nội dung (đặt trong
  // MindmapScreen), nên người chỉ dùng ECG/thẻ ghi nhớ/bài viết tự nhập, không đụng tới Sơ đồ tư duy,
  // không bao giờ thấy lời nhắc dù dữ liệu tự nhập của họ cũng chỉ nằm trên máy này. Nâng lên cấp
  // App() và tính theo TẤT CẢ mục tự nhập (không chỉ Sơ đồ tư duy) để hiện được ở bất cứ tab nào.
  const hasCustomContent =
    customArticlesCol.items.length > 0 ||
    customAntibioticsCol.items.length > 0 ||
    customDiseasesCol.items.length > 0 ||
    INFUSION_CATEGORIES.some((c) => infusionCols[c.id].items.length > 0) ||
    ecgCol.items.length > 0 ||
    customFlashcardsCol.items.length > 0 ||
    mindmap.data.nodes.length > 1 ||
    (mindmap.data.strokes?.length ?? 0) > 0 ||
    (mindmap.data.images?.length ?? 0) > 0
  const [showBackupReminder, setShowBackupReminder] = useState(false)
  useEffect(() => {
    if (customArticlesCol.loading || ecgCol.loading || mindmap.loading) return
    // Công thức pha đọc thẳng từ localStorage (không phải state React) — xem lib/wardRecipes.ts.
    const wardRecipeCount = Object.values(loadWardRecipes()).reduce((n, list) => n + list.length, 0)
    if (hasCustomContent || wardRecipeCount > 0) setShowBackupReminder(shouldRemindBackup())
  }, [customArticlesCol.loading, ecgCol.loading, mindmap.loading, hasCustomContent])

  const NON_TAB_SCREENS: Screen[] = [
    "article",
    "specialty",
    "addEntry",
    "search",
    "customEntry",
    "addAntibiotic",
    "addInfusion",
    "editAntibiotic",
    "editInfusion",
    "dataSync",
    "ecg",
    "ecgDetail",
    "addEcg",
    "addFlashcard",
    "comingSoon",
  ]

  function navigate(s: Screen, id?: string) {
    // Mở một bài để đọc = ghi vào "Đã đọc gần đây". Đặt ngay tại đây (chỗ duy nhất mọi đường dẫn tới
    // ba màn hình đọc bài đều đi qua: bấm thẻ, tìm kiếm, mở liên kết trong bài) nên không có lối vào
    // nào bị bỏ sót.
    if (s === "article" && id) {
      setArticleId(id)
      setRecentReads(recordRead("article", id))
    }
    if (s === "specialty" && id) setSpecialtyId(id)
    if (s === "comingSoon" && id) setComingSoonFeature(id)
    if (s === "customEntry" && id) {
      setViewCustomId(id)
      setRecentReads(recordRead("custom", id))
    }
    if (s === "ecgDetail" && id) {
      setViewEcgId(id)
      setRecentReads(recordRead("ecg", id))
    }
    // Vào màn soạn thảo qua nút "+" luôn là TẠO MỚI — xoá bản nháp đang sửa (nếu có) để không mở
    // nhầm nội dung của lần sửa trước. Muốn sửa thì đi qua goToEditArticle/goToEditEcg.
    if (s === "addEntry") setEditArticleDraft(null)
    if (s === "addEcg") setEditEcgDraft(null)
    if (!NON_TAB_SCREENS.includes(s)) setActiveTab(s)
    setHistory((h) => [...h, screen])
    setScreen(s)
  }

  // Mở tab Mindmap thẳng vào MỘT bảng cụ thể (kèm từ khoá tìm nếu có) — dùng cho kết quả Mindmap ở
  // ô tìm kiếm chung và mục "Sơ đồ tư duy" trong màn chuyên khoa (SpecialtyScreen). `navigate("mindmap")`
  // chỉ chuyển TAB, còn bảng nào mở ra là việc của pendingMindmapOpen (MindmapScreen tự đọc và tiêu
  // thụ — xem ghi chú ở khai báo state).
  function openMindmapNode(boardId: string, query?: string) {
    setPendingMindmapOpen({ boardId, query })
    navigate("mindmap")
  }

  // Sửa thuốc trong "Dùng thuốc": khác các mục khác (tra theo id từ một danh sách có sẵn ở đây),
  // thuốc cần sửa có thể đến từ dữ liệu dựng sẵn (không nằm trong bất kỳ collection tự nhập nào) —
  // nên phải mang theo cả object thuốc, không chỉ id, vì vậy dùng hàm điều hướng riêng thay vì
  // `navigate()` (chỉ nhận id dạng string).
  function goToEditAntibiotic(drug: Antibiotic) {
    setEditAntibioticDraft(drug)
    setHistory((h) => [...h, screen])
    setScreen("editAntibiotic")
  }

  function goToEditInfusion(category: InfusionCategory, drug: InfusionDrug) {
    setEditInfusionDraft({ category, drug })
    setHistory((h) => [...h, screen])
    setScreen("editInfusion")
  }

  // Mở màn thêm thuốc mới cho một nhóm — nhóm đi kèm trong state chứ không nằm trong tên màn hình.
  function goToAddInfusion(category: InfusionCategory) {
    setAddInfusionCategory(category)
    navigate("addInfusion")
  }

  // "Đã đọc gần đây" cho Trang chủ: tra tiêu đề từ dữ liệu THẬT theo id đã lưu, nên bài đổi tên thì
  // dòng này đổi theo, bài đã xoá thì rơi ra khỏi danh sách thay vì để lại một dòng bấm vào không có
  // gì. Lấy 4 mục — vừa một khoảng cuối trang chủ, không phải cuộn thêm.
  const recentReadItems = useMemo<RecentReadItem[]>(() => {
    const out: RecentReadItem[] = []
    for (const e of recentReads) {
      if (out.length >= 4) break
      if (e.kind === "article") {
        const a = ARTICLES.find((x) => x.id === e.id)
        if (a) out.push({ key: `article:${a.id}`, id: a.id, title: a.title, at: e.at, screen: "article", tag: a.specialty })
      } else if (e.kind === "custom") {
        const a = customArticlesCol.items.find((x) => x.id === e.id)
        if (a) out.push({ key: `custom:${a.id}`, id: a.id, title: a.title, at: e.at, screen: "customEntry", tag: "Tự nhập" })
      } else {
        const l = allEcgLessons.find((x) => x.id === e.id)
        if (l) out.push({ key: `ecg:${l.id}`, id: l.id, title: l.title, at: e.at, screen: "ecgDetail", tag: "ECG" })
      }
    }
    return out
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [recentReads, customArticlesCol.items, ecgCol.items])

  // Danh sách mọi bài có thể chèn liên kết tới, dùng cho trình soạn thảo. `target` mã hoá luôn loại
  // màn hình cần mở ("article" = bài dựng sẵn, "custom" = bài tự nhập, "ecg" = bài học ECG) nên khi
  // bấm vào liên kết chỉ cần đọc chuỗi là biết đi đâu, không phải tra ngược nhiều danh sách.
  const linkTargets = useMemo(
    () => [
      ...ARTICLES.map((a) => ({ target: `article:${a.id}`, label: a.title, group: a.specialty })),
      ...customArticlesCol.items.map((a) => ({ target: `custom:${a.id}`, label: a.title, group: "Tự nhập" })),
      ...allEcgLessons.map((l) => ({ target: `ecg:${l.id}`, label: l.title, group: "ECG" })),
    ],
    [customArticlesCol.items, allEcgLessons],
  )

  // Mở một liên kết trong bài. Id không còn tồn tại (bài đã bị xoá sau khi chèn liên kết) thì bỏ
  // qua, không điều hướng tới màn trống.
  function openLinkTarget(target: string) {
    const sep = target.indexOf(":")
    if (sep < 0) return
    const kind = target.slice(0, sep)
    const id = target.slice(sep + 1)
    if (kind === "article" && ARTICLES.some((a) => a.id === id)) navigate("article", id)
    else if (kind === "custom" && customArticlesCol.items.some((a) => a.id === id)) navigate("customEntry", id)
    else if (kind === "ecg" && allEcgLessons.some((l) => l.id === id)) navigate("ecgDetail", id)
  }

  // Hiện một dải xác nhận ngắn ở đáy màn hình rồi tự tắt. Kèm một nhịp rung nhẹ: hai tín hiệu này
  // cho biết việc vừa làm đã xong thật, thay vì chỉ thấy màn hình đổi rồi tự hỏi "đã lưu chưa".
  function showToast(message: string) {
    setToast(message)
    tickHaptic()
    if (toastTimer.current) clearTimeout(toastTimer.current)
    toastTimer.current = setTimeout(() => setToast(null), 1900)
  }

  useEffect(() => {
    return () => {
      if (toastTimer.current) clearTimeout(toastTimer.current)
    }
  }, [])

  function goToEditArticle(a: Article) {
    setEditArticleDraft(a)
    setHistory((h) => [...h, screen])
    setScreen("addEntry")
  }

  function goToEditEcg(l: EcgLesson) {
    setEditEcgDraft(l)
    setHistory((h) => [...h, screen])
    setScreen("addEcg")
  }

  function handleSaveEntry(a: Article) {
    // Sửa: ghi đè đúng mục rồi quay lại màn đang xem. Tạo mới: về Trang chủ để thấy mục vừa thêm.
    if (editArticleDraft) {
      customArticlesCol.update(a)
      showToast("Đã lưu thay đổi")
      goBack()
      return
    }
    customArticlesCol.add(a)
    showToast("Đã lưu bài mới")
    setActiveTab("home")
    setHistory((h) => [...h, screen])
    setScreen("home")
  }

  function handleDeleteArticle(id: string) {
    customArticlesCol.remove(id)
    // Bỏ luôn khỏi "Đã đọc gần đây": bài không còn thì không được để lại một dòng bấm vào không mở
    // được gì. (Danh sách vẫn tự lọc khi hiển thị, đây là dọn sạch ngay cả trong bộ nhớ.)
    setRecentReads(forgetRead("custom", id))
    showToast("Đã xoá mục")
    goBack()
  }

  function handleSaveAntibiotic(a: Antibiotic, newDiseases: DiseaseEntry[] = []) {
    newDiseases.forEach((d) => customDiseasesCol.add(d))
    customAntibioticsCol.update(a)
    showToast("Đã lưu kháng sinh")
    goBack()
  }

  // Thêm mới và sửa đều ghi vào đúng collection của nhóm — không còn một hàm lưu riêng cho từng
  // nhóm (trước đây là 5 hàm giống hệt nhau cộng một `switch` 5 nhánh, tức là thêm nhóm mới phải
  // nhớ sửa đúng cả hai chỗ).
  function handleSaveInfusion(category: InfusionCategory, d: InfusionDrug) {
    infusionCols[category].update(d)
    goBack()
  }

  function handleSaveEcg(l: EcgLesson) {
    if (editEcgDraft) ecgCol.update(l)
    else ecgCol.add(l)
    showToast(editEcgDraft ? "Đã lưu thay đổi" : "Đã lưu bài học ECG")
    goBack()
  }

  function handleDeleteEcg(id: string) {
    ecgCol.remove(id)
    setRecentReads(forgetRead("ecg", id))
    showToast("Đã xoá bài học")
    goBack()
  }

  function handleSaveFlashcard(c: FlashCard) {
    customFlashcardsCol.add(c)
    showToast("Đã thêm thẻ ghi nhớ")
    goBack()
  }

  // Nhập mỗi bảng Sơ đồ tư duy trong file vào ĐÚNG bảng cùng id trên máy (tạo bảng mới nếu id đó
  // chưa từng có). Bảng đang mở gộp qua state đang chạy (mindmap.importMerge) để giao diện cập nhật
  // ngay; các bảng khác không cần tải lên bộ nhớ chỉ để nhập — đọc/gộp/ghi thẳng trong IndexedDB.
  async function handleImportData(data: {
    articles: Article[]
    antibiotics: Antibiotic[]
    diseases: DiseaseEntry[]
    // Thuốc truyền tự nhập, gom theo nhóm — khoá của từng nhóm trong file sao lưu là
    // `backupKey` khai trong data/categories.ts (giữ nguyên tên cũ để file xuất từ bản trước vẫn
    // nhập lại được).
    infusions: Record<InfusionCategory, InfusionDrug[]>
    ecgLessons: EcgLesson[]
    flashcards: FlashCard[]
    mindmapBoards: { board: MindBoard; mindmap: MindmapData }[]
    wardRecipes: WardRecipe[]
  }) {
    if (data.articles.length) customArticlesCol.upsertMany(data.articles)
    if (data.antibiotics.length) customAntibioticsCol.upsertMany(data.antibiotics)
    if (data.diseases.length) customDiseasesCol.upsertMany(data.diseases)
    INFUSION_CATEGORIES.forEach((c) => {
      const list = data.infusions[c.id]
      if (list?.length) infusionCols[c.id].upsertMany(list)
    })
    if (data.ecgLessons.length) ecgCol.upsertMany(data.ecgLessons)
    if (data.flashcards.length) customFlashcardsCol.upsertMany(data.flashcards)
    if (data.wardRecipes.length) importWardRecipes(data.wardRecipes)
    for (const entry of data.mindmapBoards) {
      const existsLocally = boards.some((b) => b.id === entry.board.id)
      if (entry.board.id === activeBoardId) {
        mindmap.importMerge(entry.mindmap)
        if (!existsLocally) upsertBoardLocal(entry.board)
      } else {
        const current = await loadMindmap(entry.board.id)
        await saveMindmap(entry.board.id, mergeMindmaps(current, entry.mindmap))
        if (!existsLocally) upsertBoardLocal(entry.board)
      }
    }
  }

  // Hoàn tác một lần nhập file: thay HẲN từng bảng bằng đúng snapshot chụp trước lúc nhập (khác
  // `handleImportData` — gộp theo id, không xoá mục file thêm mới). Không đụng tới sơ đồ tư duy, xem
  // lý do ở khai báo `SyncSnapshot` cạnh DataSyncScreen.
  function handleRestoreSnapshot(snapshot: {
    articles: Article[]
    antibiotics: Antibiotic[]
    diseases: DiseaseEntry[]
    infusions: Record<InfusionCategory, InfusionDrug[]>
    ecgLessons: EcgLesson[]
    flashcards: FlashCard[]
    wardRecipes: WardRecipe[]
  }) {
    customArticlesCol.replaceAll(snapshot.articles)
    customAntibioticsCol.replaceAll(snapshot.antibiotics)
    customDiseasesCol.replaceAll(snapshot.diseases)
    INFUSION_CATEGORIES.forEach((c) => infusionCols[c.id].replaceAll(snapshot.infusions[c.id] ?? []))
    ecgCol.replaceAll(snapshot.ecgLessons)
    customFlashcardsCol.replaceAll(snapshot.flashcards)
    // Chỉ có state cục bộ của DungThuocScreen đọc danh sách này — màn đó đã unmount lúc "Đồng bộ dữ
    // liệu" đang mở nên không cần đồng bộ state ở đây, chỉ cần ghi đúng xuống localStorage; lần sau
    // mở lại "Dùng thuốc" nó tự đọc lại từ đầu bằng loadWardRecipes().
    replaceAllWardRecipes(snapshot.wardRecipes)
  }

  function jumpTo(id: string, isFinal: boolean) {
    if (id === "home") {
      if (screen !== "home") {
        setHistory((h) => [...h, screen])
        setScreen("home")
      }
      setActiveTab("home")
      if (isFinal) setPulseKey((k) => k + 1)
      return
    }
    setSpecialtyId(id)
    if (screen !== "specialty") {
      setHistory((h) => [...h, screen])
      setScreen("specialty")
    }
    if (isFinal) setPulseKey((k) => k + 1)
  }

  function goBack() {
    const prev = history[history.length - 1]
    if (prev) {
      setHistory((h) => h.slice(0, -1))
      setScreen(prev)
      if (!NON_TAB_SCREENS.includes(prev)) setActiveTab(prev)
    }
  }

  const isDetailScreen = NON_TAB_SCREENS.includes(screen)

  return (
    <div
      // `body` (index.css) đã tự ghim đúng khít khung nhìn thật bằng `position: fixed; inset: 0`.
      // Trước đây div này CŨNG tự `fixed inset-0` — tức là WebKit phải tính "khung nhìn" một lần
      // NỮA, độc lập với body. Trên máy thật, khi chạy như PWA cài ra màn hình chính, hai phép
      // tính đó đôi khi lệch nhau vài chục pixel: div này kết thúc SỚM hơn body một khoảng, để lộ
      // đúng màu nền của body phía dưới — chính là dải tối dưới thanh nav mà ảnh test cho thấy, và
      // vì vậy thanh nav (nằm trong div này) cũng dừng lại trước khi chạm đáy thật.
      // Sửa: cho div này ăn theo khung của body luôn (absolute + inset-0 lấy body — phần tử
      // position:fixed gần nhất — làm containing block) thay vì tự đo lại từ đầu. Chỉ còn MỘT nơi
      // duy nhất tính "viewport" ra sao, nên không thể vênh nhau nữa.
      className="absolute inset-0 flex flex-col overflow-hidden"
      style={{
        background: "var(--c-surface)",
      }}
    >
        {/* Chừa chỗ cho tai thỏ / Dynamic Island. */}
        <div className="flex-none" style={{ height: "calc(var(--safe-top) + 6px)" }} />

        <OfflineBar />

        {/* Cụm nút nổi góc trên phải. Gom nút chủ đề và nút chọn chuyên khoa vào CÙNG một hàng
            flex thay vì để mỗi cái tự neo tuyệt đối: trước đây nút chuyên khoa neo `right: 18` và
            phủ z-50 lên đúng chỗ nút chủ đề nằm trong header Trang chủ — đo được chồng nhau 60px,
            tức là nút chủ đề bị che kín hoàn toàn. Nằm chung một hàng flex thì khoảng cách do
            `gap` quyết định, không cách nào đè lên nhau, và cả hai luôn thẳng một hàng ngang. */}
        {(screen === "home" || screen === "specialty") && (
          <div
            className="absolute z-50 flex items-center gap-2"
            style={{ top: "calc(var(--safe-top) + 36px)", right: 18, transform: "translateY(-50%)" }}
          >
            {screen === "home" && <ThemeToggle />}
            <SpecialtyPicker onSelect={jumpTo} currentId={screen === "home" ? "home" : specialtyId} />
          </div>
        )}

        {/* Vùng nội dung chiếm hết chiều cao còn lại SAU khi trừ thanh nav — nội dung dừng hẳn
            phía trên thanh nav, không thẻ nào bị cắt ngang. */}
        {/* Landmark <main>: trước đây toàn trang không có landmark ngữ nghĩa nào, trình đọc màn
            hình không có cách "nhảy" qua phần đầu (disclaimer, khung bệnh nhân...) tới thẳng nội
            dung chính. Đổi thẳng thẻ, không đổi class/style — main không có style mặc định khác
            div nên an toàn với toàn bộ layout đang có. */}
        <main className={`flex-1 overflow-hidden${isDetailScreen ? "" : " has-nav"}`}>
          {screen === "home" && <HomeScreen onNavigate={navigate} ecgCount={allEcgLessons.length} recentReads={recentReadItems} />}
          {screen === "library" && <LibraryScreen onNavigate={navigate} customArticles={customArticlesCol.items} />}
          {screen === "search" && (
            <SearchScreen
              onNavigate={navigate}
              onBack={goBack}
              customArticles={customArticlesCol.items}
              customFlashcards={customFlashcardsCol.items}
              boards={boards}
              onOpenMindmapNode={openMindmapNode}
              ecgLessons={allEcgLessons}
            />
          )}
          {screen === "mindmap" && (
            <MindmapScreen
              data={mindmap.data}
              loading={mindmap.loading}
              savedTick={mindmap.savedTick}
              linkTargets={linkTargets}
              onOpenLink={openLinkTarget}
              updateNodes={mindmap.updateNodes}
              updateEdges={mindmap.updateEdges}
              updateStrokes={mindmap.updateStrokes}
              updateImages={mindmap.updateImages}
              replaceAll={mindmap.replaceAll}
              undoStore={mindmap.undoStore}
              boards={boards}
              activeBoardId={activeBoardId}
              onSwitchBoard={setActiveBoardId}
              // Trả lại id bảng vừa tạo để màn Mindmap mở thẳng vào đó — tạo bảng xong mà vẫn đứng
              // ở danh sách thì lần nào cũng phải chạm thêm một cái nữa vào đúng thứ mình vừa tạo.
              onCreateBoard={(name, color, specialtyId) => createBoard(name, color, specialtyId).then((b) => b.id)}
              onUpdateBoard={updateBoard}
              onDeleteBoard={(id) => void trashBoard(id)}
              onDuplicateBoard={(id) => duplicateBoard(id).then((b) => b?.id ?? null)}
              trashedBoards={trashedBoards}
              onRestoreBoard={(id) => void restoreBoard(id)}
              onPurgeBoard={(id) => void purgeBoard(id)}
              pendingOpen={pendingMindmapOpen}
              onConsumePendingOpen={() => setPendingMindmapOpen(null)}
            />
          )}
          {/* FlashcardScreen hoãn lại — UI hiện tại còn lỗi, đưa "sắp ra mắt" thay vì để người dùng
              thấy một tab lỗi tùm lum. Vẫn giữ nguyên tab dưới thanh nav (không phải NON_TAB_SCREENS)
              để không phá cấu trúc điều hướng — chỉ đổi nội dung bên trong. */}
          {screen === "flashcard" && <ComingSoonScreen feature="Thẻ ghi nhớ" />}
          {screen === "guideline" && <ComingSoonScreen feature="Hướng dẫn" />}
          {screen === "article" && <ArticleScreen articleId={articleId} onBack={goBack} />}
          {screen === "specialty" && (
            <SpecialtyScreen
              specialtyId={specialtyId}
              pulseKey={pulseKey}
              customArticles={customArticlesCol.items}
              customFlashcards={customFlashcardsCol.items}
              boards={boards}
              onOpenMindmapBoard={(boardId) => openMindmapNode(boardId)}
              onBack={goBack}
              onNavigate={navigate}
            />
          )}
          {screen === "addEntry" && (
            <AddEntryScreen key={editArticleDraft?.id ?? "new"} initial={editArticleDraft ?? undefined} linkTargets={linkTargets} onSave={handleSaveEntry} onBack={goBack} />
          )}
          {screen === "mixing" && (
            <DungThuocScreen
              customAntibiotics={customAntibioticsCol.items}
              diseases={allDiseases}
              customInfusions={customInfusions}
              onAddAntibiotic={() => navigate("addAntibiotic")}
              onAddInfusion={goToAddInfusion}
              onEditAntibiotic={goToEditAntibiotic}
              onEditInfusion={goToEditInfusion}
              // Xoá thuốc tự nhập thì công thức pha đã lưu riêng cho nó (nếu có) cũng phải xoá theo —
              // không thì công thức đó thành mồ côi, không thuốc nào tham chiếu tới nhưng vẫn nằm
              // mãi trên máy và trong mọi lần xuất file sao lưu sau này.
              onDeleteAntibiotic={(id) => {
                clearWardRecipesForDrug(id)
                customAntibioticsCol.remove(id)
              }}
              onDeleteInfusion={(category, id) => {
                clearWardRecipesForDrug(id)
                infusionCols[category].remove(id)
              }}
            />
          )}
          {screen === "addAntibiotic" && <AddAntibioticScreen diseases={allDiseases} onSave={handleSaveAntibiotic} onBack={goBack} />}
          {screen === "addInfusion" && (
            <AddInfusionScreen
              key={addInfusionCategory}
              category={addInfusionCategory}
              diseases={allDiseases}
              onSave={(d) => handleSaveInfusion(addInfusionCategory, d)}
              onBack={goBack}
            />
          )}
          {screen === "editAntibiotic" &&
            (editAntibioticDraft ? (
              <EditAntibioticScreen drug={editAntibioticDraft} diseases={allDiseases} onSave={handleSaveAntibiotic} onBack={goBack} />
            ) : (
              <div className="h-full flex flex-col items-center justify-center gap-3 px-5">
                <p className="text-sm text-slate-500">Không tìm thấy thuốc cần sửa.</p>
                <button onClick={goBack} className="text-sm font-semibold" style={{ color: "var(--c-primary)" }}>
                  Quay lại
                </button>
              </div>
            ))}
          {screen === "editInfusion" &&
            (editInfusionDraft ? (
              <AddInfusionScreen
                category={editInfusionDraft.category}
                initial={editInfusionDraft.drug}
                diseases={allDiseases}
                onSave={(d) => handleSaveInfusion(editInfusionDraft.category, d)}
                onBack={goBack}
              />
            ) : (
              <div className="h-full flex flex-col items-center justify-center gap-3 px-5">
                <p className="text-sm text-slate-500">Không tìm thấy thuốc cần sửa.</p>
                <button onClick={goBack} className="text-sm font-semibold" style={{ color: "var(--c-primary)" }}>
                  Quay lại
                </button>
              </div>
            ))}
          {screen === "dataSync" && (
            <DataSyncScreen
              customArticles={customArticlesCol.items}
              customAntibiotics={customAntibioticsCol.items}
              customDiseases={customDiseasesCol.items}
              customInfusions={customInfusions}
              customEcgLessons={ecgCol.items}
              customFlashcards={customFlashcardsCol.items}
              boards={boards}
              activeBoardId={activeBoardId}
              onImport={handleImportData}
              onRestoreSnapshot={handleRestoreSnapshot}
              onBackupDone={() => setShowBackupReminder(false)}
              onBack={goBack}
            />
          )}
          {screen === "customEntry" && (
            <CustomEntryScreen
              article={customArticlesCol.items.find((a) => a.id === viewCustomId)}
              relatedArticles={customArticlesCol.items.filter(
                (a) => a.specialty === customArticlesCol.items.find((x) => x.id === viewCustomId)?.specialty,
              )}
              onEdit={goToEditArticle}
              onDelete={handleDeleteArticle}
              onOpenLink={openLinkTarget}
              onOpenArticle={(a) => navigate("customEntry", a.id)}
              onBack={goBack}
            />
          )}
          {screen === "ecg" && <EcgScreen lessons={allEcgLessons} onNavigate={navigate} onBack={goBack} />}
          {screen === "ecgDetail" && (
            <EcgDetailScreen
              lesson={allEcgLessons.find((l) => l.id === viewEcgId)}
              onEdit={goToEditEcg}
              onDelete={handleDeleteEcg}
              onOpenLink={openLinkTarget}
              onBack={goBack}
            />
          )}
          {screen === "addEcg" && (
            <AddEcgScreen key={editEcgDraft?.id ?? "new"} initial={editEcgDraft ?? undefined} linkTargets={linkTargets} onSave={handleSaveEcg} onBack={goBack} />
          )}
          {screen === "addFlashcard" && <AddFlashcardScreen onSave={handleSaveFlashcard} onBack={goBack} />}
          {screen === "comingSoon" && <ComingSoonScreen feature={comingSoonFeature} onBack={goBack} />}
        </main>

        {/* Thanh điều hướng dưới. Mặt nền XÁM NHẠT (không phải trắng như nền trang) và kéo liền
            xuống hết vùng thanh gạt Home: đây là điểm mấu chốt của lỗi "dải trắng dưới thanh nav"
            trên iPhone. Khoảng chừa cho thanh gạt vẫn phải có (không được đặt nút bấm vào đó),
            nhưng khi nó cùng màu trắng với nền trang thì nhìn thành một khoảng trống thừa; tô khác
            màu một chút là cả dải đó đọc thành phần thân của thanh nav, liền tới cạnh máy. */}
        {!isDetailScreen && (
          <nav
            className="flex-none"
            aria-label="Điều hướng chính"
            style={{
              background: "var(--c-nav-bg)",
              backdropFilter: "blur(20px) saturate(1.8)",
              WebkitBackdropFilter: "blur(20px) saturate(1.8)",
              borderTop: "1px solid var(--c-nav-border)",
              // Phần phủ lên vùng thanh gạt Home: chỉ là nền, không đặt nút bấm vào đây.
              paddingBottom: "var(--nav-pad-bottom)",
            }}
          >
            <div className="flex items-stretch" style={{ height: "var(--nav-body-h)" }}>
              {NAV_ITEMS.map(({ id, label, icon, navId }) => {
                const isActive = activeTab === id
                return (
                  // flex-1: mỗi mục chiếm đúng 1/5 bề ngang nên vùng chạm rộng hơn hẳn so với việc
                  // chỉ đệm quanh chữ — ngón cái bấm hụt ít hơn, nhất là 2 mục ngoài rìa.
                  <button
                    key={id}
                    onClick={() => navigate(id, navId)}
                    aria-current={isActive ? "page" : undefined}
                    className="nav-press flex-1 flex flex-col items-center justify-center gap-1"
                    // Mục chưa chọn dùng --c-text-muted chứ không phải --c-muted: nhãn nav chỉ cao
                    // 10px nên phải đạt ngưỡng tương phản 4.5:1 của chữ nhỏ. Đo trên nền thanh nav
                    // bản tối, --c-muted chỉ được 4.33:1 (trượt), --c-text-muted đạt 5.8:1.
                    style={{ color: isActive ? "var(--c-primary)" : "var(--c-text-muted)", transition: "color .2s ease" }}
                  >
                    <span
                      className="flex items-center justify-center h-8 rounded-full"
                      style={{
                        width: isActive ? 58 : 44,
                        // Viên nền của mục đang chọn đọc từ biến chủ đề. Mã cứng #e0edff cũ là một
                        // viên xanh nhạt gần trắng — trên nền tối nó sáng chói hơn cả icon bên trong.
                        background: isActive ? "var(--c-nav-active-bg)" : "transparent",
                        transition: "width .28s cubic-bezier(.34,1.4,.64,1), background-color .2s ease",
                      }}
                    >
                      {icon(isActive)}
                    </span>
                    <span
                      className="text-[10px] leading-none"
                      style={{ fontWeight: isActive ? 700 : 500, transition: "font-weight .2s ease" }}
                    >
                      {label}
                    </span>
                  </button>
                )
              })}
            </div>
          </nav>
        )}

        {/* Ở màn chi tiết KHÔNG có thanh nav để tự "nuốt" giùm vùng thanh gạt Home, nên phải cộng
            tay `--safe-bottom` vào đây — nếu không, dải này sẽ nổi quá thấp, lấn vào đúng vùng
            thanh gạt trên iPhone toàn màn hình. */}
        <UpdateBanner offsetBottom={isDetailScreen ? "calc(24px + var(--safe-bottom))" : "calc(var(--nav-body-h) + 18px)"} />

        {/* Dải xác nhận — nổi trên thanh nav, không nhận thao tác nên không che nút nào. Cộng thêm
            52px (chiều cao viên "Có bản cập nhật" + khoảng cách) khi dải đó đang hiện, để xếp CHỒNG
            LÊN NHAU thay vì đè thẳng lên nhau — trước đây cả hai dải neo đúng một `bottom`. */}
        {toast && (
          <div
            className="toast-in absolute left-1/2 z-40 px-4 py-2.5 rounded-full text-[13px] font-semibold text-white pointer-events-none flex items-center gap-2"
            style={{
              bottom: updateBannerVisible
                ? (isDetailScreen ? "calc(24px + var(--safe-bottom) + 52px)" : "calc(var(--nav-body-h) + 18px + 52px)")
                : (isDetailScreen ? "calc(24px + var(--safe-bottom))" : "calc(var(--nav-body-h) + 18px)"),
              transform: "translateX(-50%)",
              background: "rgba(15,23,42,.92)",
              boxShadow: "0 8px 24px rgba(15,23,42,.28)",
              whiteSpace: "nowrap",
            }}
          >
            {/* Dải này LUÔN có nền tối (rgba(15,23,42,.92)) bất kể theme — #4ade80 là đúng giá trị
                --c-green của bản tối, chọn cố định vì đổi theo --c-green sẽ tối sẫm lại ở bản sáng
                và mất tương phản trên nền navy cố định này. */}
            <span style={{ color: "#4ade80" }}>✓</span>
            {toast}
          </div>
        )}

        {/* Hiện ở BẤT KỲ tab nào (không riêng Sơ đồ tư duy) — xem lý do ở khai báo `hasCustomContent`
            phía trên. Xếp CHỒNG lên cả dải cập nhật lẫn dải xác nhận nếu chúng đang hiện cùng lúc,
            theo đúng quy ước 52px/dải đã dùng cho hai dải đó. */}
        {showBackupReminder && (
          <div
            className="toast-in-full absolute flex items-center gap-2.5 px-4 py-2.5 rounded-2xl z-40"
            style={{
              left: 12,
              right: 12,
              bottom: `calc(${isDetailScreen ? "24px + var(--safe-bottom)" : "var(--nav-body-h) + 18px"} + ${
                (updateBannerVisible ? 52 : 0) + (toast ? 52 : 0)
              }px)`,
              background: "rgba(15,23,42,.94)",
            }}
          >
            <span className="flex-1 text-[12.5px] text-white leading-snug">
              Đã lâu chưa sao lưu — dữ liệu chỉ nằm trên máy này, mất máy là mất hết.
            </span>
            <button
              onClick={() => {
                snoozeBackupReminder()
                setShowBackupReminder(false)
              }}
              className="flex-none text-[12.5px] font-medium px-2 py-1 text-slate-300"
            >
              Để sau
            </button>
            <button
              onClick={() => navigate("dataSync")}
              className="flex-none text-[12.5px] font-bold px-3 py-1.5 rounded-full"
              style={{ background: "var(--c-surface)", color: "var(--c-primary)" }}
            >
              Sao lưu
            </button>
          </div>
        )}
    </div>
  )
}
